    @staticmethod
    def _norm(value: Any) -> str:
        return " ".join(str(value or "").strip().lower().split())

    @staticmethod
    def _parse_dataset_list(value: Any) -> Set[str]:
        if isinstance(value, (list, tuple, set)):
            parts = value
        else:
            parts = str(value or "").split(",")
        return {str(part).strip().lower() for part in parts if str(part).strip()}

    @staticmethod
    def _safe_int(value: Any, default: int = 10**9) -> int:
        try:
            return int(value)
        except (TypeError, ValueError):
            return default

    @staticmethod
    def _safe_float(value: Any, default: float = 0.0) -> float:
        try:
            return float(value)
        except (TypeError, ValueError):
            return default

    def _content_tokens(self, value: Any, max_tokens: int = 32) -> List[str]:
        text = text_processing(str(value or "").replace("_", " ").replace("-", " "))
        tokens: List[str] = []
        seen: Set[str] = set()
        for token in tokenize(text):
            if len(token) <= 2 or token in self._TEXT_VERIFIER_STOPWORDS:
                continue
            if token in seen:
                continue
            seen.add(token)
            tokens.append(token)
            if len(tokens) >= max_tokens:
                break
        return tokens

    def _phrase_or_token_hit(self, phrase: Any, text_norm: str, text_tokens: Set[str]) -> bool:
        phrase_norm = text_processing(str(phrase or "").replace("_", " ").replace("-", " "))
        if len(phrase_norm) <= 2:
            return False
        if f" {phrase_norm} " in f" {text_norm} ":
            return True
        phrase_tokens = self._content_tokens(phrase_norm, max_tokens=8)
        if not phrase_tokens:
            return False
        hits = sum(1 for token in phrase_tokens if token in text_tokens)
        return (hits / max(len(phrase_tokens), 1)) >= 0.67

    def _collect_text_verifier_terms(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        anchors: List[str] = []
        terminals: List[str] = []
        relation_terms: Set[str] = set()
        answer_terms: Set[str] = set()
        contexts = list(item.get("contexts", []) or [])
        for context in contexts:
            if not isinstance(context, Mapping):
                continue
            anchor = self._norm(context.get("anchor_entity"))
            terminal = self._norm(context.get("end_entity"))
            if anchor:
                anchors.append(anchor)
            if terminal:
                terminals.append(terminal)
            for relation in context.get("relations", []) or []:
                relation_terms.update(self._content_tokens(relation, max_tokens=8))
            for key in ("relation_family", "route", "signature_match_mode"):
                relation_terms.update(self._content_tokens(context.get(key), max_tokens=8))

        condition = query_plan_log.get("query_condition", {}) or {}
        if isinstance(condition, Mapping):
            answer_terms.update(self._content_tokens(condition.get("answer_type"), max_tokens=8))
            for key in ("relation_terms", "relation_families", "path_signatures", "query_relation_terms"):
                value = condition.get(key)
                if isinstance(value, (list, tuple, set)):
                    for part in value:
                        relation_terms.update(self._content_tokens(part, max_tokens=8))
                else:
                    relation_terms.update(self._content_tokens(value, max_tokens=8))
        query_terms = set(self._content_tokens(query_plan_log.get("query", ""), max_tokens=24))



        entity_tokens: Set[str] = set()
        for entity in anchors + terminals:
            entity_tokens.update(self._content_tokens(entity, max_tokens=8))
        query_terms = {token for token in query_terms if token not in entity_tokens}
        return {
            "anchors": sorted(set(anchors))[:6],
            "terminals": sorted(set(terminals))[:6],
            "relation_terms": sorted(relation_terms)[:24],
            "answer_terms": sorted(answer_terms)[:10],
            "query_terms": sorted(query_terms)[:24],
        }

    def _apply_text_verifier(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, str]:
        if self.text_verifier_mode == "off" or self.passage_text_getter is None:
            item["text_verifier"] = {"enabled": False, "reason": "disabled"}
            return True, "disabled"
        passage_idx = int(item.get("passage_idx", -1))
        try:
            passage_text = str(self.passage_text_getter(passage_idx) or "")
        except Exception as exc:
            item["text_verifier"] = {
                "enabled": True,
                "reason": "getter_error",
                "error": str(exc)[:120],
                "score": 0.0,
            }
            return True, "getter_error"
        if self.text_verifier_max_chars > 0:
            passage_text = passage_text[: self.text_verifier_max_chars]
        text_norm = text_processing(passage_text)
        if not text_norm:
            item["text_verifier"] = {"enabled": True, "reason": "empty_text", "score": 0.0}
            return True, "empty_text"

        text_tokens = set(tokenize(text_norm))
        terms = self._collect_text_verifier_terms(item, query_plan_log)
        anchors = terms["anchors"]
        terminals = terms["terminals"]
        anchor_hits = sum(1 for anchor in anchors if self._phrase_or_token_hit(anchor, text_norm, text_tokens))
        terminal_hits = sum(
            1 for terminal in terminals if self._phrase_or_token_hit(terminal, text_norm, text_tokens)
        )
        anchor_score = anchor_hits / max(len(anchors), 1) if anchors else 0.0
        terminal_score = terminal_hits / max(len(terminals), 1) if terminals else 0.0
        endpoint_score = max(anchor_score, terminal_score)
        both_endpoint_score = 1.0 if anchor_hits > 0 and terminal_hits > 0 else 0.0

        relation_terms = set(terms["relation_terms"])
        answer_terms = set(terms["answer_terms"])
        query_terms = set(terms["query_terms"])
        relation_overlap = relation_terms & text_tokens
        answer_overlap = answer_terms & text_tokens
        query_overlap = query_terms & text_tokens
        relation_score = (
            min(len(relation_overlap) / max(min(len(relation_terms), 8), 1), 1.0)
            if relation_terms else 0.0
        )
        answer_score = (
            min(len(answer_overlap) / max(min(len(answer_terms), 4), 1), 1.0)
            if answer_terms else 0.0
        )
        query_score = (
            min(len(query_overlap) / max(min(len(query_terms), 10), 1), 1.0)
            if query_terms else 0.0
        )
        path_info = item.get("path_aware", {}) or {}
        path_score = self._safe_float(path_info.get("score"), 0.0) if bool(path_info.get("approved")) else 0.0

        if anchors or terminals:
            score = (
                0.36 * endpoint_score
                + 0.24 * relation_score
                + 0.18 * query_score
                + 0.12 * both_endpoint_score
                + 0.06 * answer_score
                + 0.04 * path_score
            )
        else:
            score = 0.45 * relation_score + 0.35 * query_score + 0.10 * answer_score + 0.10 * path_score
        score = min(max(float(score), 0.0), 1.0)
        promoted = score >= self.text_verifier_min_score
        rejected = False
        reason = "passed" if promoted else "below_min_score"
        if (
            self.text_verifier_mode == "filter"
            and self.text_verifier_reject_below > 0.0
            and score < self.text_verifier_reject_below
            and not bool(item.get("has_strict") or item.get("has_multihop"))
            and not bool(path_info.get("approved"))
            and self._safe_int(item.get("original_rank"), 10**9) > 2
        ):
            rejected = True
            reason = "low_text_support"
        if promoted:
            item["score"] = self._safe_float(item.get("score"), 0.0) + self.text_verifier_score_weight * score
            current_confidence = self._safe_float(item.get("confidence"), 0.0)
            item["confidence"] = min(
                0.99,
                max(current_confidence, current_confidence + self.text_verifier_confidence_boost * score),
            )
        item["text_verifier"] = {
            "enabled": True,
            "mode": self.text_verifier_mode,
            "score": round(score, 6),
            "promoted": bool(promoted),
            "rejected": bool(rejected),
            "reason": reason,
            "anchor_hits": int(anchor_hits),
            "anchor_count": int(len(anchors)),
            "terminal_hits": int(terminal_hits),
            "terminal_count": int(len(terminals)),
            "relation_overlap": sorted(relation_overlap)[:8],
            "query_overlap": sorted(query_overlap)[:8],
            "answer_overlap": sorted(answer_overlap)[:6],
        }
        return (not rejected), reason

    def _rank_window_text_signal(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Cheap text predicate for the rank-window access path.

        The global text verifier may be disabled in a run configuration. Rank
        window recall still needs a local evidence predicate; otherwise the
        access path can generate candidates but reject all of them as
        ``missing_text_signal``.
        """
        text_info = item.get("text_verifier", {}) or {}
        if not isinstance(text_info, Mapping):
            text_info = {}

        existing = {
            "enabled": bool(text_info.get("enabled", False)),
            "source": "text_verifier",
            "score": min(max(self._safe_float(text_info.get("score"), 0.0), 0.0), 1.0),
            "query_overlap": list(text_info.get("query_overlap", []) or []),
            "answer_overlap": list(text_info.get("answer_overlap", []) or []),
            "relation_overlap": list(text_info.get("relation_overlap", []) or []),
            "anchor_hits": self._safe_int(text_info.get("anchor_hits"), 0),
            "terminal_hits": self._safe_int(text_info.get("terminal_hits"), 0),
            "reason": str(text_info.get("reason") or ""),
        }
        if (
            existing["score"] > 0.0
            or existing["query_overlap"]
            or existing["answer_overlap"]
            or existing["relation_overlap"]
            or existing["anchor_hits"] > 0
            or existing["terminal_hits"] > 0
        ):
            return existing

        fallback = {
            "enabled": True,
            "source": "rank_window_text_fallback",
            "score": 0.0,
            "query_overlap": [],
            "answer_overlap": [],
            "relation_overlap": [],
            "anchor_hits": 0,
            "terminal_hits": 0,
            "reason": "",
        }
        if self.passage_text_getter is None:
            fallback["enabled"] = False
            fallback["reason"] = "no_passage_text_getter"
            return fallback

        passage_idx = self._safe_int(item.get("passage_idx"), -1)
        if passage_idx < 0:
            fallback["reason"] = "missing_passage_idx"
            return fallback
        try:
            passage_text = str(self.passage_text_getter(passage_idx) or "")
        except Exception as exc:
            fallback["reason"] = "getter_error"
            fallback["error"] = str(exc)[:120]
            return fallback

        if self.text_verifier_max_chars > 0:
            passage_text = passage_text[: self.text_verifier_max_chars]
        text_norm = text_processing(passage_text)
        if not text_norm:
            fallback["reason"] = "empty_text"
            return fallback

        text_tokens = set(tokenize(text_norm))
        terms = self._collect_text_verifier_terms(item, query_plan_log)
        anchors = list(terms.get("anchors", []) or [])
        terminals = list(terms.get("terminals", []) or [])
        anchor_hits = sum(1 for anchor in anchors if self._phrase_or_token_hit(anchor, text_norm, text_tokens))
        terminal_hits = sum(
            1 for terminal in terminals if self._phrase_or_token_hit(terminal, text_norm, text_tokens)
        )

        relation_terms = set(terms.get("relation_terms", []) or [])
        answer_terms = set(terms.get("answer_terms", []) or [])
        query_terms = set(terms.get("query_terms", []) or [])
        relation_overlap = relation_terms & text_tokens
        answer_overlap = answer_terms & text_tokens
        query_overlap = query_terms & text_tokens

        anchor_score = anchor_hits / max(len(anchors), 1) if anchors else 0.0
        terminal_score = terminal_hits / max(len(terminals), 1) if terminals else 0.0
        endpoint_score = max(anchor_score, terminal_score)
        both_endpoint_score = 1.0 if anchor_hits > 0 and terminal_hits > 0 else 0.0
        relation_score = (
            min(len(relation_overlap) / max(min(len(relation_terms), 8), 1), 1.0)
            if relation_terms else 0.0
        )
        answer_score = (
            min(len(answer_overlap) / max(min(len(answer_terms), 4), 1), 1.0)
            if answer_terms else 0.0
        )
        query_score = (
            min(len(query_overlap) / max(min(len(query_terms), 10), 1), 1.0)
            if query_terms else 0.0
        )

        path_info = item.get("path_aware", {}) or {}
        path_score = self._safe_float(path_info.get("score"), 0.0) if bool(path_info.get("approved")) else 0.0
        if anchors or terminals:
            score = (
                0.34 * endpoint_score
                + 0.22 * relation_score
                + 0.22 * query_score
                + 0.10 * both_endpoint_score
                + 0.08 * answer_score
                + 0.04 * path_score
            )
        else:
            score = 0.42 * query_score + 0.34 * relation_score + 0.14 * answer_score + 0.10 * path_score
        score = min(max(float(score), 0.0), 1.0)

        fallback.update(
            {
                "score": round(score, 6),
                "query_overlap": sorted(query_overlap)[:8],
                "answer_overlap": sorted(answer_overlap)[:6],
                "relation_overlap": sorted(relation_overlap)[:8],
                "anchor_hits": int(anchor_hits),
                "terminal_hits": int(terminal_hits),
                "reason": "computed",
            }
        )
        return fallback

    def _apply_schema_route_adapter(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, str]:
        """Youtu-style schema route signal for ontology candidates.

        This does not add new passages by itself. It asks whether an existing
        candidate covers entity/triple/path/community/answer routes implied by
        the query-plan schema, then uses that structured signal as a calibrated
        boost or optional filter.
        """
        if self.schema_route_adapter.mode == "off":
            item["schema_route_adapter"] = {
                "enabled": False,
                "mode": self.schema_route_adapter.mode,
            }
            return True, "disabled"

        route = self.schema_route_adapter.score_candidate(query_plan_log, item)
        score = self._safe_float(route.get("score"), 0.0)
        item["schema_route_adapter"] = route

        if route.get("decision") == "reject":
            return False, "schema_route_low_score"

        if score >= self.schema_route_adapter.min_score:
            item["confidence"] = min(
                0.99,
                max(
                    self._safe_float(item.get("confidence"), 0.0),
                    self._safe_float(item.get("confidence"), 0.0)
                    + self.schema_route_adapter.confidence_boost * score,
                ),
            )
        if self.schema_route_adapter.score_weight > 0.0:
            item["score"] = (
                self._safe_float(item.get("score"), 0.0)
                + self.schema_route_adapter.score_weight * score
            )
        return True, str(route.get("decision") or "keep")

    @staticmethod
    def _merge_signature(target: Dict[str, set], source: Mapping[str, set]) -> None:
        for key in target:
            target[key].update(source.get(key, set()) or set())

    def _empty_signature(self) -> Dict[str, set]:
        return {
            "roles": set(),
            "anchors": set(),
            "terminals": set(),
            "relations": set(),
            "plans": set(),
            "facts": set(),
        }

    def _context_signature(self, contexts: Iterable[Mapping[str, Any]]) -> Dict[str, set]:
        signature = self._empty_signature()
        for context in contexts or []:
            if not isinstance(context, Mapping):
                continue
            plan_id = self._norm(context.get("plan_id"))
            anchor = self._norm(context.get("anchor_entity"))
            terminal = self._norm(context.get("end_entity"))
            if plan_id:
                signature["plans"].add(plan_id)
            if anchor:
                signature["anchors"].add(anchor)
            if terminal:
                signature["terminals"].add(terminal)
            fact_position = context.get("fact_position")
            if plan_id and fact_position is not None:
                signature["roles"].add((plan_id, str(fact_position)))
            for fact_idx in context.get("fact_indices", []) or []:
                signature["facts"].add(str(fact_idx))
            support_key = self._norm(context.get("support_key"))
            if support_key:
                signature["facts"].add(f"support::{support_key}")
                signature["roles"].add(("support", support_key))
            relations = tuple(
                self._norm(relation)
                for relation in (context.get("relations", []) or [])
                if self._norm(relation)
            )
            if relations:
                signature["relations"].add(relations)
        return signature

    def _context_decomposition_slots(
        self,
        contexts: Iterable[Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
    ) -> Set[str]:
        """Return schema-guided sub-question slots covered by a passage.

        These slots are intentionally coarser than the regular evidence-set
        signature. In particular, they avoid passage-specific support keys so
        the selector cannot treat every dense candidate as a new reasoning step.
        The slot shape mirrors Youtu-style decomposition routes: anchor-relation,
        terminal-relation, endpoint, plan-step, and answer-type relation.
        """
        slots: Set[str] = set()
        condition = query_plan_log.get("query_condition", {}) or {}
        answer_type = self._norm(condition.get("answer_type")) if isinstance(condition, Mapping) else ""
        for context in contexts or []:
            if not isinstance(context, Mapping):
                continue
            plan_id = self._norm(context.get("plan_id"))
            anchor = self._norm(context.get("anchor_entity"))
            terminal = self._norm(context.get("end_entity"))
            route = self._norm(context.get("route"))
            if not route:
                route = self._norm(context.get("signature_match_mode"))
            relations = tuple(
                self._norm(relation)
                for relation in (context.get("relations", []) or [])
                if self._norm(relation)
            )
            relation_key = "|".join(relations)
            fact_position = context.get("fact_position")

            if plan_id and fact_position is not None:
                slots.add(f"plan_step::{plan_id}::{fact_position}")
            if anchor and relation_key:
                slots.add(f"anchor_relation::{anchor}::{relation_key}")
            if terminal and relation_key:
                slots.add(f"terminal_relation::{terminal}::{relation_key}")
            if anchor and terminal:
                slots.add(f"endpoint::{anchor}::{terminal}")
            if route and relation_key:
                slots.add(f"route_relation::{route}::{relation_key}")
            if answer_type and relation_key:
                slots.add(f"answer_relation::{answer_type}::{relation_key}")
            if plan_id and relation_key:
                slots.add(f"plan_relation::{plan_id}::{relation_key}")
        return set(sorted(slots)[: self.decomposition_slot_max_slots])

    def _path_aware_features(self, contexts: Iterable[Mapping[str, Any]]) -> Dict[str, Any]:
        path_context_count = 0
        max_path_length = 0
        max_terminal_type_score = 0.0
        max_query_relation_coverage = 0.0
        max_source_coverage = 0.0
        relation_count = 0
        has_anchor = False
        has_terminal = False
        for context in contexts or []:
            if not isinstance(context, Mapping) or not bool(context.get("ontology_path_executor", False)):
                continue
            path_context_count += 1
            reasons = context.get("fact_score_reasons", {}) or {}
            path_length = self._safe_int(reasons.get("path_length"), 0)
            if path_length <= 0:
                path_length = len(context.get("slot_ids", []) or [])
            max_path_length = max(max_path_length, path_length)
            max_terminal_type_score = max(
                max_terminal_type_score,
                self._safe_float(context.get("terminal_type_score"), self._safe_float(reasons.get("terminal_type_score"), 0.0)),
            )
            max_query_relation_coverage = max(
                max_query_relation_coverage,
                self._safe_float(context.get("query_relation_coverage"), self._safe_float(reasons.get("query_relation_coverage"), 0.0)),
            )
            max_source_coverage = max(max_source_coverage, self._safe_float(reasons.get("source_coverage"), 0.0))
            relation_count = max(relation_count, len(context.get("relations", []) or []))
            has_anchor = has_anchor or bool(context.get("anchor_entity"))
            has_terminal = has_terminal or bool(context.get("end_entity")) or max_terminal_type_score >= self.path_aware_min_terminal_type_score

        if path_context_count <= 0:
            return {
                "enabled": self.enable_path_aware_selector,
                "approved": False,
                "score": 0.0,
                "path_context_count": 0,
            }
        length_score = min(max_path_length / 3.0, 1.0)
        relation_score = min(relation_count / 3.0, 1.0)
        score = (
            0.28 * length_score
            + 0.26 * max_terminal_type_score
            + 0.24 * max_query_relation_coverage
            + 0.14 * max_source_coverage
            + 0.08 * relation_score
        )
        score = min(max(float(score), 0.0), 1.0)
        relation_ok = (
            max_query_relation_coverage >= 0.999
            if self.path_aware_require_query_relation_coverage else True
        )
        approved = (
            score >= self.path_aware_min_score
            and max_terminal_type_score >= self.path_aware_min_terminal_type_score
            and relation_ok
            and has_anchor
            and has_terminal
        )
        return {
            "enabled": self.enable_path_aware_selector,
            "approved": bool(approved),
            "score": round(score, 6),
            "path_context_count": path_context_count,
            "path_length": int(max_path_length),
            "terminal_type_score": round(max_terminal_type_score, 6),
            "query_relation_coverage": round(max_query_relation_coverage, 6),
            "source_coverage": round(max_source_coverage, 6),
            "relation_count": int(relation_count),
            "has_anchor": bool(has_anchor),
            "has_terminal": bool(has_terminal),
            "relation_ok": bool(relation_ok),
            "min_score": self.path_aware_min_score,
        }

    def _coverage_delta(self, candidate: Mapping[str, set], covered: Mapping[str, set]) -> Dict[str, int]:
        return {
            "new_roles": len(candidate["roles"] - covered["roles"]),
            "new_anchors": len(candidate["anchors"] - covered["anchors"]),
            "new_terminals": len(candidate["terminals"] - covered["terminals"]),
            "new_relations": len(candidate["relations"] - covered["relations"]),
            "new_plans": len(candidate["plans"] - covered["plans"]),
            "new_facts": len(candidate["facts"] - covered["facts"]),
        }

    def _overlap_count(self, candidate: Mapping[str, set], covered: Mapping[str, set]) -> int:
        return sum(len(candidate[key] & covered[key]) for key in candidate)

    def _candidate_confidence(
        self,
        passage: Mapping[str, Any],
        max_raw_score: float,
    ) -> float:
        contexts = list(passage.get("contexts", []) or [])
        decision = passage.get("reranker_decision", {}) or {}
        explicit_confidence = self._safe_float(decision.get("confidence"), -1.0)
        if explicit_confidence >= 0.0:
            confidence = explicit_confidence
        else:
            raw_score = self._safe_float(passage.get("raw_lift_score"), 0.0)
            normalized_raw = 0.0 if max_raw_score <= 0.0 else raw_score / max(max_raw_score, 1e-8)
            normalized_raw = min(max(normalized_raw, 0.0), 1.0)
            precision = max(
                (self._safe_float(context.get("plan_effective_precision"), 0.0) for context in contexts),
                default=0.0,
            )
            scale = max(
                (self._safe_float(context.get("plan_lift_weight_scale"), 1.0) for context in contexts),
                default=1.0,
            )
            strict = any(
                str(context.get("signature_match_mode", "") or "").strip().lower() == "strict"
                for context in contexts
            )
            confidence = (
                0.38 * normalized_raw
                + 0.28 * min(max(precision, 0.0), 1.0)
                + 0.14 * min(max(scale, 0.0), 1.0)
                + 0.12 * (1.0 if strict else 0.0)
                + 0.08 * min(len(contexts) / 2.0, 1.0)
            )
        return min(max(float(confidence), 0.0), 1.0)

    def _candidate_quality_flags(self, contexts: Sequence[Mapping[str, Any]]) -> Dict[str, bool]:
        has_strict = False
        has_multihop = False
        has_terminal = False
        has_relation = False
        for context in contexts or []:
            if str(context.get("signature_match_mode", "") or "").strip().lower() == "strict":
                has_strict = True
            if len(context.get("fact_indices", []) or []) >= 2 or len(context.get("relations", []) or []) >= 2:
                has_multihop = True
            if self._norm(context.get("end_entity")):
                has_terminal = True
            if context.get("relations"):
                has_relation = True
        return {
            "has_strict": has_strict,
            "has_multihop": has_multihop,
            "has_terminal": has_terminal,
            "has_relation": has_relation,
        }

    def _evidence_grounded_profile(
        self,
        contexts: Sequence[Mapping[str, Any]],
        original_rank: int,
    ) -> Dict[str, Any]:
        """Summarize retrieval-feedback evidence-grounded contexts.

        This profile lets the selector admit high-quality grounded candidates
        apply source-aware thresholds only when the ontology plan has real
        retrieval feedback, instead of weakening the global policy.
        """
        eg_contexts = [
            context for context in contexts or []
            if isinstance(context, Mapping) and bool(context.get("evidence_grounded"))
        ]
        if not eg_contexts:
            return {
                "is_evidence_grounded": False,
                "tier": "",
                "precision": 0.0,
                "gt5_precision": 0.0,
                "selected_precision": 0.0,
                "min_confidence": self.min_candidate_confidence,
                "intervention_min_confidence": self.intervention_min_confidence,
                "max_original_rank": 0,
                "approved": False,
                "reason": "not_evidence_grounded",
            }
        tier_order = {"strong": 3, "moderate": 2, "weak": 1}
        tiers = [
            str(context.get("plan_action_tier", "") or "").split("_small_sample")[0]
            for context in eg_contexts
        ]
        tier = max(tiers, key=lambda item: tier_order.get(item, 0)) if tiers else ""
        precision = max(
            self._safe_float(context.get("plan_effective_precision"), 0.0)
            for context in eg_contexts
        )
        gt5_precision = max(
            self._safe_float(context.get("plan_feedback_gt5_precision"), 0.0)
            for context in eg_contexts
        )
        selected_precision = max(
            self._safe_float(context.get("plan_feedback_selected_precision"), 0.0)
            for context in eg_contexts
        )
        signal = max(precision, gt5_precision, selected_precision)
        if (
            tier == "strong"
            and original_rank <= 20
            and (precision >= 0.30 or gt5_precision >= 0.08 or selected_precision >= 0.30)
        ):
            return {
                "is_evidence_grounded": True,
                "tier": tier,
                "precision": precision,
                "gt5_precision": gt5_precision,
                "selected_precision": selected_precision,
                "min_confidence": min(self.min_candidate_confidence, 0.58),
                "intervention_min_confidence": min(self.intervention_min_confidence, 0.56),
                "max_original_rank": 20,
                "approved": True,
                "reason": "strong_feedback",
            }
        if (
            tier in {"strong", "moderate"}
            and original_rank <= 20
            and (precision >= 0.15 or gt5_precision >= 0.05 or selected_precision >= 0.15)
        ):
            return {
                "is_evidence_grounded": True,
                "tier": tier,
                "precision": precision,
                "gt5_precision": gt5_precision,
                "selected_precision": selected_precision,
                "min_confidence": min(self.min_candidate_confidence, 0.64),
                "intervention_min_confidence": min(self.intervention_min_confidence, 0.62),
                "max_original_rank": 20,
                "approved": True,
                "reason": "moderate_feedback",
            }
        return {
            "is_evidence_grounded": True,
            "tier": tier,
            "precision": precision,
            "gt5_precision": gt5_precision,
            "selected_precision": selected_precision,
            "min_confidence": self.min_candidate_confidence,
            "intervention_min_confidence": self.intervention_min_confidence,
            "max_original_rank": 20,
            "approved": False,
            "reason": "weak_feedback" if signal > 0 else "no_feedback_signal",
        }

    def _is_simple_relation_query(self, query_plan_log: Mapping[str, Any]) -> bool:
        query_condition = query_plan_log.get("query_condition", {}) or {}
        relation_families = query_condition.get("relation_families", []) or []
        relation_signatures = query_condition.get("relation_signatures", []) or []
        matched_plan_count = self._safe_int(query_plan_log.get("matched_plan_count"), 0)
        executable_path_count = self._safe_int(query_plan_log.get("executable_path_count"), 0)
        strict_path_count = self._safe_int(query_plan_log.get("strict_executable_path_count"), 0)
        anchors = [
            self._norm(anchor)
            for anchor in (query_plan_log.get("anchor_entities", []) or [])
            if self._norm(anchor)
        ]
        return (
            matched_plan_count <= 2
            and executable_path_count <= 2
            and strict_path_count <= 2
            and len(anchors) <= 2
            and len(set(relation_families + relation_signatures)) <= 3
        )

    def _intervention_features(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        contexts = list(item.get("contexts", []) or [])
        has_path_seed = False
        has_path_neighbor = False
        has_anchor = False
        has_terminal = False
        has_anchor_relation = False
        has_terminal_relation = False
        has_endpoint_pair = False
        relation_only_contexts = 0
        strong_contexts = 0

        for context in contexts:
            if not isinstance(context, Mapping):
                continue
            reasons = context.get("fact_score_reasons", {}) or {}
            path_seed = bool(context.get("path_seed_hit")) or int(reasons.get("path_seed", 0) or 0) > 0
            path_neighbor = int(reasons.get("path_neighbor", 0) or 0) > 0
            anchor = bool(self._norm(context.get("anchor_entity")))
            terminal = bool(self._norm(context.get("end_entity")))
            relation = bool(context.get("relations"))
            if path_seed:
                has_path_seed = True
            if path_neighbor:
                has_path_neighbor = True
            if anchor:
                has_anchor = True
            if terminal:
                has_terminal = True
            if anchor and relation:
                has_anchor_relation = True
            if terminal and relation:
                has_terminal_relation = True
            if anchor and terminal:
                has_endpoint_pair = True
            if relation and not anchor and not terminal and not path_seed and not path_neighbor:
                relation_only_contexts += 1
            if path_seed or (anchor and terminal) or (anchor and relation) or (terminal and relation):
                strong_contexts += 1

        has_relation = bool(item.get("has_relation"))
        relation_only = (
            has_relation
            and not has_anchor
            and not has_terminal
            and not has_path_seed
            and not has_path_neighbor
        )
        return {
            "has_path_seed": has_path_seed,
            "has_path_neighbor": has_path_neighbor,
            "has_anchor": has_anchor,
            "has_terminal": has_terminal,
            "has_anchor_relation": has_anchor_relation,
            "has_terminal_relation": has_terminal_relation,
            "has_endpoint_pair": has_endpoint_pair,
            "relation_only": relation_only,
            "relation_only_contexts": relation_only_contexts,
            "strong_contexts": strong_contexts,
            "simple_relation_query": self._is_simple_relation_query(query_plan_log),
        }

    def _anchor_relation_has_source_support(self, source_policy: Mapping[str, Any]) -> bool:
        if bool(source_policy.get("approved", False)):
            return True
        precision = self._safe_float(source_policy.get("precision"), 0.0)
        gt5_precision = self._safe_float(source_policy.get("gt5_precision"), 0.0)
        selected_precision = self._safe_float(source_policy.get("selected_precision"), 0.0)
        return (
            precision >= self.anchor_relation_min_source_precision
            or selected_precision >= self.anchor_relation_min_selected_precision
            or gt5_precision >= max(0.05, self.anchor_relation_min_selected_precision)
        )

    def _is_backbone_candidate(
        self,
        item: Mapping[str, Any],
        features: Mapping[str, Any],
        source_policy: Mapping[str, Any],
    ) -> bool:
        relation_only_simple = (
            features.get("relation_only")
            and self.intervention_allow_relation_only_simple
            and features.get("simple_relation_query")
            and self._safe_float(item.get("confidence"), 0.0) >= self.intervention_relation_only_min_confidence
        )
        if not self.strict_backbone_scope:
            return (
                bool(source_policy.get("approved"))
                or bool(features.get("has_path_seed"))
                or bool(features.get("has_endpoint_pair"))
                or bool(features.get("has_anchor_relation"))
                or bool(features.get("has_terminal_relation"))
                or (bool(features.get("has_path_neighbor")) and bool(item.get("has_relation")))
                or bool(relation_only_simple)
            )

        anchor_relation_is_grounded = (
            bool(features.get("has_anchor_relation"))
            and self._anchor_relation_has_source_support(source_policy)
        )
        return (
            bool(source_policy.get("approved"))
            or bool(features.get("has_path_seed"))
            or bool(features.get("has_endpoint_pair"))
            or bool(features.get("has_terminal_relation"))
            or bool(anchor_relation_is_grounded)
            or (bool(features.get("has_path_neighbor")) and bool(item.get("has_relation")))
            or bool(relation_only_simple)
        )

    def _passes_intervention_policy(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, str, Dict[str, Any]]:
        features = self._intervention_features(item, query_plan_log)
        confidence = float(item.get("confidence", 0.0) or 0.0)
        original_rank = int(item.get("original_rank", 10**9) or 10**9)
        source_policy = item.get("source_policy", {}) or {}
        swapper_score = self._safe_float((item.get("recall_swapper", {}) or {}).get("score"), 0.0)
        swapper_structure_ok = (
            bool(features.get("has_anchor"))
            or bool(features.get("has_terminal"))
            or bool(features.get("has_path_seed"))
            or bool(features.get("has_endpoint_pair"))
            or bool(item.get("has_relation"))
        )
        swapper_relation_only_ok = (
            not bool(features.get("relation_only"))
            or self.recall_swapper_allow_relation_only_top2
            or bool(features.get("simple_relation_query"))
        )
        if (
            self.recall_swapper_mode != "off"
            and self.recall_swapper.is_ready()
            and swapper_score >= self.recall_swapper_min_score
            and swapper_structure_ok
            and swapper_relation_only_ok
            and confidence >= min(self.intervention_min_confidence, 0.58)
        ):
            features["recall_swapper_override"] = True
            features["recall_swapper_score"] = swapper_score
            return True, "recall_swapper_override", features

        if (
            bool(source_policy.get("approved", False))
            and bool(source_policy.get("is_evidence_grounded", False))
            and original_rank <= int(source_policy.get("max_original_rank", 0) or 0)
            and confidence >= float(source_policy.get("intervention_min_confidence", self.intervention_min_confidence) or 0.0)
        ):
            features["source_aware_policy"] = dict(source_policy)
            return True, f"source_aware_{source_policy.get('reason', 'evidence_grounded')}", features

        if confidence < self.intervention_min_confidence:
            return False, "low_intervention_confidence", features

        if features["has_path_seed"] or features["has_endpoint_pair"]:
            return True, "path_or_endpoint", features

        if features["has_terminal_relation"]:
            return True, "terminal_relation", features

        if features["has_anchor_relation"]:
            if (
                not self.strict_backbone_scope
                or self._anchor_relation_has_source_support(source_policy)
            ):
                return True, "anchored_relation", features
            features["weak_anchor_relation_requires_utility"] = True
            return True, "weak_anchor_relation_needs_utility", features

        if features["has_path_neighbor"] and bool(item.get("has_relation")):
            return True, "path_neighbor_relation", features

        if features["relation_only"]:
            relation_only_rank_ok = (
                self.intervention_relation_only_max_original_rank <= 0
                or original_rank <= self.intervention_relation_only_max_original_rank
            )
            if (
                self.intervention_allow_relation_only_simple
                and features["simple_relation_query"]
                and relation_only_rank_ok
                and confidence >= self.intervention_relation_only_min_confidence
            ):
                return True, "simple_relation_only", features
            return False, "relation_only_without_anchor_or_terminal", features

        return False, "no_strong_ontology_context", features

    def _candidate_evidence_value(self, item: Mapping[str, Any]) -> float:
        """Estimate whether an ontology candidate is worth replacing a top-5 passage.

        This estimate combines local confidence
        with retrieval-feedback precision and a small structural bonus.
        """
        confidence = float(item.get("confidence", 0.0) or 0.0)
        source_policy = item.get("source_policy", {}) or {}
        precision = self._safe_float(source_policy.get("precision"), 0.0)
        gt5_precision = self._safe_float(source_policy.get("gt5_precision"), 0.0)
        selected_precision = self._safe_float(source_policy.get("selected_precision"), 0.0)
        feedback_value = max(
            selected_precision,
            0.70 * precision,
            min(1.0, 3.0 * gt5_precision),
        )
        tier = str(source_policy.get("tier", "") or "")
        tier_bonus = 0.06 if tier == "strong" else 0.03 if tier == "moderate" else 0.0
        structural_bonus = 0.0
        if bool(item.get("has_strict")):
            structural_bonus += 0.04
        if bool(item.get("has_multihop")):
            structural_bonus += 0.03
        if bool(item.get("has_terminal")):
            structural_bonus += 0.03
        if bool(item.get("has_relation")):
            structural_bonus += 0.02
        value = 0.55 * confidence + 0.35 * feedback_value + tier_bonus + min(structural_bonus, 0.08)
        policy_info = item.get("evidence_set_policy", {}) or {}
        policy_score = self._safe_float(policy_info.get("score"), 0.0)
        if policy_score > 0.0 and self.evidence_set_policy_counterfactual_weight > 0.0:
            value += self.evidence_set_policy_counterfactual_weight * policy_score
        recall_info = item.get("recall_selector", {}) or {}
        recall_score = self._safe_float(recall_info.get("score"), 0.0)
        if recall_score > 0.0 and self.recall_selector_counterfactual_weight > 0.0:
            value += self.recall_selector_counterfactual_weight * recall_score
        swapper_info = item.get("recall_swapper", {}) or {}
        swapper_score = self._safe_float(swapper_info.get("score"), 0.0)
        if swapper_score > 0.0 and self.recall_swapper_counterfactual_weight > 0.0:
            value += self.recall_swapper_counterfactual_weight * swapper_score
        utility_info = item.get("utility_policy", {}) or {}
        utility_score = self._safe_float(utility_info.get("score"), 0.0)
        if utility_score > 0.0 and self.utility_policy_counterfactual_weight > 0.0:
            value += self.utility_policy_counterfactual_weight * utility_score
        planner_info = item.get("utility_planner", {}) or {}
        planner_score = self._safe_float(planner_info.get("score"), 0.0)
        if planner_score > 0.0 and self.utility_planner_counterfactual_weight > 0.0:
            value += self.utility_planner_counterfactual_weight * planner_score
        recall_plan_info = item.get("recall_plan_optimizer", {}) or {}
        recall_plan_score = self._safe_float(recall_plan_info.get("score"), 0.0)
        if recall_plan_score > 0.0 and self.recall_plan_optimizer_score_weight > 0.0:
            value += 0.25 * self.recall_plan_optimizer_score_weight * recall_plan_score
        rank_window_info = item.get("rank_window_recall", {}) or {}
        rank_window_score = self._safe_float(rank_window_info.get("score"), 0.0)
        if rank_window_score > 0.0 and self.rank_window_recall_score_weight > 0.0:
            text_score = self._safe_float(rank_window_info.get("text_score"), 0.0)
            dense_score_norm = self._safe_float(rank_window_info.get("dense_score_norm"), 0.0)
            value += self.rank_window_recall_score_weight * (
                0.42 * rank_window_score
                + 0.08 * text_score
                + 0.05 * dense_score_norm
            )
        return min(max(value, 0.0), 1.25)

    def _apply_evidence_set_policy(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, str]:
        if self.evidence_set_policy_mode == "off" or not self.evidence_set_policy.is_ready():
            item["evidence_set_policy"] = {
                "enabled": False,
                "mode": self.evidence_set_policy_mode,
                "model_ready": self.evidence_set_policy.is_ready(),
            }
            return True, "disabled"
        policy = self.evidence_set_policy.score(query_plan_log, item)
        score = self._safe_float(policy.get("score"), 0.0)
        policy.update({
            "enabled": True,
            "mode": self.evidence_set_policy_mode,
            "min_score": self.evidence_set_policy_min_score,
            "reject_below": self.evidence_set_policy_reject_below,
            "score_weight": self.evidence_set_policy_score_weight,
        })
        decision = "keep"
        if score >= self.evidence_set_policy_min_score:
            decision = "promote"
            item["confidence"] = max(
                self._safe_float(item.get("confidence"), 0.0),
                self.evidence_set_policy_promote_confidence,
                min(score, 0.98),
            )
        if self.evidence_set_policy_score_weight > 0.0:
            item["score"] = self._safe_float(item.get("score"), 0.0) + self.evidence_set_policy_score_weight * score
        if self.evidence_set_policy_mode in {"filter", "selector"} and score < self.evidence_set_policy_reject_below:
            decision = "reject"
            policy["decision"] = decision
            item["evidence_set_policy"] = policy
            return False, "evidence_set_policy_low_score"
        policy["decision"] = decision
        item["evidence_set_policy"] = policy
        return True, decision

    def _apply_recall_selector(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> str:
        """Score candidates for recall-oriented top-5 promotion.

        The ordinary evidence-set policy learns whether a candidate is broadly
        useful. This selector is trained with a narrower target: candidates
        that cover gold evidence absent from the baseline top-5. It therefore
        changes ordering only when the model sees an explicit recall signal.
        """
        if self.recall_selector_mode == "off" or not self.recall_selector.is_ready():
            item["recall_selector"] = {
                "enabled": False,
                "mode": self.recall_selector_mode,
                "model_ready": self.recall_selector.is_ready(),
            }
            return "disabled"
        selector = self.recall_selector.score(query_plan_log, item)
        score = self._safe_float(selector.get("score"), 0.0)
        decision = "keep"
        selector.update({
            "enabled": True,
            "mode": self.recall_selector_mode,
            "min_score": self.recall_selector_min_score,
            "score_weight": self.recall_selector_score_weight,
            "counterfactual_weight": self.recall_selector_counterfactual_weight,
            "bypass_router_min_score": self.recall_selector_bypass_router_min_score,
        })
        if score >= self.recall_selector_min_score:
            decision = "promote"
            item["confidence"] = max(
                self._safe_float(item.get("confidence"), 0.0),
                self.recall_selector_promote_confidence,
                min(score, 0.99),
            )
            item["score"] = self._safe_float(item.get("score"), 0.0) + self.recall_selector_score_weight * score
            item["effective_min_confidence"] = min(
                self._safe_float(item.get("effective_min_confidence"), self.min_candidate_confidence),
                self.recall_selector_promote_confidence,
            )
        selector["decision"] = decision
        item["recall_selector"] = selector
        return decision

    def _apply_recall_swapper(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> str:
        """Score candidates for direct Recall@2/5 evidence-window swapping.

        This policy is intentionally placed after candidate construction and
        before final window assembly. It learns from oracle-gap labels whether
        a candidate should displace a baseline passage, instead of only adding
        a soft score inside an upstream retriever.
        """
        if self.recall_swapper_mode == "off" or not self.recall_swapper.is_ready():
            item["recall_swapper"] = {
                "enabled": False,
                "mode": self.recall_swapper_mode,
                "model_ready": self.recall_swapper.is_ready(),
            }
            return "disabled"
        swapper = self.recall_swapper.score(query_plan_log, item)
        score = self._safe_float(swapper.get("score"), 0.0)
        decision = "keep"
        swapper.update({
            "enabled": True,
            "mode": self.recall_swapper_mode,
            "min_score": self.recall_swapper_min_score,
            "top2_min_score": self.recall_swapper_top2_min_score,
            "score_weight": self.recall_swapper_score_weight,
            "counterfactual_weight": self.recall_swapper_counterfactual_weight,
            "max_top2_swaps": self.recall_swapper_max_top2_swaps,
        })
        if score >= self.recall_swapper_min_score:
            decision = "promote"
            item["confidence"] = max(
                self._safe_float(item.get("confidence"), 0.0),
                self.recall_swapper_promote_confidence,
                min(score, 0.99),
            )
            item["score"] = self._safe_float(item.get("score"), 0.0) + self.recall_swapper_score_weight * score
            item["effective_min_confidence"] = min(
                self._safe_float(item.get("effective_min_confidence"), self.min_candidate_confidence),
                max(0.50, min(self.recall_swapper_promote_confidence, score)),
            )
        swapper["decision"] = decision
        item["recall_swapper"] = swapper
        return decision

    def _apply_rank2_rescue(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> str:
        """Score a candidate for conservative rank-2 replacement only.

        Unlike the recall swapper, this model must not broadly promote
        candidates or reshape top-5 ordering. It is used only by the final
        rank-2 rescue gate, after structural and retrieval-feedback checks.
        """
        if self.rank2_rescue_mode == "off" or not self.rank2_rescue.is_ready():
            item["rank2_rescue"] = {
                "enabled": False,
                "mode": self.rank2_rescue_mode,
                "model_ready": self.rank2_rescue.is_ready(),
            }
            return "disabled"
        rescue = self.rank2_rescue.score(query_plan_log, item)
        score = self._safe_float(rescue.get("score"), 0.0)
        decision = "candidate" if score >= self.rank2_rescue_min_score else "keep"
        rescue.update({
            "enabled": True,
            "mode": self.rank2_rescue_mode,
            "min_score": self.rank2_rescue_min_score,
            "min_confidence": self.rank2_rescue_min_confidence,
            "max_original_rank": self.rank2_rescue_max_original_rank,
            "min_source_precision": self.rank2_rescue_min_source_precision,
            "min_selected_precision": self.rank2_rescue_min_selected_precision,
            "require_terminal_or_strict": self.rank2_rescue_require_terminal_or_strict,
            "max_swaps": self.rank2_rescue_max_swaps,
            "decision": decision,
        })
        item["rank2_rescue"] = rescue
        return decision

    def _rank2_rescue_source_score(self, source_policy: Mapping[str, Any]) -> float:
        return max(
            self._safe_float(source_policy.get("selected_precision"), 0.0),
            self._safe_float(source_policy.get("precision"), 0.0),
            self._safe_float(source_policy.get("gt5_precision"), 0.0),
        )

    def _rank2_rescue_sort_score(self, item: Mapping[str, Any]) -> float:
        if self.rank2_rescue_mode == "rescue":
            return self._safe_float((item.get("rank2_rescue", {}) or {}).get("score"), 0.0)
        if self.rank2_rescue_mode != "high_confidence":
            return 0.0
        source_score = self._rank2_rescue_source_score(item.get("source_policy", {}) or {})
        structural_bonus = 0.0
        if bool(item.get("has_terminal")):
            structural_bonus += 0.06
        if bool(item.get("has_strict")):
            structural_bonus += 0.05
        if bool(item.get("has_multihop")):
            structural_bonus += 0.04
        rank_bonus = 0.03 if int(item.get("original_rank", 10**9) or 10**9) <= 20 else 0.0
        return (
            self._safe_float(item.get("confidence"), 0.0)
            + 0.35 * source_score
            + min(structural_bonus, 0.10)
            + rank_bonus
        )

    def _is_rank2_rescue_candidate(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, str, Dict[str, Any]]:
        score = self._safe_float((item.get("rank2_rescue", {}) or {}).get("score"), 0.0)
        confidence = self._safe_float(item.get("confidence"), 0.0)
        original_rank = int(item.get("original_rank", 10**9) or 10**9)
        source_policy = item.get("source_policy", {}) or {}
        source_score = self._rank2_rescue_source_score(source_policy)
        features = self._intervention_features(item, query_plan_log)
        terminal_or_strict = (
            bool(item.get("has_terminal"))
            or bool(item.get("has_strict"))
            or bool(item.get("has_multihop"))
            or bool(features.get("has_endpoint_pair"))
            or bool(features.get("has_terminal_relation"))
            or bool(features.get("has_path_seed"))
        )
        source_grounded = (
            bool(source_policy.get("approved"))
            or bool(source_policy.get("is_evidence_grounded"))
        )
        selected_precision = self._safe_float(source_policy.get("selected_precision"), 0.0)
        checks = {
            "score": round(float(score), 6),
            "confidence": round(float(confidence), 6),
            "original_rank": int(original_rank),
            "source_score": round(float(source_score), 6),
            "selected_precision": round(float(selected_precision), 6),
            "source_grounded": bool(source_grounded),
            "terminal_or_strict": bool(terminal_or_strict),
            "relation_only": bool(features.get("relation_only")),
        }
        if self.rank2_rescue_mode == "off" or not self.rank2_rescue.is_ready():
            return False, "rank2_rescue_disabled", checks
        if self.rank2_rescue_mode != "high_confidence" and score < self.rank2_rescue_min_score:
            return False, "rank2_rescue_low_score", checks
        if confidence < self.rank2_rescue_min_confidence:
            return False, "rank2_rescue_low_confidence", checks
        if self.rank2_rescue_max_original_rank > 0 and original_rank > self.rank2_rescue_max_original_rank:
            return False, "rank2_rescue_rank_too_low", checks
        if not source_grounded:
            return False, "rank2_rescue_not_source_grounded", checks
        if source_score < self.rank2_rescue_min_source_precision:
            return False, "rank2_rescue_low_source_precision", checks
        if selected_precision < self.rank2_rescue_min_selected_precision:
            return False, "rank2_rescue_low_selected_precision", checks
        if self.rank2_rescue_require_terminal_or_strict and not terminal_or_strict:
            return False, "rank2_rescue_weak_structure", checks
        if bool(features.get("relation_only")):
            return False, "rank2_rescue_relation_only", checks
        return True, "rank2_rescue_approved", checks

    def _all_candidate_contexts(self, item: Mapping[str, Any]) -> List[Mapping[str, Any]]:
        contexts = item.get("_all_contexts", None)
        if contexts is None:
            contexts = item.get("contexts", []) or []
        return [context for context in contexts if isinstance(context, Mapping)]

    def _schema_slot_contexts(self, item: Mapping[str, Any]) -> List[Mapping[str, Any]]:
        contexts = self._all_candidate_contexts(item)
        return [
            context for context in contexts
            if bool(context.get("schema_slot_recall"))
            or str(context.get("schema_route_source", "") or "").lower() == "schema_slot_recall"
            or str(context.get("support_key", "") or "").startswith("schema_slot_recall::")
        ]

    def _schema_slot_context_is_schema_only(self, item: Mapping[str, Any]) -> bool:
        contexts = self._all_candidate_contexts(item)
        schema_slot_contexts = self._schema_slot_contexts(item)
        if not schema_slot_contexts:
            return False
        return len(schema_slot_contexts) >= len(contexts)

    def _score_schema_slot_utility(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        schema_contexts = self._schema_slot_contexts(item)
        if not schema_contexts:
            return {
                "enabled": self.enable_schema_slot_utility,
                "has_schema_slot": False,
                "score": 0.0,
                "approved": False,
                "top2_approved": False,
                "reason": "no_schema_slot_context",
            }

        features = self._intervention_features(item, query_plan_log)
        source_policy = item.get("source_policy", {}) or {}
        confidence = self._safe_float(item.get("confidence"), 0.0)
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        plan_precision = max(
            (self._safe_float(context.get("plan_effective_precision"), 0.0) for context in schema_contexts),
            default=0.0,
        )
        source_record = self._recall_plan_default_source_record("schema_slot_recall")
        source_precision = max(
            plan_precision,
            self._safe_float(source_policy.get("precision"), 0.0),
            self._safe_float(source_policy.get("selected_precision"), 0.0),
            self._safe_float(source_policy.get("gt5_precision"), 0.0),
            self._safe_float(source_record.get("selected_precision"), 0.0),
        )
        relation_count = max(
            (len(context.get("relations", []) or []) for context in schema_contexts),
            default=0,
        )
        modes = [
            str(context.get("signature_match_mode", "") or "").lower()
            for context in schema_contexts
        ]
        has_slot_probe = any("slot" in mode or "bridge" in mode for mode in modes)
        has_original_probe = any("original" in mode for mode in modes)
        text_score = self._safe_float((item.get("text_verifier", {}) or {}).get("score"), 0.0)
        path_score = self._safe_float((item.get("path_aware", {}) or {}).get("score"), 0.0)
        score = 0.22 * confidence + 0.18 * source_precision
        score += 0.08 * min(len(schema_contexts) / 2.0, 1.0)
        if bool(features.get("has_anchor_relation")):
            score += 0.13
        if bool(features.get("has_terminal_relation")):
            score += 0.15
        if bool(features.get("has_endpoint_pair")):
            score += 0.13
        if bool(features.get("has_path_seed")) or bool(features.get("has_path_neighbor")):
            score += 0.08
        if bool(item.get("has_multihop")):
            score += 0.08
        if bool(item.get("has_strict")):
            score += 0.05
        if bool(item.get("has_relation")) and relation_count > 0:
            score += 0.05
        if self._safe_float(item.get("coverage_gain"), 0.0) > 0.0:
            score += 0.06
        if self._safe_int(item.get("decomposition_slot_gain"), 0) > 0:
            score += 0.04
        if has_slot_probe:
            score += 0.06
        if has_original_probe:
            score -= 0.03
        if bool(source_policy.get("approved")):
            score += 0.05
        if text_score > 0.0:
            score += 0.08 * min(text_score, 1.0)
        if path_score > 0.0:
            score += 0.06 * min(path_score, 1.0)
        if original_rank <= 20:
            score += 0.05
        elif original_rank <= 80:
            score += 0.02
        if bool(features.get("relation_only")):
            score -= 0.18
        if not bool(features.get("has_anchor")) and not bool(features.get("has_terminal")):
            score -= 0.08
        if not bool(item.get("has_relation")):
            score -= 0.07

        score = min(max(float(score), 0.0), 1.0)
        structural_ok = (
            bool(features.get("has_anchor_relation"))
            or bool(features.get("has_terminal_relation"))
            or bool(features.get("has_endpoint_pair"))
            or bool(features.get("has_path_seed"))
            or bool(features.get("has_path_neighbor"))
            or bool(item.get("has_multihop"))
            or bool(item.get("has_strict"))
        )
        top2_structure_ok = (
            bool(features.get("has_terminal_relation"))
            or bool(features.get("has_endpoint_pair"))
            or bool(item.get("has_multihop"))
            or bool(item.get("has_strict"))
            or (bool(features.get("has_anchor_relation")) and text_score >= 0.45)
        )
        rank_ok = self.top2_max_original_rank <= 0 or original_rank <= self.top2_max_original_rank
        approved = (
            score >= self.schema_slot_utility_min_score
            and structural_ok
            and bool(item.get("has_relation") or features.get("has_terminal") or features.get("has_anchor"))
            and not bool(features.get("relation_only"))
        )
        top2_approved = (
            approved
            and score >= self.schema_slot_utility_top2_min_score
            and top2_structure_ok
            and rank_ok
        )
        reason = "approved" if approved else "low_utility"
        if bool(features.get("relation_only")):
            reason = "relation_only"
        elif not structural_ok:
            reason = "weak_structure"
        elif score < self.schema_slot_utility_min_score:
            reason = "low_score"
        elif not rank_ok and score >= self.schema_slot_utility_top2_min_score:
            reason = "top2_rank_too_low"
        return {
            "enabled": self.enable_schema_slot_utility,
            "has_schema_slot": True,
            "score": round(float(score), 6),
            "approved": bool(approved),
            "top2_approved": bool(top2_approved),
            "reason": reason,
            "min_score": self.schema_slot_utility_min_score,
            "top2_min_score": self.schema_slot_utility_top2_min_score,
            "confidence": round(float(confidence), 6),
            "plan_precision": round(float(plan_precision), 6),
            "source_precision": round(float(source_precision), 6),
            "text_score": round(float(text_score), 6),
            "path_score": round(float(path_score), 6),
            "schema_context_count": int(len(schema_contexts)),
            "relation_count": int(relation_count),
            "schema_only": bool(self._schema_slot_context_is_schema_only(item)),
            "structural_ok": bool(structural_ok),
            "top2_structure_ok": bool(top2_structure_ok),
            "rank_ok": bool(rank_ok),
            "features": {
                "has_anchor": bool(features.get("has_anchor")),
                "has_terminal": bool(features.get("has_terminal")),
                "has_anchor_relation": bool(features.get("has_anchor_relation")),
                "has_terminal_relation": bool(features.get("has_terminal_relation")),
                "has_endpoint_pair": bool(features.get("has_endpoint_pair")),
                "has_path_seed": bool(features.get("has_path_seed")),
                "has_path_neighbor": bool(features.get("has_path_neighbor")),
                "relation_only": bool(features.get("relation_only")),
            },
            "modes": sorted(set(modes))[:8],
        }

    def _apply_schema_slot_utility(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, str]:
        if not self.enable_schema_slot_utility:
            item["schema_slot_utility"] = {
                "enabled": False,
                "has_schema_slot": bool(self._schema_slot_contexts(item)),
                "reason": "disabled",
                "score": 0.0,
                "approved": False,
                "top2_approved": False,
            }
            return True, "disabled"

        utility = self._score_schema_slot_utility(item, query_plan_log)
        item["schema_slot_utility"] = utility
        if not bool(utility.get("has_schema_slot", False)):
            return True, "no_schema_slot_context"

        if not bool(utility.get("approved", False)):
            if bool(utility.get("schema_only", False)):
                return False, str(utility.get("reason") or "low_utility")
            return True, str(utility.get("reason") or "weak_mixed_source")

        score = self._safe_float(utility.get("score"), 0.0)
        item["score"] = self._safe_float(item.get("score"), 0.0) + self.schema_slot_utility_score_weight * score
        item["confidence"] = min(
            0.99,
            max(
                self._safe_float(item.get("confidence"), 0.0),
                min(0.95, score),
            ),
        )
        item["effective_min_confidence"] = min(
            self._safe_float(item.get("effective_min_confidence"), self.min_candidate_confidence),
            max(0.55, min(self.min_candidate_confidence, score)),
        )
        return True, "approved"

    def _provenance_groupwise_score(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Cost/provenance-aware utility for safe top-5 evidence repair.

        This listwise score rewards reliable provenance, passage text support,
        and coverage complementarity, while penalizing relation-only and
        schema-only noise.
        """
        source_signature = self._candidate_source_signature(item)
        source_record = self._recall_plan_source_record(source_signature)
        source_policy = item.get("source_policy", {}) or {}
        if not isinstance(source_policy, Mapping):
            source_policy = {}
        features = self._intervention_features(item, query_plan_log)
        text_info = item.get("text_verifier", {}) or {}
        if not isinstance(text_info, Mapping):
            text_info = {}
        path_info = item.get("path_aware", {}) or {}
        if not isinstance(path_info, Mapping):
            path_info = {}

        source_precision = max(
            self._safe_float(source_record.get("precision"), 0.0),
            self._safe_float(source_record.get("selected_precision"), 0.0),
            self._safe_float(source_policy.get("selected_precision"), 0.0),
            self._safe_float(source_policy.get("precision"), 0.0),
            2.0 * self._safe_float(source_policy.get("gt5_precision"), 0.0),
        )
        source_precision = min(max(source_precision, 0.0), 1.0)
        recall_yield = min(max(self._safe_float(source_record.get("recall_yield"), 0.0), 0.0), 1.0)
        cost = min(max(self._safe_float(source_record.get("cost"), 0.50), 0.02), 1.0)
        confidence = self._safe_float(item.get("confidence"), 0.0)
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        rank_cost = 0.0
        if self.candidate_pool_top_k > 0:
            rank_cost = min(float(original_rank) / float(max(self.candidate_pool_top_k, 1)), 1.0)

        text_score = self._safe_float(text_info.get("score"), 0.0)
        anchor_hits = self._safe_int(text_info.get("anchor_hits"), 0)
        terminal_hits = self._safe_int(text_info.get("terminal_hits"), 0)
        relation_hits = len(text_info.get("relation_overlap", []) or [])
        answer_hits = len(text_info.get("answer_overlap", []) or [])
        text_signal = (
            text_score >= 0.45
            or (anchor_hits > 0 and relation_hits > 0)
            or (terminal_hits > 0 and relation_hits > 0)
            or answer_hits > 0
        )

        structural_score = 0.0
        if bool(features.get("has_endpoint_pair")):
            structural_score += 0.12
        if bool(features.get("has_terminal_relation")):
            structural_score += 0.12
        if bool(features.get("has_anchor_relation")):
            structural_score += 0.08
        if bool(features.get("has_path_seed")) or bool(features.get("has_path_neighbor")):
            structural_score += 0.08
        if bool(item.get("has_multihop")):
            structural_score += 0.08
        if bool(item.get("has_strict")):
            structural_score += 0.06
        if bool(path_info.get("approved", False)):
            structural_score += 0.08

        coverage_gain = self._safe_float(item.get("coverage_gain"), 0.0)
        decomposition_gain = float(self._safe_int(item.get("decomposition_slot_gain"), 0))
        novelty = min(0.16, 0.05 * coverage_gain + 0.04 * decomposition_gain)
        if bool(item.get("_recall_plan_optimizer_no_new_slot_bypass", False)):
            novelty += 0.02

        schema_only = bool(self._schema_slot_context_is_schema_only(item))
        source_bonus = 0.0
        if "path_executor" in source_signature:
            source_bonus += 0.06
        if "evidence_grounded" in source_signature:
            source_bonus += 0.05
        if "schema_slot_recall" in source_signature:
            source_bonus += 0.02
        if "support" in source_signature and not text_signal:
            source_bonus -= 0.04

        score = (
            0.22 * confidence
            + 0.24 * source_precision
            + 0.12 * recall_yield
            + 0.18 * min(text_score, 1.0)
            + min(structural_score, 0.22)
            + novelty
            + source_bonus
            - 0.08 * cost
            - 0.06 * rank_cost
        )
        if schema_only and not text_signal:
            score -= 0.12
        if bool(features.get("relation_only")):
            score -= 0.14
        if self.provenance_groupwise_require_text_signal and not text_signal:
            score -= 0.05
        score = min(max(float(score), 0.0), 1.0)

        strong_structure = (
            bool(features.get("has_endpoint_pair"))
            or bool(features.get("has_terminal_relation"))
            or bool(features.get("has_path_seed"))
            or bool(item.get("has_multihop"))
            or bool(item.get("has_strict"))
            or bool(path_info.get("approved", False))
        )
        enough_source = source_precision >= self.provenance_groupwise_min_source_precision or strong_structure
        enough_text = text_signal or not self.provenance_groupwise_require_text_signal or strong_structure
        approved = (
            score >= self.provenance_groupwise_min_score
            and enough_source
            and enough_text
            and not bool(features.get("relation_only"))
        )
        top2_approved = (
            approved
            and score >= self.provenance_groupwise_top2_min_score
            and strong_structure
            and text_signal
            and source_precision >= max(0.10, self.provenance_groupwise_min_source_precision)
            and (self.top2_max_original_rank <= 0 or original_rank <= self.top2_max_original_rank)
        )
        reason = "approved" if approved else "low_score"
        if not enough_source:
            reason = "low_source_precision"
        elif not enough_text:
            reason = "weak_text_signal"
        elif bool(features.get("relation_only")):
            reason = "relation_only"
        elif score < self.provenance_groupwise_min_score:
            reason = "low_score"
        return {
            "enabled": self.enable_provenance_groupwise_selector,
            "score": round(float(score), 6),
            "approved": bool(approved),
            "top2_approved": bool(top2_approved),
            "reason": reason,
            "source_signature": source_signature,
            "source_precision": round(float(source_precision), 6),
            "recall_yield": round(float(recall_yield), 6),
            "cost": round(float(cost), 6),
            "rank_cost": round(float(rank_cost), 6),
            "confidence": round(float(confidence), 6),
            "text_score": round(float(text_score), 6),
            "text_signal": bool(text_signal),
            "anchor_hits": int(anchor_hits),
            "terminal_hits": int(terminal_hits),
            "relation_hits": int(relation_hits),
            "answer_hits": int(answer_hits),
            "coverage_gain": round(float(coverage_gain), 6),
            "decomposition_gain": int(decomposition_gain),
            "schema_only": bool(schema_only),
            "strong_structure": bool(strong_structure),
            "features": {
                "has_anchor_relation": bool(features.get("has_anchor_relation")),
                "has_terminal_relation": bool(features.get("has_terminal_relation")),
                "has_endpoint_pair": bool(features.get("has_endpoint_pair")),
                "has_path_seed": bool(features.get("has_path_seed")),
                "has_path_neighbor": bool(features.get("has_path_neighbor")),
                "relation_only": bool(features.get("relation_only")),
            },
        }

    def _apply_provenance_groupwise_selector(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> str:
        if not self.enable_provenance_groupwise_selector:
            item["provenance_groupwise"] = {
                "enabled": False,
                "score": 0.0,
                "approved": False,
                "top2_approved": False,
                "reason": "disabled",
            }
            return "disabled"
        info = self._provenance_groupwise_score(item, query_plan_log)
        item["provenance_groupwise"] = info
        if bool(info.get("approved", False)):
            score = self._safe_float(info.get("score"), 0.0)
            item["_provenance_groupwise_candidate"] = True
            item["score"] = self._safe_float(item.get("score"), 0.0) + self.provenance_groupwise_score_weight * score
            item["confidence"] = min(
                0.99,
                max(
                    self._safe_float(item.get("confidence"), 0.0),
                    self._safe_float(item.get("confidence"), 0.0) + 0.04 * score,
                ),
            )
            item["effective_min_confidence"] = min(
                self._safe_float(item.get("effective_min_confidence"), self.min_candidate_confidence),
                max(0.54, self.min_candidate_confidence - 0.05 * score),
            )
        return str(info.get("reason") or "scored")

    def _provenance_groupwise_direct_signal_enabled(self) -> bool:
        """Whether provenance/groupwise is allowed to directly affect ranking.

        The scorer itself is still useful as a feature provider. Direct use must
        be explicit, otherwise a zero-weight configuration can still perturb the
        first candidate sort through its raw score.
        """
        if not self.enable_provenance_groupwise_selector:
            return False
        return bool(
            self.provenance_groupwise_score_weight > 0.0
            or self.provenance_groupwise_max_top5_swaps > 0
            or self.provenance_groupwise_max_top2_swaps > 0
            or self.utility_planner_mode == "groupwise_top5_planner"
        )

    def _query_is_evidence_complex(self, query_plan_log: Mapping[str, Any]) -> bool:
        condition = query_plan_log.get("query_condition", {}) or {}
        relation_terms: List[str] = []
        relation_signatures: List[str] = []
        relation_families: List[str] = []
        if isinstance(condition, Mapping):
            relation_terms = [self._norm(item) for item in (condition.get("relation_terms", []) or []) if self._norm(item)]
            relation_signatures = [
                self._norm(item)
                for item in (condition.get("relation_signatures", []) or [])
                if self._norm(item)
            ]
            relation_families = [
                self._norm(item)
                for item in (condition.get("relation_families", []) or [])
                if self._norm(item)
            ]
        if len(set(relation_terms + relation_signatures + relation_families)) >= 2:
            return True
        if int(query_plan_log.get("matched_plan_count", 0) or 0) >= 2:
            return True
        if int(query_plan_log.get("executable_path_count", 0) or 0) >= 2:
            return True
        query = self._norm(query_plan_log.get("query"))
        complex_markers = (
            "which",
            "whose",
            "where",
            "when",
            "first",
            "last",
            "before",
            "after",
            "later",
            "earlier",
            "larger",
            "smaller",
            "more",
            "less",
            "same",
            "director",
            "record label",
            "headquarters",
            "located",
            "born",
        )
        return sum(1 for marker in complex_markers if marker in query) >= 2

    def _evidence_set_optimizer_value(self, item: Mapping[str, Any]) -> float:
        value = self._candidate_evidence_value(item)
        path_info = item.get("path_aware", {}) or {}
        source_policy = item.get("source_policy", {}) or {}
        if bool(path_info.get("approved")):
            value += 0.08 * self._safe_float(path_info.get("score"), 0.0)
        if self._safe_float(source_policy.get("gt5_precision"), 0.0) >= 0.25:
            value += 0.04
        if bool(source_policy.get("approved")) or bool(source_policy.get("is_evidence_grounded")):
            value += 0.03
        return min(max(value, 0.0), 1.08)

    def _passes_evidence_set_optimizer_candidate(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
        selected: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
    ) -> Tuple[bool, str, Dict[str, Any]]:
        source_policy = item.get("source_policy", {}) or {}
        path_info = item.get("path_aware", {}) or {}
        features = self._intervention_features(item, query_plan_log)
        confidence = self._safe_float(item.get("confidence"), 0.0)
        original_rank = int(item.get("original_rank", 10**9) or 10**9)
        source_score = self._rank2_rescue_source_score(source_policy)
        path_approved = bool(path_info.get("approved", False))
        path_score = self._safe_float(path_info.get("score"), 0.0)
        terminal_or_strict = (
            bool(item.get("has_terminal"))
            or bool(item.get("has_strict"))
            or bool(item.get("has_multihop"))
            or bool(features.get("has_endpoint_pair"))
            or bool(features.get("has_terminal_relation"))
            or bool(features.get("has_path_seed"))
        )
        source_grounded = bool(source_policy.get("approved")) or bool(source_policy.get("is_evidence_grounded"))
        complex_query = self._query_is_evidence_complex(query_plan_log)
        candidate_value = self._evidence_set_optimizer_value(item)
        replacement_doc = int(selected[1]) if len(selected) >= 2 else -1
        replacement_rank = int(original_rank_by_doc.get(replacement_doc, 2))
        replacement_value = self._baseline_replacement_value(
            replacement_doc,
            replacement_rank,
            passage_details,
            max_raw_score,
        ) if replacement_doc >= 0 else 0.0
        margin = candidate_value - replacement_value
        checks = {
            "mode": self.evidence_set_optimizer_mode,
            "confidence": round(float(confidence), 6),
            "original_rank": int(original_rank),
            "source_score": round(float(source_score), 6),
            "source_grounded": bool(source_grounded),
            "path_approved": bool(path_approved),
            "path_score": round(float(path_score), 6),
            "terminal_or_strict": bool(terminal_or_strict),
            "relation_only": bool(features.get("relation_only")),
            "complex_query": bool(complex_query),
            "candidate_value": round(float(candidate_value), 6),
            "replacement_doc": int(replacement_doc),
            "replacement_rank": int(replacement_rank),
            "replacement_value": round(float(replacement_value), 6),
            "margin": round(float(margin), 6),
            "rank2_margin": round(float(self.evidence_set_optimizer_rank2_margin), 6),
        }
        if self.evidence_set_optimizer_mode != "top2" or self.evidence_set_optimizer_max_swaps <= 0:
            return False, "optimizer_disabled", checks
        if len(selected) < 2:
            return False, "optimizer_no_rank2", checks
        if confidence < self.evidence_set_optimizer_min_confidence:
            return False, "optimizer_low_confidence", checks
        if self.evidence_set_optimizer_max_original_rank > 0 and original_rank > self.evidence_set_optimizer_max_original_rank:
            return False, "optimizer_rank_too_low", checks
        source_ok = source_score >= self.evidence_set_optimizer_min_source_precision
        path_source_ok = path_approved and source_score >= self.evidence_set_optimizer_min_path_source_precision
        if not source_grounded and not path_approved:
            return False, "optimizer_not_source_or_path_grounded", checks
        if not (source_ok or path_source_ok):
            return False, "optimizer_low_source_precision", checks
        if not terminal_or_strict:
            return False, "optimizer_weak_structure", checks
        if bool(features.get("relation_only")):
            return False, "optimizer_relation_only", checks
        if self.evidence_set_optimizer_require_complex_or_path and not (
            complex_query
            or path_approved
            or bool(item.get("has_multihop"))
            or bool(item.get("has_strict"))
        ):
            return False, "optimizer_simple_query", checks
        if margin < self.evidence_set_optimizer_rank2_margin:
            return False, "optimizer_low_margin", checks
        return True, "optimizer_approved", checks

    def _apply_evidence_set_optimizer(
        self,
        selected: List[int],
        selected_set: Set[int],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        rejections: Counter,
        rejected_candidates: List[Dict[str, Any]],
        selected_candidates: List[Dict[str, Any]],
    ) -> int:
        if self.evidence_set_optimizer_mode != "top2" or self.evidence_set_optimizer_max_swaps <= 0:
            return 0
        if len(selected) < 2 or not selected_ontology:
            return 0

        swaps = 0
        candidates = sorted(
            selected_ontology,
            key=lambda item: (
                self._evidence_set_optimizer_value(item),
                self._safe_float(item.get("confidence"), 0.0),
                -int(item.get("original_rank", 10**9) or 10**9),
            ),
            reverse=True,
        )
        for item in candidates:
            if swaps >= self.evidence_set_optimizer_max_swaps:
                break
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0:
                continue
            if selected and int(selected[0]) == candidate_doc:
                continue
            if len(selected) >= 2 and int(selected[1]) == candidate_doc:
                continue
            approved, reason, features = self._passes_evidence_set_optimizer_candidate(
                item=item,
                query_plan_log=query_plan_log,
                selected=selected,
                original_rank_by_doc=original_rank_by_doc,
                passage_details=passage_details,
                max_raw_score=max_raw_score,
            )
            item["evidence_set_optimizer"] = {
                "approved": bool(approved),
                "reason": reason,
                "features": features,
            }
            if not approved:
                rejections[reason] += 1
                if len(rejected_candidates) < 12 and reason not in {"optimizer_low_confidence", "optimizer_low_margin"}:
                    rejected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=False,
                            reason=f"optimizer_rejected:{reason}",
                        )
                    )
                continue

            replaced_doc = int(selected[1])
            selected[:] = [int(doc_id) for doc_id in selected if int(doc_id) != candidate_doc]
            selected_set.discard(candidate_doc)
            if len(selected) < 2:
                selected.append(replaced_doc)
            replaced_doc = int(selected[1])
            selected[1] = candidate_doc
            selected_set.discard(replaced_doc)
            selected_set.add(candidate_doc)
            item["_evidence_set_optimizer_selected"] = True
            item["_evidence_set_optimizer_replaced_doc"] = replaced_doc
            swaps += 1
            if len(selected_candidates) < 12:
                selected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason="evidence_set_optimizer_selected",
                        final_rank=2,
                    )
                )
        return swaps

    def _rank2_replacement_info(
        self,
        selected: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
    ) -> Dict[str, Any]:
        if len(selected) < 2:
            return {
                "doc_id": None,
                "rank": 2,
                "value": 0.0,
                "confidence": 0.0,
                "score": 0.0,
            }
        doc_id = int(selected[1])
        original_rank = int(original_rank_by_doc.get(doc_id, 2))
        value = self._baseline_replacement_value(
            doc_id,
            original_rank,
            passage_details,
            max_raw_score,
        )
        detail = passage_details.get(doc_id)
        confidence = self._candidate_confidence(detail, max_raw_score) if detail else value
        return {
            "doc_id": doc_id,
            "rank": original_rank,
            "value": float(value),
            "confidence": float(confidence),
            "score": float(value),
        }

    def _apply_rank2_pairwise_optimizer(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        rejections: Counter,
        rejected_candidates: List[Dict[str, Any]],
        selected_candidates: List[Dict[str, Any]],
    ) -> int:
        if (
            self.rank2_pairwise_optimizer_mode != "top2"
            or self.rank2_pairwise_optimizer_max_swaps <= 0
            or not self.rank2_pairwise_optimizer.is_ready()
        ):
            return 0
        if len(selected) < 2 or not candidates:
            return 0

        scored: List[Tuple[float, Dict[str, Any]]] = []
        replacement_info = self._rank2_replacement_info(
            selected=selected,
            original_rank_by_doc=original_rank_by_doc,
            passage_details=passage_details,
            max_raw_score=max_raw_score,
        )
        for item in candidates:
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0:
                continue
            if selected and int(selected[0]) == candidate_doc:
                continue
            if len(selected) >= 2 and int(selected[1]) == candidate_doc:
                continue
            original_rank = int(item.get("original_rank", 10**9) or 10**9)
            confidence = self._safe_float(item.get("confidence"), 0.0)
            result = self.rank2_pairwise_optimizer.score(query_plan_log, item, replacement_info)
            score = self._safe_float(result.get("score"), 0.0)
            feature_snapshot = result.get("feature_snapshot", {}) or {}
            if not isinstance(feature_snapshot, Mapping):
                feature_snapshot = {}
            candidate_value = self._safe_float(
                feature_snapshot.get("candidate_value"),
                self._evidence_set_optimizer_value(item),
            )
            replacement_value = self._safe_float(
                feature_snapshot.get("replacement_value"),
                self._safe_float(replacement_info.get("value"), 0.0),
            )
            value_margin = self._safe_float(
                feature_snapshot.get("value_margin"),
                candidate_value - replacement_value,
            )
            path_info = item.get("path_aware", {}) or {}
            if not isinstance(path_info, Mapping):
                path_info = {}
            intervention_features = self._intervention_features(item, query_plan_log)
            complex_query = self._query_is_evidence_complex(query_plan_log)
            path_approved = bool(path_info.get("approved", False))
            terminal_or_strict = (
                bool(item.get("has_terminal"))
                or bool(item.get("has_strict"))
                or bool(item.get("has_multihop"))
                or bool(intervention_features.get("has_endpoint_pair"))
                or bool(intervention_features.get("has_terminal_relation"))
                or bool(intervention_features.get("has_path_seed"))
            )
            relation_only = bool(intervention_features.get("relation_only"))
            structural_override = bool(path_approved and terminal_or_strict and not relation_only)
            min_margin_active = self.rank2_pairwise_optimizer_min_value_margin > -0.999
            path_margin_active = self.rank2_pairwise_optimizer_path_override_min_value_margin > -0.999
            normal_margin_ok = (
                not min_margin_active
                or value_margin >= self.rank2_pairwise_optimizer_min_value_margin
            )
            path_margin_ok = (
                path_margin_active
                and structural_override
                and value_margin >= self.rank2_pairwise_optimizer_path_override_min_value_margin
            )
            margin_ok = normal_margin_ok or path_margin_ok
            scope_ok = (
                not self.rank2_pairwise_optimizer_require_complex_or_path
                or complex_query
                or structural_override
                or bool(item.get("has_multihop"))
                or bool(item.get("has_strict"))
            )
            cost_guard = {
                "candidate_value": round(float(candidate_value), 6),
                "replacement_value": round(float(replacement_value), 6),
                "value_margin": round(float(value_margin), 6),
                "min_value_margin": round(float(self.rank2_pairwise_optimizer_min_value_margin), 6),
                "path_override_min_value_margin": round(
                    float(self.rank2_pairwise_optimizer_path_override_min_value_margin),
                    6,
                ),
                "normal_margin_ok": bool(normal_margin_ok),
                "path_margin_ok": bool(path_margin_ok),
                "margin_ok": bool(margin_ok),
                "complex_query": bool(complex_query),
                "path_approved": bool(path_approved),
                "terminal_or_strict": bool(terminal_or_strict),
                "relation_only": bool(relation_only),
                "structural_override": bool(structural_override),
                "scope_ok": bool(scope_ok),
                "require_complex_or_path": bool(self.rank2_pairwise_optimizer_require_complex_or_path),
            }
            reason = "rank2_pairwise_approved"
            approved = True
            if original_rank <= 2:
                approved = False
                reason = "rank2_pairwise_already_top2"
            elif (
                self.rank2_pairwise_optimizer_max_original_rank > 0
                and original_rank > self.rank2_pairwise_optimizer_max_original_rank
            ):
                approved = False
                reason = "rank2_pairwise_rank_too_low"
            elif confidence < self.rank2_pairwise_optimizer_min_confidence:
                approved = False
                reason = "rank2_pairwise_low_confidence"
            elif score < self.rank2_pairwise_optimizer_min_score:
                approved = False
                reason = "rank2_pairwise_low_score"
            elif not scope_ok:
                approved = False
                reason = "rank2_pairwise_simple_query_scope"
            elif not margin_ok:
                approved = False
                reason = "rank2_pairwise_low_value_margin"
            result.update({
                "mode": self.rank2_pairwise_optimizer_mode,
                "approved": bool(approved),
                "reason": reason,
                "min_score": self.rank2_pairwise_optimizer_min_score,
                "min_confidence": self.rank2_pairwise_optimizer_min_confidence,
                "max_original_rank": self.rank2_pairwise_optimizer_max_original_rank,
                "max_swaps": self.rank2_pairwise_optimizer_max_swaps,
                "cost_guard": cost_guard,
                "replacement_info": replacement_info,
            })
            item["rank2_pairwise_optimizer"] = result
            if approved:
                scored.append((score, item))
            else:
                rejections[reason] += 1
                if len(rejected_candidates) < 12 and reason not in {"rank2_pairwise_low_score"}:
                    rejected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=False,
                            reason=f"rank2_pairwise_rejected:{reason}",
                        )
                    )

        if not scored:
            return 0
        scored.sort(
            key=lambda pair: (
                pair[0],
                self._safe_float(pair[1].get("confidence"), 0.0),
                -int(pair[1].get("original_rank", 10**9) or 10**9),
            ),
            reverse=True,
        )
        swaps = 0
        for _, item in scored:
            if swaps >= self.rank2_pairwise_optimizer_max_swaps:
                break
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0:
                continue
            if selected and int(selected[0]) == candidate_doc:
                continue
            if len(selected) < 2 or int(selected[1]) == candidate_doc:
                continue
            replaced_doc = int(selected[1])
            selected[:] = [int(doc_id) for doc_id in selected if int(doc_id) != candidate_doc]
            selected_set.discard(candidate_doc)
            if len(selected) < 2:
                selected.append(replaced_doc)
            selected[1] = candidate_doc
            selected_set.discard(replaced_doc)
            selected_set.add(candidate_doc)
            item["_rank2_pairwise_optimizer_selected"] = True
            item["_rank2_pairwise_optimizer_replaced_doc"] = replaced_doc
            if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                selected_ontology.append(item)
            swaps += 1
            if len(selected_candidates) < 12:
                selected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason="rank2_pairwise_selected",
                        final_rank=2,
                    )
                )
        return swaps

    def _utility_policy_scope_applies(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, str]:
        scope = self.utility_policy_apply_scope
        if scope == "all":
            return True, "all"

        recall_info = item.get("recall_selector", {}) or {}
        recall_score = self._safe_float(recall_info.get("score"), 0.0)
        recall_promoted = (
            str(recall_info.get("decision", "") or "") == "promote"
            or recall_score >= self.recall_selector_min_score
        )
        source_policy = item.get("source_policy", {}) or {}
        features = self._intervention_features(item, query_plan_log)
        backbone_candidate = self._is_backbone_candidate(item, features, source_policy)

        if scope == "recall_selector":
            return recall_promoted, "recall_selector" if recall_promoted else "not_recall_selected"
        if scope == "recall_only":
            if not recall_promoted:
                return False, "not_recall_selected"
            if backbone_candidate:
                return False, "backbone_candidate"
            return True, "recall_only"
        if scope == "weak_only":
            return (not backbone_candidate), "weak_only" if not backbone_candidate else "backbone_candidate"
        return True, "all"

    def _apply_utility_policy(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, str]:
        """Learned gate for whether an ontology candidate should alter top-k.

        The recall selector intentionally over-generates candidates. This
        policy is trained on intervention utility, including hard negatives
        from candidates that looked ontology-relevant but hurt the final top-5.
        """
        if self.utility_policy_mode == "off" or not self.utility_policy.is_ready():
            item["utility_policy"] = {
                "enabled": False,
                "mode": self.utility_policy_mode,
                "model_ready": self.utility_policy.is_ready(),
            }
            return True, "disabled"

        scope_applies, scope_reason = self._utility_policy_scope_applies(item, query_plan_log)
        if not scope_applies:
            item["utility_policy"] = {
                "enabled": False,
                "mode": self.utility_policy_mode,
                "model_ready": self.utility_policy.is_ready(),
                "apply_scope": self.utility_policy_apply_scope,
                "scope_reason": scope_reason,
            }
            return True, f"scope_skipped:{scope_reason}"

        policy = self.utility_policy.score(query_plan_log, item)
        score = self._safe_float(policy.get("score"), 0.0)
        decision = "keep"
        policy.update({
            "enabled": True,
            "mode": self.utility_policy_mode,
            "apply_scope": self.utility_policy_apply_scope,
            "scope_reason": scope_reason,
            "min_score": self.utility_policy_min_score,
            "reject_below": self.utility_policy_reject_below,
            "score_weight": self.utility_policy_score_weight,
            "counterfactual_weight": self.utility_policy_counterfactual_weight,
        })
        if score >= self.utility_policy_min_score:
            decision = "promote"
            item["confidence"] = max(
                self._safe_float(item.get("confidence"), 0.0),
                self.utility_policy_promote_confidence,
                min(score, 0.99),
            )
        if self.utility_policy_score_weight > 0.0:
            item["score"] = self._safe_float(item.get("score"), 0.0) + self.utility_policy_score_weight * score

        reject_threshold = self.utility_policy_reject_below
        if self.utility_policy_mode == "selector":
            reject_threshold = max(reject_threshold, self.utility_policy_min_score)
        if self.utility_policy_mode in {"filter", "selector"} and score < reject_threshold:
            policy["decision"] = "reject"
            item["utility_policy"] = policy
            return False, "utility_policy_low_score"

        policy["decision"] = decision
        item["utility_policy"] = policy
        return True, decision

    def _utility_planner_scope_ok(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, str]:
        if not self.utility_planner_require_complex_or_path:
            return True, "all"
        condition = query_plan_log.get("query_condition", {}) or {}
        condition_text = " ".join(
            str(condition.get(key, "") or "")
            for key in ("query_type", "intent", "answer_type", "family", "mode")
        ).lower()
        families = " ".join(str(value) for value in condition.get("relation_families", []) or []).lower()
        path_info = item.get("path_aware", {}) or {}
        complex_query = any(token in f"{condition_text} {families}" for token in (
            "multi",
            "hop",
            "bridge",
            "comparison",
            "composition",
            "constraint",
        ))
        strong_path = bool(path_info.get("approved")) or bool(item.get("has_strict")) or bool(item.get("has_multihop"))
        endpoint_grounded = bool(item.get("has_terminal")) and bool(item.get("has_relation"))
        if complex_query or strong_path or endpoint_grounded:
            return True, "complex_or_path"
        return False, "simple_scope_without_path"

    def _apply_utility_planner_score(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> str:
        """Score a candidate with a recall-utility model used by the planner.

        Unlike the older utility policy, this score is interpreted together
        with the cost of displacing an existing top-k passage.  In score mode it
        only affects ordering; in planner mode it also gates top-k insertion.
        """
        if self.utility_planner_mode in {
            "gold_aware_text_top5_planner",
            "gap_aware_topk_planner",
            "oracle_delta_recall_planner",
            "counterfactual_topk_benefit_planner",
            "metric_aligned_action_risk_planner",
            "set_counterfactual_recall_planner",
        }:
            item["utility_planner"] = {
                "enabled": True,
                "mode": self.utility_planner_mode,
                "model_ready": self.utility_planner.is_ready(),
                "deferred": True,
                "reason": "awaiting_counterfactual_text_profile",
            }
            return f"deferred:{self.utility_planner_mode}"
        if self.utility_planner_mode == "off" or not self.utility_planner.is_ready():
            item["utility_planner"] = {
                "enabled": False,
                "mode": self.utility_planner_mode,
                "model_ready": self.utility_planner.is_ready(),
            }
            return "disabled"
        scope_ok, scope_reason = self._utility_planner_scope_ok(item, query_plan_log)
        if not scope_ok:
            item["utility_planner"] = {
                "enabled": False,
                "mode": self.utility_planner_mode,
                "model_ready": self.utility_planner.is_ready(),
                "scope_reason": scope_reason,
            }
            return f"scope_skipped:{scope_reason}"
        planner = self.utility_planner.score(query_plan_log, item)
        score = self._safe_float(planner.get("score"), 0.0)
        decision = "keep"
        source_policy = item.get("source_policy", {}) or {}
        safe_source = bool(source_policy.get("approved")) or bool(item.get("has_strict")) or bool(
            item.get("has_multihop")
        ) or (bool(item.get("has_terminal")) and bool(item.get("has_relation")))
        safe_rank = (
            self.utility_planner_max_original_rank <= 0
            or self._safe_int(item.get("original_rank"), 10**9) <= self.utility_planner_max_original_rank
        )
        safe_candidate = bool(safe_source and safe_rank)
        score_for_sort = score
        confidence_promoted = False
        posthoc_only_planner_mode = self.utility_planner_mode in {
            "hard_negative_top5_planner",
            "gap_aware_topk_planner",
            "oracle_delta_recall_planner",
            "counterfactual_topk_benefit_planner",
            "metric_aligned_action_risk_planner",
            "set_counterfactual_recall_planner",
        }
        safe_planner_mode = self.utility_planner_mode in {
            "safe_planner",
            "position_planner",
            "position_top5_planner",
            "groupwise_top5_planner",
            "hard_negative_top5_planner",
            "gap_aware_topk_planner",
            "oracle_delta_recall_planner",
            "counterfactual_topk_benefit_planner",
            "metric_aligned_action_risk_planner",
            "set_counterfactual_recall_planner",
        }
        if safe_planner_mode and not safe_candidate:




            score_for_sort = 0.0
        if score >= self.utility_planner_min_score:
            if posthoc_only_planner_mode:
                decision = "posthoc_score"
            else:
                decision = "safe_promote" if safe_planner_mode else "promote"
            if (not posthoc_only_planner_mode) and (not safe_planner_mode or safe_candidate):
                item["confidence"] = max(
                    self._safe_float(item.get("confidence"), 0.0),
                    min(score, 0.99),
                )
                confidence_promoted = True
        if self.utility_planner_mode in {
            "groupwise_top5_planner",
            "hard_negative_top5_planner",
            "gap_aware_topk_planner",
            "oracle_delta_recall_planner",
            "counterfactual_topk_benefit_planner",
            "metric_aligned_action_risk_planner",
            "set_counterfactual_recall_planner",
        }:




            score_for_sort = 0.0
        if (
            self.utility_planner_score_weight > 0.0
            and self.utility_planner_mode not in {
                "groupwise_top5_planner",
                "hard_negative_top5_planner",
                "gap_aware_topk_planner",
                "oracle_delta_recall_planner",
                "counterfactual_topk_benefit_planner",
                "metric_aligned_action_risk_planner",
                "set_counterfactual_recall_planner",
            }
        ):
            item["score"] = (
                self._safe_float(item.get("score"), 0.0)
                + self.utility_planner_score_weight * score_for_sort
            )
        planner.update({
            "enabled": True,
            "mode": self.utility_planner_mode,
            "decision": decision,
            "scope_reason": scope_reason,
            "posthoc_only": posthoc_only_planner_mode,
            "safe_candidate": safe_candidate,
            "safe_source": safe_source,
            "safe_rank": safe_rank,
            "score_for_sort": round(float(score_for_sort), 6),
            "confidence_promoted": confidence_promoted,
            "min_score": self.utility_planner_min_score,
            "top2_min_score": self.utility_planner_top2_min_score,
            "score_weight": self.utility_planner_score_weight,
            "counterfactual_weight": self.utility_planner_counterfactual_weight,
        })
        item["utility_planner"] = planner
        return decision

    def _candidate_source_signature(self, item: Mapping[str, Any]) -> str:
        contexts = list(item.get("contexts", []) or [])
        labels: Set[str] = set()
        for context in contexts:
            if not isinstance(context, Mapping):
                continue
            if context.get("evidence_grounded"):
                labels.add("evidence_grounded")
            if context.get("support_evidence"):
                labels.add("support")
            if context.get("ontology_evidence_index"):
                labels.add("evidence_index")
            if context.get("schema_route_evidence"):
                labels.add("schema_route")
            if context.get("schema_slot_recall"):
                labels.add("schema_slot_recall")
            if context.get("ontology_bind_probe_join") or context.get("bind_probe_join"):
                labels.add("bind_probe_join")
            if context.get("failure_evidence"):
                labels.add("failure_evidence")
            if context.get("missing_evidence"):
                labels.add("missing")
            if context.get("subgraph_candidate"):
                labels.add("subgraph")
            if context.get("terminal_evidence"):
                labels.add("terminal")
            if context.get("structural_candidate"):
                labels.add("structural")
            if context.get("path_executor") or context.get("path_seed_hit"):
                labels.add("path_executor")
            if context.get("dense_rank_window"):
                labels.add("dense_rank_window")
        if labels:
            return "+".join(sorted(labels))
        source = str((item.get("reranker_decision", {}) or {}).get("source", "") or "").strip().lower()
        return source or "unknown"

    def _candidate_source_labels(self, item: Mapping[str, Any]) -> Set[str]:
        labels = set(
            part.strip().lower()
            for part in self._candidate_source_signature(item).replace(",", "+").split("+")
            if part.strip()
        )
        source = str((item.get("reranker_decision", {}) or {}).get("source", "") or "").strip().lower()
        if source:
            labels.add(source)
        contexts = list(item.get("contexts", []) or [])
        for context in contexts:
            if not isinstance(context, Mapping):
                continue
            schema_source = str(context.get("schema_route_source", "") or "").strip().lower()
            if schema_source:
                labels.add(schema_source)
            route = str(context.get("route", "") or "").strip().lower()
            if route:
                labels.add(route)
            if context.get("ontology_path_executor") or context.get("path_executor") or context.get("path_seed_hit"):
                labels.add("path_executor")
            if context.get("ontology_evidence_index"):
                labels.add("evidence_index")
            if context.get("dense_rank_window"):
                labels.add("rank_window")
            if context.get("schema_slot_recall"):
                labels.add("schema_slot_recall")
            if context.get("ontology_bind_probe_join") or context.get("bind_probe_join"):
                labels.add("bind_probe_join")
            if context.get("evidence_grounded"):
                labels.add("evidence_grounded")
            if context.get("support_evidence"):
                labels.add("support")
            if context.get("missing_evidence"):
                labels.add("missing")
        if bool(item.get("_rank_window_recall_candidate", False)):
            labels.add("rank_window")
        if bool(item.get("_recall_plan_optimizer_candidate", False)):
            labels.add("recall_plan")
        if bool(item.get("_utility_planner_selected", False)) or bool(item.get("_utility_planner_gap_aware_candidate", False)):
            labels.add("utility_planner")
        if bool(item.get("_evidence_join_candidate", False)):
            labels.add("evidence_join")
        if bool(item.get("_answer_pairwise_candidate", False)):
            labels.add("answer_pairwise")
        return {label for label in labels if label}

    def _evidence_sidecar_query_route(self, query_plan_log: Mapping[str, Any]) -> Dict[str, Any]:
        mode = self.evidence_sidecar_gate_mode
        dataset = str(
            query_plan_log.get("dataset")
            or query_plan_log.get("dataset_name")
            or query_plan_log.get("qa_dataset")
            or ""
        ).strip().lower()
        complex_query = self._query_is_evidence_complex(query_plan_log)
        simple_query = self._query_is_simple_factoid(query_plan_log) or self._is_simple_relation_query(query_plan_log)
        complex_dataset = bool(dataset and dataset in self.evidence_sidecar_complex_datasets)
        simple_dataset = bool(dataset and dataset in self.evidence_sidecar_simple_datasets)
        route = "global"
        strict_gate = mode == "strict"
        simple_route = False
        reason = "loose"
        if mode == "complex_only_strict":
            if simple_dataset and not complex_dataset:
                route = "simple"
                simple_route = True
                strict_gate = False
                reason = "simple_dataset"
            elif complex_dataset or complex_query:
                route = "complex"
                strict_gate = True
                reason = "complex_dataset" if complex_dataset else "complex_query"
            elif simple_query:
                route = "simple"
                simple_route = True
                strict_gate = False
                reason = "simple_query"
            else:
                route = "neutral"
                strict_gate = True
                reason = "neutral_strict"
        elif mode == "strict":
            strict_gate = True
            if simple_dataset or simple_query:
                route = "simple"
                simple_route = True
                reason = "strict_simple"
            elif complex_dataset or complex_query:
                route = "complex"
                reason = "strict_complex"
            else:
                route = "neutral"
                reason = "strict_global"
        return {
            "mode": mode,
            "dataset": dataset,
            "route": route,
            "reason": reason,
            "strict_gate": bool(strict_gate),
            "simple_route": bool(simple_route),
            "complex_query": bool(complex_query),
            "simple_query": bool(simple_query),
        }

    @staticmethod
    def _sidecar_text_looks_numeric_or_temporal(value: Any) -> bool:
        text = " ".join(str(value or "").strip().lower().split())
        if not text:
            return False
        tokens = text.replace(",", " ").replace(".", " ").replace("/", " ").replace("-", " ").split()
        if any(token.isdigit() and len(token) == 4 for token in tokens):
            return True
        if any(token.isdigit() for token in tokens) and any(
            marker in text
            for marker in (
                "january", "february", "march", "april", "may", "june",
                "july", "august", "september", "october", "november", "december",
                "year", "date", "century", "season",
            )
        ):
            return True
        return False

    def _evidence_sidecar_expected_answer_type(self, query_plan_log: Mapping[str, Any]) -> str:
        condition = query_plan_log.get("query_condition", {}) or {}
        if isinstance(condition, Mapping):
            answer_type = self._norm(condition.get("answer_type"))
            if answer_type:
                return answer_type
        query = f" {self._norm(query_plan_log.get('query') or query_plan_log.get('question'))} "
        if query.startswith(" who ") or query.startswith(" whom ") or query.startswith(" whose "):
            return "person"
        if query.startswith(" when ") or " what year " in query or " what date " in query:
            return "date"
        if query.startswith(" where ") or " which city " in query or " which country " in query:
            return "location"
        if " how many " in query or " how much " in query or " number of " in query:
            return "number"
        creative_markers = (
            " which film ", " which movie ", " which album ", " which book ",
            " which song ", " what film ", " what movie ", " what album ",
            " what book ", " what song ",
        )
        if any(marker in query for marker in creative_markers):
            return "creative_work"
        return ""

    def _evidence_sidecar_candidate_answer_types(self, item: Mapping[str, Any]) -> Set[str]:
        answer_types: Set[str] = set()
        for context in list(item.get("contexts", []) or []) + list(item.get("_all_contexts", []) or []):
            if not isinstance(context, Mapping):
                continue
            for key in ("plan_answer_type", "answer_type", "terminal_type", "object_type"):
                value = self._norm(context.get(key))
                if value:
                    answer_types.add(value)
        return answer_types

    def _evidence_sidecar_candidate_terminal_values(self, item: Mapping[str, Any]) -> List[str]:
        values: List[str] = []
        for key in ("new_terminals", "terminals", "terminal_entities"):
            raw_values = item.get(key, []) or []
            if isinstance(raw_values, (list, tuple, set)):
                values.extend(str(value or "") for value in raw_values if str(value or "").strip())
        for context in list(item.get("contexts", []) or []) + list(item.get("_all_contexts", []) or []):
            if not isinstance(context, Mapping):
                continue
            for key in ("end_entity", "terminal_entity", "answer", "object"):
                value = str(context.get(key) or "").strip()
                if value:
                    values.append(value)
        return values[:12]

    def _evidence_sidecar_answer_type_conflict(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        expected = self._evidence_sidecar_expected_answer_type(query_plan_log)
        candidate_types = self._evidence_sidecar_candidate_answer_types(item)
        terminals = self._evidence_sidecar_candidate_terminal_values(item)
        terminal_is_numeric_or_temporal = any(
            self._sidecar_text_looks_numeric_or_temporal(value) for value in terminals
        )
        conflict = False
        reason = "no_expected_type"
        if expected:
            reason = "compatible"
        if expected in {"person", "organization"}:
            bad_types = {"date", "time", "year", "number", "location"}
            if candidate_types & bad_types or terminal_is_numeric_or_temporal:
                conflict = True
                reason = "person_query_numeric_or_place_candidate"
        elif expected in {"date", "time", "year"}:
            bad_types = {"person", "organization", "location", "creative_work"}
            if candidate_types & bad_types and not terminal_is_numeric_or_temporal:
                conflict = True
                reason = "date_query_entity_candidate"
        elif expected == "location":
            bad_types = {"person", "date", "time", "year", "number"}
            if candidate_types & bad_types:
                conflict = True
                reason = "location_query_wrong_candidate_type"
        elif expected == "number":
            bad_types = {"person", "organization", "location", "creative_work"}
            if candidate_types & bad_types and not terminal_is_numeric_or_temporal:
                conflict = True
                reason = "number_query_entity_candidate"
        elif expected == "creative_work":
            bad_types = {"date", "time", "year", "number", "person", "location"}
            if candidate_types & bad_types or terminal_is_numeric_or_temporal:
                conflict = True
                reason = "creative_work_query_wrong_candidate_type"
        return {
            "conflict": bool(conflict),
            "reason": reason,
            "expected": expected,
            "candidate_types": sorted(candidate_types)[:8],
            "terminal_is_numeric_or_temporal": bool(terminal_is_numeric_or_temporal),
            "terminal_values": terminals[:5],
        }

    def _evidence_sidecar_profile(
        self,
        item: Mapping[str, Any],
        base_top_k_set: Set[int],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        if not self.enable_evidence_sidecar:
            return {"enabled": False, "approved": False, "reason": "disabled"}
        passage_idx = self._safe_int(item.get("passage_idx"), -1)
        profile: Dict[str, Any] = {
            "enabled": True,
            "approved": False,
            "reason": "not_evaluated",
            "score": 0.0,
        }
        if passage_idx < 0:
            profile["reason"] = "invalid_passage"
            return profile
        if passage_idx in base_top_k_set:
            profile["reason"] = "already_in_topk"
            return profile
        contexts = list(item.get("contexts", []) or [])
        if not contexts:
            profile["reason"] = "no_contexts"
            return profile
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        if self.evidence_sidecar_max_original_rank > 0 and original_rank > self.evidence_sidecar_max_original_rank:
            profile.update({
                "reason": "rank_too_low",
                "original_rank": int(original_rank),
                "max_original_rank": int(self.evidence_sidecar_max_original_rank),
            })
            return profile

        source_labels = self._candidate_source_labels(item)
        source_policy = item.get("source_policy", {}) or {}
        if not isinstance(source_policy, Mapping):
            source_policy = {}
        source_precision = max(
            self._safe_float(source_policy.get("selected_precision"), 0.0),
            self._safe_float(source_policy.get("precision"), 0.0),
            min(1.0, 3.0 * self._safe_float(source_policy.get("gt5_precision"), 0.0)),
        )
        confidence = min(max(self._safe_float(item.get("confidence"), 0.0), 0.0), 1.0)
        text_info = item.get("text_verifier", {}) or {}
        if not isinstance(text_info, Mapping):
            text_info = {}
        text_score = min(max(self._safe_float(text_info.get("score"), 0.0), 0.0), 1.0)
        rank_window_text = self._rank_window_text_signal(item, query_plan_log)
        if isinstance(rank_window_text, Mapping):
            text_score = max(text_score, min(max(self._safe_float(rank_window_text.get("score"), 0.0), 0.0), 1.0))
            if not text_info.get("answer_overlap") and rank_window_text.get("answer_overlap"):
                text_info = dict(text_info)
                text_info["answer_overlap"] = list(rank_window_text.get("answer_overlap", []) or [])
            if not text_info.get("relation_overlap") and rank_window_text.get("relation_overlap"):
                text_info = dict(text_info)
                text_info["relation_overlap"] = list(rank_window_text.get("relation_overlap", []) or [])
            if not self._safe_int(text_info.get("anchor_hits"), 0):
                text_info = dict(text_info)
                text_info["anchor_hits"] = self._safe_int(rank_window_text.get("anchor_hits"), 0)
            if not self._safe_int(text_info.get("terminal_hits"), 0):
                text_info = dict(text_info)
                text_info["terminal_hits"] = self._safe_int(rank_window_text.get("terminal_hits"), 0)

        path_info = item.get("path_aware", {}) or {}
        if not isinstance(path_info, Mapping):
            path_info = {}
        path_score = self._safe_float(path_info.get("score"), 0.0) if bool(path_info.get("approved", False)) else 0.0
        rank_window = item.get("rank_window_recall", {}) or {}
        if not isinstance(rank_window, Mapping):
            rank_window = {}
        planner = item.get("utility_planner", {}) or {}
        if not isinstance(planner, Mapping):
            planner = {}
        utility_signal = max(
            self._safe_float(planner.get("score_for_sort"), self._safe_float(planner.get("score"), 0.0)),
            self._safe_float((item.get("recall_plan_optimizer", {}) or {}).get("score"), 0.0),
            self._safe_float(rank_window.get("score"), 0.0),
            self._safe_float((item.get("schema_slot_utility", {}) or {}).get("score"), 0.0),
            self._safe_float((item.get("provenance_groupwise", {}) or {}).get("score"), 0.0),
            self._safe_float((item.get("evidence_join_planner", {}) or {}).get("score"), 0.0),
            self._safe_float((item.get("answer_pairwise_verifier", {}) or {}).get("score"), 0.0),
            self._safe_float((item.get("counterfactual_text_verifier", {}) or {}).get("score"), 0.0),
        )
        coverage = min(max(self._safe_float(item.get("coverage_gain"), 0.0) / 2.0, 0.0), 1.0)
        structural = (
            bool(item.get("has_strict"))
            or bool(item.get("has_multihop"))
            or (bool(item.get("has_terminal")) and bool(item.get("has_relation")))
            or path_score >= 0.45
        )
        relation_only = bool(item.get("has_relation")) and not (
            bool(item.get("has_terminal")) or bool(item.get("has_multihop")) or bool(item.get("has_strict")) or path_score > 0.0
        )
        preferred_hit = bool(source_labels & self.evidence_sidecar_preferred_sources)
        anchor_hits = self._safe_int(text_info.get("anchor_hits"), 0)
        terminal_hits = self._safe_int(text_info.get("terminal_hits"), 0)
        answer_overlap_count = len(text_info.get("answer_overlap", []) or [])
        relation_overlap_count = len(text_info.get("relation_overlap", []) or [])
        query_route = self._evidence_sidecar_query_route(query_plan_log)
        answer_type_conflict = self._evidence_sidecar_answer_type_conflict(item, query_plan_log)

        if relation_only and not self.evidence_sidecar_allow_relation_only:
            profile.update({
                "reason": "relation_only",
                "text_score": round(float(text_score), 6),
                "path_score": round(float(path_score), 6),
                "source_labels": sorted(source_labels)[:12],
                "gate_mode": self.evidence_sidecar_gate_mode,
                "query_route": query_route,
            })
            return profile
        if (
            query_route.get("simple_route", False)
            and self.evidence_sidecar_disable_simple_without_answer_overlap
            and answer_overlap_count <= 0
            and terminal_hits <= 0
        ):
            profile.update({
                "reason": "simple_without_answer_or_terminal_overlap",
                "text_score": round(float(text_score), 6),
                "answer_overlap_count": int(answer_overlap_count),
                "terminal_hits": int(terminal_hits),
                "gate_mode": self.evidence_sidecar_gate_mode,
                "query_route": query_route,
                "source_labels": sorted(source_labels)[:12],
            })
            return profile
        if query_route.get("strict_gate", False):
            if self.evidence_sidecar_require_preferred_source and not preferred_hit:
                profile.update({
                    "reason": "strict_missing_preferred_source",
                    "text_score": round(float(text_score), 6),
                    "path_score": round(float(path_score), 6),
                    "source_labels": sorted(source_labels)[:12],
                    "gate_mode": self.evidence_sidecar_gate_mode,
                    "query_route": query_route,
                })
                return profile
            if self.evidence_sidecar_require_anchor_hit and anchor_hits <= 0:
                profile.update({
                    "reason": "strict_missing_anchor_hit",
                    "text_score": round(float(text_score), 6),
                    "anchor_hits": int(anchor_hits),
                    "gate_mode": self.evidence_sidecar_gate_mode,
                    "query_route": query_route,
                    "source_labels": sorted(source_labels)[:12],
                })
                return profile
            if self.evidence_sidecar_require_terminal_hit and terminal_hits <= 0 and answer_overlap_count <= 0:
                profile.update({
                    "reason": "strict_missing_terminal_or_answer_hit",
                    "text_score": round(float(text_score), 6),
                    "terminal_hits": int(terminal_hits),
                    "answer_overlap_count": int(answer_overlap_count),
                    "gate_mode": self.evidence_sidecar_gate_mode,
                    "query_route": query_route,
                    "source_labels": sorted(source_labels)[:12],
                })
                return profile
            if text_score < self.evidence_sidecar_strict_min_text_score:
                profile.update({
                    "reason": "strict_weak_text_signal",
                    "text_score": round(float(text_score), 6),
                    "strict_min_text_score": round(float(self.evidence_sidecar_strict_min_text_score), 6),
                    "gate_mode": self.evidence_sidecar_gate_mode,
                    "query_route": query_route,
                    "source_labels": sorted(source_labels)[:12],
                })
                return profile
            path_like = bool(source_labels & {"path_executor", "ontology_path_executor"}) or path_score > 0.0
            if path_like and path_score < self.evidence_sidecar_strict_min_path_score:
                profile.update({
                    "reason": "strict_weak_path_signal",
                    "path_score": round(float(path_score), 6),
                    "strict_min_path_score": round(float(self.evidence_sidecar_strict_min_path_score), 6),
                    "gate_mode": self.evidence_sidecar_gate_mode,
                    "query_route": query_route,
                    "source_labels": sorted(source_labels)[:12],
                })
                return profile
            if self.evidence_sidecar_disable_answer_type_conflict and answer_type_conflict.get("conflict", False):
                profile.update({
                    "reason": "strict_answer_type_conflict",
                    "answer_type_conflict": answer_type_conflict,
                    "text_score": round(float(text_score), 6),
                    "path_score": round(float(path_score), 6),
                    "gate_mode": self.evidence_sidecar_gate_mode,
                    "query_route": query_route,
                    "source_labels": sorted(source_labels)[:12],
                })
                return profile
        if text_score < self.evidence_sidecar_min_text_score and not structural:
            profile.update({
                "reason": "weak_text_or_path_signal",
                "text_score": round(float(text_score), 6),
                "min_text_score": round(float(self.evidence_sidecar_min_text_score), 6),
                "path_score": round(float(path_score), 6),
                "gate_mode": self.evidence_sidecar_gate_mode,
                "query_route": query_route,
                "source_labels": sorted(source_labels)[:12],
            })
            return profile

        source_bonus = 0.08 if preferred_hit else 0.0
        structural_bonus = 0.05 if structural else 0.0
        score = (
            0.32 * confidence
            + 0.22 * utility_signal
            + 0.18 * text_score
            + 0.10 * path_score
            + 0.10 * source_precision
            + 0.08 * coverage
            + source_bonus
            + structural_bonus
        )
        score = min(max(float(score), 0.0), 1.0)
        approved = score >= self.evidence_sidecar_min_score
        profile.update({
            "approved": bool(approved),
            "reason": "approved" if approved else "low_score",
            "score": round(float(score), 6),
            "min_score": round(float(self.evidence_sidecar_min_score), 6),
            "text_score": round(float(text_score), 6),
            "min_text_score": round(float(self.evidence_sidecar_min_text_score), 6),
            "path_score": round(float(path_score), 6),
            "utility_signal": round(float(utility_signal), 6),
            "source_precision": round(float(source_precision), 6),
            "coverage_signal": round(float(coverage), 6),
            "preferred_source_hit": bool(preferred_hit),
            "source_labels": sorted(source_labels)[:12],
            "original_rank": int(original_rank),
            "structural": bool(structural),
            "gate_mode": self.evidence_sidecar_gate_mode,
            "query_route": query_route,
            "anchor_hits": int(anchor_hits),
            "terminal_hits": int(terminal_hits),
            "answer_overlap_count": int(answer_overlap_count),
            "relation_overlap_count": int(relation_overlap_count),
            "answer_type_conflict": answer_type_conflict,
        })
        return profile

    def _evidence_sidecar_key(self, item: Mapping[str, Any]) -> str:
        parts: List[str] = [str(item.get("passage_idx", ""))]
        for context in list(item.get("contexts", []) or [])[:2]:
            if not isinstance(context, Mapping):
                continue
            parts.append(str(context.get("plan_id", "") or ""))
            parts.append(str(context.get("anchor_entity", "") or ""))
            parts.append(str(context.get("end_entity", "") or ""))
            relation_values = context.get("relations", []) or context.get("relation_path", []) or []
            if isinstance(relation_values, (list, tuple, set)):
                parts.extend(str(value) for value in list(relation_values)[:4])
            else:
                parts.append(str(relation_values))
            parts.append(str(context.get("signature_match_mode", "") or ""))
        return text_processing(" ".join(parts)) or str(item.get("passage_idx", ""))

    def _build_evidence_sidecar_log_items(
        self,
        candidates: Sequence[Mapping[str, Any]],
        base_doc_ids: Sequence[int],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        result = {
            "considered_count": 0,
            "candidate_count": 0,
            "selected_count": 0,
            "items": [],
            "rejection_reasons": {},
        }
        if not self.enable_evidence_sidecar or self.evidence_sidecar_max_items <= 0:
            result["rejection_reasons"] = {"disabled": len(candidates)}
            return result
        base_top_k_set = {int(doc_id) for doc_id in list(base_doc_ids)[: self.final_top_k]}
        rejections: Counter = Counter()
        approved: List[Mapping[str, Any]] = []
        for item in candidates:
            profile = self._evidence_sidecar_profile(item, base_top_k_set, query_plan_log)
            if isinstance(item, dict):
                item["evidence_sidecar"] = profile
            result["considered_count"] += 1
            if bool(profile.get("approved", False)):
                approved.append(item)
            else:
                rejections[str(profile.get("reason") or "rejected")] += 1
        result["candidate_count"] = len(approved)
        seen: Set[str] = set()
        selected: List[Dict[str, Any]] = []
        for item in sorted(
            approved,
            key=lambda candidate: (
                self._safe_float((candidate.get("evidence_sidecar", {}) or {}).get("score"), 0.0),
                self._safe_float((candidate.get("evidence_sidecar", {}) or {}).get("text_score"), 0.0),
                self._safe_float((candidate.get("evidence_sidecar", {}) or {}).get("path_score"), 0.0),
                self._safe_float(candidate.get("confidence"), 0.0),
                -self._safe_int(candidate.get("original_rank"), 10**9),
            ),
            reverse=True,
        ):
            key = self._evidence_sidecar_key(item)
            if not key or key in seen:
                rejections["duplicate_signature"] += 1
                continue
            seen.add(key)
            selected.append(
                self._decision_for_log(
                    item,
                    selected=False,
                    reason="evidence_sidecar_selected",
                    final_rank=-1,
                )
            )
            if len(selected) >= self.evidence_sidecar_max_items:
                break
        result["selected_count"] = len(selected)
        result["items"] = selected
        result["rejection_reasons"] = dict(rejections)
        return result

    def _load_recall_plan_optimizer_stats(self, path: str) -> Dict[str, Any]:
        if not path:
            return {}
        try:
            if not os.path.exists(path):
                return {}
            with open(path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
            return data if isinstance(data, dict) else {}
        except (OSError, ValueError, TypeError):
            return {}

    def _recall_plan_default_source_record(self, source: str) -> Dict[str, float]:
        source = str(source or "unknown").lower()
        defaults = {
            "lifted": {"precision": 0.18, "selected_precision": 0.12, "recall_yield": 0.20, "cost": 0.18},
            "evidence_index": {"precision": 0.16, "selected_precision": 0.10, "recall_yield": 0.22, "cost": 0.30},
            "path_executor": {"precision": 0.12, "selected_precision": 0.08, "recall_yield": 0.18, "cost": 0.28},
            "evidence_grounded": {"precision": 0.09, "selected_precision": 0.06, "recall_yield": 0.25, "cost": 0.42},
            "failure_evidence": {"precision": 0.08, "selected_precision": 0.05, "recall_yield": 0.20, "cost": 0.44},
            "support": {"precision": 0.05, "selected_precision": 0.04, "recall_yield": 0.16, "cost": 0.55},
            "schema_route": {"precision": 0.07, "selected_precision": 0.04, "recall_yield": 0.14, "cost": 0.46},
            "schema_slot_recall": {"precision": 0.10, "selected_precision": 0.06, "recall_yield": 0.24, "cost": 0.36},
            "bind_probe_join": {"precision": 0.22, "selected_precision": 0.16, "recall_yield": 0.26, "cost": 0.42},
            "dense_rank_window": {"precision": 0.12, "selected_precision": 0.08, "recall_yield": 0.32, "cost": 0.22},
            "missing": {"precision": 0.06, "selected_precision": 0.04, "recall_yield": 0.14, "cost": 0.50},
            "projected_graph": {"precision": 0.05, "selected_precision": 0.03, "recall_yield": 0.12, "cost": 0.58},
            "terminal": {"precision": 0.05, "selected_precision": 0.03, "recall_yield": 0.10, "cost": 0.52},
            "structural": {"precision": 0.06, "selected_precision": 0.04, "recall_yield": 0.12, "cost": 0.45},
            "subgraph": {"precision": 0.05, "selected_precision": 0.03, "recall_yield": 0.10, "cost": 0.56},
            "unknown": {"precision": 0.04, "selected_precision": 0.02, "recall_yield": 0.08, "cost": 0.65},
        }
        for key, record in defaults.items():
            if key in source:
                return dict(record)
        return dict(defaults["unknown"])

    def _recall_plan_source_record(self, source_signature: str) -> Dict[str, Any]:
        source_signature = str(source_signature or "unknown").strip().lower() or "unknown"
        stats = self.recall_plan_optimizer_stats.get("source_stats", {}) if isinstance(self.recall_plan_optimizer_stats, Mapping) else {}
        if not isinstance(stats, Mapping):
            stats = {}
        labels = [part for part in source_signature.split("+") if part]
        keys = [source_signature] + labels
        records: List[Mapping[str, Any]] = []
        for key in keys:
            record = stats.get(key)
            if isinstance(record, Mapping):
                records.append(record)
        if not records:
            records = [self._recall_plan_default_source_record(label) for label in (labels or [source_signature])]
        precision = max(self._safe_float(record.get("precision"), 0.0) for record in records)
        selected_precision = max(self._safe_float(record.get("selected_precision"), 0.0) for record in records)
        recall_yield = max(
            self._safe_float(record.get("recall_yield"), self._safe_float(record.get("oracle_gain_rate"), 0.0))
            for record in records
        )
        cost = min(max(self._safe_float(record.get("cost"), 0.50), 0.02) for record in records)
        count = sum(self._safe_int(record.get("candidate_count"), 0) for record in records)
        return {
            "source_signature": source_signature,
            "precision": float(precision),
            "selected_precision": float(selected_precision),
            "recall_yield": float(recall_yield),
            "cost": float(cost),
            "candidate_count": int(count),
        }

    def _recall_plan_query_pressure(self, query_plan_log: Mapping[str, Any]) -> float:
        pressure = 0.0
        if self._query_is_evidence_complex(query_plan_log):
            pressure += 0.10
        lifted_count = len(query_plan_log.get("lifted_passages", []) or [])
        if lifted_count <= 1:
            pressure += 0.08
        if not (query_plan_log.get("path_executor_retriever", {}) or {}).get("added_candidates"):
            pressure += 0.03
        if (query_plan_log.get("evidence_index_retriever", {}) or {}).get("added_candidates"):
            pressure += 0.03
        return min(pressure, 0.18)

    def _source_gap_aperture_query_pressure(self, query_plan_log: Mapping[str, Any]) -> float:
        """Estimate whether a query needs a wider evidence access path.

        This is intentionally local and cheap: it uses already materialized
        trace signals, not gold labels.  High pressure means the current
        ontology path is underspecified or source generators found many
        candidate passages that the fixed candidate-pool cutoff may hide.
        """
        pressure = self._recall_plan_query_pressure(query_plan_log)
        matched_plans = self._safe_int(query_plan_log.get("matched_plan_count"), 0)
        strict_paths = self._safe_int(query_plan_log.get("strict_executable_path_count"), 0)
        executable_paths = self._safe_int(query_plan_log.get("executable_path_count"), 0)
        if matched_plans <= 0:
            pressure += 0.14
        elif matched_plans <= 2:
            pressure += 0.05
        if strict_paths <= 0:
            pressure += 0.12
        elif strict_paths <= 2:
            pressure += 0.04
        if executable_paths <= 0:
            pressure += 0.06

        source_logs = [
            query_plan_log.get("schema_slot_recall_expander", {}) or {},
            query_plan_log.get("bind_probe_join", {}) or {},
            query_plan_log.get("evidence_grounded_support_retriever", {}) or {},
            query_plan_log.get("support_evidence_retriever", {}) or {},
            query_plan_log.get("path_executor_retriever", {}) or {},
            query_plan_log.get("evidence_index_retriever", {}) or {},
        ]
        for source_log in source_logs:
            candidate_count = self._safe_int(source_log.get("candidate_count"), 0)
            candidate_count = max(candidate_count, self._safe_int(source_log.get("selected_count"), 0))
            candidate_count = max(candidate_count, len(source_log.get("added_candidates", []) or []))
            if candidate_count > 0:
                pressure += min(0.12, 0.02 + 0.01 * min(candidate_count, 10))
        return min(max(float(pressure), 0.0), 1.0)

    def _source_gap_aperture_profile(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        if not self.enable_source_gap_aperture:
            return {"enabled": False, "approved": False, "reason": "disabled"}
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        rank_ok = (
            self.source_gap_aperture_max_original_rank <= 0
            or original_rank <= self.source_gap_aperture_max_original_rank
        )
        confidence = self._safe_float(item.get("confidence"), 0.0)
        source_signature = self._candidate_source_signature(item)
        source_record = self._recall_plan_source_record(source_signature)
        source_policy = item.get("source_policy", {}) or {}
        if not isinstance(source_policy, Mapping):
            source_policy = {}
        source_score = max(
            self._safe_float(source_record.get("precision"), 0.0),
            self._safe_float(source_record.get("selected_precision"), 0.0),
            0.50 * self._safe_float(source_record.get("recall_yield"), 0.0),
            self._safe_float(source_policy.get("precision"), 0.0),
            self._safe_float(source_policy.get("selected_precision"), 0.0),
            2.0 * self._safe_float(source_policy.get("gt5_precision"), 0.0),
        )
        source_score = min(max(float(source_score), 0.0), 1.0)
        pressure = self._source_gap_aperture_query_pressure(query_plan_log)
        labels = set(source_signature.split("+")) if source_signature else set()
        source_is_recall_operator = bool(
            labels
            & {
                "evidence_grounded",
                "schema_slot_recall",
                "bind_probe_join",
                "path_executor",
                "support",
                "evidence_index",
                "failure_evidence",
            }
        )
        structural_score = 0.0
        if bool(item.get("has_strict")):
            structural_score += 0.20
        if bool(item.get("has_multihop")):
            structural_score += 0.18
        if bool(item.get("has_terminal")):
            structural_score += 0.12
        if bool(item.get("has_relation")):
            structural_score += 0.10
        if self._safe_float(item.get("coverage_gain"), 0.0) > 0.0:
            structural_score += 0.08
        if self._safe_int(item.get("decomposition_slot_gain"), 0) > 0:
            structural_score += 0.06
        structural_score = min(structural_score, 1.0)
        score = (
            0.30 * confidence
            + 0.28 * source_score
            + 0.24 * pressure
            + 0.18 * structural_score
        )
        if source_is_recall_operator:
            score += 0.04
        score = min(max(float(score), 0.0), 1.0)

        reason = "approved"
        approved = True
        if not rank_ok:
            approved = False
            reason = "rank_after_aperture_max"
        elif confidence < self.source_gap_aperture_min_confidence:
            approved = False
            reason = "low_confidence"
        elif source_score < self.source_gap_aperture_min_source_score and not source_is_recall_operator:
            approved = False
            reason = "low_source_score"
        elif pressure < self.source_gap_aperture_min_query_pressure and not source_is_recall_operator:
            approved = False
            reason = "low_query_pressure"
        elif structural_score <= 0.0 and not source_is_recall_operator:
            approved = False
            reason = "no_structure"
        return {
            "enabled": True,
            "approved": bool(approved),
            "reason": reason,
            "score": round(float(score), 6),
            "original_rank": int(original_rank),
            "max_original_rank": int(self.source_gap_aperture_max_original_rank),
            "confidence": round(float(confidence), 6),
            "min_confidence": round(float(self.source_gap_aperture_min_confidence), 6),
            "source_signature": source_signature,
            "source_score": round(float(source_score), 6),
            "min_source_score": round(float(self.source_gap_aperture_min_source_score), 6),
            "query_pressure": round(float(pressure), 6),
            "min_query_pressure": round(float(self.source_gap_aperture_min_query_pressure), 6),
            "structural_score": round(float(structural_score), 6),
            "source_is_recall_operator": bool(source_is_recall_operator),
        }

    def _apply_recall_plan_optimizer(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
        no_new_slot: bool = False,
    ) -> str:
        if self.recall_plan_optimizer_mode == "off":
            item["recall_plan_optimizer"] = {"mode": "off", "decision": "disabled"}
            return "disabled"
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        source_signature = self._candidate_source_signature(item)
        source_record = self._recall_plan_source_record(source_signature)
        source_precision = max(
            self._safe_float(source_record.get("precision"), 0.0),
            self._safe_float(source_record.get("selected_precision"), 0.0),
            self._safe_float((item.get("source_policy", {}) or {}).get("selected_precision"), 0.0),
            self._safe_float((item.get("source_policy", {}) or {}).get("precision"), 0.0) * 0.70,
        )
        recall_yield = self._safe_float(source_record.get("recall_yield"), 0.0)
        cost = max(self._safe_float(source_record.get("cost"), 0.50), 0.02)
        rank_cost = 0.0
        if self.recall_plan_optimizer_max_original_rank > 0:
            rank_cost = min(float(original_rank) / float(self.recall_plan_optimizer_max_original_rank), 1.0)
        confidence = self._safe_float(item.get("confidence"), 0.0)
        coverage_gain = self._safe_float(item.get("coverage_gain"), 0.0)
        decomposition_gain = float(self._safe_int(item.get("decomposition_slot_gain"), 0))
        path_info = item.get("path_aware", {}) or {}
        if not isinstance(path_info, Mapping):
            path_info = {}
        structural = 0.0
        if bool(item.get("has_strict")):
            structural += 0.10
        if bool(item.get("has_multihop")):
            structural += 0.08
        if bool(item.get("has_terminal")):
            structural += 0.06
        if bool(item.get("has_relation")):
            structural += 0.04
        if bool(path_info.get("approved", False)):
            structural += 0.08
        if bool((item.get("text_verifier", {}) or {}).get("promoted", False)):
            structural += 0.04
        novelty = min(0.18, 0.08 * coverage_gain + 0.05 * decomposition_gain)
        if no_new_slot:
            novelty -= 0.05
        source_utility = min(1.0, 0.60 * source_precision + 0.40 * recall_yield)
        score = (
            0.32 * confidence
            + 0.28 * source_utility
            + min(structural, 0.22)
            + novelty
            + self._recall_plan_query_pressure(query_plan_log)
            - 0.10 * rank_cost
            - 0.08 * cost
        )
        score = min(max(score, 0.0), 1.0)
        eligible_rank = (
            self.recall_plan_optimizer_max_original_rank <= 0
            or original_rank <= self.recall_plan_optimizer_max_original_rank
        )
        eligible_source = source_precision >= self.recall_plan_optimizer_min_source_precision or (
            bool(path_info.get("approved", False)) and source_precision >= self.recall_plan_optimizer_min_source_precision * 0.50
        )
        promoted = (
            eligible_rank
            and eligible_source
            and score >= self.recall_plan_optimizer_min_score
        )
        decision = "promote" if promoted else "score_only"
        if not eligible_rank:
            decision = "rank_too_low"
        elif not eligible_source:
            decision = "low_source_precision"
        item["recall_plan_optimizer"] = {
            "mode": self.recall_plan_optimizer_mode,
            "decision": decision,
            "score": round(float(score), 6),
            "source_signature": source_signature,
            "source_precision": round(float(source_precision), 6),
            "recall_yield": round(float(recall_yield), 6),
            "cost": round(float(cost), 6),
            "rank_cost": round(float(rank_cost), 6),
            "no_new_slot": bool(no_new_slot),
            "eligible_rank": bool(eligible_rank),
            "eligible_source": bool(eligible_source),
            "min_score": self.recall_plan_optimizer_min_score,
            "score_weight": self.recall_plan_optimizer_score_weight,
        }
        if promoted:
            item["_recall_plan_optimizer_candidate"] = True
            item["score"] = self._safe_float(item.get("score"), 0.0) + self.recall_plan_optimizer_score_weight * score
            item["confidence"] = min(
                0.99,
                max(
                    self._safe_float(item.get("confidence"), 0.0),
                    self._safe_float(item.get("confidence"), 0.0)
                    + self.recall_plan_optimizer_confidence_boost * score,
                ),
            )
            item["effective_min_confidence"] = min(
                self._safe_float(item.get("effective_min_confidence"), self.min_candidate_confidence),
                max(0.52, self.min_candidate_confidence - 0.08 * score),
            )
            if no_new_slot and self.recall_plan_optimizer_allow_no_new_slot:
                item["_recall_plan_optimizer_no_new_slot_bypass"] = True
        return decision

    def _best_recall_plan_optimizer_score(self, candidates: Sequence[Mapping[str, Any]]) -> float:
        return max(
            (
                self._safe_float((candidate.get("recall_plan_optimizer", {}) or {}).get("score"), 0.0)
                for candidate in candidates
            ),
            default=0.0,
        )

    def _load_rank_window_recall_model(self, path: str) -> Dict[str, Any]:
        if not path:
            return {}
        try:
            if not os.path.exists(path):
                return {}
            with open(path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
            return data if isinstance(data, dict) else {}
        except (OSError, ValueError, TypeError):
            return {}

    def _rank_window_model_ready(self) -> bool:
        model = self.rank_window_recall_model
        if not isinstance(model, Mapping) or not model:
            return False
        return isinstance(model.get("weights"), (Mapping, list, tuple))

    @staticmethod
    def _sigmoid(value: float) -> float:
        value = max(min(float(value), 50.0), -50.0)
        return 1.0 / (1.0 + math.exp(-value))

    def _rank_window_context(self, item: Mapping[str, Any]) -> Dict[str, Any]:
        for context in list(item.get("_all_contexts", []) or []) + list(item.get("contexts", []) or []):
            if isinstance(context, Mapping) and bool(context.get("dense_rank_window", False)):
                return dict(context)
        return {}

    def _rank_window_query_route(self, query_plan_log: Mapping[str, Any]) -> Dict[str, Any]:
        mode = str(self.rank_window_recall_query_router_mode or "off").strip().lower()
        dataset = str(query_plan_log.get("dataset") or "").strip().lower()
        query_pressure = self._source_gap_aperture_query_pressure(query_plan_log)
        complex_query = self._query_is_evidence_complex(query_plan_log)
        simple_query = self._query_is_simple_factoid(query_plan_log) or self._is_simple_relation_query(query_plan_log)
        base = {
            "mode": mode,
            "route": "global",
            "reason": "router_disabled",
            "dataset": dataset,
            "target_datasets": sorted(self.rank_window_recall_target_datasets),
            "target_dataset_allowed": (
                not self.rank_window_recall_target_datasets
                or dataset in self.rank_window_recall_target_datasets
            ),
            "complex_query": bool(complex_query),
            "simple_query": bool(simple_query),
            "query_pressure": round(float(query_pressure), 6),
            "min_score": float(self.rank_window_recall_min_score),
            "top2_min_score": float(self.rank_window_recall_top2_min_score),
            "router_bypass_min_score": float(self.rank_window_recall_router_bypass_min_score),
            "min_text_score": float(self.rank_window_recall_min_text_score),
            "require_text_signal": bool(self.rank_window_recall_require_text_signal),
            "require_answer_signal": False,
            "answer_signal_min_text_score": float(self.rank_window_recall_simple_answer_signal_min_text_score),
        }
        if not bool(base["target_dataset_allowed"]):
            base.update({
                "route": "disabled",
                "reason": "dataset_not_targeted",
                "min_score": 1.01,
                "top2_min_score": 1.01,
                "router_bypass_min_score": 1.01,
                "min_text_score": 1.01,
                "require_text_signal": True,
                "require_answer_signal": True,
            })
            return base
        if mode in {"off", "global", ""}:
            return base

        complex_dataset = dataset in self.rank_window_recall_complex_datasets
        simple_dataset = dataset in self.rank_window_recall_simple_datasets






        if simple_dataset and not complex_dataset:
            base.update({
                "route": "simple_entity",
                "reason": "simple_dataset",
                "min_score": max(
                    float(self.rank_window_recall_min_score),
                    float(self.rank_window_recall_simple_min_score),
                ),
                "min_text_score": max(
                    float(self.rank_window_recall_min_text_score),
                    float(self.rank_window_recall_simple_min_text_score),
                ),
                "require_text_signal": True,
                "require_answer_signal": bool(self.rank_window_recall_simple_require_answer_signal),
                "router_bypass_min_score": max(
                    float(self.rank_window_recall_router_bypass_min_score),
                    float(self.rank_window_recall_simple_min_score),
                ),
            })
            return base

        if complex_dataset or complex_query or query_pressure >= 0.16:
            base.update({
                "route": "complex_path",
                "reason": (
                    "complex_dataset"
                    if complex_dataset else "complex_query"
                    if complex_query else "high_query_pressure"
                ),
                "min_score": float(self.rank_window_recall_complex_min_score),
                "min_text_score": float(self.rank_window_recall_complex_min_text_score),
                "require_text_signal": True,
                "require_answer_signal": False,
                "router_bypass_min_score": min(
                    float(self.rank_window_recall_router_bypass_min_score),
                    max(float(self.rank_window_recall_complex_min_score) + 0.14, 0.66),
                ),
            })
            return base

        if simple_query:
            base.update({
                "route": "simple_entity",
                "reason": "simple_query",
                "min_score": max(
                    float(self.rank_window_recall_min_score),
                    float(self.rank_window_recall_simple_min_score),
                ),
                "min_text_score": max(
                    float(self.rank_window_recall_min_text_score),
                    float(self.rank_window_recall_simple_min_text_score),
                ),
                "require_text_signal": True,
                "require_answer_signal": bool(self.rank_window_recall_simple_require_answer_signal),
                "router_bypass_min_score": max(
                    float(self.rank_window_recall_router_bypass_min_score),
                    float(self.rank_window_recall_simple_min_score),
                ),
            })
            return base

        base.update({
            "route": "neutral",
            "reason": "adaptive_neutral",
            "min_score": max(float(self.rank_window_recall_min_score), 0.70),
            "min_text_score": max(float(self.rank_window_recall_min_text_score), 0.08),
            "require_text_signal": True,
            "require_answer_signal": False,
        })
        return base

    def _rank_window_item_min_score(self, item: Mapping[str, Any]) -> float:
        profile = item.get("rank_window_recall", {}) or {}
        return self._safe_float(profile.get("effective_min_score"), self.rank_window_recall_min_score)

    def _rank_window_item_min_text_score(self, item: Mapping[str, Any]) -> float:
        profile = item.get("rank_window_recall", {}) or {}
        return self._safe_float(profile.get("effective_min_text_score"), self.rank_window_recall_min_text_score)

    def _rank_window_recall_profile(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        if not self.enable_rank_window_recall:
            return {"enabled": False, "approved": False, "reason": "disabled"}
        context = self._rank_window_context(item)
        if not context:
            return {"enabled": True, "approved": False, "reason": "no_dense_rank_window_context"}

        original_rank = self._safe_int(item.get("original_rank"), self._safe_int(context.get("dense_rank"), 10**9))
        rank_ok = self.rank_window_recall_start_rank <= original_rank <= self.rank_window_recall_end_rank
        rank_span = max(self.rank_window_recall_end_rank - self.rank_window_recall_start_rank + 1, 1)
        rank_prior = self._safe_float(
            context.get("rank_prior"),
            1.0 - min(max(original_rank - self.rank_window_recall_start_rank, 0), rank_span) / rank_span,
        )
        rank_prior = min(max(float(rank_prior), 0.0), 1.0)
        dense_score_norm = min(max(self._safe_float(context.get("dense_score_norm"), rank_prior), 0.0), 1.0)
        dense_score = self._safe_float(context.get("dense_score"), 0.0)
        text_signal = self._rank_window_text_signal(item, query_plan_log)
        text_score = min(max(self._safe_float(text_signal.get("score"), 0.0), 0.0), 1.0)
        query_overlap_count = len(text_signal.get("query_overlap", []) or [])
        answer_overlap_count = len(text_signal.get("answer_overlap", []) or [])
        terminal_hits = self._safe_int(text_signal.get("terminal_hits"), 0)
        anchor_hits = self._safe_int(text_signal.get("anchor_hits"), 0)
        query_pressure = self._source_gap_aperture_query_pressure(query_plan_log)
        confidence = min(max(self._safe_float(item.get("confidence"), 0.0), 0.0), 1.0)
        has_ontology_context = any(
            isinstance(ctx, Mapping) and not bool(ctx.get("dense_rank_window", False))
            for ctx in list(item.get("_all_contexts", []) or [])
        )
        query_route = self._rank_window_query_route(query_plan_log)
        route_name = str(query_route.get("route") or "global")
        effective_min_score = self._safe_float(query_route.get("min_score"), self.rank_window_recall_min_score)
        effective_min_text_score = self._safe_float(
            query_route.get("min_text_score"),
            self.rank_window_recall_min_text_score,
        )
        effective_require_text_signal = bool(query_route.get("require_text_signal", self.rank_window_recall_require_text_signal))
        effective_require_answer_signal = bool(query_route.get("require_answer_signal", False))
        answer_signal_min_text_score = self._safe_float(
            query_route.get("answer_signal_min_text_score"),
            self.rank_window_recall_simple_answer_signal_min_text_score,
        )
        answer_signal = (
            answer_overlap_count > 0
            or terminal_hits > 0
            or anchor_hits > 0 and query_overlap_count > 0
            or text_score >= answer_signal_min_text_score
        )
        feature_values = {
            "rank_prior": rank_prior,
            "rank_inv": 1.0 / max(original_rank, 1),
            "rank_log_inv": 1.0 / max(math.log2(max(original_rank, 2)), 1.0),
            "rank_le_5": 1.0 if original_rank <= 5 else 0.0,
            "rank_le_10": 1.0 if original_rank <= 10 else 0.0,
            "dense_score_norm": dense_score_norm,
            "text_score": text_score,
            "query_overlap_count": min(query_overlap_count / 6.0, 1.0),
            "answer_overlap_count": min(answer_overlap_count / 3.0, 1.0),
            "query_pressure": query_pressure,
            "candidate_confidence": confidence,
            "has_ontology_context": 1.0 if has_ontology_context else 0.0,
            "is_rank_window_only": 0.0 if has_ontology_context else 1.0,
        }

        model_score = None
        if self._rank_window_model_ready():
            model = self.rank_window_recall_model
            names = list(model.get("feature_names", []) or feature_values.keys())
            weights_obj = model.get("weights", {})
            if isinstance(weights_obj, Mapping):
                weighted = sum(
                    self._safe_float(weights_obj.get(name), 0.0) * self._safe_float(feature_values.get(name), 0.0)
                    for name in names
                )
            else:
                weights = list(weights_obj or [])
                weighted = sum(
                    self._safe_float(weights[idx], 0.0) * self._safe_float(feature_values.get(name), 0.0)
                    for idx, name in enumerate(names)
                    if idx < len(weights)
                )
            model_score = self._sigmoid(self._safe_float(model.get("bias"), 0.0) + weighted)

        if model_score is None:
            score = (
                0.30 * rank_prior
                + 0.26 * dense_score_norm
                + 0.18 * text_score
                + 0.14 * query_pressure
                + 0.07 * confidence
                + 0.05 * min((query_overlap_count + answer_overlap_count) / 5.0, 1.0)
            )
            if original_rank <= 5:
                score += 0.04
            elif original_rank <= 10:
                score += 0.02
        else:
            score = float(model_score)
        score = min(max(float(score), 0.0), 1.0)

        reason = "approved"
        approved = True
        if not rank_ok:
            approved = False
            reason = "rank_outside_window"
        elif route_name == "disabled":
            approved = False
            reason = str(query_route.get("reason") or "query_route_disabled")
        elif effective_require_text_signal and text_score <= 0.0 and query_overlap_count <= 0:
            approved = False
            reason = "missing_text_signal"
        elif effective_min_text_score > 0.0 and text_score < effective_min_text_score:
            approved = False
            reason = "low_text_score"
        elif effective_require_answer_signal and not answer_signal:
            approved = False
            reason = "query_router_simple_missing_answer_signal"
        elif score < effective_min_score:
            approved = False
            reason = "low_score"

        return {
            "enabled": True,
            "approved": bool(approved),
            "reason": reason,
            "score": round(float(score), 6),
            "model_ready": self._rank_window_model_ready(),
            "model_path": self.rank_window_recall_model_path,
            "original_rank": int(original_rank),
            "start_rank": int(self.rank_window_recall_start_rank),
            "end_rank": int(self.rank_window_recall_end_rank),
            "rank_prior": round(float(rank_prior), 6),
            "dense_score": round(float(dense_score), 6),
            "dense_score_norm": round(float(dense_score_norm), 6),
            "text_score": round(float(text_score), 6),
            "text_signal_source": str(text_signal.get("source") or ""),
            "text_signal_reason": str(text_signal.get("reason") or ""),
            "query_overlap_count": int(query_overlap_count),
            "answer_overlap_count": int(answer_overlap_count),
            "relation_overlap_count": int(len(text_signal.get("relation_overlap", []) or [])),
            "anchor_hits": int(anchor_hits),
            "terminal_hits": int(terminal_hits),
            "answer_signal": bool(answer_signal),
            "query_pressure": round(float(query_pressure), 6),
            "candidate_confidence": round(float(confidence), 6),
            "has_ontology_context": bool(has_ontology_context),
            "min_score": self.rank_window_recall_min_score,
            "top2_min_score": self.rank_window_recall_top2_min_score,
            "router_bypass_min_score": self.rank_window_recall_router_bypass_min_score,
            "require_text_signal": bool(self.rank_window_recall_require_text_signal),
            "min_text_score": self.rank_window_recall_min_text_score,
            "query_route": query_route,
            "query_route_name": route_name,
            "query_route_reason": str(query_route.get("reason") or ""),
            "target_datasets": sorted(self.rank_window_recall_target_datasets),
            "target_dataset_allowed": bool(query_route.get("target_dataset_allowed", True)),
            "effective_min_score": round(float(effective_min_score), 6),
            "effective_min_text_score": round(float(effective_min_text_score), 6),
            "effective_router_bypass_min_score": round(
                self._safe_float(
                    query_route.get("router_bypass_min_score"),
                    self.rank_window_recall_router_bypass_min_score,
                ),
                6,
            ),
            "effective_require_text_signal": bool(effective_require_text_signal),
            "effective_require_answer_signal": bool(effective_require_answer_signal),
            "answer_signal_min_text_score": round(float(answer_signal_min_text_score), 6),
            "defer_to_planner": bool(self.rank_window_recall_defer_to_planner),
            "protect_original_top_k": int(self.rank_window_recall_protect_original_top_k),
            "min_replacement_rank": int(self.rank_window_recall_min_replacement_rank),
            "features": {key: round(float(value), 6) for key, value in feature_values.items()},
        }

    def _apply_rank_window_recall_score(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> str:
        previous_bonus = self._safe_float(item.pop("_rank_window_recall_score_bonus", 0.0), 0.0)
        if previous_bonus:
            item["score"] = self._safe_float(item.get("score"), 0.0) - previous_bonus
        profile = self._rank_window_recall_profile(item, query_plan_log)
        item["rank_window_recall"] = profile
        item.pop("_rank_window_recall_candidate", None)
        if not bool(profile.get("approved", False)):
            return str(profile.get("reason") or "rejected")

        score = self._safe_float(profile.get("score"), 0.0)
        bonus = self.rank_window_recall_score_weight * score
        item["_rank_window_recall_score_bonus"] = bonus
        item["_rank_window_recall_candidate"] = True
        bypass_allowed, bypass_reason = self._rank_window_no_new_slot_bypass_allowed(item, profile)
        profile["no_new_slot_bypass_allowed"] = bool(bypass_allowed)
        profile["no_new_slot_bypass_reason"] = str(bypass_reason)
        if bypass_allowed:
            item["_rank_window_recall_no_new_slot_bypass"] = True
        else:
            item.pop("_rank_window_recall_no_new_slot_bypass", None)
        item["score"] = self._safe_float(item.get("score"), 0.0) + bonus
        item["confidence"] = min(
            0.99,
            max(
                self._safe_float(item.get("confidence"), 0.0),
                self.rank_window_recall_confidence_floor + 0.12 * score,
            ),
        )
        item["effective_min_confidence"] = min(
            self._safe_float(item.get("effective_min_confidence"), self.min_candidate_confidence),
            max(0.42, self.rank_window_recall_confidence_floor),
        )
        return "rank_window_candidate"

    def _rank_window_no_new_slot_candidate(self, item: Mapping[str, Any]) -> bool:
        if self._safe_float(item.get("coverage_gain"), 0.0) > 0.0:
            return False
        if self._safe_int(item.get("decomposition_slot_gain"), 0) > 0:
            return False
        delta = item.get("delta", {}) or {}
        if isinstance(delta, Mapping):
            for key in ("new_roles", "new_anchors", "new_terminals", "new_relations", "new_plans", "new_facts"):
                if self._safe_int(delta.get(key), 0) > 0:
                    return False
        return True

    def _rank_window_no_new_slot_bypass_allowed(
        self,
        item: Mapping[str, Any],
        profile: Mapping[str, Any],
    ) -> Tuple[bool, str]:
        if not self._rank_window_no_new_slot_candidate(item):
            return False, "not_needed"
        if not self.rank_window_recall_allow_no_new_slot_bypass:
            return False, "disabled"
        route_name = str(profile.get("query_route_name") or "global")
        if route_name == "simple_entity":
            return False, "simple_entity_route"
        if not self.rank_window_recall_enable_net_benefit_gate:
            return True, "legacy_non_simple_route"

        score = self._safe_float(profile.get("score"), 0.0)
        text_score = self._safe_float(profile.get("text_score"), 0.0)
        if score < self.rank_window_recall_no_new_slot_min_score:
            return False, "low_score"
        if text_score < self.rank_window_recall_no_new_slot_min_text_score:
            return False, "low_text_score"

        path_aware = item.get("path_aware", {}) or {}
        path_approved = bool(isinstance(path_aware, Mapping) and path_aware.get("approved", False))
        terminal_hits = self._safe_int(profile.get("terminal_hits"), 0)
        answer_overlap = self._safe_int(profile.get("answer_overlap_count"), 0)
        relation_overlap = self._safe_int(profile.get("relation_overlap_count"), 0)
        query_overlap = self._safe_int(profile.get("query_overlap_count"), 0)
        has_structural_terminal = bool(item.get("has_terminal", False) and item.get("has_strict", False))
        has_path_or_terminal = (
            path_approved
            or terminal_hits > 0
            or answer_overlap > 0
            or has_structural_terminal
        )
        if self.rank_window_recall_no_new_slot_require_path_or_terminal and not has_path_or_terminal:
            return False, "missing_path_or_terminal"
        if not has_path_or_terminal and (relation_overlap <= 0 or query_overlap <= 1):
            return False, "weak_text_only_signal"
        return True, "net_benefit_signal"

    def _rank_window_source_prior(self, item: Mapping[str, Any]) -> float:
        source_policy = item.get("source_policy", {}) or {}
        if not isinstance(source_policy, Mapping):
            return 0.0
        return min(
            max(
                self._safe_float(source_policy.get("selected_precision"), 0.0),
                0.70 * self._safe_float(source_policy.get("precision"), 0.0),
                min(1.0, 3.0 * self._safe_float(source_policy.get("gt5_precision"), 0.0)),
            ),
            1.0,
        )

    def _rank_window_net_benefit_gate(
        self,
        item: Mapping[str, Any],
        candidate_value: float,
        replacement_value: float,
        target: str,
        replacement_rank: int,
        required_margin: float,
    ) -> Dict[str, Any]:
        profile = item.get("rank_window_recall", {}) or {}
        raw_margin = float(candidate_value) - float(replacement_value)
        if not self.rank_window_recall_enable_net_benefit_gate:
            return {
                "enabled": False,
                "approved": True,
                "reason": "disabled",
                "candidate_value": round(float(candidate_value), 6),
                "replacement_value": round(float(replacement_value), 6),
                "raw_margin": round(float(raw_margin), 6),
                "net_margin": round(float(raw_margin), 6),
                "required_margin": round(float(required_margin), 6),
            }

        delta = item.get("delta", {}) or {}
        if not isinstance(delta, Mapping):
            delta = {}
        path_aware = item.get("path_aware", {}) or {}
        path_approved = bool(isinstance(path_aware, Mapping) and path_aware.get("approved", False))
        score = self._safe_float(profile.get("score"), 0.0)
        text_score = self._safe_float(profile.get("text_score"), 0.0)
        dense_score_norm = self._safe_float(profile.get("dense_score_norm"), 0.0)
        rank_prior = self._safe_float(profile.get("rank_prior"), 0.0)
        terminal_hits = self._safe_int(profile.get("terminal_hits"), 0)
        answer_overlap = self._safe_int(profile.get("answer_overlap_count"), 0)
        relation_overlap = self._safe_int(profile.get("relation_overlap_count"), 0)
        query_overlap = self._safe_int(profile.get("query_overlap_count"), 0)
        coverage_gain = self._safe_float(item.get("coverage_gain"), 0.0)
        decomposition_gain = float(self._safe_int(item.get("decomposition_slot_gain"), 0))
        no_new_slot = self._rank_window_no_new_slot_candidate(item)
        has_strict = bool(item.get("has_strict", False))
        has_multihop = bool(item.get("has_multihop", False))
        has_terminal = bool(item.get("has_terminal", False))
        source_prior = self._rank_window_source_prior(item)
        structural_gain = min(
            0.30,
            0.050 * self._safe_int(delta.get("new_roles"), 0)
            + 0.055 * self._safe_int(delta.get("new_terminals"), 0)
            + 0.040 * self._safe_int(delta.get("new_relations"), 0)
            + 0.055 * self._safe_int(delta.get("new_plans"), 0)
            + 0.025 * self._safe_int(delta.get("new_anchors"), 0)
            + 0.035 * min(max(coverage_gain, 0.0), 3.0)
            + 0.060 * min(max(decomposition_gain, 0.0), 3.0),
        )
        strong_signal = (
            path_approved
            or terminal_hits > 0
            or answer_overlap > 0
            or (has_terminal and has_strict)
        )
        benefit = (
            structural_gain
            + 0.110 * min(max(score, 0.0), 1.0)
            + 0.160 * min(max(text_score, 0.0), 1.0)
            + 0.055 * min(max(dense_score_norm, 0.0), 1.0)
            + 0.035 * min(max(rank_prior, 0.0), 1.0)
            + 0.090 * source_prior
        )
        if path_approved:
            benefit += 0.090
        if bool(profile.get("answer_signal", False)):
            benefit += 0.060
        if terminal_hits > 0:
            benefit += min(0.090, 0.045 * terminal_hits)
        if answer_overlap > 0:
            benefit += min(0.080, 0.050 * answer_overlap)
        if has_strict and has_multihop:
            benefit += 0.080
        elif has_strict or has_multihop:
            benefit += 0.035

        displacement_cost = self.rank_window_recall_displacement_cost_weight * max(float(replacement_value), 0.0)
        no_new_slot_cost = 0.0
        if no_new_slot:
            no_new_slot_cost += 0.180
            if not bool(profile.get("no_new_slot_bypass_allowed", False)):
                no_new_slot_cost += 0.260
        weak_signal_cost = 0.0 if strong_signal else 0.150
        low_text_cost = max(0.0, self.rank_window_recall_no_new_slot_min_text_score - text_score) * (
            0.50 if no_new_slot else 0.24
        )
        relation_only_cost = 0.0
        if relation_overlap > 0 and terminal_hits <= 0 and answer_overlap <= 0 and not path_approved:
            relation_only_cost = 0.080
        rank_cost = 0.050 if int(replacement_rank) <= 5 and target != "append" else 0.0
        net_margin = (
            float(candidate_value)
            + benefit
            - displacement_cost
            - no_new_slot_cost
            - weak_signal_cost
            - low_text_cost
            - relation_only_cost
            - rank_cost
        )
        approved = bool(net_margin >= float(required_margin))
        reason = "approved" if approved else "low_net_benefit"
        return {
            "enabled": True,
            "approved": approved,
            "reason": reason,
            "target": str(target),
            "candidate_value": round(float(candidate_value), 6),
            "replacement_value": round(float(replacement_value), 6),
            "raw_margin": round(float(raw_margin), 6),
            "net_margin": round(float(net_margin), 6),
            "required_margin": round(float(required_margin), 6),
            "benefit": round(float(benefit), 6),
            "displacement_cost": round(float(displacement_cost), 6),
            "no_new_slot_cost": round(float(no_new_slot_cost), 6),
            "weak_signal_cost": round(float(weak_signal_cost), 6),
            "low_text_cost": round(float(low_text_cost), 6),
            "relation_only_cost": round(float(relation_only_cost), 6),
            "rank_cost": round(float(rank_cost), 6),
            "source_prior": round(float(source_prior), 6),
            "strong_signal": bool(strong_signal),
            "no_new_slot": bool(no_new_slot),
        }

    def _best_rank_window_recall_score(self, candidates: Sequence[Mapping[str, Any]]) -> float:
        return max(
            (
                self._safe_float((candidate.get("rank_window_recall", {}) or {}).get("score"), 0.0)
                for candidate in candidates
            ),
            default=0.0,
        )

    def _rank_window_router_override_ready(self, candidates: Sequence[Mapping[str, Any]]) -> bool:
        for candidate in candidates:
            profile = candidate.get("rank_window_recall", {}) or {}
            if not bool(candidate.get("_rank_window_recall_candidate", False)):
                continue
            score = self._safe_float(profile.get("score"), 0.0)
            threshold = self._safe_float(
                profile.get("effective_router_bypass_min_score"),
                self.rank_window_recall_router_bypass_min_score,
            )
            if score >= threshold:
                return True
        return False

    def _build_rank_window_recall_details(
        self,
        passage_details: Dict[int, Dict[str, Any]],
        base_doc_ids: Sequence[int],
        base_scores: Sequence[float],
        original_rank_by_doc: Mapping[int, int],
    ) -> Dict[str, Any]:
        stats = {
            "rank_window_recall_added_count": 0,
            "rank_window_recall_new_detail_count": 0,
            "rank_window_recall_merged_detail_count": 0,
            "rank_window_recall_candidate_samples": [],
        }
        if not self.enable_rank_window_recall:
            return stats
        if not base_doc_ids:
            return stats
        start = max(self.rank_window_recall_start_rank, 1)
        end = max(self.rank_window_recall_end_rank, start)
        if start > len(base_doc_ids):
            return stats
        end = min(end, len(base_doc_ids))
        window_scores = [
            self._safe_float(base_scores[idx], 0.0)
            for idx in range(start - 1, end)
            if idx < len(base_scores)
        ]
        max_score = max(window_scores, default=0.0)
        min_score = min(window_scores, default=max_score)
        score_span = max(max_score - min_score, 1e-8)
        rank_span = max(end - start + 1, 1)
        for zero_based_idx in range(start - 1, end):
            if zero_based_idx >= len(base_doc_ids):
                break
            passage_idx = int(base_doc_ids[zero_based_idx])
            original_rank = int(original_rank_by_doc.get(passage_idx, zero_based_idx + 1))
            dense_score = self._safe_float(
                base_scores[zero_based_idx] if zero_based_idx < len(base_scores) else 0.0,
                0.0,
            )
            rank_prior = 1.0 - min(max(original_rank - start, 0), rank_span - 1) / max(rank_span - 1, 1)
            dense_score_norm = (dense_score - min_score) / score_span if score_span > 1e-8 else rank_prior
            dense_score_norm = min(max(float(dense_score_norm), 0.0), 1.0)
            confidence = min(
                0.98,
                max(
                    self.rank_window_recall_confidence_floor,
                    self.rank_window_recall_confidence_floor + 0.18 * dense_score_norm + 0.08 * rank_prior,
                ),
            )
            contexts = [{
                "dense_rank_window": True,
                "schema_route_source": "dense_rank_window",
                "signature_match_mode": "dense_rank_window",
                "anchor_entity": "",
                "end_entity": "",
                "relations": [],
                "fact_indices": [],
                "plan_effective_precision": confidence,
                "plan_lift_weight_scale": 0.62,
                "dense_rank": int(original_rank),
                "dense_score": round(float(dense_score), 6),
                "dense_score_norm": round(float(dense_score_norm), 6),
                "rank_prior": round(float(rank_prior), 6),
            }]
            current = passage_details.get(passage_idx)
            if current is not None:
                current_contexts = list(current.get("contexts", []) or [])
                if not any(
                    isinstance(context, Mapping) and bool(context.get("dense_rank_window", False))
                    for context in current_contexts
                ):
                    current["contexts"] = current_contexts + contexts
                    stats["rank_window_recall_added_count"] += 1
                    stats["rank_window_recall_merged_detail_count"] += 1
                current["raw_lift_score"] = max(
                    self._safe_float(current.get("raw_lift_score"), 0.0),
                    confidence,
                )
                current["original_rank"] = min(
                    self._safe_int(current.get("original_rank"), original_rank),
                    int(original_rank),
                )
                decision = dict(current.get("reranker_decision", {}) or {})
                decision["confidence"] = max(self._safe_float(decision.get("confidence"), 0.0), confidence)
                source = str(decision.get("source", "") or "")
                if "dense_rank_window" not in source:
                    decision["source"] = f"{source}+dense_rank_window" if source else "dense_rank_window"
                current["reranker_decision"] = decision
            else:
                passage_details[passage_idx] = {
                    "passage_idx": passage_idx,
                    "raw_lift_score": confidence,
                    "original_rank": int(original_rank),
                    "contexts": contexts,
                    "reranker_decision": {
                        "confidence": confidence,
                        "source": "dense_rank_window",
                    },
                }
                stats["rank_window_recall_added_count"] += 1
                stats["rank_window_recall_new_detail_count"] += 1
            if len(stats["rank_window_recall_candidate_samples"]) < 12:
                stats["rank_window_recall_candidate_samples"].append({
                    "passage_idx": int(passage_idx),
                    "original_rank": int(original_rank),
                    "dense_score": round(float(dense_score), 6),
                    "dense_score_norm": round(float(dense_score_norm), 6),
                    "rank_prior": round(float(rank_prior), 6),
                    "merged": bool(current is not None),
                })
        return stats

    def _rank_window_candidate_value(self, item: Mapping[str, Any]) -> float:
        profile = item.get("rank_window_recall", {}) or {}
        score = self._safe_float(profile.get("score"), 0.0)
        text_score = self._safe_float(profile.get("text_score"), 0.0)
        dense_score_norm = self._safe_float(profile.get("dense_score_norm"), 0.0)
        rank_prior = self._safe_float(profile.get("rank_prior"), 0.0)
        confidence = self._safe_float(item.get("confidence"), 0.0)
        heuristic_value = (
            0.40 * score
            + 0.18 * dense_score_norm
            + 0.16 * rank_prior
            + 0.14 * text_score
            + 0.12 * confidence
        )
        if self.rank_window_recall_enable_net_benefit_gate and self._rank_window_no_new_slot_candidate(item):
            path_aware = item.get("path_aware", {}) or {}
            strong_signal = (
                bool(isinstance(path_aware, Mapping) and path_aware.get("approved", False))
                or self._safe_int(profile.get("terminal_hits"), 0) > 0
                or self._safe_int(profile.get("answer_overlap_count"), 0) > 0
            )
            heuristic_value *= 0.82 if strong_signal else 0.68
        return min(max(max(self._candidate_evidence_value(item), heuristic_value), 0.0), 1.25)

    def _evidence_warehouse_route(self, query_plan_log: Mapping[str, Any]) -> Dict[str, Any]:
        dataset = str(
            query_plan_log.get("dataset")
            or query_plan_log.get("dataset_name")
            or ""
        ).strip().lower()
        target_allowed = (
            not self.evidence_warehouse_target_datasets
            or dataset in self.evidence_warehouse_target_datasets
        )
        if not self.enable_evidence_warehouse_optimizer:
            reason = "disabled"
        elif not target_allowed:
            reason = "dataset_not_targeted"
        else:
            reason = "enabled"
        operator_profile = self._evidence_join_operator_profile(query_plan_log)
        return {
            "enabled": bool(self.enable_evidence_warehouse_optimizer and target_allowed),
            "reason": reason,
            "dataset": dataset,
            "target_datasets": sorted(self.evidence_warehouse_target_datasets),
            "operator": str(operator_profile.get("operator") or "single"),
            "chain_pressure": self._safe_float(operator_profile.get("chain_pressure"), 0.0),
            "complex": bool(operator_profile.get("complex", False)),
        }

    def _evidence_warehouse_selected_slots(
        self,
        selected: Sequence[int],
        passage_details: Mapping[int, Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
        exclude_doc: int = -1,
    ) -> Set[str]:
        slots: Set[str] = set()
        for doc_id in selected[: self.final_top_k]:
            doc_id = int(doc_id)
            if doc_id == int(exclude_doc):
                continue
            slots.update(self._evidence_join_doc_slots(doc_id, passage_details, query_plan_log))
        return slots

    def _evidence_warehouse_candidate_row(
        self,
        item: Mapping[str, Any],
        selected: Sequence[int],
        passage_details: Mapping[int, Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        confidence = self._safe_float(item.get("confidence"), 0.0)
        source_signature = self._candidate_source_signature(item)
        source_labels = self._candidate_source_labels(item)
        source_record = self._recall_plan_source_record(source_signature)
        source_policy = item.get("source_policy", {}) or {}
        if not isinstance(source_policy, Mapping):
            source_policy = {}
        source_precision = max(
            self._safe_float(source_record.get("precision"), 0.0),
            self._safe_float(source_record.get("selected_precision"), 0.0),
            self._safe_float(source_policy.get("selected_precision"), 0.0),
            0.75 * self._safe_float(source_policy.get("precision"), 0.0),
            2.0 * self._safe_float(source_policy.get("gt5_precision"), 0.0),
        )
        source_precision = min(max(float(source_precision), 0.0), 1.0)
        source_cost = min(max(self._safe_float(source_record.get("cost"), 0.50), 0.02), 1.0)
        recall_yield = min(max(self._safe_float(source_record.get("recall_yield"), 0.0), 0.0), 1.0)

        text_signal = self._rank_window_text_signal(item, query_plan_log)
        text_score = min(max(self._safe_float(text_signal.get("score"), 0.0), 0.0), 1.0)
        anchor_hits = self._safe_int(text_signal.get("anchor_hits"), 0)
        terminal_hits = self._safe_int(text_signal.get("terminal_hits"), 0)
        answer_overlap_count = len(text_signal.get("answer_overlap", []) or [])
        relation_overlap_count = len(text_signal.get("relation_overlap", []) or [])
        query_overlap_count = len(text_signal.get("query_overlap", []) or [])

        path_info = item.get("path_aware", {}) or {}
        if not isinstance(path_info, Mapping):
            path_info = {}
        path_score = self._safe_float(path_info.get("score"), 0.0) if bool(path_info.get("approved", False)) else 0.0

        join_profile = self._evidence_join_profile(item, query_plan_log)
        join_score = self._safe_float(join_profile.get("score"), 0.0)
        operator_score = self._safe_float(join_profile.get("operator_score"), 0.0)
        query_slot_value = self._safe_float(join_profile.get("query_slot_value"), 0.0)
        slots = set(join_profile.get("slots", []) or [])
        if not slots:
            slots = self._evidence_join_context_slots(self._all_candidate_contexts(item), query_plan_log)
        query_slots = self._evidence_join_query_slots(query_plan_log)
        selected_slots = self._evidence_warehouse_selected_slots(
            selected=selected,
            passage_details=passage_details,
            query_plan_log=query_plan_log,
        )
        novelty_slots = set(slots) - set(selected_slots)
        novelty_value = self._evidence_join_slot_value(novelty_slots, query_slots)

        features = self._intervention_features(item, query_plan_log)
        relation_only = bool(features.get("relation_only")) or bool(join_profile.get("relation_only", False))
        structural = (
            bool(join_profile.get("structural", False))
            or bool(features.get("has_endpoint_pair"))
            or bool(features.get("has_terminal_relation"))
            or bool(features.get("has_anchor_relation"))
            or bool(features.get("has_path_seed"))
            or bool(features.get("has_path_neighbor"))
            or bool(item.get("has_multihop"))
            or bool(item.get("has_strict"))
        )
        answer_signal = (
            answer_overlap_count > 0
            or terminal_hits > 0
            or (anchor_hits > 0 and (relation_overlap_count > 0 or query_overlap_count > 0))
            or text_score >= 0.34
            or path_score >= 0.58
            or bool(features.get("has_endpoint_pair"))
            or (bool(item.get("has_terminal")) and bool(item.get("has_relation")))
        )
        source_is_recall_access = bool(
            source_labels
            & {
                "evidence_grounded",
                "support",
                "path_executor",
                "evidence_index",
                "schema_slot_recall",
                "rank_window",
                "dense_rank_window",
                "recall_plan",
            }
        )
        candidate_value = self._candidate_evidence_value(item)
        query_pressure = self._source_gap_aperture_query_pressure(query_plan_log)
        rank_cost = 0.0
        if self.evidence_warehouse_max_original_rank > 0:
            rank_cost = min(float(original_rank) / float(max(self.evidence_warehouse_max_original_rank, 1)), 1.0)
        slot_signal = min((novelty_value + 0.65 * query_slot_value) / 1.6, 1.0)
        benefit = (
            0.14 * min(candidate_value, 1.0)
            + self.evidence_warehouse_source_weight * max(source_precision, 0.55 * recall_yield)
            + self.evidence_warehouse_text_weight * text_score
            + self.evidence_warehouse_path_weight * min(path_score, 1.0)
            + self.evidence_warehouse_slot_weight * slot_signal
            + 0.13 * join_score
            + 0.09 * operator_score
            + 0.07 * query_pressure
            + 0.05 * min(confidence, 1.0)
        )
        if structural:
            benefit += 0.04
        if source_is_recall_access:
            benefit += 0.035
        benefit = min(max(float(benefit), 0.0), 1.35)

        risk = 0.16 * rank_cost + 0.18 * source_cost
        if relation_only and not self.evidence_warehouse_allow_relation_only:
            risk += 0.28
        if self.evidence_warehouse_require_answer_signal and not answer_signal:
            risk += 0.20
        if novelty_value <= 0.0 and self._safe_float(item.get("coverage_gain"), 0.0) <= 0.0:
            risk += 0.08
        if source_precision < 0.04 and path_score < 0.58:
            risk += 0.08
        if text_score < 0.06 and not (path_score >= 0.58 or structural):
            risk += 0.08
        risk = min(max(float(risk), 0.0), 1.0)

        eligible_rank = (
            self.evidence_warehouse_max_original_rank <= 0
            or original_rank <= self.evidence_warehouse_max_original_rank
        )
        eligible_benefit = benefit >= self.evidence_warehouse_min_benefit
        eligible_answer = (not self.evidence_warehouse_require_answer_signal) or bool(answer_signal)
        eligible_relation = self.evidence_warehouse_allow_relation_only or not relation_only
        approved = bool(eligible_rank and eligible_benefit and eligible_answer and eligible_relation)
        reason = "approved"
        if not eligible_rank:
            reason = "rank_after_max_original_rank"
        elif not eligible_benefit:
            reason = "low_benefit"
        elif not eligible_answer:
            reason = "missing_answer_signal"
        elif not eligible_relation:
            reason = "relation_only"
        return {
            "enabled": True,
            "approved": approved,
            "reason": reason,
            "benefit": round(float(benefit), 6),
            "risk": round(float(risk), 6),
            "candidate_value": round(float(candidate_value), 6),
            "source_signature": source_signature,
            "source_labels": sorted(source_labels)[:16],
            "source_precision": round(float(source_precision), 6),
            "recall_yield": round(float(recall_yield), 6),
            "source_cost": round(float(source_cost), 6),
            "text_score": round(float(text_score), 6),
            "path_score": round(float(path_score), 6),
            "join_score": round(float(join_score), 6),
            "operator_score": round(float(operator_score), 6),
            "query_slot_value": round(float(query_slot_value), 6),
            "novelty_value": round(float(novelty_value), 6),
            "slot_signal": round(float(slot_signal), 6),
            "query_pressure": round(float(query_pressure), 6),
            "rank_cost": round(float(rank_cost), 6),
            "original_rank": int(original_rank),
            "answer_signal": bool(answer_signal),
            "relation_only": bool(relation_only),
            "structural": bool(structural),
            "source_is_recall_access": bool(source_is_recall_access),
            "candidate_slots": sorted(slots)[:80],
            "novelty_slots": sorted(novelty_slots)[:48],
            "query_slots": sorted(query_slots)[:48],
            "text_signal": {
                "source": str(text_signal.get("source") or ""),
                "anchor_hits": int(anchor_hits),
                "terminal_hits": int(terminal_hits),
                "answer_overlap_count": int(answer_overlap_count),
                "relation_overlap_count": int(relation_overlap_count),
                "query_overlap_count": int(query_overlap_count),
            },
        }

    def _pairwise_top2_join_route(self, query_plan_log: Mapping[str, Any]) -> Dict[str, Any]:
        dataset = str(
            query_plan_log.get("dataset")
            or query_plan_log.get("dataset_name")
            or ""
        ).strip().lower()
        target_allowed = (
            not self.pairwise_top2_join_target_datasets
            or dataset in self.pairwise_top2_join_target_datasets
        )
        if not self.enable_pairwise_top2_join:
            reason = "disabled"
        elif not target_allowed:
            reason = "dataset_not_targeted"
        elif self.pairwise_top2_join_max_swaps <= 0:
            reason = "zero_budget"
        else:
            reason = "enabled"
        operator_profile = self._evidence_join_operator_profile(query_plan_log)
        return {
            "enabled": bool(
                self.enable_pairwise_top2_join
                and target_allowed
                and self.pairwise_top2_join_max_swaps > 0
            ),
            "reason": reason,
            "dataset": dataset,
            "target_datasets": sorted(self.pairwise_top2_join_target_datasets),
            "operator": str(operator_profile.get("operator") or "single"),
            "chain_pressure": self._safe_float(operator_profile.get("chain_pressure"), 0.0),
            "complex": bool(operator_profile.get("complex", False)),
            "required_slots": list(operator_profile.get("required_slots", []) or [])[:80],
        }

    def _pairwise_top2_join_profile(
        self,
        doc_id: int,
        item: Optional[Dict[str, Any]],
        selected: Sequence[int],
        passage_details: Mapping[int, Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
        original_rank_by_doc: Mapping[int, int],
        max_raw_score: float,
    ) -> Dict[str, Any]:
        doc_id = int(doc_id)
        original_rank = int(original_rank_by_doc.get(doc_id, 10**9))
        detail = passage_details.get(doc_id, {}) or {}
        if detail:
            original_rank = min(original_rank, self._safe_int(detail.get("original_rank"), original_rank))
        synthetic_item = False
        if item is None:
            item = self._answer_pairwise_doc_item(
                doc_id=doc_id,
                original_rank=original_rank,
                passage_details=passage_details,
                max_raw_score=max_raw_score,
                query_plan_log=query_plan_log,
            )
            synthetic_item = True
        else:
            item = dict(item)
            item.setdefault("passage_idx", doc_id)
            item.setdefault("original_rank", original_rank)
            if "text_verifier" not in item:
                self._apply_text_verifier(item, query_plan_log)
            if "evidence_join_planner" not in item:
                item["evidence_join_planner"] = self._evidence_join_profile(item, query_plan_log)

        contexts = list(item.get("_all_contexts", item.get("contexts", [])) or [])
        if not contexts and detail:
            contexts = list(detail.get("contexts", []) or [])
        slots = self._evidence_join_context_slots(contexts, query_plan_log)
        join_profile = item.get("evidence_join_planner", {}) or {}
        if not isinstance(join_profile, Mapping):
            join_profile = self._evidence_join_profile(item, query_plan_log)
        text_signal = self._rank_window_text_signal(item, query_plan_log)
        text_info = item.get("text_verifier", {}) or {}
        if not isinstance(text_info, Mapping):
            text_info = {}
        text_score = max(
            self._safe_float(text_signal.get("score"), 0.0),
            self._safe_float(text_info.get("score"), 0.0),
            self._safe_float(join_profile.get("text_score"), 0.0),
        )
        anchor_hits = max(
            self._safe_int(text_signal.get("anchor_hits"), 0),
            self._safe_int(text_info.get("anchor_hits"), 0),
        )
        terminal_hits = max(
            self._safe_int(text_signal.get("terminal_hits"), 0),
            self._safe_int(text_info.get("terminal_hits"), 0),
        )
        answer_hits = max(
            len(text_signal.get("answer_overlap", []) or []),
            len(text_info.get("answer_overlap", []) or []),
        )
        relation_hits = max(
            len(text_signal.get("relation_overlap", []) or []),
            len(text_info.get("relation_overlap", []) or []),
        )
        query_hits = max(
            len(text_signal.get("query_overlap", []) or []),
            len(text_info.get("query_overlap", []) or []),
        )
        path_info = item.get("path_aware", {}) or {}
        if not isinstance(path_info, Mapping):
            path_info = {}
        path_score = self._safe_float(path_info.get("score"), 0.0) if bool(path_info.get("approved", False)) else 0.0
        source_policy = item.get("source_policy", {}) or {}
        if not isinstance(source_policy, Mapping):
            source_policy = {}
        source_signature = self._candidate_source_signature(item)
        source_record = self._recall_plan_source_record(source_signature)
        source_precision = max(
            self._safe_float(source_record.get("precision"), 0.0),
            self._safe_float(source_record.get("selected_precision"), 0.0),
            self._safe_float(source_policy.get("selected_precision"), 0.0),
            0.75 * self._safe_float(source_policy.get("precision"), 0.0),
            2.0 * self._safe_float(source_policy.get("gt5_precision"), 0.0),
            self._safe_float(join_profile.get("source_precision"), 0.0),
        )
        source_precision = min(max(float(source_precision), 0.0), 1.0)
        confidence = self._safe_float(item.get("confidence"), 0.0)
        baseline_value = self._baseline_replacement_value(
            doc_id=doc_id,
            original_rank=original_rank,
            passage_details=passage_details,
            max_raw_score=max_raw_score,
        )
        candidate_value = max(
            self._candidate_evidence_value(item),
            self._rank_window_candidate_value(item),
            0.72 * baseline_value,
        )
        relation_only = bool(join_profile.get("relation_only", False))
        structural = (
            bool(join_profile.get("structural", False))
            or bool(item.get("has_strict"))
            or bool(item.get("has_multihop"))
            or bool(item.get("has_terminal") and item.get("has_relation"))
        )
        answer_signal = (
            answer_hits > 0
            or terminal_hits > 0
            or text_score >= 0.34
            or path_score >= 0.58
            or (anchor_hits > 0 and (relation_hits > 0 or query_hits > 0))
            or structural
        )
        risk = 0.0
        if self.pairwise_top2_join_max_original_rank > 0:
            risk += 0.16 * min(
                float(original_rank) / float(max(self.pairwise_top2_join_max_original_rank, 1)),
                1.0,
            )
        if relation_only:
            risk += 0.24
        if not answer_signal:
            risk += 0.18
        if text_score < 0.06 and path_score < 0.58 and not structural:
            risk += 0.10
        if source_precision < 0.04 and path_score < 0.58:
            risk += 0.07
        return {
            "doc_id": int(doc_id),
            "item": item,
            "synthetic_item": bool(synthetic_item),
            "original_rank": int(original_rank),
            "slots": set(slots),
            "slot_value": self._safe_float(join_profile.get("slot_value"), 0.0),
            "query_slot_value": self._safe_float(join_profile.get("query_slot_value"), 0.0),
            "join_score": self._safe_float(join_profile.get("score"), 0.0),
            "operator_score": self._safe_float(join_profile.get("operator_score"), 0.0),
            "text_score": min(max(float(text_score), 0.0), 1.0),
            "anchor_hits": int(anchor_hits),
            "terminal_hits": int(terminal_hits),
            "answer_hits": int(answer_hits),
            "relation_hits": int(relation_hits),
            "query_hits": int(query_hits),
            "path_score": min(max(float(path_score), 0.0), 1.0),
            "source_precision": round(float(source_precision), 6),
            "confidence": min(max(float(confidence), 0.0), 1.0),
            "baseline_value": min(max(float(baseline_value), 0.0), 1.25),
            "candidate_value": min(max(float(candidate_value), 0.0), 1.25),
            "relation_only": bool(relation_only),
            "structural": bool(structural),
            "answer_signal": bool(answer_signal),
            "risk": min(max(float(risk), 0.0), 1.0),
            "source_signature": source_signature,
            "source_labels": sorted(self._candidate_source_labels(item))[:16],
        }

    def _pairwise_top2_join_score(
        self,
        first: Mapping[str, Any],
        second: Mapping[str, Any],
        current_profiles: Sequence[Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        query_slots = self._evidence_join_query_slots(query_plan_log)
        operator_profile = self._evidence_join_operator_profile(query_plan_log)
        required_slots = set(operator_profile.get("required_slots", []) or [])
        pair_slots = set(first.get("slots", set()) or set()) | set(second.get("slots", set()) or set())
        current_slots: Set[str] = set()
        for profile in current_profiles:
            current_slots.update(profile.get("slots", set()) or set())
        pair_slot_value = self._evidence_join_slot_value(pair_slots, query_slots)
        current_slot_value = self._evidence_join_slot_value(current_slots, query_slots)
        coverage_gain = pair_slot_value - current_slot_value
        if required_slots:
            pair_required = len(pair_slots & required_slots) / max(len(required_slots), 1)
            current_required = len(current_slots & required_slots) / max(len(required_slots), 1)
        else:
            pair_required = 0.0
            current_required = 0.0
        required_gain = pair_required - current_required

        text_scores = sorted(
            [self._safe_float(first.get("text_score"), 0.0), self._safe_float(second.get("text_score"), 0.0)],
            reverse=True,
        )
        max_text = text_scores[0] if text_scores else 0.0
        min_text = text_scores[1] if len(text_scores) > 1 else 0.0
        answer_count = int(bool(first.get("answer_signal", False))) + int(bool(second.get("answer_signal", False)))
        structural_count = int(bool(first.get("structural", False))) + int(bool(second.get("structural", False)))
        relation_only_count = int(bool(first.get("relation_only", False))) + int(bool(second.get("relation_only", False)))
        source_precision = max(
            self._safe_float(first.get("source_precision"), 0.0),
            self._safe_float(second.get("source_precision"), 0.0),
        )
        avg_source = (
            self._safe_float(first.get("source_precision"), 0.0)
            + self._safe_float(second.get("source_precision"), 0.0)
        ) / 2.0
        path_score = max(
            self._safe_float(first.get("path_score"), 0.0),
            self._safe_float(second.get("path_score"), 0.0),
        )
        value_score = min(
            (
                self._safe_float(first.get("candidate_value"), 0.0)
                + self._safe_float(second.get("candidate_value"), 0.0)
            ) / 2.0,
            1.0,
        )
        ranks = [
            self._safe_int(first.get("original_rank"), 10**9),
            self._safe_int(second.get("original_rank"), 10**9),
        ]
        rank_cost = min(
            sum(
                min(float(rank) / float(max(self.pairwise_top2_join_max_original_rank, 1)), 1.0)
                for rank in ranks
            )
            / max(len(ranks), 1),
            1.0,
        ) if self.pairwise_top2_join_max_original_rank > 0 else 0.0
        risk = (
            self._safe_float(first.get("risk"), 0.0)
            + self._safe_float(second.get("risk"), 0.0)
        ) / 2.0
        if relation_only_count >= 2:
            risk += 0.18
        first_slots = set(first.get("slots", set()) or set())
        second_slots = set(second.get("slots", set()) or set())
        shared_anchors = {
            slot for slot in first_slots & second_slots
            if slot.startswith("anchor:") or slot.startswith("terminal:")
        }
        complementary_query_slots = ((first_slots ^ second_slots) & query_slots)
        complement_score = min(float(len(complementary_query_slots)) / max(len(query_slots), 1), 1.0) if query_slots else 0.0
        bridge_score = 0.0
        if shared_anchors:
            bridge_score += 0.18
        if complement_score > 0.0:
            bridge_score += 0.22 * complement_score
        if structural_count >= 1 and answer_count >= 1:
            bridge_score += 0.16
        if str(operator_profile.get("operator") or "") in {"bridge", "comparison", "boolean"}:
            bridge_score += 0.14 * self._safe_float(operator_profile.get("chain_pressure"), 0.0)
        bridge_score = min(max(float(bridge_score), 0.0), 1.0)

        pair_score = (
            0.18 * min(pair_slot_value / 1.3, 1.0)
            + 0.13 * max(pair_required, 0.0)
            + 0.16 * max_text
            + 0.08 * min_text
            + 0.12 * min(float(answer_count) / 2.0, 1.0)
            + 0.11 * bridge_score
            + 0.08 * source_precision
            + 0.05 * avg_source
            + 0.07 * path_score
            + 0.06 * min(float(structural_count) / 2.0, 1.0)
            + 0.08 * value_score
            - 0.07 * rank_cost
            - 0.08 * min(max(float(risk), 0.0), 1.0)
        )
        pair_score = min(max(float(pair_score), 0.0), 1.2)
        return {
            "pair_score": round(float(pair_score), 6),
            "pair_slot_value": round(float(pair_slot_value), 6),
            "current_slot_value": round(float(current_slot_value), 6),
            "coverage_gain": round(float(coverage_gain), 6),
            "pair_required_coverage": round(float(pair_required), 6),
            "current_required_coverage": round(float(current_required), 6),
            "required_gain": round(float(required_gain), 6),
            "max_text_score": round(float(max_text), 6),
            "min_text_score": round(float(min_text), 6),
            "answer_count": int(answer_count),
            "structural_count": int(structural_count),
            "relation_only_count": int(relation_only_count),
            "source_precision": round(float(source_precision), 6),
            "path_score": round(float(path_score), 6),
            "bridge_score": round(float(bridge_score), 6),
            "rank_cost": round(float(rank_cost), 6),
            "risk": round(float(min(max(risk, 0.0), 1.0)), 6),
            "operator": str(operator_profile.get("operator") or "single"),
            "query_slots": sorted(query_slots)[:48],
            "pair_query_overlap": sorted(pair_slots & query_slots)[:48],
            "complementary_query_slots": sorted(complementary_query_slots)[:32],
            "shared_anchors": sorted(shared_anchors)[:16],
        }

    def _pairwise_top2_join_displacement_cost(
        self,
        pair_docs: Sequence[int],
        before_top2: Sequence[int],
        profiles: Mapping[int, Mapping[str, Any]],
        score_profile: Mapping[str, Any],
        simple_route: bool,
    ) -> Tuple[float, Dict[str, Any]]:
        pair_set = {int(doc_id) for doc_id in pair_docs}
        displaced: List[Dict[str, Any]] = []
        raw_cost = 0.0
        top1_replaced = bool(before_top2 and int(before_top2[0]) not in pair_set)

        for doc_id in before_top2:
            doc_id = int(doc_id)
            if doc_id in pair_set:
                continue
            profile = profiles.get(doc_id, {})
            original_rank = self._safe_int(profile.get("original_rank"), 10**9)
            text_score = self._safe_float(profile.get("text_score"), 0.0)
            path_score = self._safe_float(profile.get("path_score"), 0.0)
            source_precision = self._safe_float(profile.get("source_precision"), 0.0)
            candidate_value = self._safe_float(profile.get("candidate_value"), 0.0)
            confidence = self._safe_float(profile.get("confidence"), 0.0)
            risk = self._safe_float(profile.get("risk"), 0.0)

            if original_rank <= 1:
                rank_cost = 0.20
            elif original_rank <= 2:
                rank_cost = 0.13
            elif original_rank <= 5:
                rank_cost = 0.06
            else:
                rank_cost = 0.025

            doc_cost = (
                rank_cost
                + 0.08 * min(max(text_score, 0.0), 1.0)
                + 0.07 * min(max(candidate_value, 0.0), 1.0)
                + 0.045 * min(max(source_precision, 0.0), 1.0)
                + 0.050 * min(max(path_score, 0.0), 1.0)
                + 0.030 * min(max(confidence, 0.0), 1.0)
                + 0.025 * (1.0 - min(max(risk, 0.0), 1.0))
            )
            if bool(profile.get("answer_signal", False)):
                doc_cost += 0.055
            if bool(profile.get("structural", False)):
                doc_cost += 0.035
            if bool(profile.get("relation_only", False)):
                doc_cost -= 0.030
            if simple_route:
                doc_cost += 0.060
            raw_cost += max(float(doc_cost), 0.0)
            displaced.append({
                "doc_id": int(doc_id),
                "original_rank": int(original_rank),
                "text_score": round(float(text_score), 6),
                "candidate_value": round(float(candidate_value), 6),
                "answer_signal": bool(profile.get("answer_signal", False)),
                "structural": bool(profile.get("structural", False)),
                "relation_only": bool(profile.get("relation_only", False)),
                "doc_cost": round(float(max(doc_cost, 0.0)), 6),
            })

        if top1_replaced:
            raw_cost += 0.10
        if simple_route and displaced:
            raw_cost += 0.04 * float(len(displaced))

        answer_count = self._safe_int(score_profile.get("answer_count"), 0)
        max_text = self._safe_float(score_profile.get("max_text_score"), 0.0)
        min_text = self._safe_float(score_profile.get("min_text_score"), 0.0)
        source_precision = self._safe_float(score_profile.get("source_precision"), 0.0)
        path_score = self._safe_float(score_profile.get("path_score"), 0.0)
        coverage_gain = self._safe_float(score_profile.get("coverage_gain"), 0.0)
        required_gain = self._safe_float(score_profile.get("required_gain"), 0.0)
        bridge_score = self._safe_float(score_profile.get("bridge_score"), 0.0)
        evidence_credit = (
            0.035 * min(max(max_text, 0.0), 1.0)
            + 0.025 * min(max(min_text, 0.0), 1.0)
            + 0.035 * min(float(answer_count) / 2.0, 1.0)
            + 0.025 * min(max(source_precision, 0.0), 1.0)
            + 0.025 * min(max(path_score, 0.0), 1.0)
            + 0.020 * min(max(bridge_score, 0.0), 1.0)
            + 0.020 * min(max(coverage_gain, 0.0) / 0.5, 1.0)
            + 0.020 * min(max(required_gain, 0.0) / 0.35, 1.0)
        )
        cost = max(0.0, raw_cost - evidence_credit)
        details = {
            "cost": round(float(cost), 6),
            "raw_cost": round(float(raw_cost), 6),
            "evidence_credit": round(float(evidence_credit), 6),
            "top1_replaced": bool(top1_replaced),
            "simple_route": bool(simple_route),
            "displaced_docs": displaced,
        }
        return round(float(cost), 6), details

    def _apply_pairwise_top2_join_optimizer(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
    ) -> Dict[str, Any]:
        route = self._pairwise_top2_join_route(query_plan_log)
        stats: Dict[str, Any] = {
            "enabled": bool(self.enable_pairwise_top2_join),
            "route_enabled": bool(route.get("enabled", False)),
            "route_reason": str(route.get("reason") or "not_evaluated"),
            "route_dataset": str(route.get("dataset") or ""),
            "operator": str(route.get("operator") or "single"),
            "candidate_count": 0,
            "pair_count": 0,
            "selected_count": 0,
            "changed_top2": False,
            "changed_top5": False,
            "current_pair_score": 0.0,
            "best_pair_score": 0.0,
            "best_margin": 0.0,
            "best_net_margin": 0.0,
            "best_displacement_cost": 0.0,
            "best_pair": [],
            "rejection_reasons": {},
            "selected_candidates": [],
            "row_samples": [],
        }
        if not bool(route.get("enabled", False)):
            return stats
        if len(selected) < 2:
            stats["rejection_reasons"] = {"short_selected_window": 1}
            return stats

        before_top2 = [int(doc_id) for doc_id in selected[:2]]
        before_top5 = [int(doc_id) for doc_id in selected[: self.final_top_k]]
        item_by_doc: Dict[int, Dict[str, Any]] = {}
        for item in candidates:
            doc_id = int(item.get("passage_idx", -1))
            if doc_id >= 0 and doc_id not in item_by_doc:
                item_by_doc[doc_id] = item

        pool_docs: List[int] = []
        for doc_id in selected[: self.final_top_k]:
            doc_id = int(doc_id)
            if doc_id not in pool_docs:
                pool_docs.append(doc_id)
        presorted = [
            item for item in candidates
            if int(item.get("passage_idx", -1)) >= 0
            and (
                self.pairwise_top2_join_max_original_rank <= 0
                or self._safe_int(item.get("original_rank"), 10**9)
                <= self.pairwise_top2_join_max_original_rank
            )
        ]
        presorted.sort(
            key=lambda item: (
                self._candidate_evidence_value(item),
                self._safe_float((item.get("evidence_warehouse_optimizer", {}) or {}).get("benefit"), 0.0),
                self._safe_float((item.get("evidence_join_planner", {}) or {}).get("score"), 0.0),
                self._safe_float((item.get("rank_window_recall", {}) or {}).get("score"), 0.0),
                self._safe_float(item.get("confidence"), 0.0),
                -self._safe_int(item.get("original_rank"), 10**9),
            ),
            reverse=True,
        )
        for item in presorted:
            doc_id = int(item.get("passage_idx", -1))
            if doc_id < 0 or doc_id in pool_docs:
                continue
            pool_docs.append(doc_id)
            if len(pool_docs) >= self.pairwise_top2_join_candidate_pool:
                break
        stats["candidate_count"] = int(len(pool_docs))

        profiles: Dict[int, Dict[str, Any]] = {}
        for doc_id in pool_docs:
            profile = self._pairwise_top2_join_profile(
                doc_id=doc_id,
                item=item_by_doc.get(int(doc_id)),
                selected=selected,
                passage_details=passage_details,
                query_plan_log=query_plan_log,
                original_rank_by_doc=original_rank_by_doc,
                max_raw_score=max_raw_score,
            )
            profiles[int(doc_id)] = profile
            if len(stats["row_samples"]) < 18:
                stats["row_samples"].append({
                    "doc_id": int(doc_id),
                    "original_rank": int(profile.get("original_rank", 0) or 0),
                    "text_score": self._safe_float(profile.get("text_score"), 0.0),
                    "path_score": self._safe_float(profile.get("path_score"), 0.0),
                    "source_precision": self._safe_float(profile.get("source_precision"), 0.0),
                    "candidate_value": self._safe_float(profile.get("candidate_value"), 0.0),
                    "answer_signal": bool(profile.get("answer_signal", False)),
                    "relation_only": bool(profile.get("relation_only", False)),
                    "synthetic_item": bool(profile.get("synthetic_item", False)),
                })

        current_profiles = [profiles[doc_id] for doc_id in before_top2 if doc_id in profiles]
        if len(current_profiles) < 2:
            stats["rejection_reasons"] = {"missing_current_profiles": 1}
            return stats
        current_score_profile = self._pairwise_top2_join_score(
            current_profiles[0],
            current_profiles[1],
            current_profiles=current_profiles,
            query_plan_log=query_plan_log,
        )
        current_pair_score = self._safe_float(current_score_profile.get("pair_score"), 0.0)
        stats["current_pair_score"] = round(float(current_pair_score), 6)
        current_pair_risk = self._safe_float(current_score_profile.get("risk"), 0.0)
        current_retrieval_value = sum(
            self._safe_float(profile.get("candidate_value"), 0.0)
            for profile in current_profiles
        ) / max(1, len(current_profiles))
        route_dataset = str(route.get("dataset") or "").lower()
        route_operator = str(route.get("operator") or "single").lower()
        route_chain_pressure = self._safe_float(route.get("chain_pressure"), 0.0)
        simple_pairwise_route = bool(
            route_dataset in {"nq_rear", "popqa"}
            or (
                not bool(route.get("complex", False))
                and route_operator in {"single", "entity", "lookup", "attribute"}
                and route_chain_pressure < 0.18
            )
        )
        stats["simple_route_guard"] = bool(simple_pairwise_route)
        stats["current_retrieval_value"] = round(float(current_retrieval_value), 6)
        stats["current_pair_risk"] = round(float(current_pair_risk), 6)

        rejections = Counter()
        best: Optional[Tuple[float, float, float, Tuple[int, int], Dict[str, Any]]] = None
        current_set = set(before_top2)
        for i, first_doc in enumerate(pool_docs):
            for second_doc in pool_docs[i + 1:]:
                first_doc = int(first_doc)
                second_doc = int(second_doc)
                pair_docs = (first_doc, second_doc)
                outside_count = sum(1 for doc_id in pair_docs if doc_id not in current_set)
                if outside_count <= 0:
                    rejections["same_as_current_top2"] += 1
                    continue
                if outside_count > self.pairwise_top2_join_max_swaps:
                    rejections["outside_swap_budget"] += 1
                    continue
                if self.pairwise_top2_join_protect_top1 and before_top2[0] not in pair_docs:
                    rejections["protect_top1"] += 1
                    continue
                first = profiles.get(first_doc)
                second = profiles.get(second_doc)
                if not first or not second:
                    rejections["missing_profile"] += 1
                    continue
                if self.pairwise_top2_join_max_original_rank > 0 and any(
                    self._safe_int(profile.get("original_rank"), 10**9)
                    > self.pairwise_top2_join_max_original_rank
                    for profile in (first, second)
                    if int(profile.get("doc_id", -1)) not in current_set
                ):
                    rejections["rank_after_max_original_rank"] += 1
                    continue
                score_profile = self._pairwise_top2_join_score(
                    first,
                    second,
                    current_profiles=current_profiles,
                    query_plan_log=query_plan_log,
                )
                stats["pair_count"] = int(stats["pair_count"]) + 1
                pair_score = self._safe_float(score_profile.get("pair_score"), 0.0)
                margin = pair_score - current_pair_score
                score_profile["margin"] = round(float(margin), 6)
                if pair_score < self.pairwise_top2_join_min_pair_score:
                    rejections["low_pair_score"] += 1
                    continue
                if margin < self.pairwise_top2_join_min_margin:
                    rejections["low_margin"] += 1
                    continue
                coverage_gain = self._safe_float(score_profile.get("coverage_gain"), 0.0)
                required_gain = self._safe_float(score_profile.get("required_gain"), 0.0)
                max_text_score = self._safe_float(score_profile.get("max_text_score"), 0.0)
                min_text_score = self._safe_float(score_profile.get("min_text_score"), 0.0)
                answer_count = self._safe_int(score_profile.get("answer_count"), 0)
                pair_risk = self._safe_float(score_profile.get("risk"), 0.0)
                pair_retrieval_value = (
                    self._safe_float(first.get("candidate_value"), 0.0)
                    + self._safe_float(second.get("candidate_value"), 0.0)
                ) / 2.0
                top1_replaced = bool(before_top2 and before_top2[0] not in pair_docs)
                displacement_cost, displacement_details = self._pairwise_top2_join_displacement_cost(
                    pair_docs=pair_docs,
                    before_top2=before_top2,
                    profiles=profiles,
                    score_profile=score_profile,
                    simple_route=simple_pairwise_route,
                )
                net_margin = margin - displacement_cost
                score_profile["displacement_cost"] = round(float(displacement_cost), 6)
                score_profile["displacement"] = displacement_details
                score_profile["net_margin"] = round(float(net_margin), 6)
                score_profile["pair_retrieval_value"] = round(float(pair_retrieval_value), 6)
                score_profile["current_retrieval_value"] = round(float(current_retrieval_value), 6)
                if net_margin < max(self.pairwise_top2_join_min_margin, 0.0):
                    rejections["negative_net_displacement_margin"] += 1
                    continue
                if top1_replaced and (
                    net_margin < max(self.pairwise_top2_join_min_margin + 0.030, 0.045)
                    or margin < max(self.pairwise_top2_join_min_margin + 0.040, 0.055)
                    or max_text_score < max(self.pairwise_top2_join_min_text_score, 0.20)
                    or answer_count <= 0
                ):
                    rejections["unsafe_top1_replacement"] += 1
                    continue
                if simple_pairwise_route:
                    if top1_replaced:
                        rejections["simple_protect_top1"] += 1
                        continue
                    if answer_count <= 0 or max_text_score < max(self.pairwise_top2_join_min_text_score, 0.18):
                        rejections["simple_weak_answer_signal"] += 1
                        continue
                    if min_text_score < max(self.pairwise_top2_join_min_second_text_score, 0.06):
                        rejections["simple_weak_second_text"] += 1
                        continue
                    if margin < max(self.pairwise_top2_join_min_margin + 0.040, 0.055):
                        rejections["simple_low_margin"] += 1
                        continue
                    if net_margin < max(self.pairwise_top2_join_min_margin + 0.025, 0.040):
                        rejections["simple_negative_net_margin"] += 1
                        continue
                    if (
                        pair_retrieval_value + 0.040 < current_retrieval_value
                        and coverage_gain < 0.16
                        and required_gain < 0.25
                    ):
                        rejections["simple_retrieval_value_loss"] += 1
                        continue
                if (
                    pair_retrieval_value + 0.080 < current_retrieval_value
                    and coverage_gain < 0.12
                    and required_gain < 0.20
                ):
                    rejections["retrieval_value_loss"] += 1
                    continue
                if pair_risk > current_pair_risk + 0.16 and coverage_gain < 0.18:
                    rejections["risk_regression"] += 1
                    continue
                if (
                    coverage_gain < self.pairwise_top2_join_min_coverage_gain
                    and required_gain < 0.10
                    and margin < self.pairwise_top2_join_min_margin + 0.035
                ):
                    rejections["low_coverage_gain"] += 1
                    continue
                if max_text_score < self.pairwise_top2_join_min_text_score:
                    rejections["weak_pair_text"] += 1
                    continue
                second_text_ok = (
                    min_text_score >= self.pairwise_top2_join_min_second_text_score
                    or any(
                        bool(profile.get("answer_signal", False))
                        or self._safe_float(profile.get("path_score"), 0.0) >= 0.58
                        or bool(profile.get("structural", False))
                        for profile in (first, second)
                    )
                )
                if not second_text_ok:
                    rejections["weak_second_evidence"] += 1
                    continue
                if self.pairwise_top2_join_require_answer_signal and answer_count <= 0:
                    rejections["missing_answer_signal"] += 1
                    continue
                if self._safe_int(score_profile.get("relation_only_count"), 0) >= 2:
                    rejections["both_relation_only"] += 1
                    continue
                if self._safe_float(score_profile.get("risk"), 0.0) > 0.64:
                    rejections["high_pair_risk"] += 1
                    continue
                ordered_pair = tuple(
                    doc_id for _, doc_id in sorted(
                        [
                            (
                                -self._safe_float(profiles[doc_id].get("candidate_value"), 0.0),
                                doc_id,
                            )
                            for doc_id in pair_docs
                        ],
                        key=lambda row: (row[0], self._safe_int(profiles[row[1]].get("original_rank"), 10**9)),
                    )
                )
                if self.pairwise_top2_join_protect_top1 and before_top2[0] in ordered_pair:
                    ordered_pair = (
                        before_top2[0],
                        ordered_pair[0] if ordered_pair[1] == before_top2[0] else ordered_pair[1],
                    )
                ranking_key = (net_margin, margin, pair_score)
                if best is None or ranking_key > (best[0], best[1], best[2]):
                    best = (
                        net_margin,
                        margin,
                        pair_score,
                        (int(ordered_pair[0]), int(ordered_pair[1])),
                        score_profile,
                    )

        stats["rejection_reasons"] = dict(rejections)
        if best is None:
            return stats
        best_net_margin, best_margin, best_score, best_pair, best_profile = best
        stats["best_pair_score"] = round(float(best_score), 6)
        stats["best_margin"] = round(float(best_margin), 6)
        stats["best_net_margin"] = round(float(best_net_margin), 6)
        stats["best_displacement_cost"] = self._safe_float(
            best_profile.get("displacement_cost"),
            0.0,
        )
        stats["best_pair"] = [int(best_pair[0]), int(best_pair[1])]
        stats["best_profile"] = best_profile

        new_selected = [int(best_pair[0]), int(best_pair[1])]
        for doc_id in selected:
            doc_id = int(doc_id)
            if doc_id not in new_selected:
                new_selected.append(doc_id)
        for doc_id in base_doc_ids:
            doc_id = int(doc_id)
            if doc_id not in new_selected:
                new_selected.append(doc_id)
        selected[:] = new_selected
        selected_set.clear()
        selected_set.update(int(doc_id) for doc_id in selected)

        after_top2 = [int(doc_id) for doc_id in selected[:2]]
        after_top5 = [int(doc_id) for doc_id in selected[: self.final_top_k]]
        stats["changed_top2"] = bool(before_top2 != after_top2)
        stats["changed_top5"] = bool(before_top5 != after_top5)
        selected_docs = [doc_id for doc_id in after_top2 if doc_id not in before_top2]
        stats["selected_count"] = int(len(selected_docs))
        for doc_id in selected_docs:
            profile = profiles.get(int(doc_id), {})
            item = profile.get("item") if isinstance(profile, Mapping) else None
            if not isinstance(item, dict):
                continue
            item["_pairwise_top2_join_selected"] = True
            item["_pairwise_top2_join_replaced_docs"] = [doc for doc in before_top2 if doc not in after_top2]
            item["pairwise_top2_join"] = {
                "enabled": True,
                "pair_score": round(float(best_score), 6),
                "margin": round(float(best_margin), 6),
                "net_margin": round(float(best_net_margin), 6),
                "displacement_cost": self._safe_float(best_profile.get("displacement_cost"), 0.0),
                "pair_docs": [int(best_pair[0]), int(best_pair[1])],
                "profile": best_profile,
            }
            if not any(int(prev.get("passage_idx", -1)) == int(doc_id) for prev in selected_ontology):
                selected_ontology.append(item)
            if len(stats["selected_candidates"]) < 12:
                stats["selected_candidates"].append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason="pairwise_top2_join_selected",
                        final_rank=int(after_top2.index(int(doc_id)) + 1),
                    )
                )
        return stats

    def _decomposed_chain_join_route(self, query_plan_log: Mapping[str, Any]) -> Dict[str, Any]:
        dataset = str(
            query_plan_log.get("dataset")
            or query_plan_log.get("dataset_name")
            or ""
        ).strip().lower()
        target_allowed = (
            not self.decomposed_chain_join_target_datasets
            or dataset in self.decomposed_chain_join_target_datasets
        )
        slot_completion_allowed = bool(
            self.decomposed_chain_join_enable_slot_completion_promotion
            and (
                not self.decomposed_chain_join_slot_completion_target_datasets
                or dataset in self.decomposed_chain_join_slot_completion_target_datasets
            )
        )
        operator_profile = self._evidence_join_operator_profile(query_plan_log)
        if not self.enable_decomposed_chain_join:
            reason = "disabled"
        elif not target_allowed:
            reason = "dataset_not_targeted"
        elif self.decomposed_chain_join_max_swaps <= 0:
            reason = "zero_budget"
        elif (
            self.decomposed_chain_join_enable_decomposition
            and not bool(operator_profile.get("complex", False))
            and str(operator_profile.get("operator") or "single") in {"single", "entity", "lookup", "attribute"}
            and not slot_completion_allowed
        ):
            reason = "simple_operator"
        else:
            reason = "enabled"
        return {
            "enabled": reason == "enabled",
            "reason": reason,
            "dataset": dataset,
            "target_datasets": sorted(self.decomposed_chain_join_target_datasets),
            "operator": str(operator_profile.get("operator") or "single"),
            "complex": bool(operator_profile.get("complex", False)),
            "chain_pressure": self._safe_float(operator_profile.get("chain_pressure"), 0.0),
            "slot_completion_allowed": bool(slot_completion_allowed),
        }

    def _decomposed_chain_slot_groups(
        self,
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Set[str]]:
        query_slots = self._evidence_join_query_slots(query_plan_log)
        operator_profile = self._evidence_join_operator_profile(query_plan_log)
        required_slots = set(operator_profile.get("required_slots", []) or []) or set(query_slots)
        if not self.decomposed_chain_join_enable_decomposition:
            return {
                "anchor": set(),
                "bridge": set(),
                "answer": set(),
                "relation": set(),
                "required": set(required_slots),
                "query": set(query_slots),
            }

        anchor_slots = {slot for slot in required_slots | query_slots if slot.startswith("anchor:")}
        relation_slots = {
            slot for slot in required_slots | query_slots
            if slot.startswith("relation:") or slot.startswith("relation_token:")
        }
        answer_slots = {
            slot for slot in required_slots | query_slots
            if slot.startswith("answer_type:") or slot.startswith("terminal:")
        }
        bridge_slots = {
            slot for slot in required_slots | query_slots
            if (
                slot == "fact_linked"
                or slot == "source:path_executor"
                or slot.startswith("endpoint:")
                or slot.startswith("anchor_relation:")
                or slot.startswith("terminal_relation:")
                or slot.startswith("path_plan:")
            )
        }
        if relation_slots:
            bridge_slots.update(relation_slots)
        if not bridge_slots and str(operator_profile.get("operator") or "") in {"bridge", "comparison", "boolean"}:
            bridge_slots.add("fact_linked")
        return {
            "anchor": anchor_slots,
            "bridge": bridge_slots,
            "answer": answer_slots,
            "relation": relation_slots,
            "required": required_slots,
            "query": query_slots,
        }

    def _decomposed_chain_doc_roles(
        self,
        profile: Mapping[str, Any],
        slot_groups: Mapping[str, Set[str]],
    ) -> Set[str]:
        slots = set(profile.get("slots", set()) or set())
        roles: Set[str] = set()
        if slots & set(slot_groups.get("anchor", set())) or self._safe_int(profile.get("anchor_hits"), 0) > 0:
            roles.add("anchor")
        if (
            slots & set(slot_groups.get("bridge", set()))
            or self._safe_int(profile.get("relation_hits"), 0) > 0
            or self._safe_float(profile.get("path_score"), 0.0) >= 0.55
            or bool(profile.get("structural", False))
            or any(
                str(slot).startswith(("endpoint:", "anchor_relation:", "terminal_relation:"))
                for slot in slots
            )
        ):
            roles.add("bridge")
        if (
            slots & set(slot_groups.get("answer", set()))
            or self._safe_int(profile.get("terminal_hits"), 0) > 0
            or self._safe_int(profile.get("answer_hits"), 0) > 0
            or bool(profile.get("answer_signal", False))
        ):
            roles.add("answer")
        if slots & set(slot_groups.get("relation", set())):
            roles.add("relation")
        if not roles and self._safe_float(profile.get("text_score"), 0.0) >= 0.24:
            roles.add("lexical")
        return roles

    def _decomposed_chain_profile(
        self,
        doc_id: int,
        item: Optional[Dict[str, Any]],
        selected: Sequence[int],
        passage_details: Mapping[int, Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
        original_rank_by_doc: Mapping[int, int],
        max_raw_score: float,
        slot_groups: Mapping[str, Set[str]],
    ) -> Dict[str, Any]:
        profile = self._pairwise_top2_join_profile(
            doc_id=doc_id,
            item=item,
            selected=selected,
            passage_details=passage_details,
            query_plan_log=query_plan_log,
            original_rank_by_doc=original_rank_by_doc,
            max_raw_score=max_raw_score,
        )
        roles = self._decomposed_chain_doc_roles(profile, slot_groups)
        slots = set(profile.get("slots", set()) or set())
        required_slots = set(slot_groups.get("required", set()) or set())
        query_slots = set(slot_groups.get("query", set()) or set())
        required_overlap = slots & required_slots
        query_overlap = slots & query_slots
        role_credit = min(float(len(roles & {"anchor", "bridge", "answer"})) / 3.0, 1.0)
        slot_credit = self._evidence_join_slot_value(required_overlap | query_overlap, query_slots)
        if required_slots:
            required_coverage = len(required_overlap) / max(len(required_slots), 1)
        else:
            required_coverage = 0.0
        subquery_access_score = (
            0.22 * role_credit
            + 0.20 * min(slot_credit / 1.1, 1.0)
            + 0.16 * min(max(required_coverage, 0.0), 1.0)
            + 0.13 * self._safe_float(profile.get("text_score"), 0.0)
            + 0.10 * self._safe_float(profile.get("path_score"), 0.0)
            + 0.08 * self._safe_float(profile.get("source_precision"), 0.0)
            + 0.07 * min(self._safe_float(profile.get("candidate_value"), 0.0), 1.0)
            + 0.04 * self._safe_float(profile.get("confidence"), 0.0)
        )
        if bool(profile.get("relation_only", False)) and "answer" not in roles:
            subquery_access_score -= 0.08
        profile["decomposed_chain_roles"] = sorted(roles)
        profile["decomposed_chain_required_overlap"] = sorted(required_overlap)[:48]
        profile["decomposed_chain_query_overlap"] = sorted(query_overlap)[:48]
        profile["decomposed_chain_required_coverage"] = round(float(required_coverage), 6)
        profile["decomposed_chain_subquery_access_score"] = round(
            float(min(max(subquery_access_score, 0.0), 1.2)),
            6,
        )
        return profile

    def _decomposed_chain_score(
        self,
        first: Mapping[str, Any],
        second: Mapping[str, Any],
        current_profiles: Sequence[Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
        slot_groups: Mapping[str, Set[str]],
    ) -> Dict[str, Any]:
        pairwise_profile = self._pairwise_top2_join_score(
            first,
            second,
            current_profiles=current_profiles,
            query_plan_log=query_plan_log,
        )
        query_slots = set(slot_groups.get("query", set()) or set())
        required_slots = set(slot_groups.get("required", set()) or set())
        pair_slots = set(first.get("slots", set()) or set()) | set(second.get("slots", set()) or set())
        current_slots: Set[str] = set()
        for profile in current_profiles:
            current_slots.update(profile.get("slots", set()) or set())
        pair_roles = set(first.get("decomposed_chain_roles", []) or []) | set(
            second.get("decomposed_chain_roles", []) or []
        )
        current_roles: Set[str] = set()
        for profile in current_profiles:
            current_roles.update(profile.get("decomposed_chain_roles", []) or [])

        important_roles = {"anchor", "bridge", "answer"}
        pair_role_coverage = len(pair_roles & important_roles) / float(len(important_roles))
        current_role_coverage = len(current_roles & important_roles) / float(len(important_roles))
        role_gain = pair_role_coverage - current_role_coverage
        required_coverage = (
            len(pair_slots & required_slots) / max(len(required_slots), 1)
            if required_slots else 0.0
        )
        current_required_coverage = (
            len(current_slots & required_slots) / max(len(required_slots), 1)
            if required_slots else 0.0
        )
        required_gain = required_coverage - current_required_coverage
        pair_slot_value = self._evidence_join_slot_value(pair_slots, query_slots)
        current_slot_value = self._evidence_join_slot_value(current_slots, query_slots)
        coverage_gain = pair_slot_value - current_slot_value
        first_roles = set(first.get("decomposed_chain_roles", []) or [])
        second_roles = set(second.get("decomposed_chain_roles", []) or [])
        complementary_roles = bool((first_roles ^ second_roles) & important_roles)
        bridge_signal = (
            "bridge" in pair_roles
            and ("answer" in pair_roles or "anchor" in pair_roles)
        )
        if not bridge_signal:
            bridge_signal = bool(pairwise_profile.get("bridge_score", 0.0))
        subquery_access = (
            self._safe_float(first.get("decomposed_chain_subquery_access_score"), 0.0)
            + self._safe_float(second.get("decomposed_chain_subquery_access_score"), 0.0)
        ) / 2.0
        text_pair = (
            self._safe_float(pairwise_profile.get("max_text_score"), 0.0)
            + 0.55 * self._safe_float(pairwise_profile.get("min_text_score"), 0.0)
        )
        chain_score = (
            0.18 * min(pair_slot_value / 1.4, 1.0)
            + 0.17 * min(max(required_coverage, 0.0), 1.0)
            + 0.16 * min(max(pair_role_coverage, 0.0), 1.0)
            + 0.14 * min(max(subquery_access, 0.0), 1.0)
            + 0.11 * min(max(self._safe_float(pairwise_profile.get("pair_score"), 0.0), 0.0), 1.0)
            + 0.10 * min(max(text_pair, 0.0), 1.0)
            + 0.06 * self._safe_float(pairwise_profile.get("path_score"), 0.0)
            + 0.05 * self._safe_float(pairwise_profile.get("source_precision"), 0.0)
            + 0.05 * (1.0 if complementary_roles else 0.0)
            + 0.04 * (1.0 if bridge_signal else 0.0)
            - 0.06 * self._safe_float(pairwise_profile.get("risk"), 0.0)
            - 0.04 * self._safe_float(pairwise_profile.get("rank_cost"), 0.0)
        )
        chain_score = min(max(float(chain_score), 0.0), 1.2)
        pairwise_profile.update({
            "chain_score": round(float(chain_score), 6),
            "pair_role_coverage": round(float(pair_role_coverage), 6),
            "current_role_coverage": round(float(current_role_coverage), 6),
            "role_gain": round(float(role_gain), 6),
            "required_coverage": round(float(required_coverage), 6),
            "current_required_coverage": round(float(current_required_coverage), 6),
            "required_gain": round(float(required_gain), 6),
            "coverage_gain": round(float(coverage_gain), 6),
            "subquery_access_score": round(float(subquery_access), 6),
            "bridge_signal": bool(bridge_signal),
            "complementary_roles": bool(complementary_roles),
            "pair_roles": sorted(pair_roles),
            "current_roles": sorted(current_roles),
            "pair_required_overlap": sorted(pair_slots & required_slots)[:48],
        })
        return pairwise_profile

    def _decomposed_chain_slot_completion_gate(
        self,
        route: Mapping[str, Any],
        score_profile: Mapping[str, Any],
        best_pair: Sequence[int],
        before_top2: Sequence[int],
        outside_count: int,
    ) -> Dict[str, Any]:
        dataset = str(route.get("dataset") or "").strip().lower()
        target_allowed = (
            not self.decomposed_chain_join_slot_completion_target_datasets
            or dataset in self.decomposed_chain_join_slot_completion_target_datasets
        )
        chain_score = self._safe_float(score_profile.get("chain_score"), 0.0)
        required_gain = self._safe_float(score_profile.get("required_gain"), 0.0)
        coverage_gain = self._safe_float(score_profile.get("coverage_gain"), 0.0)
        role_gain = self._safe_float(score_profile.get("role_gain"), 0.0)
        current_required_coverage = self._safe_float(
            score_profile.get("current_required_coverage"),
            0.0,
        )
        required_coverage = self._safe_float(score_profile.get("required_coverage"), 0.0)
        max_text_score = self._safe_float(score_profile.get("max_text_score"), 0.0)
        min_text_score = self._safe_float(score_profile.get("min_text_score"), 0.0)
        risk = self._safe_float(score_profile.get("risk"), 0.0)
        answer_count = self._safe_int(score_profile.get("answer_count"), 0)
        pair_roles = {
            str(role)
            for role in (score_profile.get("pair_roles", []) or [])
            if str(role)
        }
        top1_replaced = bool(before_top2 and int(before_top2[0]) not in {int(doc_id) for doc_id in best_pair})
        bridge_or_answer = bool(
            answer_count > 0
            or "answer" in pair_roles
            or "bridge" in pair_roles
            or bool(score_profile.get("bridge_signal", False))
        )
        gain_ok = bool(
            required_gain >= self.decomposed_chain_join_slot_completion_min_required_gain
            or coverage_gain >= self.decomposed_chain_join_slot_completion_min_coverage_gain
            or role_gain >= self.decomposed_chain_join_slot_completion_min_role_gain > 0.0
        )
        gate = {
            "approved": False,
            "reason": "not_evaluated",
            "dataset": dataset,
            "target_datasets": sorted(self.decomposed_chain_join_slot_completion_target_datasets),
            "best_pair": [int(doc_id) for doc_id in best_pair],
            "outside_count": int(outside_count),
            "top1_replaced": bool(top1_replaced),
            "chain_score": round(float(chain_score), 6),
            "required_gain": round(float(required_gain), 6),
            "coverage_gain": round(float(coverage_gain), 6),
            "role_gain": round(float(role_gain), 6),
            "required_coverage": round(float(required_coverage), 6),
            "current_required_coverage": round(float(current_required_coverage), 6),
            "max_text_score": round(float(max_text_score), 6),
            "min_text_score": round(float(min_text_score), 6),
            "risk": round(float(risk), 6),
            "answer_count": int(answer_count),
            "pair_roles": sorted(pair_roles),
        }
        if not self.decomposed_chain_join_enable_slot_completion_promotion:
            gate["reason"] = "disabled"
            return gate
        if not target_allowed:
            gate["reason"] = "dataset_not_targeted"
            return gate
        if outside_count <= 0:
            gate["reason"] = "same_as_current_top2"
            return gate
        if current_required_coverage > self.decomposed_chain_join_slot_completion_max_current_coverage:
            gate["reason"] = "current_chain_already_complete"
            return gate
        if chain_score < self.decomposed_chain_join_slot_completion_min_chain_score:
            gate["reason"] = "low_chain_score"
            return gate
        if not gain_ok:
            gate["reason"] = "low_slot_completion_gain"
            return gate
        if max_text_score < self.decomposed_chain_join_slot_completion_min_text_score:
            gate["reason"] = "low_text_score"
            return gate
        if min_text_score < self.decomposed_chain_join_slot_completion_min_second_text_score:
            gate["reason"] = "low_second_text_score"
            return gate
        if risk > self.decomposed_chain_join_slot_completion_max_risk:
            gate["reason"] = "high_risk"
            return gate
        if top1_replaced and not self.decomposed_chain_join_slot_completion_allow_top1_replacement:
            gate["reason"] = "top1_replacement_blocked"
            return gate
        if self.decomposed_chain_join_slot_completion_require_bridge_or_answer and not bridge_or_answer:
            gate["reason"] = "missing_bridge_or_answer"
            return gate
        gate["approved"] = True
        gate["reason"] = "approved"
        return gate

    def _decomposed_chain_metric_regret_gate(
        self,
        route: Mapping[str, Any],
        best_profile: Mapping[str, Any],
        best_pair: Sequence[int],
    ) -> Dict[str, Any]:
        dataset = str(route.get("dataset") or "").strip().lower()
        target_allowed = (
            not self.decomposed_chain_join_metric_regret_target_datasets
            or dataset in self.decomposed_chain_join_metric_regret_target_datasets
        )
        slot_gate = best_profile.get("slot_completion_gate")
        if not isinstance(slot_gate, Mapping):
            slot_gate = {}
        top1_replaced = bool(slot_gate.get("top1_replaced", False))
        outside_count = self._safe_int(slot_gate.get("outside_count"), 0)
        net_margin = self._safe_float(best_profile.get("net_margin"), 0.0)
        required_gain = self._safe_float(best_profile.get("required_gain"), 0.0)
        coverage_gain = self._safe_float(best_profile.get("coverage_gain"), 0.0)
        min_text_score = self._safe_float(best_profile.get("min_text_score"), 0.0)
        max_text_score = self._safe_float(best_profile.get("max_text_score"), 0.0)
        source_precision = self._safe_float(best_profile.get("source_precision"), 0.0)
        risk = self._safe_float(best_profile.get("risk"), 0.0)
        answer_count = self._safe_int(best_profile.get("answer_count"), 0)
        pair_roles = {
            str(role)
            for role in (best_profile.get("pair_roles", []) or [])
            if str(role)
        }
        answer_signal = bool(answer_count > 0 or "answer" in pair_roles)
        gate = {
            "enabled": bool(self.decomposed_chain_join_enable_metric_regret_gate),
            "approved": True,
            "top5_append_allowed": False,
            "reason": "disabled",
            "dataset": dataset,
            "target_datasets": sorted(self.decomposed_chain_join_metric_regret_target_datasets),
            "best_pair": [int(doc_id) for doc_id in best_pair],
            "top1_replaced": bool(top1_replaced),
            "outside_count": int(outside_count),
            "net_margin": round(float(net_margin), 6),
            "required_gain": round(float(required_gain), 6),
            "coverage_gain": round(float(coverage_gain), 6),
            "min_text_score": round(float(min_text_score), 6),
            "max_text_score": round(float(max_text_score), 6),
            "source_precision": round(float(source_precision), 6),
            "risk": round(float(risk), 6),
            "answer_signal": bool(answer_signal),
        }
        if not self.decomposed_chain_join_enable_metric_regret_gate:
            return gate
        gate["reason"] = "approved"
        if not target_allowed:
            gate["reason"] = "dataset_not_targeted"
            return gate

        if top1_replaced and self.decomposed_chain_join_metric_regret_protect_top1:
            exceptional_top1 = (
                net_margin >= self.decomposed_chain_join_metric_regret_allow_top1_min_net_margin
                and required_gain >= self.decomposed_chain_join_metric_regret_allow_top1_min_required_gain
                and min_text_score >= self.decomposed_chain_join_metric_regret_allow_top1_min_text_score
                and source_precision >= self.decomposed_chain_join_metric_regret_allow_top1_min_source_precision
                and risk <= self.decomposed_chain_join_metric_regret_allow_top1_max_risk
                and answer_signal
            )
            if not exceptional_top1:
                gate["approved"] = False
                gate["top5_append_allowed"] = bool(
                    self.decomposed_chain_join_metric_regret_enable_top5_append
                )
                gate["reason"] = "top1_replacement_metric_regret"
                return gate
            gate["reason"] = "top1_exceptional_metric_gain"
            return gate

        if outside_count > 0:
            if net_margin < self.decomposed_chain_join_metric_regret_rank2_min_net_margin:
                gate["approved"] = False
                gate["top5_append_allowed"] = bool(
                    self.decomposed_chain_join_metric_regret_enable_top5_append
                )
                gate["reason"] = "rank2_low_metric_net_margin"
                return gate
            if required_gain < self.decomposed_chain_join_metric_regret_rank2_min_required_gain:
                gate["approved"] = False
                gate["top5_append_allowed"] = bool(
                    self.decomposed_chain_join_metric_regret_enable_top5_append
                )
                gate["reason"] = "rank2_low_required_gain"
                return gate
            if max_text_score < self.decomposed_chain_join_metric_regret_rank2_min_text_score:
                gate["approved"] = False
                gate["top5_append_allowed"] = bool(
                    self.decomposed_chain_join_metric_regret_enable_top5_append
                )
                gate["reason"] = "rank2_low_text_score"
                return gate
        return gate

    def _decomposed_chain_top2_gate(
        self,
        route: Mapping[str, Any],
        best_profile: Mapping[str, Any],
        best_pair: Sequence[int],
    ) -> Dict[str, Any]:
        dataset = str(route.get("dataset") or "").strip().lower()
        operator = str(
            best_profile.get("operator")
            or route.get("operator")
            or "single"
        ).strip().lower()
        top2_dataset_allowed = (
            not self.decomposed_chain_join_top2_target_datasets
            or dataset in self.decomposed_chain_join_top2_target_datasets
        )
        chain_score = self._safe_float(best_profile.get("chain_score"), 0.0)
        margin = self._safe_float(best_profile.get("margin"), 0.0)
        net_margin = self._safe_float(best_profile.get("net_margin"), 0.0)
        max_text_score = self._safe_float(best_profile.get("max_text_score"), 0.0)
        min_text_score = self._safe_float(best_profile.get("min_text_score"), 0.0)
        source_precision = self._safe_float(best_profile.get("source_precision"), 0.0)
        risk = self._safe_float(best_profile.get("risk"), 0.0)
        answer_count = self._safe_int(best_profile.get("answer_count"), 0)
        pair_roles = {
            str(role)
            for role in (best_profile.get("pair_roles", []) or [])
            if str(role)
        }
        top2_gate = {
            "approved": False,
            "reason": "not_evaluated",
            "dataset": dataset,
            "operator": operator,
            "top2_target_datasets": sorted(self.decomposed_chain_join_top2_target_datasets),
            "chain_score": round(float(chain_score), 6),
            "margin": round(float(margin), 6),
            "net_margin": round(float(net_margin), 6),
            "max_text_score": round(float(max_text_score), 6),
            "min_text_score": round(float(min_text_score), 6),
            "source_precision": round(float(source_precision), 6),
            "risk": round(float(risk), 6),
            "answer_count": int(answer_count),
            "pair_roles": sorted(pair_roles),
            "best_pair": [int(doc_id) for doc_id in best_pair],
        }
        if not top2_dataset_allowed:
            top2_gate["reason"] = "dataset_top5_only"
            return top2_gate
        slot_completion_gate = best_profile.get("slot_completion_gate")
        if isinstance(slot_completion_gate, Mapping) and bool(
            slot_completion_gate.get("approved", False)
        ):
            regret_gate = self._decomposed_chain_metric_regret_gate(
                route=route,
                best_profile=best_profile,
                best_pair=best_pair,
            )
            top2_gate["metric_regret_gate"] = dict(regret_gate)
            top2_gate["slot_completion_gate"] = dict(slot_completion_gate)
            if not bool(regret_gate.get("approved", True)):
                top2_gate["reason"] = str(
                    regret_gate.get("reason") or "metric_regret_rejected"
                )
                top2_gate["top5_append_allowed"] = bool(
                    regret_gate.get("top5_append_allowed", False)
                )
                return top2_gate
            top2_gate["approved"] = True
            top2_gate["reason"] = "slot_completion_promotion"
            return top2_gate
        if (
            self.decomposed_chain_join_top2_require_non_simple
            and not bool(route.get("complex", False))
            and operator in {"single", "entity", "lookup", "attribute"}
        ):
            top2_gate["reason"] = "simple_operator_top5_only"
            return top2_gate
        if chain_score < self.decomposed_chain_join_top2_min_chain_score:
            top2_gate["reason"] = "top2_low_chain_score"
            return top2_gate
        if margin < self.decomposed_chain_join_top2_min_margin:
            top2_gate["reason"] = "top2_low_margin"
            return top2_gate
        if net_margin < self.decomposed_chain_join_top2_min_net_margin:
            top2_gate["reason"] = "top2_low_net_margin"
            return top2_gate
        if max_text_score < self.decomposed_chain_join_top2_min_text_score:
            top2_gate["reason"] = "top2_low_text_score"
            return top2_gate
        if min_text_score < self.decomposed_chain_join_top2_min_second_text_score:
            top2_gate["reason"] = "top2_low_second_text_score"
            return top2_gate
        if source_precision < self.decomposed_chain_join_top2_min_source_precision:
            top2_gate["reason"] = "top2_low_source_precision"
            return top2_gate
        if risk > self.decomposed_chain_join_top2_max_risk:
            top2_gate["reason"] = "top2_high_risk"
            return top2_gate
        if (
            self.decomposed_chain_join_top2_require_answer_signal
            and answer_count <= 0
            and "answer" not in pair_roles
        ):
            top2_gate["reason"] = "top2_missing_answer_signal"
            return top2_gate
        top2_gate["approved"] = True
        top2_gate["reason"] = "approved"
        return top2_gate

    def _decomposed_chain_top5_gate(
        self,
        route: Mapping[str, Any],
        best_profile: Mapping[str, Any],
        best_pair: Sequence[int],
        top2_gate: Mapping[str, Any],
    ) -> Dict[str, Any]:
        dataset = str(route.get("dataset") or "").strip().lower()
        target_allowed = (
            not self.decomposed_chain_join_top5_fallback_target_datasets
            or dataset in self.decomposed_chain_join_top5_fallback_target_datasets
        )
        chain_score = self._safe_float(best_profile.get("chain_score"), 0.0)
        net_margin = self._safe_float(best_profile.get("net_margin"), 0.0)
        max_text_score = self._safe_float(best_profile.get("max_text_score"), 0.0)
        min_text_score = self._safe_float(best_profile.get("min_text_score"), 0.0)
        risk = self._safe_float(best_profile.get("risk"), 0.0)
        answer_count = self._safe_int(best_profile.get("answer_count"), 0)
        pair_roles = {
            str(role)
            for role in (best_profile.get("pair_roles", []) or [])
            if str(role)
        }
        answer_signal = bool(answer_count > 0 or "answer" in pair_roles)
        top5_gate = {
            "approved": False,
            "reason": "not_evaluated",
            "dataset": dataset,
            "top5_target_datasets": sorted(self.decomposed_chain_join_top5_fallback_target_datasets),
            "top2_gate_reason": str(top2_gate.get("reason") or ""),
            "chain_score": round(float(chain_score), 6),
            "net_margin": round(float(net_margin), 6),
            "max_text_score": round(float(max_text_score), 6),
            "min_text_score": round(float(min_text_score), 6),
            "risk": round(float(risk), 6),
            "answer_count": int(answer_count),
            "answer_signal": bool(answer_signal),
            "pair_roles": sorted(pair_roles),
            "best_pair": [int(doc_id) for doc_id in best_pair],
        }
        if not self.decomposed_chain_join_enable_top5_fallback:
            top5_gate["reason"] = "top5_fallback_disabled"
            return top5_gate
        if not target_allowed:
            top5_gate["reason"] = "top5_dataset_not_targeted"
            return top5_gate
        if chain_score < self.decomposed_chain_join_top5_min_chain_score:
            top5_gate["reason"] = "top5_low_chain_score"
            return top5_gate
        if net_margin < self.decomposed_chain_join_top5_min_net_margin:
            top5_gate["reason"] = "top5_low_net_margin"
            return top5_gate
        if max_text_score < self.decomposed_chain_join_top5_min_text_score:
            top5_gate["reason"] = "top5_low_text_score"
            return top5_gate
        if risk > self.decomposed_chain_join_top5_max_risk:
            top5_gate["reason"] = "top5_high_risk"
            return top5_gate
        if self.decomposed_chain_join_top5_require_answer_signal and not answer_signal:
            top5_gate["reason"] = "top5_missing_answer_signal"
            return top5_gate
        top5_gate["approved"] = True
        top5_gate["reason"] = "approved"
        return top5_gate

    def _apply_decomposed_chain_join_optimizer(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
    ) -> Dict[str, Any]:
        route = self._decomposed_chain_join_route(query_plan_log)
        slot_groups = self._decomposed_chain_slot_groups(query_plan_log)
        stats: Dict[str, Any] = {
            "enabled": bool(self.enable_decomposed_chain_join),
            "route_enabled": bool(route.get("enabled", False)),
            "route_reason": str(route.get("reason") or "not_evaluated"),
            "route_dataset": str(route.get("dataset") or ""),
            "operator": str(route.get("operator") or "single"),
            "decomposition_enabled": bool(self.decomposed_chain_join_enable_decomposition),
            "subquery_access_enabled": bool(self.decomposed_chain_join_enable_subquery_access),
            "chain_join_enabled": bool(self.decomposed_chain_join_enable_chain_join),
            "slot_completion_promotion_enabled": bool(
                self.decomposed_chain_join_enable_slot_completion_promotion
            ),
            "slot_completion_promotion_target_datasets": sorted(
                self.decomposed_chain_join_slot_completion_target_datasets
            ),
            "top2_target_datasets": sorted(self.decomposed_chain_join_top2_target_datasets),
            "top5_fallback_enabled": bool(self.decomposed_chain_join_enable_top5_fallback),
            "top5_fallback_target_datasets": sorted(
                self.decomposed_chain_join_top5_fallback_target_datasets
            ),
            "slot_count": int(len(slot_groups.get("required", set()) or set())),
            "candidate_count": 0,
            "chain_candidate_count": 0,
            "selected_count": 0,
            "changed_top2": False,
            "changed_top5": False,
            "rewrite_mode": "none",
            "top2_gate": {"approved": False, "reason": "not_evaluated"},
            "top5_gate": {"approved": False, "reason": "not_evaluated"},
            "current_chain_score": 0.0,
            "best_chain_score": 0.0,
            "best_margin": 0.0,
            "best_net_margin": 0.0,
            "best_pair": [],
            "best_profile": {},
            "slot_completion_promotion_candidate_count": 0,
            "slot_completion_promotion_approved_count": 0,
            "slot_completion_promotion_used": False,
            "slot_completion_promotion_best_required_gain": 0.0,
            "slot_completion_promotion_best_coverage_gain": 0.0,
            "slot_completion_promotion_best_gate": {"approved": False, "reason": "not_evaluated"},
            "metric_regret_gate_enabled": bool(
                self.decomposed_chain_join_enable_metric_regret_gate
            ),
            "metric_regret_gate_target_datasets": sorted(
                self.decomposed_chain_join_metric_regret_target_datasets
            ),
            "metric_regret_gate_evaluated": False,
            "metric_regret_gate_top2_vetoed": False,
            "metric_regret_gate_top5_append_allowed": False,
            "metric_regret_gate_reason": "not_evaluated",
            "metric_regret_gate_profile": {},
            "role_counts": {},
            "rejection_reasons": {},
            "selected_candidates": [],
            "row_samples": [],
        }
        if not bool(route.get("enabled", False)):
            return stats
        if len(selected) < 2:
            stats["rejection_reasons"] = {"short_selected_window": 1}
            return stats

        before_top2 = [int(doc_id) for doc_id in selected[:2]]
        before_top5 = [int(doc_id) for doc_id in selected[: self.final_top_k]]
        item_by_doc: Dict[int, Dict[str, Any]] = {}
        for item in candidates:
            doc_id = self._safe_int(item.get("passage_idx"), -1)
            if doc_id >= 0 and doc_id not in item_by_doc:
                item_by_doc[int(doc_id)] = item

        raw_docs: List[int] = []
        for doc_id in selected[: self.final_top_k]:
            doc_id = int(doc_id)
            if doc_id not in raw_docs:
                raw_docs.append(doc_id)
        presorted = [
            item for item in candidates
            if self._safe_int(item.get("passage_idx"), -1) >= 0
            and (
                self.decomposed_chain_join_max_original_rank <= 0
                or self._safe_int(item.get("original_rank"), 10**9)
                <= self.decomposed_chain_join_max_original_rank
            )
        ]
        presorted.sort(
            key=lambda item: (
                self._candidate_evidence_value(item),
                self._safe_float((item.get("evidence_join_planner", {}) or {}).get("score"), 0.0),
                self._safe_float((item.get("rank_window_recall", {}) or {}).get("score"), 0.0),
                self._safe_float(item.get("confidence"), 0.0),
                -self._safe_int(item.get("original_rank"), 10**9),
            ),
            reverse=True,
        )
        for item in presorted[: max(self.decomposed_chain_join_candidate_pool * 4, 24)]:
            doc_id = self._safe_int(item.get("passage_idx"), -1)
            if doc_id >= 0 and doc_id not in raw_docs:
                raw_docs.append(int(doc_id))

        profiles: Dict[int, Dict[str, Any]] = {}
        for doc_id in raw_docs:
            profile = self._decomposed_chain_profile(
                doc_id=doc_id,
                item=item_by_doc.get(int(doc_id)),
                selected=selected,
                passage_details=passage_details,
                query_plan_log=query_plan_log,
                original_rank_by_doc=original_rank_by_doc,
                max_raw_score=max_raw_score,
                slot_groups=slot_groups,
            )
            profiles[int(doc_id)] = profile

        pool_docs = [int(doc_id) for doc_id in selected[: self.final_top_k] if int(doc_id) in profiles]
        candidate_docs = [doc_id for doc_id in raw_docs if doc_id not in set(pool_docs)]
        if self.decomposed_chain_join_enable_subquery_access:
            candidate_docs.sort(
                key=lambda doc_id: (
                    self._safe_float(profiles[doc_id].get("decomposed_chain_subquery_access_score"), 0.0),
                    len(set(profiles[doc_id].get("decomposed_chain_roles", []) or [])),
                    self._safe_float(profiles[doc_id].get("candidate_value"), 0.0),
                    -self._safe_int(profiles[doc_id].get("original_rank"), 10**9),
                ),
                reverse=True,
            )
        else:
            candidate_docs.sort(
                key=lambda doc_id: (
                    self._safe_float(profiles[doc_id].get("candidate_value"), 0.0),
                    self._safe_float(profiles[doc_id].get("text_score"), 0.0),
                    -self._safe_int(profiles[doc_id].get("original_rank"), 10**9),
                ),
                reverse=True,
            )
        for doc_id in candidate_docs:
            if len(pool_docs) >= self.decomposed_chain_join_candidate_pool:
                break
            if int(doc_id) not in pool_docs:
                pool_docs.append(int(doc_id))
        stats["candidate_count"] = int(len(pool_docs))

        role_counter: Counter = Counter()
        for doc_id in pool_docs:
            profile = profiles.get(int(doc_id), {})
            for role in profile.get("decomposed_chain_roles", []) or []:
                role_counter[str(role)] += 1
            if len(stats["row_samples"]) < 20:
                stats["row_samples"].append({
                    "doc_id": int(doc_id),
                    "original_rank": self._safe_int(profile.get("original_rank"), 0),
                    "roles": list(profile.get("decomposed_chain_roles", []) or []),
                    "subquery_access_score": self._safe_float(
                        profile.get("decomposed_chain_subquery_access_score"),
                        0.0,
                    ),
                    "text_score": self._safe_float(profile.get("text_score"), 0.0),
                    "path_score": self._safe_float(profile.get("path_score"), 0.0),
                    "source_precision": self._safe_float(profile.get("source_precision"), 0.0),
                    "answer_signal": bool(profile.get("answer_signal", False)),
                    "required_coverage": self._safe_float(
                        profile.get("decomposed_chain_required_coverage"),
                        0.0,
                    ),
                })
        stats["role_counts"] = dict(role_counter)

        current_profiles = [profiles[doc_id] for doc_id in before_top2 if doc_id in profiles]
        if len(current_profiles) < 2:
            stats["rejection_reasons"] = {"missing_current_profiles": 1}
            return stats
        current_score_profile = self._decomposed_chain_score(
            current_profiles[0],
            current_profiles[1],
            current_profiles=current_profiles,
            query_plan_log=query_plan_log,
            slot_groups=slot_groups,
        )
        current_chain_score = self._safe_float(current_score_profile.get("chain_score"), 0.0)
        stats["current_chain_score"] = round(float(current_chain_score), 6)
        if not self.decomposed_chain_join_enable_chain_join:
            stats["rejection_reasons"] = {"chain_join_disabled": 1}
            return stats

        rejections: Counter = Counter()
        best: Optional[Tuple[float, float, float, Tuple[int, int], Dict[str, Any]]] = None
        current_set = set(before_top2)
        for i, first_doc in enumerate(pool_docs):
            for second_doc in pool_docs[i + 1:]:
                first_doc = int(first_doc)
                second_doc = int(second_doc)
                pair_docs = (first_doc, second_doc)
                outside_count = sum(1 for doc_id in pair_docs if doc_id not in current_set)
                if outside_count <= 0:
                    rejections["same_as_current_top2"] += 1
                    continue
                if outside_count > self.decomposed_chain_join_max_swaps:
                    rejections["outside_swap_budget"] += 1
                    continue
                if self.decomposed_chain_join_protect_top1 and before_top2[0] not in pair_docs:
                    rejections["protect_top1"] += 1
                    continue
                first = profiles.get(first_doc)
                second = profiles.get(second_doc)
                if not first or not second:
                    rejections["missing_profile"] += 1
                    continue
                if self.decomposed_chain_join_max_original_rank > 0 and any(
                    self._safe_int(profile.get("original_rank"), 10**9)
                    > self.decomposed_chain_join_max_original_rank
                    for profile in (first, second)
                    if self._safe_int(profile.get("doc_id"), -1) not in current_set
                ):
                    rejections["rank_after_max_original_rank"] += 1
                    continue
                score_profile = self._decomposed_chain_score(
                    first,
                    second,
                    current_profiles=current_profiles,
                    query_plan_log=query_plan_log,
                    slot_groups=slot_groups,
                )
                stats["chain_candidate_count"] = int(stats["chain_candidate_count"]) + 1
                chain_score = self._safe_float(score_profile.get("chain_score"), 0.0)
                margin = chain_score - current_chain_score
                coverage_gain = self._safe_float(score_profile.get("coverage_gain"), 0.0)
                required_gain = self._safe_float(score_profile.get("required_gain"), 0.0)
                role_gain = self._safe_float(score_profile.get("role_gain"), 0.0)
                bridge_signal = bool(score_profile.get("bridge_signal", False))
                risk = self._safe_float(score_profile.get("risk"), 0.0)
                rank_cost = self._safe_float(score_profile.get("rank_cost"), 0.0)
                displacement_cost = 0.10 * float(outside_count) + 0.05 * risk + 0.03 * rank_cost
                if before_top2 and before_top2[0] not in pair_docs:
                    displacement_cost += 0.08
                net_margin = margin - displacement_cost
                score_profile["margin"] = round(float(margin), 6)
                score_profile["displacement_cost"] = round(float(displacement_cost), 6)
                score_profile["net_margin"] = round(float(net_margin), 6)
                slot_completion_gate = self._decomposed_chain_slot_completion_gate(
                    route=route,
                    score_profile=score_profile,
                    best_pair=pair_docs,
                    before_top2=before_top2,
                    outside_count=outside_count,
                )
                slot_completion_approved = bool(slot_completion_gate.get("approved", False))
                score_profile["slot_completion_gate"] = slot_completion_gate
                score_profile["slot_completion_promotion_approved"] = bool(slot_completion_approved)
                if str(slot_completion_gate.get("reason") or "") not in {"disabled", "dataset_not_targeted"}:
                    stats["slot_completion_promotion_candidate_count"] = int(
                        stats["slot_completion_promotion_candidate_count"]
                    ) + 1
                if slot_completion_approved:
                    stats["slot_completion_promotion_approved_count"] = int(
                        stats["slot_completion_promotion_approved_count"]
                    ) + 1
                    if (
                        self._safe_float(slot_completion_gate.get("required_gain"), 0.0)
                        > self._safe_float(
                            stats.get("slot_completion_promotion_best_required_gain"),
                            0.0,
                        )
                    ):
                        stats["slot_completion_promotion_best_required_gain"] = self._safe_float(
                            slot_completion_gate.get("required_gain"),
                            0.0,
                        )
                        stats["slot_completion_promotion_best_coverage_gain"] = self._safe_float(
                            slot_completion_gate.get("coverage_gain"),
                            0.0,
                        )
                        stats["slot_completion_promotion_best_gate"] = dict(slot_completion_gate)
                if chain_score < self.decomposed_chain_join_min_chain_score and not slot_completion_approved:
                    rejections["low_chain_score"] += 1
                    continue
                if margin < self.decomposed_chain_join_min_margin and not slot_completion_approved:
                    rejections["low_margin"] += 1
                    continue
                if (
                    net_margin < max(self.decomposed_chain_join_min_margin, 0.0)
                    and not slot_completion_approved
                ):
                    rejections["negative_net_margin"] += 1
                    continue
                if (
                    coverage_gain < self.decomposed_chain_join_min_coverage_gain
                    and required_gain < 0.08
                    and role_gain < 0.20
                    and not slot_completion_approved
                ):
                    rejections["low_decomposition_gain"] += 1
                    continue
                if (
                    self.decomposed_chain_join_require_bridge_signal
                    and not bridge_signal
                    and not slot_completion_approved
                ):
                    rejections["missing_bridge_signal"] += 1
                    continue
                if risk > 0.68 and coverage_gain < 0.18 and not slot_completion_approved:
                    rejections["high_chain_risk"] += 1
                    continue
                if before_top2 and before_top2[0] not in pair_docs and (
                    margin < self.decomposed_chain_join_min_margin + 0.050
                    or net_margin < self.decomposed_chain_join_min_margin + 0.035
                ) and not slot_completion_approved:
                    rejections["unsafe_top1_replacement"] += 1
                    continue

                def _order_key(doc_id: int) -> Tuple[float, float, float, int]:
                    profile = profiles[int(doc_id)]
                    roles = set(profile.get("decomposed_chain_roles", []) or [])
                    role_bonus = 0.10 if "answer" in roles else 0.0
                    role_bonus += 0.06 if "bridge" in roles else 0.0
                    return (
                        role_bonus + self._safe_float(profile.get("candidate_value"), 0.0),
                        self._safe_float(profile.get("decomposed_chain_subquery_access_score"), 0.0),
                        self._safe_float(profile.get("text_score"), 0.0),
                        -self._safe_int(profile.get("original_rank"), 10**9),
                    )

                ordered_pair = tuple(
                    doc_id for doc_id in sorted(pair_docs, key=_order_key, reverse=True)
                )
                selection_net_margin = net_margin + (0.30 if slot_completion_approved else 0.0)
                score_profile["selection_net_margin"] = round(float(selection_net_margin), 6)
                ranking_key = (selection_net_margin, margin, chain_score)
                if best is None or ranking_key > (best[0], best[1], best[2]):
                    best = (
                        round(float(net_margin), 6),
                        round(float(margin), 6),
                        round(float(chain_score), 6),
                        (int(ordered_pair[0]), int(ordered_pair[1])),
                        dict(score_profile),
                    )

        stats["rejection_reasons"] = dict(rejections)
        if best is None:
            return stats

        best_net_margin, best_margin, best_score, best_pair, best_profile = best
        stats["best_chain_score"] = round(float(best_score), 6)
        stats["best_margin"] = round(float(best_margin), 6)
        stats["best_net_margin"] = round(float(best_net_margin), 6)
        stats["best_pair"] = [int(best_pair[0]), int(best_pair[1])]
        stats["best_profile"] = best_profile
        top2_gate = self._decomposed_chain_top2_gate(
            route=route,
            best_profile=best_profile,
            best_pair=best_pair,
        )
        stats["top2_gate"] = top2_gate
        metric_regret_gate = top2_gate.get("metric_regret_gate")
        if isinstance(metric_regret_gate, Mapping):
            stats["metric_regret_gate_evaluated"] = True
            stats["metric_regret_gate_top2_vetoed"] = not bool(
                metric_regret_gate.get("approved", True)
            )
            stats["metric_regret_gate_top5_append_allowed"] = bool(
                metric_regret_gate.get("top5_append_allowed", False)
            )
            stats["metric_regret_gate_reason"] = str(
                metric_regret_gate.get("reason") or "not_evaluated"
            )
            stats["metric_regret_gate_profile"] = dict(metric_regret_gate)
        top2_approved = bool(top2_gate.get("approved", False))
        stats["slot_completion_promotion_used"] = bool(
            top2_approved
            and str(top2_gate.get("reason") or "") == "slot_completion_promotion"
        )
        if top2_approved:
            stats["rewrite_mode"] = "top2"
        elif self.decomposed_chain_join_enable_top5_fallback:
            rejections[str(top2_gate.get("reason") or "top2_gate_rejected")] += 1
            top5_gate = self._decomposed_chain_top5_gate(
                route=route,
                best_profile=best_profile,
                best_pair=best_pair,
                top2_gate=top2_gate,
            )
            stats["top5_gate"] = top5_gate
            if not bool(top5_gate.get("approved", False)):
                stats["rewrite_mode"] = "rejected_by_top5_gate"
                rejections[str(top5_gate.get("reason") or "top5_gate_rejected")] += 1
                stats["rejection_reasons"] = dict(rejections)
                return stats
            stats["rewrite_mode"] = "top5_only"
            stats["rejection_reasons"] = dict(rejections)
        else:
            stats["rewrite_mode"] = "rejected_by_top2_gate"
            rejections[str(top2_gate.get("reason") or "top2_gate_rejected")] += 1
            stats["rejection_reasons"] = dict(rejections)
            return stats

        if top2_approved:
            new_selected = [int(best_pair[0]), int(best_pair[1])]
        else:
            new_selected = [int(doc_id) for doc_id in before_top2]
            for doc_id in best_pair:
                doc_id = int(doc_id)
                if doc_id not in new_selected:
                    new_selected.append(doc_id)
        for doc_id in selected:
            doc_id = int(doc_id)
            if doc_id not in new_selected:
                new_selected.append(doc_id)
        for doc_id in base_doc_ids:
            doc_id = int(doc_id)
            if doc_id not in new_selected:
                new_selected.append(doc_id)
        selected[:] = new_selected
        selected_set.clear()
        selected_set.update(int(doc_id) for doc_id in selected)

        after_top2 = [int(doc_id) for doc_id in selected[:2]]
        after_top5 = [int(doc_id) for doc_id in selected[: self.final_top_k]]
        stats["changed_top2"] = bool(before_top2 != after_top2)
        stats["changed_top5"] = bool(before_top5 != after_top5)
        if top2_approved:
            selected_docs = [doc_id for doc_id in after_top2 if doc_id not in before_top2]
            selected_baseline = before_top2
            selected_reason = "decomposed_chain_join_selected"
        else:
            selected_docs = [doc_id for doc_id in after_top5 if doc_id not in before_top5]
            selected_baseline = before_top5
            selected_reason = "decomposed_chain_join_top5_context"
        stats["selected_count"] = int(len(selected_docs))
        for doc_id in selected_docs:
            profile = profiles.get(int(doc_id), {})
            item = profile.get("item") if isinstance(profile, Mapping) else None
            if not isinstance(item, dict):
                continue
            item["_decomposed_chain_join_selected"] = True
            item["_decomposed_chain_join_replaced_docs"] = [
                doc for doc in selected_baseline
                if doc not in (after_top2 if top2_approved else after_top5)
            ]
            item["decomposed_chain_join"] = {
                "enabled": True,
                "rewrite_mode": str(stats.get("rewrite_mode") or "none"),
                "top2_gate": top2_gate,
                "chain_score": round(float(best_score), 6),
                "margin": round(float(best_margin), 6),
                "net_margin": round(float(best_net_margin), 6),
                "pair_docs": [int(best_pair[0]), int(best_pair[1])],
                "profile": best_profile,
            }
            if not any(int(prev.get("passage_idx", -1)) == int(doc_id) for prev in selected_ontology):
                selected_ontology.append(item)
            if len(stats["selected_candidates"]) < 12:
                stats["selected_candidates"].append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason=selected_reason,
                        final_rank=int(after_top5.index(int(doc_id)) + 1),
                    )
                )
        return stats

    def _evidence_warehouse_top2_guard(
        self,
        row: Mapping[str, Any],
        replacement_value: float,
        lost_slot_value: float,
    ) -> Tuple[bool, str, Dict[str, Any]]:
        text_signal = row.get("text_signal", {}) or {}
        if not isinstance(text_signal, Mapping):
            text_signal = {}
        text_score = self._safe_float(row.get("text_score"), 0.0)
        path_score = self._safe_float(row.get("path_score"), 0.0)
        source_precision = self._safe_float(row.get("source_precision"), 0.0)
        benefit = self._safe_float(row.get("benefit"), 0.0)
        risk = self._safe_float(row.get("risk"), 0.0)
        original_rank = self._safe_int(row.get("original_rank"), 10**9)
        terminal_hits = self._safe_int(text_signal.get("terminal_hits"), 0)
        answer_overlap_count = self._safe_int(text_signal.get("answer_overlap_count"), 0)
        relation_overlap_count = self._safe_int(text_signal.get("relation_overlap_count"), 0)
        query_overlap_count = self._safe_int(text_signal.get("query_overlap_count"), 0)
        strong_text = (
            text_score >= 0.50
            and (
                terminal_hits > 0
                or answer_overlap_count > 0
                or (relation_overlap_count > 0 and query_overlap_count > 0)
            )
        )
        strong_path = path_score >= 0.74
        strong_source = (
            source_precision >= 0.52
            and text_score >= 0.42
            and (terminal_hits > 0 or answer_overlap_count > 0 or relation_overlap_count > 0)
        )
        rank_ceiling = 120 if strong_path else 80
        profile = {
            "text_score": round(float(text_score), 6),
            "path_score": round(float(path_score), 6),
            "source_precision": round(float(source_precision), 6),
            "benefit": round(float(benefit), 6),
            "risk": round(float(risk), 6),
            "original_rank": int(original_rank),
            "replacement_value": round(float(replacement_value), 6),
            "lost_slot_value": round(float(lost_slot_value), 6),
            "strong_text": bool(strong_text),
            "strong_path": bool(strong_path),
            "strong_source": bool(strong_source),
        }
        if not bool(row.get("answer_signal", False)):
            return False, "top2_missing_answer_signal", profile
        if bool(row.get("relation_only", False)):
            return False, "top2_relation_only", profile
        if benefit < max(self.evidence_warehouse_min_benefit, 0.70):
            return False, "top2_low_benefit", profile
        if risk > 0.18:
            return False, "top2_high_risk", profile
        if original_rank > rank_ceiling:
            return False, "top2_rank_after_safe_window", profile
        if not (strong_text or strong_path or strong_source):
            return False, "top2_weak_support", profile
        if replacement_value > 0.82:
            return False, "top2_replacement_strong", profile
        if lost_slot_value > 0.85 and replacement_value >= 0.50:
            return False, "top2_replacement_covers_key_slot", profile
        return True, "top2_guard_approved", profile

    def _evidence_warehouse_best_action(
        self,
        item: Mapping[str, Any],
        row: Mapping[str, Any],
        selected: Sequence[int],
        selected_set: Set[int],
        passage_details: Mapping[int, Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
        original_rank_by_doc: Mapping[int, int],
        max_raw_score: float,
        top2_used: int,
        top5_used: int,
    ) -> Dict[str, Any]:
        candidate_doc = int(item.get("passage_idx", -1))
        benefit = self._safe_float(row.get("benefit"), 0.0)
        risk = self._safe_float(row.get("risk"), 0.0)
        query_slots = self._evidence_join_query_slots(query_plan_log)
        options: List[Dict[str, Any]] = []
        if len(selected) < self.final_top_k and top5_used < self.evidence_warehouse_max_top5_swaps:
            net_benefit = benefit - self.evidence_warehouse_risk_weight * risk
            options.append({
                "target": "append",
                "replacement_index": len(selected),
                "replacement_doc": -1,
                "replacement_rank": 0,
                "replacement_value": 0.0,
                "lost_slot_value": 0.0,
                "net_benefit": net_benefit,
                "required_net_benefit": self.evidence_warehouse_min_net_benefit,
            })
        max_window = min(len(selected), self.final_top_k)
        for index in range(max_window):
            final_rank = index + 1
            if int(selected[index]) == candidate_doc:
                continue
            is_top2 = final_rank <= 2
            if is_top2 and top2_used >= self.evidence_warehouse_max_top2_swaps:
                continue
            if (not is_top2) and top5_used >= self.evidence_warehouse_max_top5_swaps:
                continue
            if final_rank <= self.evidence_warehouse_protect_top_k and not is_top2:
                continue
            if is_top2 and self.evidence_warehouse_max_top2_swaps <= 0:
                continue
            replacement_doc = int(selected[index])
            replacement_rank = int(original_rank_by_doc.get(replacement_doc, final_rank))
            detail = passage_details.get(replacement_doc)
            if detail:
                replacement_rank = self._safe_int(detail.get("original_rank"), final_rank)
            replacement_value = self._baseline_replacement_value(
                replacement_doc,
                replacement_rank,
                passage_details,
                max_raw_score,
            )
            replacement_slots = self._evidence_join_doc_slots(replacement_doc, passage_details, query_plan_log)
            other_slots = self._evidence_warehouse_selected_slots(
                selected=selected,
                passage_details=passage_details,
                query_plan_log=query_plan_log,
                exclude_doc=replacement_doc,
            )
            lost_slots = set(replacement_slots) - set(other_slots)
            lost_slot_value = self._evidence_join_slot_value(lost_slots, query_slots)
            replacement_cost = replacement_value + 0.18 * min(lost_slot_value / 1.2, 1.0)
            net_benefit = (
                benefit
                - self.evidence_warehouse_cost_weight * replacement_cost
                - self.evidence_warehouse_risk_weight * risk
            )
            required = (
                self.evidence_warehouse_top2_min_net_benefit
                if is_top2
                else self.evidence_warehouse_min_net_benefit
            )
            if final_rank == 3:
                required += 0.015
            top2_guard_profile: Dict[str, Any] = {}
            if is_top2:
                guard_ok, guard_reason, top2_guard_profile = self._evidence_warehouse_top2_guard(
                    row=row,
                    replacement_value=replacement_value,
                    lost_slot_value=lost_slot_value,
                )
                if not guard_ok:
                    continue
            option = {
                "target": "top2" if is_top2 else "top5",
                "replacement_index": int(index),
                "replacement_doc": int(replacement_doc),
                "replacement_rank": int(replacement_rank),
                "replacement_value": round(float(replacement_value), 6),
                "replacement_cost": round(float(replacement_cost), 6),
                "lost_slot_value": round(float(lost_slot_value), 6),
                "lost_slots": sorted(lost_slots)[:24],
                "net_benefit": round(float(net_benefit), 6),
                "required_net_benefit": round(float(required), 6),
            }
            if is_top2:
                option["top2_guard"] = top2_guard_profile
                option["top2_guard_reason"] = guard_reason
            options.append(option)
        if not options:
            return {
                "approved": False,
                "reason": "no_replaceable_slot",
                "net_benefit": 0.0,
                "required_net_benefit": self.evidence_warehouse_min_net_benefit,
            }
        top2_options = [
            option for option in options
            if str(option.get("target") or "") == "top2"
            and self._safe_float(option.get("net_benefit"), 0.0)
            >= self._safe_float(option.get("required_net_benefit"), self.evidence_warehouse_top2_min_net_benefit)
        ]
        ranked_options = top2_options if top2_options else options
        best = max(
            ranked_options,
            key=lambda option: (
                self._safe_float(option.get("net_benefit"), 0.0),
                -self._safe_int(option.get("replacement_index"), 10**9),
            ),
        )
        net_benefit = self._safe_float(best.get("net_benefit"), 0.0)
        required = self._safe_float(best.get("required_net_benefit"), self.evidence_warehouse_min_net_benefit)
        best["approved"] = bool(net_benefit >= required)
        best["reason"] = "approved" if bool(best["approved"]) else "low_net_benefit"
        return best

    def _apply_evidence_warehouse_optimizer(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        rejections: Counter,
        rejected_candidates: List[Dict[str, Any]],
        selected_candidates: List[Dict[str, Any]],
        original_rank_by_doc: Mapping[int, int],
    ) -> Tuple[int, int, List[Dict[str, Any]]]:
        route = self._evidence_warehouse_route(query_plan_log)
        if not bool(route.get("enabled", False)):
            return 0, 0, []
        if self.enable_final_rank_evidence_warehouse:
            return 0, 0, []
        presorted = [
            item for item in candidates
            if int(item.get("passage_idx", -1)) >= 0
            and int(item.get("passage_idx", -1)) not in selected_set
        ]
        presorted.sort(
            key=lambda item: (
                self._candidate_evidence_value(item),
                self._safe_float(item.get("score"), 0.0),
                self._safe_float(item.get("confidence"), 0.0),
                -self._safe_int(item.get("original_rank"), 10**9),
            ),
            reverse=True,
        )
        if self.evidence_warehouse_max_candidates > 0:
            presorted = presorted[: self.evidence_warehouse_max_candidates]

        top2_used = 0
        top5_used = 0
        row_samples: List[Dict[str, Any]] = []
        for item in presorted:
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc in selected_set:
                continue
            row = self._evidence_warehouse_candidate_row(
                item=item,
                selected=selected,
                passage_details=passage_details,
                query_plan_log=query_plan_log,
            )
            item["evidence_warehouse_optimizer"] = dict(row)
            item["_evidence_warehouse_candidate"] = bool(row.get("approved", False))
            if len(row_samples) < 24:
                row_samples.append({
                    "passage_idx": int(candidate_doc),
                    "original_rank": int(item.get("original_rank", 0) or 0),
                    "approved": bool(row.get("approved", False)),
                    "reason": str(row.get("reason") or ""),
                    "benefit": self._safe_float(row.get("benefit"), 0.0),
                    "risk": self._safe_float(row.get("risk"), 0.0),
                    "source_signature": str(row.get("source_signature") or ""),
                    "source_precision": self._safe_float(row.get("source_precision"), 0.0),
                    "text_score": self._safe_float(row.get("text_score"), 0.0),
                    "path_score": self._safe_float(row.get("path_score"), 0.0),
                    "novelty_value": self._safe_float(row.get("novelty_value"), 0.0),
                    "answer_signal": bool(row.get("answer_signal", False)),
                    "relation_only": bool(row.get("relation_only", False)),
                })
            if not bool(row.get("approved", False)):
                reason = str(row.get("reason") or "not_approved")
                rejections[reason] += 1
                if len(rejected_candidates) < 12 and reason not in {"low_benefit"}:
                    rejected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=False,
                            reason=f"evidence_warehouse_rejected:{reason}",
                        )
                    )
                continue
            action = self._evidence_warehouse_best_action(
                item=item,
                row=row,
                selected=selected,
                selected_set=selected_set,
                passage_details=passage_details,
                query_plan_log=query_plan_log,
                original_rank_by_doc=original_rank_by_doc,
                max_raw_score=max_raw_score,
                top2_used=top2_used,
                top5_used=top5_used,
            )
            warehouse_profile = dict(item.get("evidence_warehouse_optimizer", {}) or {})
            warehouse_profile["action"] = action
            item["evidence_warehouse_optimizer"] = warehouse_profile
            if not bool(action.get("approved", False)):
                reason = str(action.get("reason") or "low_net_benefit")
                rejections[reason] += 1
                if len(rejected_candidates) < 12 and reason not in {"low_net_benefit"}:
                    rejected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=False,
                            reason=f"evidence_warehouse_rejected:{reason}",
                        )
                    )
                continue

            target = str(action.get("target") or "top5")
            replacement_index = self._safe_int(action.get("replacement_index"), len(selected))
            replacement_doc = self._safe_int(action.get("replacement_doc"), -1)
            if target == "append" or replacement_doc < 0 or replacement_index >= len(selected):
                if len(selected) >= self.final_top_k:
                    rejections["append_without_slot"] += 1
                    continue
                selected.append(candidate_doc)
                final_rank = len(selected)
            else:
                selected[replacement_index] = candidate_doc
                selected_set.discard(replacement_doc)
                final_rank = replacement_index + 1
            selected_set.add(candidate_doc)
            item["_evidence_warehouse_selected"] = True
            item["_evidence_warehouse_replaced_doc"] = int(replacement_doc)
            if final_rank <= 2:
                item["_evidence_warehouse_top2_selected"] = True
                top2_used += 1
            else:
                item["_evidence_warehouse_top5_selected"] = True
                top5_used += 1
            if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                selected_ontology.append(item)
            if len(selected_candidates) < 12:
                selected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason=f"evidence_warehouse_{target}_selected",
                        final_rank=int(final_rank),
                    )
                )
            if (
                top2_used >= self.evidence_warehouse_max_top2_swaps
                and top5_used >= self.evidence_warehouse_max_top5_swaps
            ):
                break
        return top2_used, top5_used, row_samples

    def _final_rank_evidence_warehouse_top2_guard(
        self,
        row: Mapping[str, Any],
        replacement_value: float,
        lost_slot_value: float,
    ) -> Tuple[bool, str, Dict[str, Any]]:
        text_signal = row.get("text_signal", {}) or {}
        if not isinstance(text_signal, Mapping):
            text_signal = {}
        text_score = self._safe_float(row.get("text_score"), 0.0)
        path_score = self._safe_float(row.get("path_score"), 0.0)
        source_precision = self._safe_float(row.get("source_precision"), 0.0)
        benefit = self._safe_float(row.get("benefit"), 0.0)
        risk = self._safe_float(row.get("risk"), 0.0)
        original_rank = self._safe_int(row.get("original_rank"), 10**9)
        terminal_hits = self._safe_int(text_signal.get("terminal_hits"), 0)
        answer_overlap_count = self._safe_int(text_signal.get("answer_overlap_count"), 0)
        relation_overlap_count = self._safe_int(text_signal.get("relation_overlap_count"), 0)
        query_overlap_count = self._safe_int(text_signal.get("query_overlap_count"), 0)
        strong_text = (
            text_score >= 0.56
            and (
                terminal_hits > 0
                or answer_overlap_count > 0
                or (relation_overlap_count > 0 and query_overlap_count > 0)
            )
        )
        strong_path = path_score >= 0.80 and text_score >= 0.42
        strong_source = (
            source_precision >= 0.65
            and text_score >= 0.44
            and (terminal_hits > 0 or answer_overlap_count > 0 or relation_overlap_count > 0)
        )
        rank_ceiling = 140 if strong_path else 80
        profile = {
            "text_score": round(float(text_score), 6),
            "path_score": round(float(path_score), 6),
            "source_precision": round(float(source_precision), 6),
            "benefit": round(float(benefit), 6),
            "risk": round(float(risk), 6),
            "original_rank": int(original_rank),
            "replacement_value": round(float(replacement_value), 6),
            "lost_slot_value": round(float(lost_slot_value), 6),
            "strong_text": bool(strong_text),
            "strong_path": bool(strong_path),
            "strong_source": bool(strong_source),
        }
        if not bool(row.get("answer_signal", False)):
            return False, "top2_missing_answer_signal", profile
        if bool(row.get("relation_only", False)):
            return False, "top2_relation_only", profile
        if benefit < max(self.evidence_warehouse_min_benefit, 0.78):
            return False, "top2_low_benefit", profile
        if risk > 0.18:
            return False, "top2_high_risk", profile
        if original_rank > rank_ceiling:
            return False, "top2_rank_after_safe_window", profile
        if not (strong_text or strong_path or strong_source):
            return False, "top2_weak_support", profile
        if lost_slot_value > 0.92 and replacement_value >= 0.70:
            return False, "top2_replacement_covers_key_slot", profile
        return True, "top2_guard_approved", profile

    def _final_rank_evidence_warehouse_action_counterfactual_gate(
        self,
        row: Mapping[str, Any],
        option: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, str, Dict[str, Any]]:
        text_signal = row.get("text_signal", {}) or {}
        if not isinstance(text_signal, Mapping):
            text_signal = {}
        dataset = str(query_plan_log.get("dataset") or "").strip().lower()
        target = str(option.get("target") or "top5").strip().lower()
        text_score = self._safe_float(row.get("text_score"), 0.0)
        path_score = self._safe_float(row.get("path_score"), 0.0)
        source_precision = self._safe_float(row.get("source_precision"), 0.0)
        risk = self._safe_float(row.get("risk"), 0.0)
        replacement_value = self._safe_float(option.get("replacement_value"), 0.0)
        rule_net_benefit = self._safe_float(
            option.get("rule_net_benefit"),
            self._safe_float(option.get("net_benefit"), 0.0),
        )
        selectivity_score = self._safe_float(option.get("selectivity_score"), 0.0)
        answer_aware_score = self._safe_float(option.get("answer_aware_score"), 0.0)
        answer_aware_min_score = self._safe_float(option.get("answer_aware_min_score"), 1.0)
        answer_overlap_count = self._safe_int(text_signal.get("answer_overlap_count"), 0)
        terminal_hits = self._safe_int(text_signal.get("terminal_hits"), 0)
        relation_overlap_count = self._safe_int(text_signal.get("relation_overlap_count"), 0)
        query_overlap_count = self._safe_int(text_signal.get("query_overlap_count"), 0)
        profile = {
            "enabled": bool(self.evidence_warehouse_enable_action_counterfactual_gate),
            "dataset": dataset,
            "target": target,
            "text_score": round(float(text_score), 6),
            "path_score": round(float(path_score), 6),
            "source_precision": round(float(source_precision), 6),
            "risk": round(float(risk), 6),
            "replacement_value": round(float(replacement_value), 6),
            "rule_net_benefit": round(float(rule_net_benefit), 6),
            "selectivity_score": round(float(selectivity_score), 6),
            "answer_aware_score": round(float(answer_aware_score), 6),
            "answer_aware_min_score": round(float(answer_aware_min_score), 6),
            "answer_overlap_count": int(answer_overlap_count),
            "terminal_hits": int(terminal_hits),
            "relation_overlap_count": int(relation_overlap_count),
            "query_overlap_count": int(query_overlap_count),
        }
        if not self.evidence_warehouse_enable_action_counterfactual_gate:
            return True, "disabled", profile

        no_direct_answer = answer_overlap_count <= 0 and terminal_hits <= 0
        no_path = path_score <= 1e-9
        high_replacement = replacement_value >= 0.75
        very_high_replacement = replacement_value >= 0.88

        if target == "top2":
            if (
                dataset == "musique"
                and very_high_replacement
                and no_direct_answer
                and no_path
            ):
                return False, "action_gate_musique_weak_top2_replacement", profile
            if (
                very_high_replacement
                and no_direct_answer
                and no_path
                and text_score < self.evidence_warehouse_action_gate_top2_min_text_score
                and selectivity_score < self.evidence_warehouse_action_gate_top2_min_selectivity_score
                and answer_aware_score < answer_aware_min_score
            ):
                return False, "action_gate_weak_top2_high_replacement", profile
            if (
                (bool(option.get("top2_guard_bypass", False)) or bool(option.get("answer_aware_top2_guard_bypass", False)))
                and no_direct_answer
                and no_path
                and source_precision < 0.70
                and selectivity_score < self.evidence_warehouse_action_gate_top2_min_selectivity_score
                and answer_aware_score < answer_aware_min_score
            ):
                return False, "action_gate_unsafe_top2_guard_bypass", profile
            return True, "approved", profile

        if target == "top5":
            if (
                dataset == "nq_rear"
                and high_replacement
                and no_direct_answer
                and no_path
                and rule_net_benefit < self.evidence_warehouse_action_gate_nq_top5_min_rule_net
            ):
                return False, "action_gate_nq_negative_top5_replacement", profile
            if (
                dataset in {"musique", "nq_rear"}
                and high_replacement
                and no_direct_answer
                and no_path
                and text_score < self.evidence_warehouse_action_gate_top5_min_text_score
                and selectivity_score < self.evidence_warehouse_action_gate_top5_min_selectivity_score
                and answer_aware_score < answer_aware_min_score
            ):
                return False, "action_gate_weak_top5_high_replacement", profile
            if (
                dataset == "popqa"
                and high_replacement
                and no_direct_answer
                and no_path
                and relation_overlap_count <= 0
                and query_overlap_count <= 1
            ):
                return False, "action_gate_popqa_relationless_top5", profile
        return True, "approved", profile

    def _evidence_warehouse_selectivity_ready(self) -> bool:
        model = self.evidence_warehouse_selectivity_model
        if not isinstance(model, Mapping) or not model:
            return False
        if bool(model.get("weights")) and bool(model.get("feature_names")):
            return True
        sections = model.get("sections", {}) if isinstance(model, Mapping) else {}
        if isinstance(sections, Mapping):
            for section in sections.values():
                if isinstance(section, Mapping) and bool(section.get("weights")) and bool(section.get("feature_names")):
                    return True
        for key in ("all", "top2", "top5"):
            section = model.get(key, {}) if isinstance(model, Mapping) else {}
            if isinstance(section, Mapping) and bool(section.get("weights")) and bool(section.get("feature_names")):
                return True
        return False

    def _evidence_warehouse_selectivity_section_config(
        self,
        target_top2: bool,
        dataset: str = "",
    ) -> Dict[str, Any]:
        model = self.evidence_warehouse_selectivity_model
        if not isinstance(model, Mapping) or not model:
            return {}
        section_key = "top2" if target_top2 else "top5"
        dataset_key = str(dataset or "").strip().lower()
        sections = model.get("sections", {})
        if isinstance(sections, Mapping):
            dataset_sections = model.get("dataset_sections", {})
            if dataset_key and isinstance(dataset_sections, Mapping):
                dataset_config = dataset_sections.get(dataset_key, {})
                if isinstance(dataset_config, Mapping):
                    for key in (section_key, "all"):
                        section = dataset_config.get(key, {})
                        if isinstance(section, Mapping) and section.get("weights") and section.get("feature_names"):
                            merged = dict(model)
                            merged.update(dict(section))
                            merged["section"] = f"{dataset_key}:{key}"
                            return merged
            for key in (f"{dataset_key}:{section_key}", f"{dataset_key}:all", section_key, "all"):
                if not key or key.startswith(":"):
                    continue
                section = sections.get(key, {})
                if isinstance(section, Mapping) and section.get("weights") and section.get("feature_names"):
                    merged = dict(model)
                    merged.update(dict(section))
                    merged["section"] = key
                    return merged
        for key in (section_key, "all"):
            section = model.get(key, {})
            if isinstance(section, Mapping) and section.get("weights") and section.get("feature_names"):
                merged = dict(model)
                merged.update(dict(section))
                merged["section"] = key
                return merged
        if model.get("weights") and model.get("feature_names"):
            root = dict(model)
            root["section"] = "root"
            return root
        return {}

    def _evidence_warehouse_selectivity_features(
        self,
        item: Mapping[str, Any],
        row: Mapping[str, Any],
        option: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
        target_top2: bool,
    ) -> Dict[str, float]:
        text_signal = row.get("text_signal", {}) or {}
        if not isinstance(text_signal, Mapping):
            text_signal = {}
        source_labels = row.get("source_labels", []) or []
        if not isinstance(source_labels, (list, tuple, set)):
            source_labels = [source_labels]
        source_text = " ".join(
            [str(row.get("source_signature") or "")] + [str(label or "") for label in source_labels]
        ).lower()
        contexts = list(item.get("contexts", []) or []) + list(item.get("_all_contexts", []) or [])
        max_plan_precision = 0.0
        min_path_length = 10**9
        strong_context_count = 0
        for context in contexts:
            if not isinstance(context, Mapping):
                continue
            max_plan_precision = max(
                max_plan_precision,
                self._safe_float(context.get("plan_effective_precision"), 0.0),
            )
            path_length = self._safe_int(context.get("path_length"), 10**9)
            if path_length > 0:
                min_path_length = min(min_path_length, path_length)
            if bool(context.get("path_seed_hit", False)) or bool(context.get("path_terminal_hit", False)):
                strong_context_count += 1
        if min_path_length == 10**9:
            min_path_length = 0

        original_rank = self._safe_int(row.get("original_rank"), self._safe_int(item.get("original_rank"), 10**9))
        replacement_rank = self._safe_int(option.get("replacement_rank"), 10**9)
        net_benefit = self._safe_float(option.get("net_benefit"), 0.0)
        required_net_benefit = self._safe_float(option.get("required_net_benefit"), 0.0)
        selectivity_score = self._safe_float(option.get("selectivity_score"), 0.0)
        selectivity_min_score = self._safe_float(option.get("selectivity_min_score"), 0.0)
        dataset = str(query_plan_log.get("dataset") or "").strip().lower()
        reason = str(row.get("original_reason") or row.get("reason") or "").strip().lower()
        query_pressure = self._source_gap_aperture_query_pressure(query_plan_log)
        complex_query = self._query_is_evidence_complex(query_plan_log)
        simple_query = self._query_is_simple_factoid(query_plan_log) or self._is_simple_relation_query(query_plan_log)
        set_coverage = option.get("set_coverage_cbo", {}) or {}
        if not isinstance(set_coverage, Mapping):
            set_coverage = {}
        direct_answer_signal = (
            self._safe_float(text_signal.get("answer_overlap_count"), 0.0) > 0.0
            or self._safe_float(text_signal.get("terminal_hits"), 0.0) > 0.0
        )
        grounded_answer_signal = bool(direct_answer_signal) or (
            self._safe_float(text_signal.get("anchor_hits"), 0.0) > 0.0
            and (
                self._safe_float(text_signal.get("relation_overlap_count"), 0.0) > 0.0
                or self._safe_float(text_signal.get("query_overlap_count"), 0.0) > 0.0
            )
        )
        return {
            "target_top2": 1.0 if target_top2 else 0.0,
            "target_top5": 0.0 if target_top2 else 1.0,
            "candidate_confidence": min(max(self._safe_float(item.get("confidence"), 0.0), 0.0), 1.0),
            "candidate_score": self._safe_float(item.get("score"), 0.0),
            "original_rank_log_inv": 1.0 / max(math.log2(max(original_rank, 2)), 1.0),
            "original_rank_le_50": 1.0 if original_rank <= 50 else 0.0,
            "original_rank_le_100": 1.0 if original_rank <= 100 else 0.0,
            "benefit": self._safe_float(row.get("benefit"), 0.0),
            "risk": self._safe_float(row.get("risk"), 0.0),
            "candidate_value": self._safe_float(row.get("candidate_value"), 0.0),
            "source_precision": self._safe_float(row.get("source_precision"), 0.0),
            "recall_yield": self._safe_float(row.get("recall_yield"), 0.0),
            "source_cost": self._safe_float(row.get("source_cost"), 0.0),
            "text_score": self._safe_float(row.get("text_score"), 0.0),
            "path_score": self._safe_float(row.get("path_score"), 0.0),
            "join_score": self._safe_float(row.get("join_score"), 0.0),
            "operator_score": self._safe_float(row.get("operator_score"), 0.0),
            "query_slot_value": min(self._safe_float(row.get("query_slot_value"), 0.0) / 2.5, 1.0),
            "novelty_value": min(self._safe_float(row.get("novelty_value"), 0.0) / 1.5, 1.0),
            "slot_signal": self._safe_float(row.get("slot_signal"), 0.0),
            "query_pressure": query_pressure,
            "rank_cost": self._safe_float(row.get("rank_cost"), 0.0),
            "answer_signal": 1.0 if bool(row.get("answer_signal", False)) else 0.0,
            "relation_only": 1.0 if bool(row.get("relation_only", False)) else 0.0,
            "structural": 1.0 if bool(row.get("structural", False)) else 0.0,
            "source_is_recall_access": 1.0 if bool(row.get("source_is_recall_access", False)) else 0.0,
            "row_approved": 1.0 if bool(row.get("approved", False)) else 0.0,
            "row_reason_low_benefit": 1.0 if reason == "low_benefit" else 0.0,
            "row_reason_missing_answer_signal": 1.0 if reason == "missing_answer_signal" else 0.0,
            "row_reason_relation_only": 1.0 if reason == "relation_only" else 0.0,
            "row_reason_approved": 1.0 if reason == "approved" else 0.0,
            "text_anchor_hits": min(self._safe_float(text_signal.get("anchor_hits"), 0.0) / 3.0, 1.0),
            "text_terminal_hits": min(self._safe_float(text_signal.get("terminal_hits"), 0.0) / 3.0, 1.0),
            "text_answer_overlap": min(self._safe_float(text_signal.get("answer_overlap_count"), 0.0) / 3.0, 1.0),
            "text_relation_overlap": min(self._safe_float(text_signal.get("relation_overlap_count"), 0.0) / 6.0, 1.0),
            "text_query_overlap": min(self._safe_float(text_signal.get("query_overlap_count"), 0.0) / 8.0, 1.0),
            "direct_answer_signal": 1.0 if direct_answer_signal else 0.0,
            "grounded_answer_signal": 1.0 if grounded_answer_signal else 0.0,
            "replacement_rank_log_inv": 1.0 / max(math.log2(max(replacement_rank, 2)), 1.0),
            "replacement_value": self._safe_float(option.get("replacement_value"), 0.0),
            "replacement_cost": self._safe_float(option.get("replacement_cost"), 0.0),
            "lost_slot_value": min(self._safe_float(option.get("lost_slot_value"), 0.0) / 1.5, 1.0),
            "net_benefit": net_benefit,
            "net_margin": net_benefit - required_net_benefit,
            "selectivity_score": selectivity_score,
            "selectivity_margin": selectivity_score - selectivity_min_score,
            "set_coverage_bonus": self._safe_float(set_coverage.get("bonus"), 0.0),
            "set_coverage_delta": min(max(self._safe_float(set_coverage.get("coverage_delta"), 0.0), -1.0), 1.0),
            "set_coverage_retained_gain": min(max(self._safe_float(set_coverage.get("retained_gain"), 0.0), -1.0), 1.0),
            "set_coverage_gained_slots": min(self._safe_float(set_coverage.get("gained_query_slot_count"), 0.0) / 4.0, 1.0),
            "set_coverage_bypass": 1.0 if bool(option.get("set_coverage_bypass", False)) else 0.0,
            "source_evidence_grounded": 1.0 if "evidence_grounded" in source_text else 0.0,
            "source_support": 1.0 if "support" in source_text else 0.0,
            "source_path_executor": 1.0 if "path_executor" in source_text else 0.0,
            "source_rank_window": 1.0 if "rank_window" in source_text else 0.0,
            "source_utility": 1.0 if "utility" in source_text else 0.0,
            "source_lifted": 1.0 if "lifted" in source_text else 0.0,
            "source_schema_slot": 1.0 if "schema_slot" in source_text else 0.0,
            "source_supervised": 1.0 if "supervised" in source_text else 0.0,
            "context_plan_precision": max_plan_precision,
            "context_path_length_inv": 1.0 / max(float(min_path_length), 1.0) if min_path_length else 0.0,
            "strong_context_count": min(float(strong_context_count) / 3.0, 1.0),
            "query_is_complex": 1.0 if complex_query else 0.0,
            "query_is_simple": 1.0 if simple_query else 0.0,
            "dataset_2wiki": 1.0 if dataset == "2wikimultihopqa" else 0.0,
            "dataset_hotpot": 1.0 if dataset == "hotpotqa" else 0.0,
            "dataset_musique": 1.0 if dataset == "musique" else 0.0,
            "dataset_nq": 1.0 if dataset == "nq_rear" else 0.0,
            "dataset_popqa": 1.0 if dataset == "popqa" else 0.0,
            "dataset_long": 1.0 if dataset in {"lveval", "narrativeqa_dev_10_doc"} else 0.0,
        }

    def _evidence_warehouse_selectivity_score(
        self,
        item: Mapping[str, Any],
        row: Mapping[str, Any],
        option: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
        target_top2: bool,
    ) -> Tuple[float, Dict[str, Any]]:
        dataset = str(query_plan_log.get("dataset") or "").strip().lower()
        config = self._evidence_warehouse_selectivity_section_config(target_top2, dataset=dataset)
        names = list(config.get("feature_names") or [])
        weights_obj = config.get("weights") or []
        if isinstance(weights_obj, Mapping):
            weights = [self._safe_float(weights_obj.get(name), 0.0) for name in names]
        else:
            weights = [self._safe_float(value, 0.0) for value in list(weights_obj or [])]
        if not names or not weights:
            return 0.0, {"ready": False, "target_top2": bool(target_top2)}
        means_obj = config.get("means") or [0.0] * len(names)
        stds_obj = config.get("stds") or [1.0] * len(names)
        if isinstance(means_obj, Mapping):
            means = [self._safe_float(means_obj.get(name), 0.0) for name in names]
        else:
            means = [self._safe_float(value, 0.0) for value in list(means_obj or [])]
        if isinstance(stds_obj, Mapping):
            stds = [self._safe_float(stds_obj.get(name), 1.0) for name in names]
        else:
            stds = [self._safe_float(value, 1.0) for value in list(stds_obj or [])]
        if len(means) < len(names):
            means.extend([0.0] * (len(names) - len(means)))
        if len(stds) < len(names):
            stds.extend([1.0] * (len(names) - len(stds)))
        features = self._evidence_warehouse_selectivity_features(
            item=item,
            row=row,
            option=option,
            query_plan_log=query_plan_log,
            target_top2=target_top2,
        )
        total = self._safe_float(config.get("bias"), 0.0)
        feature_snapshot: Dict[str, float] = {}
        snapshot_names = {
            "target_top2",
            "candidate_confidence",
            "original_rank_log_inv",
            "benefit",
            "risk",
            "candidate_value",
            "source_precision",
            "text_score",
            "path_score",
            "operator_score",
            "novelty_value",
            "answer_signal",
            "relation_only",
            "replacement_value",
            "lost_slot_value",
            "net_benefit",
            "net_margin",
            "source_path_executor",
            "context_plan_precision",
        }
        for index, name in enumerate(names):
            if index >= len(weights):
                break
            std = stds[index] if abs(stds[index]) > 1e-9 else 1.0
            value = self._safe_float(features.get(name), 0.0)
            total += weights[index] * ((value - means[index]) / std)
            if name in snapshot_names:
                feature_snapshot[name] = round(float(value), 6)
        score = 1.0 / (1.0 + float(np.exp(-np.clip(total, -40.0, 40.0))))
        score = min(max(float(score), 0.0), 1.0)
        runtime_min_score = (
            self.evidence_warehouse_selectivity_top2_min_score
            if target_top2
            else self.evidence_warehouse_selectivity_min_score
        )
        min_score = max(
            self._safe_float(config.get("min_score"), runtime_min_score),
            runtime_min_score,
        )
        return score, {
            "ready": True,
            "target_top2": bool(target_top2),
            "section": str(config.get("section") or ("top2" if target_top2 else "top5")),
            "objective": str(config.get("objective") or "selectivity"),
            "label": str(config.get("label") or ""),
            "score": round(float(score), 6),
            "min_score": round(float(min_score), 6),
            "feature_snapshot": feature_snapshot,
        }

    def _evidence_warehouse_answer_aware_model_ready(self) -> bool:
        model = self.evidence_warehouse_answer_aware_model
        if not isinstance(model, Mapping) or not model:
            return False
        if bool(model.get("weights")) and bool(model.get("feature_names")):
            return True
        sections = model.get("sections", {}) if isinstance(model, Mapping) else {}
        if isinstance(sections, Mapping):
            for section in sections.values():
                if isinstance(section, Mapping) and bool(section.get("weights")) and bool(section.get("feature_names")):
                    return True
        for key in ("all", "top2", "top5"):
            section = model.get(key, {}) if isinstance(model, Mapping) else {}
            if isinstance(section, Mapping) and bool(section.get("weights")) and bool(section.get("feature_names")):
                return True
        return False

    def _evidence_warehouse_answer_aware_section_config(
        self,
        target_top2: bool,
        dataset: str = "",
    ) -> Dict[str, Any]:
        model = self.evidence_warehouse_answer_aware_model
        if not isinstance(model, Mapping) or not model:
            return {}
        section_key = "top2" if target_top2 else "top5"
        dataset_key = str(dataset or "").strip().lower()
        sections = model.get("sections", {})
        if isinstance(sections, Mapping):
            dataset_sections = model.get("dataset_sections", {})
            if dataset_key and isinstance(dataset_sections, Mapping):
                dataset_config = dataset_sections.get(dataset_key, {})
                if isinstance(dataset_config, Mapping):
                    for key in (section_key, "all"):
                        section = dataset_config.get(key, {})
                        if isinstance(section, Mapping) and section.get("weights") and section.get("feature_names"):
                            merged = dict(model)
                            merged.update(dict(section))
                            merged["section"] = f"{dataset_key}:{key}"
                            return merged
            for key in (f"{dataset_key}:{section_key}", f"{dataset_key}:all", section_key, "all"):
                if not key or key.startswith(":"):
                    continue
                section = sections.get(key, {})
                if isinstance(section, Mapping) and section.get("weights") and section.get("feature_names"):
                    merged = dict(model)
                    merged.update(dict(section))
                    merged["section"] = key
                    return merged
        for key in (section_key, "all"):
            section = model.get(key, {})
            if isinstance(section, Mapping) and section.get("weights") and section.get("feature_names"):
                merged = dict(model)
                merged.update(dict(section))
                merged["section"] = key
                return merged
        if model.get("weights") and model.get("feature_names"):
            root = dict(model)
            root["section"] = "root"
            return root
        return {}

    def _evidence_warehouse_answer_aware_prior_score(
        self,
        features: Mapping[str, float],
        target_top2: bool,
        dataset: str,
    ) -> float:
        direct_answer = max(
            self._safe_float(features.get("direct_answer_signal"), 0.0),
            self._safe_float(features.get("text_answer_overlap"), 0.0),
            self._safe_float(features.get("text_terminal_hits"), 0.0),
        )
        grounded_answer = self._safe_float(features.get("grounded_answer_signal"), 0.0)
        text_score = self._safe_float(features.get("text_score"), 0.0)
        path_score = self._safe_float(features.get("path_score"), 0.0)
        source_precision = self._safe_float(features.get("source_precision"), 0.0)
        join_score = self._safe_float(features.get("join_score"), 0.0)
        operator_score = self._safe_float(features.get("operator_score"), 0.0)
        context_plan_precision = self._safe_float(features.get("context_plan_precision"), 0.0)
        slot_signal = max(
            self._safe_float(features.get("novelty_value"), 0.0),
            self._safe_float(features.get("set_coverage_bonus"), 0.0),
            0.55 * self._safe_float(features.get("set_coverage_gained_slots"), 0.0),
            self._safe_float(features.get("slot_signal"), 0.0),
        )
        net_margin = self._safe_float(features.get("net_margin"), 0.0)
        risk = self._safe_float(features.get("risk"), 0.0)
        replacement_value = self._safe_float(features.get("replacement_value"), 0.0)
        lost_slot_value = self._safe_float(features.get("lost_slot_value"), 0.0)
        relation_only = self._safe_float(features.get("relation_only"), 0.0)
        simple_query = self._safe_float(features.get("query_is_simple"), 0.0)
        source_support = max(
            self._safe_float(features.get("source_support"), 0.0),
            self._safe_float(features.get("source_path_executor"), 0.0),
            self._safe_float(features.get("source_evidence_grounded"), 0.0),
        )

        logit = -1.05
        logit += 1.55 * direct_answer
        logit += 0.70 * grounded_answer
        logit += 1.05 * text_score
        logit += 0.78 * path_score
        logit += 0.62 * source_precision
        logit += 0.48 * join_score
        logit += 0.32 * operator_score
        logit += 0.44 * context_plan_precision
        logit += 0.42 * source_support
        logit += 0.50 * slot_signal
        logit += 0.48 * net_margin
        logit -= 1.18 * risk
        logit -= 0.72 * replacement_value
        logit -= 0.52 * lost_slot_value
        logit -= 0.58 * relation_only

        if target_top2:
            logit -= 0.12
            logit += 0.42 * direct_answer
            logit += 0.28 * max(path_score, source_precision)
            if replacement_value >= 0.80 and direct_answer <= 0.0:
                logit -= 0.55
        else:
            logit += 0.12 * slot_signal
            if replacement_value >= 0.78 and direct_answer <= 0.0 and path_score < 0.58:
                logit -= 0.36

        if dataset == "nq_rear" and not target_top2 and direct_answer <= 0.0:
            logit -= 0.34
        if dataset == "popqa" and simple_query > 0.5 and direct_answer <= 0.0:
            logit -= 0.42
        if dataset in {"lveval", "narrativeqa_dev_10_doc"}:
            logit -= 0.18

        score = 1.0 / (1.0 + float(np.exp(-np.clip(logit, -40.0, 40.0))))
        return min(max(float(score), 0.0), 1.0)

    def _evidence_warehouse_answer_aware_score(
        self,
        item: Mapping[str, Any],
        row: Mapping[str, Any],
        option: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
        target_top2: bool,
    ) -> Tuple[float, Dict[str, Any]]:
        mode = str(self.evidence_warehouse_answer_aware_mode or "off").strip().lower()
        dataset = str(query_plan_log.get("dataset") or "").strip().lower()
        min_score = (
            self.evidence_warehouse_answer_aware_top2_min_score
            if target_top2
            else self.evidence_warehouse_answer_aware_min_score
        )
        if mode == "off":
            return 1.0, {
                "enabled": False,
                "mode": mode,
                "ready": False,
                "score": 1.0,
                "min_score": round(float(min_score), 6),
            }

        features = self._evidence_warehouse_selectivity_features(
            item=item,
            row=row,
            option=option,
            query_plan_log=query_plan_log,
            target_top2=target_top2,
        )
        model_ready = self._evidence_warehouse_answer_aware_model_ready()
        use_model = mode == "model" or (mode == "auto" and model_ready)
        if use_model and not model_ready:
            return 1.0, {
                "enabled": False,
                "mode": mode,
                "ready": False,
                "reason": "model_not_ready",
                "score": 1.0,
                "min_score": round(float(min_score), 6),
            }

        feature_snapshot: Dict[str, float] = {}
        snapshot_names = {
            "target_top2",
            "candidate_confidence",
            "benefit",
            "risk",
            "source_precision",
            "text_score",
            "path_score",
            "join_score",
            "operator_score",
            "novelty_value",
            "direct_answer_signal",
            "grounded_answer_signal",
            "text_answer_overlap",
            "text_terminal_hits",
            "replacement_value",
            "lost_slot_value",
            "net_margin",
            "selectivity_score",
            "selectivity_margin",
            "set_coverage_bonus",
            "set_coverage_delta",
            "set_coverage_gained_slots",
            "query_is_simple",
            "dataset_nq",
            "dataset_popqa",
        }

        if use_model:
            config = self._evidence_warehouse_answer_aware_section_config(
                target_top2=target_top2,
                dataset=dataset,
            )
            names = list(config.get("feature_names") or [])
            weights_obj = config.get("weights") or []
            if isinstance(weights_obj, Mapping):
                weights = [self._safe_float(weights_obj.get(name), 0.0) for name in names]
            else:
                weights = [self._safe_float(value, 0.0) for value in list(weights_obj or [])]
            if not names or not weights:
                return 1.0, {
                    "enabled": False,
                    "mode": mode,
                    "ready": False,
                    "reason": "empty_model_section",
                    "score": 1.0,
                    "min_score": round(float(min_score), 6),
                }
            means_obj = config.get("means") or [0.0] * len(names)
            stds_obj = config.get("stds") or [1.0] * len(names)
            if isinstance(means_obj, Mapping):
                means = [self._safe_float(means_obj.get(name), 0.0) for name in names]
            else:
                means = [self._safe_float(value, 0.0) for value in list(means_obj or [])]
            if isinstance(stds_obj, Mapping):
                stds = [self._safe_float(stds_obj.get(name), 1.0) for name in names]
            else:
                stds = [self._safe_float(value, 1.0) for value in list(stds_obj or [])]
            if len(means) < len(names):
                means.extend([0.0] * (len(names) - len(means)))
            if len(stds) < len(names):
                stds.extend([1.0] * (len(names) - len(stds)))
            total = self._safe_float(config.get("bias"), 0.0)
            for index, name in enumerate(names):
                if index >= len(weights):
                    break
                std = stds[index] if abs(stds[index]) > 1e-9 else 1.0
                value = self._safe_float(features.get(name), 0.0)
                total += weights[index] * ((value - means[index]) / std)
                if name in snapshot_names:
                    feature_snapshot[name] = round(float(value), 6)
            score = 1.0 / (1.0 + float(np.exp(-np.clip(total, -40.0, 40.0))))
            score = min(max(float(score), 0.0), 1.0)
            section = str(config.get("section") or ("top2" if target_top2 else "top5"))
            objective = str(config.get("objective") or "answer_aware_benefit")
            source = "model"
        else:
            score = self._evidence_warehouse_answer_aware_prior_score(
                features=features,
                target_top2=target_top2,
                dataset=dataset,
            )
            for name in snapshot_names:
                if name in features:
                    feature_snapshot[name] = round(float(features.get(name, 0.0)), 6)
            section = "builtin_prior"
            objective = "answer_aware_builtin_prior"
            source = "prior"

        direct_answer_signal = bool(self._safe_float(features.get("direct_answer_signal"), 0.0) > 0.0)
        grounded_answer_signal = bool(self._safe_float(features.get("grounded_answer_signal"), 0.0) > 0.0)
        return score, {
            "enabled": True,
            "mode": mode,
            "ready": True,
            "source": source,
            "target_top2": bool(target_top2),
            "section": section,
            "objective": objective,
            "score": round(float(score), 6),
            "min_score": round(float(min_score), 6),
            "direct_answer_signal": bool(direct_answer_signal),
            "grounded_answer_signal": bool(grounded_answer_signal),
            "require_direct_signal": bool(self.evidence_warehouse_answer_aware_require_direct_signal),
            "feature_snapshot": feature_snapshot,
        }

    def _evidence_warehouse_selectivity_recall_bypass(
        self,
        item: Mapping[str, Any],
        row: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, Dict[str, Any]]:
        reason = str(row.get("reason") or "").strip().lower()
        dataset = str(query_plan_log.get("dataset") or "").strip().lower()
        text_signal = row.get("text_signal", {}) or {}
        if not isinstance(text_signal, Mapping):
            text_signal = {}
        original_rank = self._safe_int(row.get("original_rank"), self._safe_int(item.get("original_rank"), 10**9))
        confidence = min(max(self._safe_float(item.get("confidence"), 0.0), 0.0), 1.0)
        text_score = self._safe_float(row.get("text_score"), 0.0)
        path_score = self._safe_float(row.get("path_score"), 0.0)
        risk = self._safe_float(row.get("risk"), 0.0)
        relation_overlap = self._safe_int(text_signal.get("relation_overlap_count"), 0)
        query_overlap = self._safe_int(text_signal.get("query_overlap_count"), 0)
        terminal_hits = self._safe_int(text_signal.get("terminal_hits"), 0)
        anchor_hits = self._safe_int(text_signal.get("anchor_hits"), 0)
        structural = bool(row.get("structural", False))
        source_is_recall_access = bool(row.get("source_is_recall_access", False))
        profile: Dict[str, Any] = {
            "enabled": bool(self.evidence_warehouse_selectivity_enable_recall_bypass),
            "dataset": dataset,
            "reason": reason,
            "model_ready": self._evidence_warehouse_selectivity_ready(),
            "original_rank": int(original_rank),
            "confidence": round(float(confidence), 6),
            "text_score": round(float(text_score), 6),
            "path_score": round(float(path_score), 6),
            "risk": round(float(risk), 6),
            "relation_overlap_count": int(relation_overlap),
            "query_overlap_count": int(query_overlap),
            "terminal_hits": int(terminal_hits),
            "anchor_hits": int(anchor_hits),
            "structural": bool(structural),
            "source_is_recall_access": bool(source_is_recall_access),
        }
        if not self.evidence_warehouse_selectivity_enable_recall_bypass:
            profile["decision"] = "disabled"
            return False, profile
        if not self._evidence_warehouse_selectivity_ready():
            profile["decision"] = "model_not_ready"
            return False, profile
        if self.evidence_warehouse_selectivity_bypass_datasets and dataset not in self.evidence_warehouse_selectivity_bypass_datasets:
            profile["decision"] = "dataset_not_allowed"
            return False, profile
        if self.evidence_warehouse_selectivity_bypass_reasons and reason not in self.evidence_warehouse_selectivity_bypass_reasons:
            profile["decision"] = "reason_not_allowed"
            return False, profile
        if (
            self.evidence_warehouse_selectivity_bypass_max_original_rank > 0
            and original_rank > self.evidence_warehouse_selectivity_bypass_max_original_rank
        ):
            profile["decision"] = "rank_after_bypass_window"
            return False, profile
        if confidence < self.evidence_warehouse_selectivity_bypass_min_confidence:
            profile["decision"] = "low_confidence"
            return False, profile
        if risk > self.evidence_warehouse_selectivity_bypass_max_risk:
            profile["decision"] = "high_risk"
            return False, profile
        text_or_structure = (
            text_score >= self.evidence_warehouse_selectivity_bypass_min_text_score
            or path_score >= 0.58
            or terminal_hits > 0
            or (anchor_hits > 0 and (relation_overlap > 0 or query_overlap > 0))
            or (relation_overlap > 0 and query_overlap > 0)
            or structural
            or source_is_recall_access
        )
        if not text_or_structure:
            profile["decision"] = "weak_signal"
            return False, profile
        probe_replacement_value = 0.70
        probe_option = {
            "target": "top5",
            "replacement_rank": 5,
            "replacement_value": probe_replacement_value,
            "replacement_cost": probe_replacement_value,
            "lost_slot_value": 0.0,
            "net_benefit": (
                self._safe_float(row.get("benefit"), 0.0)
                - self.evidence_warehouse_cost_weight * probe_replacement_value
                - self.evidence_warehouse_risk_weight * risk
            ),
            "required_net_benefit": self.evidence_warehouse_min_net_benefit,
        }
        score, selectivity = self._evidence_warehouse_selectivity_score(
            item=item,
            row=row,
            option=probe_option,
            query_plan_log=query_plan_log,
            target_top2=False,
        )
        min_score = max(
            self.evidence_warehouse_selectivity_bypass_min_score,
            self._safe_float(selectivity.get("min_score"), self.evidence_warehouse_selectivity_bypass_min_score)
            - self.evidence_warehouse_selectivity_bypass_score_relaxation,
        )
        profile["selectivity"] = dict(selectivity)
        profile["score"] = round(float(score), 6)
        profile["min_score"] = round(float(min_score), 6)
        if score < min_score:
            profile["decision"] = "selectivity_low_score"
            return False, profile
        profile["decision"] = "approved"
        return True, profile

    def _final_rank_evidence_warehouse_set_coverage_profile(
        self,
        item: Mapping[str, Any],
        row: Mapping[str, Any],
        selected: Sequence[int],
        passage_details: Mapping[int, Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
        replacement_doc: int = -1,
    ) -> Dict[str, Any]:
        query_slots = self._evidence_join_query_slots(query_plan_log)
        current_slots = self._evidence_warehouse_selected_slots(
            selected=selected,
            passage_details=passage_details,
            query_plan_log=query_plan_log,
        )
        retained_slots = self._evidence_warehouse_selected_slots(
            selected=selected,
            passage_details=passage_details,
            query_plan_log=query_plan_log,
            exclude_doc=int(replacement_doc),
        )
        candidate_slots = set(row.get("candidate_slots", []) or [])
        if not candidate_slots:
            join_profile = self._evidence_join_profile(item, query_plan_log)
            candidate_slots.update(join_profile.get("slots", []) or [])
        if not candidate_slots:
            candidate_slots.update(
                self._evidence_join_context_slots(
                    self._all_candidate_contexts(item),
                    query_plan_log,
                )
            )

        after_slots = set(retained_slots) | set(candidate_slots)
        current_value = self._evidence_join_slot_value(current_slots, query_slots)
        retained_value = self._evidence_join_slot_value(retained_slots, query_slots)
        after_value = self._evidence_join_slot_value(after_slots, query_slots)
        coverage_delta = after_value - current_value
        retained_gain = after_value - retained_value
        gained_query_slots = set(candidate_slots) & (set(query_slots) - set(current_slots))
        recovered_lost_slots = set(candidate_slots) & (set(current_slots) - set(retained_slots))
        bonus_basis = max(float(coverage_delta), 0.0)
        if gained_query_slots:
            bonus_basis += 0.08 * min(len(gained_query_slots), 3)
        if recovered_lost_slots:
            bonus_basis += 0.04 * min(len(recovered_lost_slots), 3)
        bonus = self.evidence_warehouse_set_coverage_weight * min(bonus_basis / 0.80, 1.0)
        return {
            "enabled": bool(self.evidence_warehouse_enable_set_coverage_cbo),
            "replacement_doc": int(replacement_doc),
            "current_value": round(float(current_value), 6),
            "retained_value": round(float(retained_value), 6),
            "after_value": round(float(after_value), 6),
            "coverage_delta": round(float(coverage_delta), 6),
            "retained_gain": round(float(retained_gain), 6),
            "bonus_basis": round(float(bonus_basis), 6),
            "bonus": round(float(bonus), 6),
            "candidate_slot_count": int(len(candidate_slots)),
            "current_slot_count": int(len(current_slots)),
            "after_slot_count": int(len(after_slots)),
            "gained_query_slot_count": int(len(gained_query_slots)),
            "gained_query_slots": sorted(gained_query_slots)[:16],
            "recovered_lost_slot_count": int(len(recovered_lost_slots)),
            "recovered_lost_slots": sorted(recovered_lost_slots)[:16],
        }

    def _final_rank_evidence_warehouse_set_coverage_bypass_ok(
        self,
        row: Mapping[str, Any],
        profile: Mapping[str, Any],
        is_top2: bool,
    ) -> bool:
        if not self.evidence_warehouse_enable_set_coverage_cbo or is_top2:
            return False
        risk = self._safe_float(row.get("risk"), 0.0)
        if risk > self.evidence_warehouse_set_coverage_max_risk:
            return False
        if bool(row.get("relation_only", False)) and not bool(row.get("answer_signal", False)):
            return False
        coverage_delta = self._safe_float(profile.get("coverage_delta"), 0.0)
        retained_gain = self._safe_float(profile.get("retained_gain"), 0.0)
        gained_query_slots = self._safe_int(profile.get("gained_query_slot_count"), 0)
        if (
            coverage_delta < self.evidence_warehouse_set_coverage_min_gain
            and retained_gain < self.evidence_warehouse_set_coverage_min_gain
            and gained_query_slots <= 0
        ):
            return False
        text_score = self._safe_float(row.get("text_score"), 0.0)
        path_score = self._safe_float(row.get("path_score"), 0.0)
        source_precision = self._safe_float(row.get("source_precision"), 0.0)
        support_ok = (
            bool(row.get("answer_signal", False))
            or bool(row.get("structural", False))
            or bool(row.get("source_is_recall_access", False))
            or text_score >= 0.10
            or path_score >= 0.42
            or source_precision >= 0.08
        )
        return bool(support_ok)

    def _apply_final_rank_evidence_warehouse_optimizer(
        self,
        final_doc_ids: Sequence[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        passage_details: Mapping[int, Mapping[str, Any]],
        original_rank_by_doc: Mapping[int, int],
        max_raw_score: float,
    ) -> Tuple[List[int], Dict[str, Any]]:
        stats: Dict[str, Any] = {
            "enabled": bool(self.enable_final_rank_evidence_warehouse),
            "route_enabled": False,
            "candidate_count": 0,
            "selected_count": 0,
            "top2_used_count": 0,
            "top5_used_count": 0,
            "best_net_benefit": 0.0,
            "rejection_reasons": {},
            "rejected_candidates": [],
            "selected_candidates": [],
            "row_samples": [],
            "changed_top2": False,
            "changed_top5": False,
            "selectivity_model_path": self.evidence_warehouse_selectivity_model_path,
            "selectivity_model_ready": self._evidence_warehouse_selectivity_ready(),
            "selectivity_low_score_count": 0,
            "selectivity_recall_bypass_candidate_count": 0,
            "selectivity_recall_bypass_selected_count": 0,
            "action_counterfactual_gate_enabled": bool(
                self.evidence_warehouse_enable_action_counterfactual_gate
            ),
            "action_counterfactual_gate_rejected_count": 0,
            "set_coverage_cbo_enabled": bool(self.evidence_warehouse_enable_set_coverage_cbo),
            "set_coverage_bypass_candidate_count": 0,
            "set_coverage_bypass_selected_count": 0,
            "set_coverage_bonus_sum": 0.0,
            "set_coverage_bonus_observed": 0,
            "answer_aware_mode": self.evidence_warehouse_answer_aware_mode,
            "answer_aware_enabled": self.evidence_warehouse_answer_aware_mode != "off",
            "answer_aware_model_path": self.evidence_warehouse_answer_aware_model_path,
            "answer_aware_model_ready": self._evidence_warehouse_answer_aware_model_ready(),
            "answer_aware_low_score_count": 0,
            "answer_aware_direct_signal_rejected_count": 0,
            "answer_aware_top2_guard_bypass_count": 0,
            "answer_aware_score_sum": 0.0,
            "answer_aware_score_observed": 0,
            "selected_answer_aware_score_sum": 0.0,
            "selected_answer_aware_score_count": 0,
        }
        current = [int(doc_id) for doc_id in final_doc_ids]
        if not self.enable_final_rank_evidence_warehouse:
            return current, stats
        route = self._evidence_warehouse_route(query_plan_log)
        if not bool(route.get("enabled", False)):
            stats["route_reason"] = str(route.get("reason") or "disabled")
            return current, stats
        stats["route_enabled"] = True
        stats["route_reason"] = str(route.get("reason") or "enabled")
        top_k = min(int(self.final_top_k), len(current))
        if top_k <= 1:
            stats["route_reason"] = "top_window_too_small"
            return current, stats

        before_top2 = current[:2]
        before_top5 = current[:top_k]
        presorted = [
            item for item in candidates
            if self._safe_int(item.get("passage_idx"), -1) >= 0
            and self._safe_int(item.get("passage_idx"), -1) not in set(current[:top_k])
        ]
        presorted.sort(
            key=lambda item: (
                self._candidate_evidence_value(item),
                self._safe_float(item.get("score"), 0.0),
                self._safe_float(item.get("confidence"), 0.0),
                -self._safe_int(item.get("original_rank"), 10**9),
            ),
            reverse=True,
        )
        if self.evidence_warehouse_max_candidates > 0:
            presorted = presorted[: self.evidence_warehouse_max_candidates]

        top2_used = 0
        top5_used = 0
        rejections: Counter = Counter()
        rejected_candidates: List[Dict[str, Any]] = []
        selected_candidates: List[Dict[str, Any]] = []
        row_samples: List[Dict[str, Any]] = []
        best_net_benefit = 0.0
        query_slots = self._evidence_join_query_slots(query_plan_log)

        for item in presorted:
            candidate_doc = self._safe_int(item.get("passage_idx"), -1)
            if candidate_doc < 0 or candidate_doc in set(current[:top_k]):
                continue
            row = self._evidence_warehouse_candidate_row(
                item=item,
                selected=current[:top_k],
                passage_details=passage_details,
                query_plan_log=query_plan_log,
            )
            item["final_rank_evidence_warehouse"] = dict(row)
            row_bypass_approved = False
            row_bypass_profile: Dict[str, Any] = {}
            if not bool(row.get("approved", False)):
                row_bypass_approved, row_bypass_profile = self._evidence_warehouse_selectivity_recall_bypass(
                    item=item,
                    row=row,
                    query_plan_log=query_plan_log,
                )
                if row_bypass_approved:
                    original_reason = str(row.get("reason") or "not_approved")
                    row = {
                        **dict(row),
                        "approved": True,
                        "reason": f"selectivity_recall_bypass:{original_reason}",
                        "original_reason": original_reason,
                        "selectivity_recall_bypass": dict(row_bypass_profile),
                    }
                    item["final_rank_evidence_warehouse"] = dict(row)
                    stats["selectivity_recall_bypass_candidate_count"] = (
                        int(stats.get("selectivity_recall_bypass_candidate_count", 0) or 0) + 1
                    )
                elif row_bypass_profile:
                    row = {
                        **dict(row),
                        "selectivity_recall_bypass": dict(row_bypass_profile),
                    }
                    item["final_rank_evidence_warehouse"] = dict(row)
            if (
                not bool(row.get("approved", False))
                and self.evidence_warehouse_enable_set_coverage_cbo
            ):
                original_reason = str(row.get("reason") or "not_approved")
                row_set_coverage_profile = self._final_rank_evidence_warehouse_set_coverage_profile(
                    item=item,
                    row=row,
                    selected=current[:top_k],
                    passage_details=passage_details,
                    query_plan_log=query_plan_log,
                    replacement_doc=-1,
                )
                if self._final_rank_evidence_warehouse_set_coverage_bypass_ok(
                    row=row,
                    profile=row_set_coverage_profile,
                    is_top2=False,
                ):
                    row = {
                        **dict(row),
                        "approved": True,
                        "reason": f"set_coverage_bypass:{original_reason}",
                        "original_reason": original_reason,
                        "set_coverage_cbo": dict(row_set_coverage_profile),
                    }
                    item["final_rank_evidence_warehouse"] = dict(row)
                    stats["set_coverage_bypass_candidate_count"] = (
                        int(stats.get("set_coverage_bypass_candidate_count", 0) or 0) + 1
                    )
            item["_final_rank_evidence_warehouse_candidate"] = bool(row.get("approved", False))
            stats["candidate_count"] = int(stats["candidate_count"]) + 1
            if len(row_samples) < 24:
                row_samples.append({
                    "passage_idx": int(candidate_doc),
                    "original_rank": self._safe_int(item.get("original_rank"), 0),
                    "approved": bool(row.get("approved", False)),
                    "reason": str(row.get("reason") or ""),
                    "benefit": self._safe_float(row.get("benefit"), 0.0),
                    "risk": self._safe_float(row.get("risk"), 0.0),
                    "source_signature": str(row.get("source_signature") or ""),
                    "source_precision": self._safe_float(row.get("source_precision"), 0.0),
                    "text_score": self._safe_float(row.get("text_score"), 0.0),
                    "path_score": self._safe_float(row.get("path_score"), 0.0),
                    "novelty_value": self._safe_float(row.get("novelty_value"), 0.0),
                    "answer_signal": bool(row.get("answer_signal", False)),
                    "relation_only": bool(row.get("relation_only", False)),
                    "selectivity_recall_bypass": bool(row_bypass_approved),
                })
            if not bool(row.get("approved", False)):
                reason = str(row.get("reason") or "not_approved")
                rejections[reason] += 1
                if len(rejected_candidates) < 12 and reason not in {"low_benefit"}:
                    rejected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=False,
                            reason=f"final_rank_warehouse_rejected:{reason}",
                        )
                    )
                continue

            benefit = self._safe_float(row.get("benefit"), 0.0)
            risk = self._safe_float(row.get("risk"), 0.0)
            row_bypass_approved = bool(
                isinstance(row.get("selectivity_recall_bypass", {}), Mapping)
                and (row.get("selectivity_recall_bypass", {}) or {}).get("decision") == "approved"
            )
            options: List[Dict[str, Any]] = []
            top2_guard_reasons: Counter = Counter()
            for index in range(top_k):
                final_rank = index + 1
                if final_rank == 1:
                    continue
                is_top2 = final_rank <= 2
                if is_top2 and (
                    self.evidence_warehouse_max_top2_swaps <= 0
                    or top2_used >= self.evidence_warehouse_max_top2_swaps
                ):
                    continue
                if (not is_top2) and (
                    self.evidence_warehouse_max_top5_swaps <= 0
                    or top5_used >= self.evidence_warehouse_max_top5_swaps
                    or final_rank <= self.evidence_warehouse_protect_top_k
                ):
                    continue
                replacement_doc = int(current[index])
                if replacement_doc == candidate_doc:
                    continue
                replacement_rank = int(original_rank_by_doc.get(replacement_doc, final_rank))
                detail = passage_details.get(replacement_doc)
                if detail:
                    replacement_rank = self._safe_int(detail.get("original_rank"), replacement_rank)
                replacement_value = self._baseline_replacement_value(
                    replacement_doc,
                    replacement_rank,
                    passage_details,
                    max_raw_score,
                )
                replacement_slots = self._evidence_join_doc_slots(
                    replacement_doc,
                    passage_details,
                    query_plan_log,
                )
                other_slots = self._evidence_warehouse_selected_slots(
                    selected=current[:top_k],
                    passage_details=passage_details,
                    query_plan_log=query_plan_log,
                    exclude_doc=replacement_doc,
                )
                lost_slots = set(replacement_slots) - set(other_slots)
                lost_slot_value = self._evidence_join_slot_value(lost_slots, query_slots)
                replacement_cost = replacement_value + 0.20 * min(lost_slot_value / 1.2, 1.0)
                required = (
                    self.evidence_warehouse_top2_min_net_benefit
                    if is_top2
                    else self.evidence_warehouse_min_net_benefit
                )
                if is_top2:
                    required += 0.04
                elif final_rank == 3:
                    required += 0.02
                net_benefit = (
                    benefit
                    - self.evidence_warehouse_cost_weight * replacement_cost
                    - self.evidence_warehouse_risk_weight * risk
                )
                set_coverage_profile = (
                    self._final_rank_evidence_warehouse_set_coverage_profile(
                        item=item,
                        row=row,
                        selected=current[:top_k],
                        passage_details=passage_details,
                        query_plan_log=query_plan_log,
                        replacement_doc=replacement_doc,
                    )
                    if self.evidence_warehouse_enable_set_coverage_cbo
                    else {"enabled": False, "bonus": 0.0}
                )
                set_coverage_bypass_ok = self._final_rank_evidence_warehouse_set_coverage_bypass_ok(
                    row=row,
                    profile=set_coverage_profile,
                    is_top2=is_top2,
                )
                set_coverage_bonus = (
                    self._safe_float(set_coverage_profile.get("bonus"), 0.0)
                    if self.evidence_warehouse_enable_set_coverage_cbo
                    else 0.0
                )
                if set_coverage_bonus > 0.0:
                    net_benefit += set_coverage_bonus
                top2_guard_profile: Dict[str, Any] = {}
                top2_guard_reason = ""
                top2_guard_ok = True
                if is_top2:
                    top2_guard_ok, top2_guard_reason, top2_guard_profile = (
                        self._final_rank_evidence_warehouse_top2_guard(
                            row=row,
                            replacement_value=replacement_value,
                            lost_slot_value=lost_slot_value,
                        )
                    )
                else:
                    text_score = self._safe_float(row.get("text_score"), 0.0)
                    path_score = self._safe_float(row.get("path_score"), 0.0)
                    source_precision = self._safe_float(row.get("source_precision"), 0.0)
                    if risk > 0.24 and not (row_bypass_approved or set_coverage_bypass_ok):
                        top2_guard_reasons["top5_high_risk"] += 1
                        continue
                    if not (
                        text_score >= 0.34
                        or path_score >= 0.66
                        or source_precision >= 0.58
                        or bool(row.get("structural", False))
                        or row_bypass_approved
                        or set_coverage_bypass_ok
                    ):
                        top2_guard_reasons["top5_weak_support"] += 1
                        continue
                option = {
                    "target": "top2" if is_top2 else "top5",
                    "replacement_index": int(index),
                    "replacement_doc": int(replacement_doc),
                    "replacement_rank": int(replacement_rank),
                    "replacement_value": round(float(replacement_value), 6),
                    "replacement_cost": round(float(replacement_cost), 6),
                    "lost_slot_value": round(float(lost_slot_value), 6),
                    "lost_slots": sorted(lost_slots)[:24],
                    "net_benefit": round(float(net_benefit), 6),
                    "required_net_benefit": round(float(required), 6),
                }
                if self.evidence_warehouse_enable_set_coverage_cbo:
                    option["set_coverage_cbo"] = dict(set_coverage_profile)
                    option["set_coverage_bypass"] = bool(set_coverage_bypass_ok)
                    if set_coverage_bonus > 0.0:
                        stats["set_coverage_bonus_sum"] = (
                            self._safe_float(stats.get("set_coverage_bonus_sum"), 0.0)
                            + float(set_coverage_bonus)
                        )
                        stats["set_coverage_bonus_observed"] = (
                            int(stats.get("set_coverage_bonus_observed", 0) or 0) + 1
                        )
                if is_top2:
                    option["top2_guard"] = top2_guard_profile
                    option["top2_guard_reason"] = top2_guard_reason
                if self._evidence_warehouse_selectivity_ready():
                    selectivity_score, selectivity_profile = self._evidence_warehouse_selectivity_score(
                        item=item,
                        row=row,
                        option=option,
                        query_plan_log=query_plan_log,
                        target_top2=is_top2,
                    )
                    min_selectivity = self._safe_float(
                        selectivity_profile.get("min_score"),
                        self.evidence_warehouse_selectivity_top2_min_score
                        if is_top2
                        else self.evidence_warehouse_selectivity_min_score,
                    )
                    if row_bypass_approved and not is_top2:
                        min_selectivity = max(
                            self.evidence_warehouse_selectivity_bypass_min_score,
                            min_selectivity - self.evidence_warehouse_selectivity_bypass_score_relaxation,
                        )
                    option["selectivity"] = selectivity_profile
                    option["selectivity_score"] = round(float(selectivity_score), 6)
                    option["selectivity_min_score"] = round(float(min_selectivity), 6)
                    if selectivity_score < min_selectivity:
                        relaxed_min_selectivity = max(float(min_selectivity) - 0.10, 0.42)
                        if not (
                            set_coverage_bypass_ok
                            and not is_top2
                            and selectivity_score >= relaxed_min_selectivity
                        ):
                            top2_guard_reasons["selectivity_low_score"] += 1
                            continue
                        option["set_coverage_selectivity_bypass"] = {
                            "enabled": True,
                            "score": round(float(selectivity_score), 6),
                            "original_min_score": round(float(min_selectivity), 6),
                            "relaxed_min_score": round(float(relaxed_min_selectivity), 6),
                        }
                        min_selectivity = relaxed_min_selectivity
                        option["selectivity_min_score"] = round(float(min_selectivity), 6)
                    calibrated_net_benefit = net_benefit + (
                        self.evidence_warehouse_selectivity_score_weight
                        * (selectivity_score - min_selectivity)
                    )
                    if row_bypass_approved and not is_top2:
                        calibrated_net_benefit += self.evidence_warehouse_selectivity_bypass_net_bonus
                        option["required_net_benefit"] = round(
                            float(min(required, max(required - 0.5 * self.evidence_warehouse_selectivity_bypass_net_bonus, 0.0))),
                            6,
                        )
                        option["selectivity_recall_bypass"] = dict(row.get("selectivity_recall_bypass", {}) or {})
                    option["rule_net_benefit"] = round(float(net_benefit), 6)
                    option["net_benefit"] = round(float(calibrated_net_benefit), 6)
                if self.evidence_warehouse_answer_aware_mode != "off":
                    answer_score, answer_profile = self._evidence_warehouse_answer_aware_score(
                        item=item,
                        row=row,
                        option=option,
                        query_plan_log=query_plan_log,
                        target_top2=is_top2,
                    )
                    option["answer_aware_cost_model"] = dict(answer_profile)
                    if bool(answer_profile.get("enabled", False)) and bool(answer_profile.get("ready", False)):
                        answer_min_score = self._safe_float(
                            answer_profile.get("min_score"),
                            self.evidence_warehouse_answer_aware_top2_min_score
                            if is_top2
                            else self.evidence_warehouse_answer_aware_min_score,
                        )
                        option["answer_aware_score"] = round(float(answer_score), 6)
                        option["answer_aware_min_score"] = round(float(answer_min_score), 6)
                        stats["answer_aware_score_sum"] = (
                            self._safe_float(stats.get("answer_aware_score_sum"), 0.0)
                            + float(answer_score)
                        )
                        stats["answer_aware_score_observed"] = (
                            int(stats.get("answer_aware_score_observed", 0) or 0) + 1
                        )
                        if (
                            self.evidence_warehouse_answer_aware_require_direct_signal
                            and not bool(answer_profile.get("direct_answer_signal", False))
                            and not (
                                bool(answer_profile.get("grounded_answer_signal", False))
                                and self._safe_float(row.get("path_score"), 0.0) >= 0.58
                            )
                        ):
                            top2_guard_reasons["answer_aware_missing_direct_signal"] += 1
                            continue
                        if answer_score < answer_min_score:
                            top2_guard_reasons["answer_aware_low_score"] += 1
                            continue
                        option["pre_answer_aware_net_benefit"] = option.get("net_benefit")
                        option["net_benefit"] = round(
                            float(
                                self._safe_float(option.get("net_benefit"), 0.0)
                                + self.evidence_warehouse_answer_aware_score_weight
                                * (float(answer_score) - float(answer_min_score))
                            ),
                            6,
                        )
                if is_top2 and not top2_guard_ok:
                    selectivity_score = self._safe_float(option.get("selectivity_score"), 0.0)
                    selectivity_min_score = self._safe_float(
                        option.get("selectivity_min_score"),
                        self.evidence_warehouse_selectivity_top2_min_score,
                    )
                    answer_aware_profile = option.get("answer_aware_cost_model", {}) or {}
                    if not isinstance(answer_aware_profile, Mapping):
                        answer_aware_profile = {}
                    answer_aware_score = self._safe_float(
                        answer_aware_profile.get("score"),
                        self._safe_float(option.get("answer_aware_score"), 0.0),
                    )
                    bypass_min_score = max(
                        selectivity_min_score,
                        self.evidence_warehouse_selectivity_top2_guard_bypass_min_score,
                    )
                    bypassable_reasons = {
                        "top2_low_benefit",
                        "top2_rank_after_safe_window",
                        "top2_replacement_covers_key_slot",
                        "top2_weak_support",
                    }
                    selectivity_guard_bypass_ok = (
                        self.evidence_warehouse_selectivity_enable_top2_guard_bypass
                        and self._evidence_warehouse_selectivity_ready()
                        and top2_guard_reason in bypassable_reasons
                        and selectivity_score >= bypass_min_score
                        and risk <= self.evidence_warehouse_selectivity_top2_guard_bypass_max_risk
                    )
                    answer_guard_bypass_min_score = max(
                        self.evidence_warehouse_answer_aware_top2_guard_bypass_min_score,
                        self.evidence_warehouse_answer_aware_top2_min_score,
                    )
                    answer_guard_bypass_ok = (
                        self.evidence_warehouse_answer_aware_allow_top2_guard_bypass
                        and bool(answer_aware_profile.get("enabled", False))
                        and bool(answer_aware_profile.get("ready", False))
                        and top2_guard_reason in bypassable_reasons
                        and answer_aware_score >= answer_guard_bypass_min_score
                        and risk <= self.evidence_warehouse_answer_aware_top2_guard_bypass_max_risk
                    )
                    top2_guard_bypass_ok = bool(selectivity_guard_bypass_ok or answer_guard_bypass_ok)
                    if not top2_guard_bypass_ok:
                        top2_guard_reasons[top2_guard_reason or "top2_guard_rejected"] += 1
                        continue
                    if answer_guard_bypass_ok and not selectivity_guard_bypass_ok:
                        stats["answer_aware_top2_guard_bypass_count"] = (
                            int(stats.get("answer_aware_top2_guard_bypass_count", 0) or 0) + 1
                        )
                        option["answer_aware_top2_guard_bypass"] = {
                            "enabled": True,
                            "reason": str(top2_guard_reason),
                            "answer_aware_score": round(float(answer_aware_score), 6),
                            "bypass_min_score": round(float(answer_guard_bypass_min_score), 6),
                            "max_risk": round(float(self.evidence_warehouse_answer_aware_top2_guard_bypass_max_risk), 6),
                        }
                    else:
                        option["top2_guard_bypass"] = {
                            "enabled": True,
                            "reason": str(top2_guard_reason),
                            "selectivity_score": round(float(selectivity_score), 6),
                            "bypass_min_score": round(float(bypass_min_score), 6),
                            "max_risk": round(float(self.evidence_warehouse_selectivity_top2_guard_bypass_max_risk), 6),
                        }
                    option["required_net_benefit"] = round(
                        float(min(
                            self._safe_float(option.get("required_net_benefit"), required),
                            max(required - 0.02, 0.0),
                        )),
                        6,
                    )
                action_gate_ok, action_gate_reason, action_gate_profile = (
                    self._final_rank_evidence_warehouse_action_counterfactual_gate(
                        row=row,
                        option=option,
                        query_plan_log=query_plan_log,
                    )
                )
                option["action_counterfactual_gate"] = {
                    **dict(action_gate_profile),
                    "approved": bool(action_gate_ok),
                    "reason": str(action_gate_reason),
                }
                if not action_gate_ok:
                    top2_guard_reasons[action_gate_reason or "action_counterfactual_gate_rejected"] += 1
                    continue
                options.append(option)
            if not options:
                if top2_guard_reasons:
                    for reason, count in top2_guard_reasons.items():
                        rejections[reason] += int(count)
                else:
                    rejections["no_replaceable_final_rank_slot"] += 1
                if len(rejected_candidates) < 12:
                    rejected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=False,
                            reason="final_rank_warehouse_rejected:no_replaceable_slot",
                        )
                    )
                continue
            best = max(
                options,
                key=lambda option: (
                    self._safe_float(option.get("net_benefit"), 0.0),
                    1 if str(option.get("target") or "") == "top2" else 0,
                    -self._safe_int(option.get("replacement_index"), 10**9),
                ),
            )
            net_benefit = self._safe_float(best.get("net_benefit"), 0.0)
            required = self._safe_float(best.get("required_net_benefit"), 0.0)
            best_net_benefit = max(best_net_benefit, net_benefit)
            if net_benefit < required:
                rejections["low_net_benefit"] += 1
                if len(rejected_candidates) < 12:
                    rejected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=False,
                            reason="final_rank_warehouse_rejected:low_net_benefit",
                        )
                    )
                continue

            replacement_index = self._safe_int(best.get("replacement_index"), -1)
            replacement_doc = self._safe_int(best.get("replacement_doc"), -1)
            if replacement_index < 0 or replacement_index >= len(current):
                rejections["invalid_replacement_index"] += 1
                continue
            try:
                candidate_index = current.index(candidate_doc)
            except ValueError:
                candidate_index = -1
            current[replacement_index] = candidate_doc
            if candidate_index >= 0 and candidate_index != replacement_index:
                current[candidate_index] = replacement_doc
            target = str(best.get("target") or "top5")
            final_rank = replacement_index + 1
            item["_final_rank_evidence_warehouse_selected"] = True
            item["_final_rank_evidence_warehouse_replaced_doc"] = int(replacement_doc)
            item["final_rank_evidence_warehouse"] = {
                **dict(item.get("final_rank_evidence_warehouse", {}) or {}),
                "action": dict(best),
            }
            if target == "top2":
                item["_final_rank_evidence_warehouse_top2_selected"] = True
                top2_used += 1
            else:
                item["_final_rank_evidence_warehouse_top5_selected"] = True
                top5_used += 1
            if row_bypass_approved:
                stats["selectivity_recall_bypass_selected_count"] = (
                    int(stats.get("selectivity_recall_bypass_selected_count", 0) or 0) + 1
                )
            if bool(best.get("set_coverage_bypass", False)):
                stats["set_coverage_bypass_selected_count"] = (
                    int(stats.get("set_coverage_bypass_selected_count", 0) or 0) + 1
                )
            answer_aware_action = best.get("answer_aware_cost_model", {}) or {}
            if isinstance(answer_aware_action, Mapping) and bool(answer_aware_action.get("enabled", False)):
                stats["selected_answer_aware_score_sum"] = (
                    self._safe_float(stats.get("selected_answer_aware_score_sum"), 0.0)
                    + self._safe_float(answer_aware_action.get("score"), 0.0)
                )
                stats["selected_answer_aware_score_count"] = (
                    int(stats.get("selected_answer_aware_score_count", 0) or 0) + 1
                )
            if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                selected_ontology.append(item)
            if len(selected_candidates) < 12:
                selected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason=f"final_rank_warehouse_{target}_selected",
                        final_rank=int(final_rank),
                    )
                )
            if (
                top2_used >= self.evidence_warehouse_max_top2_swaps
                and top5_used >= self.evidence_warehouse_max_top5_swaps
            ):
                break

        stats.update({
            "selected_count": int(top2_used + top5_used),
            "top2_used_count": int(top2_used),
            "top5_used_count": int(top5_used),
            "best_net_benefit": round(float(best_net_benefit), 6),
            "rejection_reasons": dict(rejections),
            "rejected_candidates": rejected_candidates,
            "selected_candidates": selected_candidates,
            "row_samples": row_samples,
            "changed_top2": before_top2 != current[:2],
            "changed_top5": before_top5 != current[:top_k],
            "selectivity_low_score_count": int(rejections.get("selectivity_low_score", 0)),
            "selectivity_recall_bypass_candidate_count": int(
                stats.get("selectivity_recall_bypass_candidate_count", 0) or 0
            ),
            "selectivity_recall_bypass_selected_count": int(
                stats.get("selectivity_recall_bypass_selected_count", 0) or 0
            ),
            "action_counterfactual_gate_enabled": bool(
                self.evidence_warehouse_enable_action_counterfactual_gate
            ),
            "action_counterfactual_gate_rejected_count": int(
                sum(
                    int(count)
                    for reason, count in rejections.items()
                    if str(reason).startswith("action_gate_")
                )
            ),
            "set_coverage_cbo_enabled": bool(self.evidence_warehouse_enable_set_coverage_cbo),
            "set_coverage_bypass_candidate_count": int(
                stats.get("set_coverage_bypass_candidate_count", 0) or 0
            ),
            "set_coverage_bypass_selected_count": int(
                stats.get("set_coverage_bypass_selected_count", 0) or 0
            ),
            "set_coverage_bonus_avg": (
                self._safe_float(stats.get("set_coverage_bonus_sum"), 0.0)
                / max(int(stats.get("set_coverage_bonus_observed", 0) or 0), 1)
            ),
            "answer_aware_mode": self.evidence_warehouse_answer_aware_mode,
            "answer_aware_enabled": self.evidence_warehouse_answer_aware_mode != "off",
            "answer_aware_model_path": self.evidence_warehouse_answer_aware_model_path,
            "answer_aware_model_ready": self._evidence_warehouse_answer_aware_model_ready(),
            "answer_aware_low_score_count": int(rejections.get("answer_aware_low_score", 0)),
            "answer_aware_direct_signal_rejected_count": int(
                rejections.get("answer_aware_missing_direct_signal", 0)
            ),
            "answer_aware_top2_guard_bypass_count": int(
                stats.get("answer_aware_top2_guard_bypass_count", 0) or 0
            ),
            "answer_aware_score_avg": (
                self._safe_float(stats.get("answer_aware_score_sum"), 0.0)
                / max(int(stats.get("answer_aware_score_observed", 0) or 0), 1)
            ),
            "selected_answer_aware_score_avg": (
                self._safe_float(stats.get("selected_answer_aware_score_sum"), 0.0)
                / max(int(stats.get("selected_answer_aware_score_count", 0) or 0), 1)
            ),
        })
        return current, stats

    def _top5_to_top2_promotion_route(self, query_plan_log: Mapping[str, Any]) -> Dict[str, Any]:
        dataset = str(
            query_plan_log.get("dataset")
            or query_plan_log.get("dataset_name")
            or ""
        ).strip().lower()
        target_allowed = (
            not self.top5_to_top2_promotion_target_datasets
            or dataset in self.top5_to_top2_promotion_target_datasets
        )
        if not self.enable_top5_to_top2_promotion:
            return {"enabled": False, "reason": "disabled", "dataset": dataset}
        if not target_allowed:
            return {"enabled": False, "reason": "dataset_not_targeted", "dataset": dataset}
        if self.top5_to_top2_promotion_max_promotions <= 0:
            return {"enabled": False, "reason": "max_promotions_zero", "dataset": dataset}
        return {"enabled": True, "reason": "enabled", "dataset": dataset}

    def _top5_to_top2_candidate_item(
        self,
        doc_id: int,
        passage_details: Mapping[int, Mapping[str, Any]],
        original_rank_by_doc: Mapping[int, int],
        max_raw_score: float,
    ) -> Dict[str, Any]:
        detail = dict(passage_details.get(int(doc_id), {}) or {})
        contexts = [context for context in detail.get("contexts", []) or [] if isinstance(context, Mapping)]
        confidence = self._candidate_confidence(detail, max_raw_score) if detail else 0.0
        original_rank = self._safe_int(
            detail.get("original_rank"),
            self._safe_int(original_rank_by_doc.get(int(doc_id)), 10**9),
        )
        decision = dict(detail.get("reranker_decision", {}) or {})
        if confidence > self._safe_float(decision.get("confidence"), -1.0):
            decision["confidence"] = confidence
        if "source" not in decision:
            decision["source"] = "top5_window"
        return {
            "passage_idx": int(doc_id),
            "original_rank": int(original_rank),
            "score": self._safe_float(detail.get("raw_lift_score"), confidence),
            "confidence": confidence,
            "raw_lift_score": self._safe_float(detail.get("raw_lift_score"), confidence),
            "contexts": contexts,
            "_all_contexts": contexts,
            "reranker_decision": decision,
        }

    def _top5_to_top2_support_score(
        self,
        row: Mapping[str, Any],
        top2_slot_value: float,
    ) -> float:
        benefit = self._safe_float(row.get("benefit"), 0.0)
        risk = self._safe_float(row.get("risk"), 0.0)
        text_score = self._safe_float(row.get("text_score"), 0.0)
        path_score = self._safe_float(row.get("path_score"), 0.0)
        source_precision = self._safe_float(row.get("source_precision"), 0.0)
        confidence = self._safe_float(row.get("confidence"), 0.0)
        slot_score = min(max(float(top2_slot_value) / 1.2, 0.0), 1.0)
        support = (
            benefit
            + 0.25 * text_score
            + 0.20 * path_score
            + 0.16 * source_precision
            + 0.20 * slot_score
            + 0.04 * min(confidence, 1.0)
            - 0.35 * risk
        )
        return round(float(support), 6)

    def _apply_top5_to_top2_promotion(
        self,
        final_doc_ids: Sequence[int],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        passage_details: Mapping[int, Mapping[str, Any]],
        original_rank_by_doc: Mapping[int, int],
        max_raw_score: float,
    ) -> Tuple[List[int], Dict[str, Any]]:
        route = self._top5_to_top2_promotion_route(query_plan_log)
        stats: Dict[str, Any] = {
            "enabled": bool(self.enable_top5_to_top2_promotion),
            "route_enabled": bool(route.get("enabled", False)),
            "route_reason": str(route.get("reason") or "not_evaluated"),
            "candidate_count": 0,
            "selected_count": 0,
            "changed_top2": False,
            "changed_top5": False,
            "best_score": 0.0,
            "best_margin": 0.0,
            "rank2_support_score": 0.0,
            "rejection_reasons": {},
            "selected_candidates": [],
            "rejected_candidates": [],
            "row_samples": [],
        }
        current = [int(doc_id) for doc_id in final_doc_ids]
        if not bool(route.get("enabled", False)):
            return current, stats
        top_k = min(int(self.final_top_k), len(current))
        if top_k < 3:
            stats["route_reason"] = "top5_window_too_small"
            stats["route_enabled"] = False
            return current, stats

        before_top2 = current[:2]
        before_top5 = current[:top_k]
        top1_doc = int(current[0])
        rank2_doc = int(current[1])
        query_slots = self._evidence_join_query_slots(query_plan_log)
        top1_slots = self._evidence_join_doc_slots(top1_doc, passage_details, query_plan_log)
        rank2_slots = self._evidence_join_doc_slots(rank2_doc, passage_details, query_plan_log)
        rank2_top2_slot_value = self._evidence_join_slot_value(set(rank2_slots) - set(top1_slots), query_slots)
        rank2_item = self._top5_to_top2_candidate_item(
            rank2_doc,
            passage_details=passage_details,
            original_rank_by_doc=original_rank_by_doc,
            max_raw_score=max_raw_score,
        )
        rank2_row = self._evidence_warehouse_candidate_row(
            item=rank2_item,
            selected=[doc for doc in current[:top_k] if int(doc) != rank2_doc],
            passage_details=passage_details,
            query_plan_log=query_plan_log,
        )
        rank2_value = self._baseline_replacement_value(
            rank2_doc,
            self._safe_int(original_rank_by_doc.get(rank2_doc), 2),
            passage_details,
            max_raw_score,
        )
        rank2_support_score = max(
            0.42 * min(rank2_value, 1.0),
            self._top5_to_top2_support_score(rank2_row, rank2_top2_slot_value),
        )
        stats["rank2_support_score"] = round(float(rank2_support_score), 6)

        rejections: Counter = Counter()
        row_samples: List[Dict[str, Any]] = []
        rejected_candidates: List[Dict[str, Any]] = []
        options: List[Dict[str, Any]] = []
        option_items: Dict[int, Dict[str, Any]] = {}

        for index in range(2, top_k):
            candidate_doc = int(current[index])
            detail = passage_details.get(candidate_doc, {}) or {}
            contexts = [context for context in detail.get("contexts", []) or [] if isinstance(context, Mapping)]
            item = self._top5_to_top2_candidate_item(
                candidate_doc,
                passage_details=passage_details,
                original_rank_by_doc=original_rank_by_doc,
                max_raw_score=max_raw_score,
            )
            option_items[candidate_doc] = item
            stats["candidate_count"] = int(stats["candidate_count"]) + 1
            if self.top5_to_top2_promotion_require_ontology_signal and not contexts:
                rejections["missing_ontology_signal"] += 1
                if len(rejected_candidates) < 10:
                    rejected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=False,
                            reason="top5_to_top2_rejected:missing_ontology_signal",
                            final_rank=index + 1,
                        )
                    )
                continue

            selected_without_candidate = [doc for doc in current[:top_k] if int(doc) != candidate_doc]
            row = self._evidence_warehouse_candidate_row(
                item=item,
                selected=selected_without_candidate,
                passage_details=passage_details,
                query_plan_log=query_plan_log,
            )
            candidate_slots = self._evidence_join_doc_slots(candidate_doc, passage_details, query_plan_log)
            candidate_top2_slot_value = self._evidence_join_slot_value(
                set(candidate_slots) - set(top1_slots),
                query_slots,
            )
            unique_vs_rank2_value = self._evidence_join_slot_value(
                set(candidate_slots) - (set(top1_slots) | set(rank2_slots)),
                query_slots,
            )
            text_score = self._safe_float(row.get("text_score"), 0.0)
            path_score = self._safe_float(row.get("path_score"), 0.0)
            source_precision = self._safe_float(row.get("source_precision"), 0.0)
            risk = self._safe_float(row.get("risk"), 0.0)
            answer_signal = bool(row.get("answer_signal", False))
            structural = bool(row.get("structural", False))
            score = self._top5_to_top2_support_score(row, candidate_top2_slot_value)
            score += 0.10 * min(max(unique_vs_rank2_value / 1.2, 0.0), 1.0)
            score -= 0.025 * max(index - 2, 0)
            score = round(float(score), 6)
            margin = round(float(score - rank2_support_score), 6)
            support_ok = (
                text_score >= self.top5_to_top2_promotion_min_text_score
                or path_score >= self.top5_to_top2_promotion_min_path_score
                or source_precision >= self.top5_to_top2_promotion_min_source_precision
                or candidate_top2_slot_value >= self.top5_to_top2_promotion_min_slot_value
                or answer_signal
                or structural
            )
            sample = {
                "passage_idx": int(candidate_doc),
                "current_rank": int(index + 1),
                "original_rank": self._safe_int(item.get("original_rank"), 0),
                "score": score,
                "margin": margin,
                "rank2_support_score": round(float(rank2_support_score), 6),
                "benefit": self._safe_float(row.get("benefit"), 0.0),
                "risk": risk,
                "text_score": text_score,
                "path_score": path_score,
                "source_precision": source_precision,
                "top2_slot_value": round(float(candidate_top2_slot_value), 6),
                "unique_vs_rank2_value": round(float(unique_vs_rank2_value), 6),
                "answer_signal": bool(answer_signal),
                "structural": bool(structural),
                "source_signature": str(row.get("source_signature") or ""),
            }
            if len(row_samples) < 24:
                row_samples.append(dict(sample))
            if risk > self.top5_to_top2_promotion_max_risk:
                rejections["high_risk"] += 1
                continue
            if not support_ok:
                rejections["weak_support"] += 1
                continue
            if score < self.top5_to_top2_promotion_min_score:
                rejections["low_score"] += 1
                continue
            if margin < self.top5_to_top2_promotion_min_margin:
                rejections["low_margin"] += 1
                continue
            options.append({
                **sample,
                "replacement_doc": int(rank2_doc),
                "replacement_rank": 2,
            })

        if options:
            best = max(
                options,
                key=lambda option: (
                    self._safe_float(option.get("margin"), 0.0),
                    self._safe_float(option.get("score"), 0.0),
                    -self._safe_int(option.get("current_rank"), 10**9),
                ),
            )
            candidate_doc = self._safe_int(best.get("passage_idx"), -1)
            try:
                candidate_index = current.index(candidate_doc)
            except ValueError:
                candidate_index = -1
            if candidate_index >= 2:
                current[1], current[candidate_index] = current[candidate_index], current[1]
                item = option_items.get(candidate_doc) or self._top5_to_top2_candidate_item(
                    candidate_doc,
                    passage_details=passage_details,
                    original_rank_by_doc=original_rank_by_doc,
                    max_raw_score=max_raw_score,
                )
                item["_top5_to_top2_promotion_selected"] = True
                item["_top5_to_top2_promotion_replaced_doc"] = int(rank2_doc)
                item["top5_to_top2_promotion"] = dict(best)
                if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                    selected_ontology.append(item)
                selected_log = self._decision_for_log(
                    item,
                    selected=True,
                    reason="top5_to_top2_promotion_selected",
                    final_rank=2,
                )
                stats["selected_candidates"] = [selected_log]
                stats["selected_count"] = 1
                stats["best_score"] = self._safe_float(best.get("score"), 0.0)
                stats["best_margin"] = self._safe_float(best.get("margin"), 0.0)
            else:
                rejections["invalid_candidate_index"] += 1

        stats.update({
            "changed_top2": before_top2 != current[:2],
            "changed_top5": before_top5 != current[:top_k],
            "rejection_reasons": dict(rejections),
            "rejected_candidates": rejected_candidates,
            "row_samples": row_samples,
        })
        return current, stats

    def _regret_calibrated_set_route(self, query_plan_log: Mapping[str, Any]) -> Dict[str, Any]:
        dataset = str(
            query_plan_log.get("dataset")
            or query_plan_log.get("dataset_name")
            or ""
        ).strip().lower()
        target_allowed = (
            not self.regret_calibrated_set_target_datasets
            or dataset in self.regret_calibrated_set_target_datasets
        )
        if not self.enable_regret_calibrated_set_optimizer:
            reason = "disabled"
        elif not target_allowed:
            reason = "dataset_not_targeted"
        elif (
            self.regret_calibrated_set_max_top2_swaps <= 0
            and self.regret_calibrated_set_max_top5_swaps <= 0
        ):
            reason = "zero_swap_budget"
        else:
            reason = "enabled"
        pressure = self._source_gap_aperture_query_pressure(query_plan_log)
        operator_profile = self._evidence_join_operator_profile(query_plan_log)
        return {
            "enabled": reason == "enabled",
            "reason": reason,
            "dataset": dataset,
            "query_pressure": round(float(pressure), 6),
            "operator": str(operator_profile.get("operator") or "single"),
            "complex": bool(operator_profile.get("complex", False)),
        }

    def _regret_calibrated_replacement_options(
        self,
        candidate_doc: int,
        current: Sequence[int],
        passage_details: Mapping[int, Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
        original_rank_by_doc: Mapping[int, int],
        max_raw_score: float,
        top2_used: int,
        top5_used: int,
    ) -> List[Dict[str, Any]]:
        top_k = min(int(self.final_top_k), len(current))
        query_slots = self._evidence_join_query_slots(query_plan_log)
        options: List[Dict[str, Any]] = []
        for index in range(top_k):
            final_rank = index + 1
            if int(current[index]) == int(candidate_doc):
                continue
            is_top2 = final_rank <= 2
            if is_top2:
                if self.regret_calibrated_set_max_top2_swaps <= 0:
                    continue
                if top2_used >= self.regret_calibrated_set_max_top2_swaps:
                    continue
                if self.regret_calibrated_set_protect_top1 and final_rank == 1:
                    continue
            else:
                if self.regret_calibrated_set_max_top5_swaps <= 0:
                    continue
                if top5_used >= self.regret_calibrated_set_max_top5_swaps:
                    continue

            replacement_doc = int(current[index])
            replacement_rank = int(original_rank_by_doc.get(replacement_doc, final_rank))
            detail = passage_details.get(replacement_doc)
            if detail:
                replacement_rank = self._safe_int(detail.get("original_rank"), replacement_rank)
            replacement_value = self._baseline_replacement_value(
                replacement_doc,
                replacement_rank,
                passage_details,
                max_raw_score,
            )
            replacement_slots = self._evidence_join_doc_slots(
                replacement_doc,
                passage_details,
                query_plan_log,
            )
            other_slots = self._evidence_warehouse_selected_slots(
                selected=current[:top_k],
                passage_details=passage_details,
                query_plan_log=query_plan_log,
                exclude_doc=replacement_doc,
            )
            lost_slots = set(replacement_slots) - set(other_slots)
            lost_slot_value = self._evidence_join_slot_value(lost_slots, query_slots)
            replacement_cost = replacement_value + 0.22 * min(lost_slot_value / 1.2, 1.0)
            if is_top2:
                replacement_cost += 0.045
            options.append({
                "target": "top2" if is_top2 else "top5",
                "replacement_index": int(index),
                "replacement_doc": int(replacement_doc),
                "replacement_rank": int(replacement_rank),
                "replacement_value": round(float(replacement_value), 6),
                "replacement_cost": round(float(replacement_cost), 6),
                "lost_slot_value": round(float(lost_slot_value), 6),
                "lost_slots": sorted(lost_slots)[:32],
            })
        return options

    def _regret_calibrated_option_score(
        self,
        item: Mapping[str, Any],
        row: Mapping[str, Any],
        option: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
        missing_slots: Set[str],
        query_slots: Set[str],
        gap_pressure: float,
    ) -> Tuple[float, Dict[str, Any]]:
        text_score = self._safe_float(row.get("text_score"), 0.0)
        path_score = self._safe_float(row.get("path_score"), 0.0)
        source_precision = self._safe_float(row.get("source_precision"), 0.0)
        recall_yield = self._safe_float(row.get("recall_yield"), 0.0)
        benefit = self._safe_float(row.get("benefit"), 0.0)
        risk = self._safe_float(row.get("risk"), 0.0)
        candidate_value = self._safe_float(row.get("candidate_value"), 0.0)
        novelty_value = self._safe_float(row.get("novelty_value"), 0.0)
        join_score = self._safe_float(row.get("join_score"), 0.0)
        operator_score = self._safe_float(row.get("operator_score"), 0.0)
        original_rank = self._safe_int(row.get("original_rank"), 10**9)
        target = str(option.get("target") or "top5")
        is_top2 = target == "top2"

        candidate_slots = set(row.get("novelty_slots", []) or [])
        if not candidate_slots:
            candidate_slots = self._evidence_join_context_slots(
                self._all_candidate_contexts(item),
                query_plan_log,
            )
        slot_repair = self._evidence_join_slot_value(candidate_slots & missing_slots, query_slots)
        support_signal = max(
            text_score,
            0.78 * path_score,
            0.68 * source_precision,
            0.58 * candidate_value,
            0.54 * join_score,
        )
        answer_signal = bool(row.get("answer_signal", False))
        structural = bool(row.get("structural", False))
        relation_only = bool(row.get("relation_only", False))
        replacement_cost = self._safe_float(option.get("replacement_cost"), 0.0)

        regret = (
            benefit
            + self.regret_calibrated_set_gap_weight * min(gap_pressure, 1.0)
            + self.regret_calibrated_set_slot_weight * min(slot_repair, 1.2)
            + 0.090 * text_score
            + 0.075 * path_score
            + 0.070 * max(source_precision, 0.65 * recall_yield)
            + 0.050 * candidate_value
            + 0.045 * join_score
            + 0.035 * operator_score
            + (0.045 if answer_signal else 0.0)
            + (0.030 if structural else 0.0)
            - self.regret_calibrated_set_cost_weight * replacement_cost
            - self.regret_calibrated_set_risk_weight * risk
        )
        if relation_only:
            regret -= 0.055
        if original_rank > 80 and is_top2:
            regret -= 0.035
        elif original_rank > 180:
            regret -= 0.020

        profile = {
            "regret": round(float(regret), 6),
            "benefit": round(float(benefit), 6),
            "risk": round(float(risk), 6),
            "support_signal": round(float(support_signal), 6),
            "slot_repair_value": round(float(slot_repair), 6),
            "gap_pressure": round(float(gap_pressure), 6),
            "text_score": round(float(text_score), 6),
            "path_score": round(float(path_score), 6),
            "source_precision": round(float(source_precision), 6),
            "candidate_value": round(float(candidate_value), 6),
            "join_score": round(float(join_score), 6),
            "operator_score": round(float(operator_score), 6),
            "answer_signal": bool(answer_signal),
            "structural": bool(structural),
            "relation_only": bool(relation_only),
            "original_rank": int(original_rank),
            "candidate_slots": sorted(candidate_slots)[:32],
            "missing_overlap": sorted(candidate_slots & missing_slots)[:32],
            "option": dict(option),
        }
        return round(float(regret), 6), profile

    def _apply_regret_calibrated_set_optimizer(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        passage_details: Mapping[int, Mapping[str, Any]],
        original_rank_by_doc: Mapping[int, int],
        max_raw_score: float,
    ) -> Dict[str, Any]:
        route = self._regret_calibrated_set_route(query_plan_log)
        stats: Dict[str, Any] = {
            "enabled": bool(self.enable_regret_calibrated_set_optimizer),
            "route_enabled": bool(route.get("enabled", False)),
            "route_reason": str(route.get("reason") or "not_evaluated"),
            "route_dataset": str(route.get("dataset") or ""),
            "operator": str(route.get("operator") or "single"),
            "query_pressure": self._safe_float(route.get("query_pressure"), 0.0),
            "candidate_count": 0,
            "option_count": 0,
            "selected_count": 0,
            "top2_used_count": 0,
            "top5_used_count": 0,
            "changed_top2": False,
            "changed_top5": False,
            "best_regret": 0.0,
            "best_top2_regret": 0.0,
            "best_top5_regret": 0.0,
            "missing_top2_slot_value": 0.0,
            "missing_top5_slot_value": 0.0,
            "rejection_reasons": {},
            "selected_candidates": [],
            "rejected_candidates": [],
            "row_samples": [],
        }
        if not bool(route.get("enabled", False)):
            return stats
        top_k = min(int(self.final_top_k), len(selected))
        if top_k <= 1:
            stats["route_reason"] = "top_window_too_small"
            stats["route_enabled"] = False
            return stats

        before_top2 = [int(doc_id) for doc_id in selected[:2]]
        before_top5 = [int(doc_id) for doc_id in selected[:top_k]]
        query_slots = self._evidence_join_query_slots(query_plan_log)
        selected_top2_slots = self._evidence_warehouse_selected_slots(
            selected=selected[:2],
            passage_details=passage_details,
            query_plan_log=query_plan_log,
        )
        selected_top5_slots = self._evidence_warehouse_selected_slots(
            selected=selected[:top_k],
            passage_details=passage_details,
            query_plan_log=query_plan_log,
        )
        missing_top2_slots = set(query_slots) - set(selected_top2_slots)
        missing_top5_slots = set(query_slots) - set(selected_top5_slots)
        missing_top2_value = self._evidence_join_slot_value(missing_top2_slots, query_slots)
        missing_top5_value = self._evidence_join_slot_value(missing_top5_slots, query_slots)
        query_pressure = max(
            self._safe_float(route.get("query_pressure"), 0.0),
            0.12 * min(missing_top2_value, 1.0),
            0.08 * min(missing_top5_value, 1.0),
        )
        stats["missing_top2_slot_value"] = round(float(missing_top2_value), 6)
        stats["missing_top5_slot_value"] = round(float(missing_top5_value), 6)
        stats["query_pressure"] = round(float(query_pressure), 6)

        presorted = [
            item for item in candidates
            if self._safe_int(item.get("passage_idx"), -1) >= 0
            and self._safe_int(item.get("passage_idx"), -1) not in set(selected[:top_k])
            and (
                self.regret_calibrated_set_max_original_rank <= 0
                or self._safe_int(item.get("original_rank"), 10**9)
                <= self.regret_calibrated_set_max_original_rank
            )
        ]
        presorted.sort(
            key=lambda item: (
                self._candidate_evidence_value(item),
                self._safe_float(item.get("score"), 0.0),
                self._safe_float(item.get("confidence"), 0.0),
                -self._safe_int(item.get("original_rank"), 10**9),
            ),
            reverse=True,
        )
        if self.regret_calibrated_set_max_candidates > 0:
            presorted = presorted[: self.regret_calibrated_set_max_candidates]

        rejections: Counter = Counter()
        rejected_candidates: List[Dict[str, Any]] = []
        row_samples: List[Dict[str, Any]] = []
        options: List[Dict[str, Any]] = []
        item_by_doc: Dict[int, Dict[str, Any]] = {}
        for item in presorted:
            candidate_doc = self._safe_int(item.get("passage_idx"), -1)
            if candidate_doc < 0 or candidate_doc in item_by_doc:
                continue
            item_by_doc[int(candidate_doc)] = item
            row = self._evidence_warehouse_candidate_row(
                item=item,
                selected=selected[:top_k],
                passage_details=passage_details,
                query_plan_log=query_plan_log,
            )
            item["regret_calibrated_set_optimizer"] = dict(row)
            stats["candidate_count"] = int(stats["candidate_count"]) + 1
            if len(row_samples) < 24:
                row_samples.append({
                    "passage_idx": int(candidate_doc),
                    "original_rank": self._safe_int(item.get("original_rank"), 0),
                    "row_approved": bool(row.get("approved", False)),
                    "row_reason": str(row.get("reason") or ""),
                    "benefit": self._safe_float(row.get("benefit"), 0.0),
                    "risk": self._safe_float(row.get("risk"), 0.0),
                    "source_precision": self._safe_float(row.get("source_precision"), 0.0),
                    "text_score": self._safe_float(row.get("text_score"), 0.0),
                    "path_score": self._safe_float(row.get("path_score"), 0.0),
                    "answer_signal": bool(row.get("answer_signal", False)),
                    "relation_only": bool(row.get("relation_only", False)),
                })

            risk = self._safe_float(row.get("risk"), 0.0)
            text_score = self._safe_float(row.get("text_score"), 0.0)
            path_score = self._safe_float(row.get("path_score"), 0.0)
            source_precision = self._safe_float(row.get("source_precision"), 0.0)
            candidate_value = self._safe_float(row.get("candidate_value"), 0.0)
            join_score = self._safe_float(row.get("join_score"), 0.0)
            answer_signal = bool(row.get("answer_signal", False))
            structural = bool(row.get("structural", False))
            relation_only = bool(row.get("relation_only", False))
            support_signal = max(
                text_score,
                0.78 * path_score,
                0.68 * source_precision,
                0.58 * candidate_value,
                0.54 * join_score,
            )
            top5_safe_risk_bypass = (
                self.regret_calibrated_set_enable_top5_safe_bypass
                and self.regret_calibrated_set_max_top5_swaps > 0
                and risk <= self.regret_calibrated_set_top5_safe_bypass_max_risk
                and support_signal >= self.regret_calibrated_set_top5_safe_bypass_min_support
                and (
                    text_score >= self.regret_calibrated_set_min_text_score
                    or path_score >= 0.62
                    or source_precision >= max(self.regret_calibrated_set_min_source_precision, 0.035)
                    or candidate_value >= 0.48
                    or join_score >= 0.42
                    or answer_signal
                    or structural
                )
                and not (relation_only and not (answer_signal or path_score >= 0.66 or text_score >= 0.32))
            )
            if risk > self.regret_calibrated_set_max_risk and not top5_safe_risk_bypass:
                rejections["high_risk"] += 1
                continue
            if top5_safe_risk_bypass and risk > self.regret_calibrated_set_max_risk:
                rejections["top5_safe_bypass_high_risk"] += 1
                row["top5_safe_bypass_high_risk"] = True
            if self.regret_calibrated_set_require_answer_signal and not answer_signal:
                rejections["missing_answer_signal"] += 1
                continue
            has_support = (
                text_score >= self.regret_calibrated_set_min_text_score
                or path_score >= 0.58
                or source_precision >= self.regret_calibrated_set_min_source_precision
                or answer_signal
                or structural
            )
            if not has_support:
                rejections["weak_support"] += 1
                continue
            if relation_only and not (answer_signal or path_score >= 0.66 or text_score >= 0.32):
                rejections["relation_only_without_support"] += 1
                continue

            replacement_options = self._regret_calibrated_replacement_options(
                candidate_doc=candidate_doc,
                current=selected[:top_k],
                passage_details=passage_details,
                query_plan_log=query_plan_log,
                original_rank_by_doc=original_rank_by_doc,
                max_raw_score=max_raw_score,
                top2_used=0,
                top5_used=0,
            )
            if not replacement_options:
                rejections["no_replaceable_slot"] += 1
                continue
            for option in replacement_options:
                target = str(option.get("target") or "top5")
                missing_slots = missing_top2_slots if target == "top2" else missing_top5_slots
                gap_pressure = query_pressure
                if target == "top2":
                    gap_pressure = max(gap_pressure, 0.14 * min(missing_top2_value, 1.0))
                else:
                    gap_pressure = max(gap_pressure, 0.10 * min(missing_top5_value, 1.0))
                regret, profile = self._regret_calibrated_option_score(
                    item=item,
                    row=row,
                    option=option,
                    query_plan_log=query_plan_log,
                    missing_slots=set(missing_slots),
                    query_slots=query_slots,
                    gap_pressure=gap_pressure,
                )
                stats["option_count"] = int(stats["option_count"]) + 1
                stats["best_regret"] = max(self._safe_float(stats.get("best_regret"), 0.0), regret)
                if target == "top2":
                    stats["best_top2_regret"] = max(
                        self._safe_float(stats.get("best_top2_regret"), 0.0),
                        regret,
                    )
                    if risk > self.regret_calibrated_set_top2_max_risk:
                        rejections["top2_high_risk"] += 1
                        continue
                    if text_score < self.regret_calibrated_set_top2_min_text_score and not (
                        answer_signal
                        and (path_score >= 0.70 or source_precision >= 0.40 or structural)
                    ):
                        rejections["top2_weak_text"] += 1
                        continue
                    required = self.regret_calibrated_set_top2_min_regret
                else:
                    stats["best_top5_regret"] = max(
                        self._safe_float(stats.get("best_top5_regret"), 0.0),
                        regret,
                    )
                    required = self.regret_calibrated_set_min_regret
                    if top5_safe_risk_bypass:
                        required = max(
                            required,
                            self.regret_calibrated_set_top5_safe_bypass_min_regret,
                        )
                    if (
                        query_pressure < self.regret_calibrated_set_min_gap_pressure
                        and self._safe_float(profile.get("slot_repair_value"), 0.0) <= 0.0
                        and not answer_signal
                    ):
                        rejections["low_gap_pressure"] += 1
                        continue
                    if (
                        top5_safe_risk_bypass
                        and self._safe_float(profile.get("slot_repair_value"), 0.0) <= 0.0
                        and not (answer_signal or support_signal >= self.regret_calibrated_set_top5_safe_bypass_min_support + 0.12)
                    ):
                        rejections["top5_safe_bypass_no_slot_or_answer"] += 1
                        continue
                    if top5_safe_risk_bypass:
                        profile["top5_safe_bypass_high_risk"] = True
                profile["required_regret"] = round(float(required), 6)
                if regret < required:
                    rejections["low_regret"] += 1
                    if len(rejected_candidates) < 12 and target == "top2":
                        rejected_candidates.append(
                            self._decision_for_log(
                                item,
                                selected=False,
                                reason="regret_calibrated_set_rejected:low_regret",
                            )
                        )
                    continue
                options.append({
                    "candidate_doc": int(candidate_doc),
                    "target": target,
                    "regret": round(float(regret), 6),
                    "profile": profile,
                    "item": item,
                })

        options.sort(
            key=lambda option: (
                self._safe_float(option.get("regret"), 0.0),
                1 if str(option.get("target") or "") == "top2" else 0,
                self._safe_float((option.get("profile", {}) or {}).get("slot_repair_value"), 0.0),
                -self._safe_int((option.get("profile", {}) or {}).get("original_rank"), 10**9),
            ),
            reverse=True,
        )

        selected_candidates: List[Dict[str, Any]] = []
        top2_used = 0
        top5_used = 0
        used_candidates: Set[int] = set()
        for option in options:
            candidate_doc = int(option.get("candidate_doc", -1))
            if candidate_doc < 0 or candidate_doc in selected_set or candidate_doc in used_candidates:
                continue
            profile = option.get("profile", {}) or {}
            action = profile.get("option", {}) or {}
            if not isinstance(action, Mapping):
                continue
            target = str(option.get("target") or "top5")
            replacement_index = self._safe_int(action.get("replacement_index"), -1)
            replacement_doc = self._safe_int(action.get("replacement_doc"), -1)
            if replacement_index < 0 or replacement_index >= len(selected):
                rejections["invalid_replacement_index"] += 1
                continue
            if replacement_index >= top_k:
                rejections["outside_topk_window"] += 1
                continue
            if int(selected[replacement_index]) != replacement_doc:
                rejections["replacement_doc_changed"] += 1
                continue
            if target == "top2":
                if top2_used >= self.regret_calibrated_set_max_top2_swaps:
                    continue
                if self.regret_calibrated_set_protect_top1 and replacement_index == 0:
                    rejections["protect_top1"] += 1
                    continue
            else:
                if top5_used >= self.regret_calibrated_set_max_top5_swaps:
                    continue
            try:
                candidate_index = selected.index(candidate_doc)
            except ValueError:
                candidate_index = -1
            selected[replacement_index] = candidate_doc
            if candidate_index >= 0 and candidate_index != replacement_index:
                selected[candidate_index] = replacement_doc
            selected_set.clear()
            selected_set.update(int(doc_id) for doc_id in selected)
            used_candidates.add(candidate_doc)
            item = option.get("item")
            if isinstance(item, dict):
                item["_regret_calibrated_set_selected"] = True
                item["_regret_calibrated_set_replaced_doc"] = int(replacement_doc)
                item["regret_calibrated_set_optimizer"] = {
                    **dict(item.get("regret_calibrated_set_optimizer", {}) or {}),
                    "action": {
                        **dict(action),
                        "regret": round(float(option.get("regret", 0.0)), 6),
                        "profile": dict(profile),
                    },
                }
                if target == "top2":
                    item["_regret_calibrated_set_top2_selected"] = True
                    top2_used += 1
                else:
                    item["_regret_calibrated_set_top5_selected"] = True
                    top5_used += 1
                if not any(
                    int(prev.get("passage_idx", -1)) == candidate_doc
                    for prev in selected_ontology
                ):
                    selected_ontology.append(item)
                if len(selected_candidates) < 12:
                    selected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=True,
                            reason=f"regret_calibrated_set_{target}_selected",
                            final_rank=int(replacement_index + 1),
                        )
                    )
            if (
                top2_used >= self.regret_calibrated_set_max_top2_swaps
                and top5_used >= self.regret_calibrated_set_max_top5_swaps
            ):
                break

        stats.update({
            "selected_count": int(top2_used + top5_used),
            "top2_used_count": int(top2_used),
            "top5_used_count": int(top5_used),
            "changed_top2": before_top2 != [int(doc_id) for doc_id in selected[:2]],
            "changed_top5": before_top5 != [int(doc_id) for doc_id in selected[:top_k]],
            "best_regret": round(float(self._safe_float(stats.get("best_regret"), 0.0)), 6),
            "best_top2_regret": round(float(self._safe_float(stats.get("best_top2_regret"), 0.0)), 6),
            "best_top5_regret": round(float(self._safe_float(stats.get("best_top5_regret"), 0.0)), 6),
            "rejection_reasons": dict(rejections),
            "selected_candidates": selected_candidates,
            "rejected_candidates": rejected_candidates,
            "row_samples": row_samples,
        })
        return stats

    def _apply_rank_window_recall_planner(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        rejections: Counter,
        rejected_candidates: List[Dict[str, Any]],
        selected_candidates: List[Dict[str, Any]],
    ) -> Tuple[int, int]:
        if not self.enable_rank_window_recall or self.rank_window_recall_max_selected <= 0:
            return 0, 0
        rank_candidates = []
        seen_rank_window_docs: Set[int] = set()
        for item in candidates:
            if not bool(item.get("_rank_window_recall_candidate", False)):
                continue
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc in seen_rank_window_docs:
                continue
            seen_rank_window_docs.add(candidate_doc)
            rank_candidates.append(item)
        rank_candidates.sort(
            key=lambda item: (
                self._safe_float((item.get("rank_window_recall", {}) or {}).get("score"), 0.0),
                self._safe_float((item.get("rank_window_recall", {}) or {}).get("text_score"), 0.0),
                self._safe_float((item.get("rank_window_recall", {}) or {}).get("dense_score_norm"), 0.0),
                -self._safe_int(item.get("original_rank"), 10**9),
            ),
            reverse=True,
        )
        top2_used = 0
        top5_used = 0

        def reject(item: Mapping[str, Any], reason: str) -> None:
            rejections[reason] += 1
            if len(rejected_candidates) < 12 and reason not in {"rank_window_low_score"}:
                rejected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=False,
                        reason=f"rank_window_recall_rejected:{reason}",
                    )
                )

        for item in rank_candidates:
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0:
                reject(item, "rank_window_invalid_doc")
                continue
            if candidate_doc in selected_set:
                reject(item, "rank_window_already_selected")
                continue
            if top2_used + top5_used >= self.rank_window_recall_max_selected:
                reject(item, "rank_window_budget_exhausted")
                continue
            profile = item.get("rank_window_recall", {}) or {}
            score = self._safe_float(profile.get("score"), 0.0)
            text_score = self._safe_float(profile.get("text_score"), 0.0)
            min_text_score = self._rank_window_item_min_text_score(item)
            require_text_signal = bool(
                profile.get("effective_require_text_signal", self.rank_window_recall_require_text_signal)
            )
            if require_text_signal and text_score <= 0.0:
                reject(item, "rank_window_missing_text_signal")
                continue
            if min_text_score > 0.0 and text_score < min_text_score:
                reject(item, "rank_window_low_text_score")
                continue
            candidate_value = self._rank_window_candidate_value(item)

            if (
                len(selected) >= 2
                and top2_used < self.rank_window_recall_max_top2_swaps
                and score >= self.rank_window_recall_top2_min_score
            ):
                replacement_doc = int(selected[1])
                replacement_rank = int(original_rank_by_doc.get(replacement_doc, 2))
                if (
                    self.rank_window_recall_protect_original_top_k > 0
                    and replacement_rank <= self.rank_window_recall_protect_original_top_k
                ):
                    reject(item, "rank_window_protected_replacement")
                    continue
                replacement_value = self._baseline_replacement_value(
                    replacement_doc,
                    replacement_rank,
                    passage_details,
                    max_raw_score,
                )
                margin = candidate_value - replacement_value
                net_gate = self._rank_window_net_benefit_gate(
                    item,
                    candidate_value=candidate_value,
                    replacement_value=replacement_value,
                    target="top2",
                    replacement_rank=replacement_rank,
                    required_margin=max(
                        self.rank_window_recall_net_benefit_min_margin,
                        self.rank_window_recall_top2_min_margin,
                    ),
                )
                item["rank_window_recall_gate"] = {
                    "target": "top2",
                    "approved": bool(
                        margin >= self.rank_window_recall_top2_min_margin
                        and bool(net_gate.get("approved", False))
                    ),
                    "score": round(float(score), 6),
                    "candidate_value": round(float(candidate_value), 6),
                    "replacement_doc": int(replacement_doc),
                    "replacement_rank": int(replacement_rank),
                    "replacement_value": round(float(replacement_value), 6),
                    "margin": round(float(margin), 6),
                    "required_margin": round(float(self.rank_window_recall_top2_min_margin), 6),
                    "net_benefit_gate": net_gate,
                }
                if margin >= self.rank_window_recall_top2_min_margin and bool(net_gate.get("approved", False)):
                    selected[1] = candidate_doc
                    selected_set.discard(replacement_doc)
                    selected_set.add(candidate_doc)
                    item["_rank_window_recall_selected"] = True
                    item["_rank_window_recall_top2_selected"] = True
                    item["_rank_window_recall_replaced_doc"] = replacement_doc
                    selected_ontology.append(item)
                    top2_used += 1
                    if len(selected_candidates) < 12:
                        selected_candidates.append(
                            self._decision_for_log(
                                item,
                                selected=True,
                                reason="rank_window_recall_top2_selected",
                                final_rank=2,
                            )
                        )
                    continue
                if margin >= self.rank_window_recall_top2_min_margin:
                    reject(item, "rank_window_net_benefit_low_margin")
                    continue
                reject(item, "rank_window_top2_low_margin")

            min_score = self._rank_window_item_min_score(item)
            if score < min_score:
                reject(item, "rank_window_low_score")
                continue
            if candidate_doc in selected_set:
                reject(item, "rank_window_already_selected")
                continue

            if len(selected) < self.final_top_k:
                append_gate = self._rank_window_net_benefit_gate(
                    item,
                    candidate_value=candidate_value,
                    replacement_value=0.0,
                    target="append",
                    replacement_rank=0,
                    required_margin=self.rank_window_recall_append_min_margin,
                )
                item["rank_window_recall_gate"] = {
                    "target": "append",
                    "approved": bool(append_gate.get("approved", False)),
                    "score": round(float(score), 6),
                    "candidate_value": round(float(candidate_value), 6),
                    "replacement_doc": -1,
                    "replacement_rank": 0,
                    "replacement_value": 0.0,
                    "margin": round(float(candidate_value), 6),
                    "required_margin": round(float(self.rank_window_recall_append_min_margin), 6),
                    "net_benefit_gate": append_gate,
                }
                if not bool(append_gate.get("approved", False)):
                    reject(item, "rank_window_net_benefit_low_margin")
                    continue
                selected.append(candidate_doc)
                selected_set.add(candidate_doc)
                item["_rank_window_recall_selected"] = True
                item["_rank_window_recall_top5_selected"] = True
                selected_ontology.append(item)
                top5_used += 1
                if len(selected_candidates) < 12:
                    selected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=True,
                            reason="rank_window_recall_top5_appended",
                            final_rank=int(len(selected)),
                        )
                    )
                continue

            replaceable: List[Tuple[float, int, int, int]] = []
            for index in range(2, min(len(selected), self.final_top_k)):
                final_rank = index + 1
                if final_rank < self.rank_window_recall_min_replacement_rank:
                    continue
                doc_id = int(selected[index])
                if doc_id == candidate_doc:
                    continue
                replacement_rank = int(original_rank_by_doc.get(doc_id, index + 1))
                if (
                    self.rank_window_recall_protect_original_top_k > 0
                    and replacement_rank <= self.rank_window_recall_protect_original_top_k
                ):
                    continue
                replacement_value = self._baseline_replacement_value(
                    doc_id,
                    replacement_rank,
                    passage_details,
                    max_raw_score,
                )
                replaceable.append((replacement_value, index, doc_id, replacement_rank))
            if not replaceable:
                reject(item, "rank_window_no_replaceable_slot")
                continue
            replacement_value, replacement_index, replacement_doc, replacement_rank = min(
                replaceable,
                key=lambda value: (value[0], -value[3]),
            )
            margin = candidate_value - replacement_value
            net_gate = self._rank_window_net_benefit_gate(
                item,
                candidate_value=candidate_value,
                replacement_value=replacement_value,
                target="top5",
                replacement_rank=replacement_rank,
                required_margin=self.rank_window_recall_net_benefit_min_margin,
            )
            item["rank_window_recall_gate"] = {
                "target": "top5",
                "approved": bool(
                    margin >= self.rank_window_recall_min_margin
                    and bool(net_gate.get("approved", False))
                ),
                "score": round(float(score), 6),
                "candidate_value": round(float(candidate_value), 6),
                "replacement_doc": int(replacement_doc),
                "replacement_rank": int(replacement_rank),
                "replacement_value": round(float(replacement_value), 6),
                "margin": round(float(margin), 6),
                "required_margin": round(float(self.rank_window_recall_min_margin), 6),
                "net_benefit_gate": net_gate,
            }
            if margin < self.rank_window_recall_min_margin:
                reject(item, "rank_window_low_margin")
                continue
            if not bool(net_gate.get("approved", False)):
                reject(item, "rank_window_net_benefit_low_margin")
                continue
            selected[replacement_index] = candidate_doc
            selected_set.discard(replacement_doc)
            selected_set.add(candidate_doc)
            item["_rank_window_recall_selected"] = True
            item["_rank_window_recall_top5_selected"] = True
            item["_rank_window_recall_replaced_doc"] = replacement_doc
            selected_ontology.append(item)
            top5_used += 1
            if len(selected_candidates) < 12:
                selected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason="rank_window_recall_top5_selected",
                        final_rank=int(replacement_index + 1),
                    )
                )
        return top2_used, top5_used

    def _groupwise_top5_config(self) -> Dict[str, Any]:
        if not self.utility_planner.is_ready():
            return {}
        config = self.utility_planner.model.get("groupwise_top5_planner", {}) or {}
        return config if isinstance(config, dict) else {}

    def _groupwise_source_prior(self, item: Mapping[str, Any], source_signature: str) -> float:
        config = self._groupwise_top5_config()
        source_stats = config.get("source_stats", {}) or {}
        if isinstance(source_stats, Mapping):
            stats = source_stats.get(source_signature, {}) or {}
            if isinstance(stats, Mapping):
                precision = self._safe_float(stats.get("precision"), -1.0)
                if precision >= 0.0:
                    return min(max(precision, 0.0), 1.0)
        source_policy = item.get("source_policy", {}) or {}
        if not isinstance(source_policy, Mapping):
            source_policy = {}
        return min(
            max(
                self._safe_float(source_policy.get("selected_precision"), 0.0),
                self._safe_float(source_policy.get("precision"), 0.0),
                2.0 * self._safe_float(source_policy.get("gt5_precision"), 0.0),
            ),
            1.0,
        )

    def _hard_negative_top5_config(self) -> Dict[str, Any]:
        if not self.utility_planner.is_ready():
            return {}
        config = self.utility_planner.model.get("hard_negative_top5_planner", {}) or {}
        return config if isinstance(config, dict) else {}

    def _query_is_simple_factoid(self, query_plan_log: Mapping[str, Any]) -> bool:
        condition = query_plan_log.get("query_condition", {}) or {}
        if not isinstance(condition, Mapping):
            condition = {}
        query = str(query_plan_log.get("query") or query_plan_log.get("question") or "")
        lowered = query.lower()
        tokens = [token for token in query.split() if token]
        text = " ".join(
            str(condition.get(key, "") or "")
            for key in ("query_type", "intent", "answer_type", "family", "mode")
        ).lower()
        families = " ".join(str(value) for value in condition.get("relation_families", []) or []).lower()
        signatures = " ".join(str(value) for value in condition.get("relation_signatures", []) or []).lower()
        combined = f"{lowered} {text} {families} {signatures}"
        complex_terms = (
            "multi",
            "hop",
            "bridge",
            "comparison",
            "comparative",
            "composition",
            "constraint",
        )
        relative_markers = (
            " whose ",
            " which ",
            " that ",
            " where ",
            " when ",
            " before ",
            " after ",
            " larger than ",
            " smaller than ",
            " older than ",
            " younger than ",
            " more than ",
            " less than ",
            " greater than ",
            " compared ",
            " located ",
            " headquarters ",
            " headquarter ",
            " record label ",
            " signed by ",
            " born in ",
            " died in ",
            " founded by ",
            " part of ",
            " member of ",
            " the person who ",
            " the city where ",
            " the organization that ",
            " the company that ",
            " the country where ",
            " the film that ",
            " the album that ",
            " the team that ",
        )
        nested_who_when = (
            " who " in lowered.strip()[4:]
            or " when " in lowered.strip()[5:]
            or " where " in lowered.strip()[6:]
        )
        explicit_complex = any(
            bool(condition.get(key))
            for key in (
                "complex",
                "multihop",
                "multi_hop",
                "comparative",
                "comparison",
                "bridge",
                "composition",
                "constraint",
            )
        )
        if (
            explicit_complex
            or len(tokens) > 12
            or nested_who_when
            or any(marker in f" {lowered} " for marker in relative_markers)
            or any(term in combined for term in complex_terms)
        ):
            return False
        if "simple_factoid" in condition:
            simple_value = condition.get("simple_factoid")
            if isinstance(simple_value, str):
                return simple_value.strip().lower() in {"1", "true", "yes", "y"}
            return bool(simple_value)
        return True

    def _hard_negative_priors(
        self,
        item: Mapping[str, Any],
        source_signature: str,
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[float, float, int, float, Dict[str, Any], Dict[str, Any]]:
        config = self._hard_negative_top5_config()
        source_stats = config.get("source_stats", {}) or {}
        dataset_source_stats = config.get("dataset_source_stats", {}) or {}
        dataset = str(query_plan_log.get("dataset") or "").strip()
        source_record: Dict[str, Any] = {}
        dataset_source_record: Dict[str, Any] = {}
        source_prior = self._groupwise_source_prior(item, source_signature)
        dataset_source_prior = -1.0
        dataset_source_count = 0
        false_positive_rate = 0.0
        if isinstance(source_stats, Mapping):
            stats = source_stats.get(source_signature, {}) or {}
            if isinstance(stats, Mapping):
                source_record = dict(stats)
                source_prior = self._safe_float(stats.get("precision"), source_prior)
                false_positive_rate = max(
                    false_positive_rate,
                    self._safe_float(stats.get("selected_false_positive_rate"), 0.0),
                )
        if dataset and isinstance(dataset_source_stats, Mapping):
            stats = dataset_source_stats.get(f"{dataset}::{source_signature}", {}) or {}
            if isinstance(stats, Mapping):
                dataset_source_record = dict(stats)
                dataset_source_prior = self._safe_float(stats.get("precision"), -1.0)
                dataset_source_count = self._safe_int(stats.get("count"), 0)
                false_positive_rate = max(
                    false_positive_rate,
                    self._safe_float(stats.get("selected_false_positive_rate"), 0.0),
                )
        return (
            min(max(source_prior, 0.0), 1.0),
            dataset_source_prior if dataset_source_prior >= 0.0 else -1.0,
            int(dataset_source_count),
            min(max(false_positive_rate, 0.0), 1.0),
            source_record,
            dataset_source_record,
        )

    def _passes_groupwise_top5_planner(
        self,
        item: Mapping[str, Any],
        selected: Sequence[int],
        selected_set: Set[int],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[bool, str, Dict[str, Any]]:
        if self.utility_planner_mode != "groupwise_top5_planner" or not self.utility_planner.is_ready():
            return False, "groupwise_disabled", {}
        if len(selected) < min(self.final_top_k, 3):
            return False, "groupwise_short_window", {}
        candidate_doc = int(item.get("passage_idx", -1))
        if candidate_doc < 0:
            return False, "groupwise_invalid_doc", {}
        if candidate_doc in selected_set:
            return False, "groupwise_already_selected", {}

        planner = item.get("utility_planner", {}) or {}
        planner_score = self._safe_float(planner.get("score"), 0.0)
        min_score = self.utility_planner_min_score
        config = self._groupwise_top5_config()
        if config:
            min_score = self._safe_float(config.get("min_score"), min_score)
        if planner_score < min_score:
            return False, "groupwise_low_score", {
                "score": round(float(planner_score), 6),
                "min_score": round(float(min_score), 6),
            }

        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        max_original_rank = int(config.get("max_original_rank", self.utility_planner_max_original_rank) or 0)
        if max_original_rank > 0 and original_rank > max_original_rank:
            return False, "groupwise_rank_too_low", {
                "original_rank": int(original_rank),
                "max_original_rank": int(max_original_rank),
            }

        source_signature = self._candidate_source_signature(item)
        source_prior = self._groupwise_source_prior(item, source_signature)
        path_info = item.get("path_aware", {}) or {}
        if not isinstance(path_info, Mapping):
            path_info = {}
        features = self._intervention_features(item, query_plan_log)
        structural = (
            bool(item.get("has_strict"))
            or bool(item.get("has_multihop"))
            or bool(features.get("has_endpoint_pair"))
            or bool(features.get("has_path_seed"))
            or bool(features.get("has_terminal_relation"))
            or (bool(item.get("has_terminal")) and bool(item.get("has_relation")))
        )
        support_only = (
            "support" in source_signature
            and "evidence_grounded" not in source_signature
            and "path_executor" not in source_signature
            and "evidence_index" not in source_signature
            and not structural
        )
        min_source_prior = self._safe_float(config.get("min_source_prior"), 0.18)
        path_or_structural_override = structural or bool(path_info.get("approved", False))
        if source_prior < min_source_prior and not path_or_structural_override:
            return False, "groupwise_low_source_prior", {
                "source_signature": source_signature,
                "source_prior": round(float(source_prior), 6),
                "min_source_prior": round(float(min_source_prior), 6),
            }
        if support_only and planner_score < min(0.99, min_score + 0.05):
            return False, "groupwise_support_only_low_score", {
                "source_signature": source_signature,
                "score": round(float(planner_score), 6),
            }

        top_without_candidate: List[int] = [int(doc_id) for doc_id in selected[: self.final_top_k]]
        top_without_set = set(top_without_candidate)
        for doc_id in base_doc_ids:
            doc_id = int(doc_id)
            if doc_id in top_without_set:
                continue
            top_without_candidate.append(doc_id)
            top_without_set.add(doc_id)
            if len(top_without_candidate) >= self.final_top_k:
                break
        if len(top_without_candidate) < self.final_top_k:
            return False, "groupwise_short_counterfactual_window", {
                "top_without_candidate": top_without_candidate,
            }

        replaceable = []
        for index in range(2, min(self.final_top_k, len(top_without_candidate))):
            doc_id = int(top_without_candidate[index])
            replacement_rank = int(original_rank_by_doc.get(doc_id, index + 1))
            replacement_value = self._baseline_replacement_value(
                doc_id,
                replacement_rank,
                passage_details,
                max_raw_score,
            )
            replaceable.append((replacement_value, index, doc_id, replacement_rank))
        if not replaceable:
            return False, "groupwise_no_replaceable_slot", {}
        replacement_value, replacement_index, replacement_doc, replacement_rank = min(
            replaceable,
            key=lambda row: (row[0], -row[1]),
        )

        candidate_value = self._candidate_evidence_value(item)
        path_bonus = 0.03 if path_or_structural_override else 0.0
        source_bonus = 0.08 * source_prior
        score_bonus = 0.18 * planner_score
        candidate_utility = min(1.35, candidate_value + source_bonus + score_bonus + path_bonus)
        margin = candidate_utility - replacement_value
        required_margin = self.utility_planner_min_value_margin
        if config:
            required_margin = self._safe_float(config.get("min_value_margin"), required_margin)
        if replacement_index == 2:
            required_margin += self._safe_float(config.get("rank3_extra_margin"), 0.04)
        elif replacement_index == 3:
            required_margin += self._safe_float(config.get("rank4_extra_margin"), 0.02)
        if support_only:
            required_margin += self._safe_float(config.get("support_only_extra_margin"), 0.03)

        approved = margin >= required_margin
        return approved, "groupwise_gain" if approved else "groupwise_low_margin", {
            "score": round(float(planner_score), 6),
            "min_score": round(float(min_score), 6),
            "candidate_value": round(float(candidate_value), 6),
            "candidate_utility": round(float(candidate_utility), 6),
            "source_signature": source_signature,
            "source_prior": round(float(source_prior), 6),
            "replacement_doc": int(replacement_doc),
            "replacement_index": int(replacement_index),
            "replacement_rank": int(replacement_rank),
            "replacement_value": round(float(replacement_value), 6),
            "margin": round(float(margin), 6),
            "required_margin": round(float(required_margin), 6),
            "structural": bool(structural),
            "path_or_structural_override": bool(path_or_structural_override),
            "support_only": bool(support_only),
            "top_without_candidate": top_without_candidate[: self.final_top_k],
        }

    def _apply_groupwise_top5_planner(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        rejections: Counter,
        rejected_candidates: List[Dict[str, Any]],
        selected_candidates: List[Dict[str, Any]],
    ) -> int:
        if self.utility_planner_mode != "groupwise_top5_planner" or not self.utility_planner.is_ready():
            return 0
        for doc_id in base_doc_ids:
            if len(selected) >= self.final_top_k:
                break
            doc_id = int(doc_id)
            if doc_id in selected_set:
                continue
            selected.append(doc_id)
            selected_set.add(doc_id)

        config = self._groupwise_top5_config()
        max_swaps = max(int(config.get("max_swaps", 1) or 1), 0)
        if max_swaps <= 0 or len(selected) < self.final_top_k:
            return 0

        scored: List[Tuple[float, float, int, Dict[str, Any], Dict[str, Any]]] = []
        for item in candidates:
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0 or candidate_doc in selected_set:
                continue
            approved, reason, features = self._passes_groupwise_top5_planner(
                item=item,
                selected=selected,
                selected_set=selected_set,
                base_doc_ids=base_doc_ids,
                original_rank_by_doc=original_rank_by_doc,
                passage_details=passage_details,
                max_raw_score=max_raw_score,
                query_plan_log=query_plan_log,
            )
            item["utility_planner_groupwise_gate"] = {
                "approved": bool(approved),
                "reason": reason,
                "features": features,
            }
            if approved:
                scored.append((
                    self._safe_float(features.get("margin"), 0.0),
                    self._safe_float(features.get("score"), 0.0),
                    -self._safe_int(item.get("original_rank"), 10**9),
                    item,
                    features,
                ))
            else:
                rejections[reason] += 1
                if len(rejected_candidates) < 12 and reason not in {"groupwise_low_score", "groupwise_rank_too_low"}:
                    rejected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=False,
                            reason=f"groupwise_top5_rejected:{reason}",
                        )
                    )
        if not scored:
            return 0

        scored.sort(key=lambda row: (row[0], row[1], row[2]), reverse=True)
        swaps = 0
        for _, _, _, item, _ in scored:
            if swaps >= max_swaps:
                break
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0 or candidate_doc in selected_set:
                continue
            approved, reason, features = self._passes_groupwise_top5_planner(
                item=item,
                selected=selected,
                selected_set=selected_set,
                base_doc_ids=base_doc_ids,
                original_rank_by_doc=original_rank_by_doc,
                passage_details=passage_details,
                max_raw_score=max_raw_score,
                query_plan_log=query_plan_log,
            )
            item["utility_planner_groupwise_gate"] = {
                "approved": bool(approved),
                "reason": reason,
                "features": features,
            }
            if not approved:
                rejections[reason] += 1
                continue
            replacement_index = self._safe_int(features.get("replacement_index"), self.final_top_k - 1)
            if replacement_index < 2 or replacement_index >= min(self.final_top_k, len(selected)):
                rejections["groupwise_bad_replacement_index"] += 1
                continue
            replaced_doc = int(selected[replacement_index])
            selected[replacement_index] = candidate_doc
            selected_set.discard(replaced_doc)
            selected_set.add(candidate_doc)
            item["_utility_planner_groupwise_top5_selected"] = True
            item["_utility_planner_safe_selected"] = True
            item["_utility_planner_replaced_doc"] = replaced_doc
            if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                selected_ontology.append(item)
            swaps += 1
            if len(selected_candidates) < 12:
                selected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason="utility_planner_groupwise_top5_selected",
                        final_rank=int(replacement_index + 1),
                    )
                )
        return swaps

    def _passes_provenance_groupwise_top5_selector(
        self,
        item: Mapping[str, Any],
        selected: Sequence[int],
        selected_set: Set[int],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
    ) -> Tuple[bool, str, Dict[str, Any]]:
        if not self.enable_provenance_groupwise_selector:
            return False, "provenance_groupwise_disabled", {}
        candidate_doc = int(item.get("passage_idx", -1))
        if candidate_doc < 0:
            return False, "provenance_groupwise_invalid_doc", {}
        if candidate_doc in selected_set:
            return False, "provenance_groupwise_already_selected", {}
        if len(selected) < min(self.final_top_k, 3):
            return False, "provenance_groupwise_short_window", {}

        info = item.get("provenance_groupwise", {}) or {}
        if not isinstance(info, Mapping):
            info = {}
        if not bool(info.get("approved", False)):
            return False, f"provenance_groupwise_{info.get('reason') or 'not_approved'}", {
                "provenance_groupwise": dict(info),
            }
        score = self._safe_float(info.get("score"), 0.0)
        if score < self.provenance_groupwise_min_score:
            return False, "provenance_groupwise_low_score", {
                "score": round(float(score), 6),
                "min_score": round(float(self.provenance_groupwise_min_score), 6),
            }

        source_precision = self._safe_float(info.get("source_precision"), 0.0)
        text_signal = bool(info.get("text_signal", False))
        strong_structure = bool(info.get("strong_structure", False))
        schema_only = bool(info.get("schema_only", False))
        if (
            source_precision < self.provenance_groupwise_min_source_precision
            and not strong_structure
        ):
            return False, "provenance_groupwise_low_source_precision", {
                "source_precision": round(float(source_precision), 6),
                "min_source_precision": round(float(self.provenance_groupwise_min_source_precision), 6),
            }
        if self.provenance_groupwise_require_text_signal and not text_signal and not strong_structure:
            return False, "provenance_groupwise_weak_text_signal", {
                "text_signal": bool(text_signal),
                "strong_structure": bool(strong_structure),
            }

        top_without_candidate: List[int] = [int(doc_id) for doc_id in selected[: self.final_top_k]]
        top_without_set = set(top_without_candidate)
        for doc_id in base_doc_ids:
            doc_id = int(doc_id)
            if doc_id in top_without_set:
                continue
            top_without_candidate.append(doc_id)
            top_without_set.add(doc_id)
            if len(top_without_candidate) >= self.final_top_k:
                break
        if len(top_without_candidate) < self.final_top_k:
            return False, "provenance_groupwise_short_counterfactual_window", {
                "top_without_candidate": top_without_candidate,
            }

        replaceable = []
        for index in range(2, min(self.final_top_k, len(top_without_candidate))):
            doc_id = int(top_without_candidate[index])
            replacement_rank = int(original_rank_by_doc.get(doc_id, index + 1))
            replacement_value = self._baseline_replacement_value(
                doc_id,
                replacement_rank,
                passage_details,
                max_raw_score,
            )
            replaceable.append((replacement_value, index, doc_id, replacement_rank))
        if not replaceable:
            return False, "provenance_groupwise_no_replaceable_slot", {}
        replacement_value, replacement_index, replacement_doc, replacement_rank = min(
            replaceable,
            key=lambda row: (row[0], -row[1]),
        )

        text_score = self._safe_float(info.get("text_score"), 0.0)
        candidate_value = self._candidate_evidence_value(item)
        structure_bonus = 0.05 if strong_structure else 0.0
        novelty_bonus = min(
            0.05,
            0.015 * self._safe_float(info.get("coverage_gain"), 0.0)
            + 0.02 * float(self._safe_int(info.get("decomposition_gain"), 0)),
        )
        candidate_utility = min(
            1.35,
            candidate_value
            + 0.18 * score
            + 0.08 * source_precision
            + 0.05 * min(text_score, 1.0)
            + structure_bonus
            + novelty_bonus,
        )
        margin = candidate_utility - replacement_value
        required_margin = 0.015
        if replacement_index == 2:
            required_margin += 0.035
        elif replacement_index == 3:
            required_margin += 0.015
        if not text_signal:
            required_margin += 0.030
        if schema_only:
            required_margin += 0.025

        approved = margin >= required_margin
        return approved, "provenance_groupwise_gain" if approved else "provenance_groupwise_low_margin", {
            "score": round(float(score), 6),
            "candidate_value": round(float(candidate_value), 6),
            "candidate_utility": round(float(candidate_utility), 6),
            "source_signature": str(info.get("source_signature") or ""),
            "source_precision": round(float(source_precision), 6),
            "text_score": round(float(text_score), 6),
            "text_signal": bool(text_signal),
            "strong_structure": bool(strong_structure),
            "schema_only": bool(schema_only),
            "replacement_doc": int(replacement_doc),
            "replacement_index": int(replacement_index),
            "replacement_rank": int(replacement_rank),
            "replacement_value": round(float(replacement_value), 6),
            "margin": round(float(margin), 6),
            "required_margin": round(float(required_margin), 6),
            "top_without_candidate": top_without_candidate[: self.final_top_k],
        }

    def _apply_provenance_groupwise_top5_selector(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        rejections: Counter,
        rejected_candidates: List[Dict[str, Any]],
        selected_candidates: List[Dict[str, Any]],
    ) -> int:
        if not self.enable_provenance_groupwise_selector:
            return 0
        for doc_id in base_doc_ids:
            if len(selected) >= self.final_top_k:
                break
            doc_id = int(doc_id)
            if doc_id in selected_set:
                continue
            selected.append(doc_id)
            selected_set.add(doc_id)

        max_swaps = self.provenance_groupwise_max_top5_swaps
        if max_swaps <= 0 or len(selected) < self.final_top_k:
            return 0

        scored: List[Tuple[float, float, float, int, Dict[str, Any], Dict[str, Any]]] = []
        for item in candidates:
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0 or candidate_doc in selected_set:
                continue
            approved, reason, features = self._passes_provenance_groupwise_top5_selector(
                item=item,
                selected=selected,
                selected_set=selected_set,
                base_doc_ids=base_doc_ids,
                original_rank_by_doc=original_rank_by_doc,
                passage_details=passage_details,
                max_raw_score=max_raw_score,
            )
            item["provenance_groupwise_gate"] = {
                "approved": bool(approved),
                "reason": reason,
                "features": features,
            }
            if approved:
                scored.append((
                    self._safe_float(features.get("margin"), 0.0),
                    self._safe_float(features.get("score"), 0.0),
                    self._safe_float(features.get("source_precision"), 0.0),
                    -self._safe_int(item.get("original_rank"), 10**9),
                    item,
                    features,
                ))
            else:
                rejections[reason] += 1
                if len(rejected_candidates) < 12 and reason not in {
                    "provenance_groupwise_low_score",
                    "provenance_groupwise_already_selected",
                }:
                    rejected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=False,
                            reason=f"provenance_groupwise_rejected:{reason}",
                        )
                    )
        if not scored:
            return 0

        scored.sort(key=lambda row: (row[0], row[1], row[2], row[3]), reverse=True)
        swaps = 0
        for _, _, _, _, item, _ in scored:
            if swaps >= max_swaps:
                break
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0 or candidate_doc in selected_set:
                continue
            approved, reason, features = self._passes_provenance_groupwise_top5_selector(
                item=item,
                selected=selected,
                selected_set=selected_set,
                base_doc_ids=base_doc_ids,
                original_rank_by_doc=original_rank_by_doc,
                passage_details=passage_details,
                max_raw_score=max_raw_score,
            )
            item["provenance_groupwise_gate"] = {
                "approved": bool(approved),
                "reason": reason,
                "features": features,
            }
            if not approved:
                rejections[reason] += 1
                continue
            replacement_index = self._safe_int(features.get("replacement_index"), self.final_top_k - 1)
            if replacement_index < 2 or replacement_index >= min(self.final_top_k, len(selected)):
                rejections["provenance_groupwise_bad_replacement_index"] += 1
                continue
            replaced_doc = int(selected[replacement_index])
            selected[replacement_index] = candidate_doc
            selected_set.discard(replaced_doc)
            selected_set.add(candidate_doc)
            item["_provenance_groupwise_top5_selected"] = True
            item["_provenance_groupwise_replaced_doc"] = replaced_doc
            if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                selected_ontology.append(item)
            swaps += 1
            if len(selected_candidates) < 12:
                selected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason="provenance_groupwise_top5_selected",
                        final_rank=int(replacement_index + 1),
                    )
                )
        return swaps

    def _evidence_join_query_slots(self, query_plan_log: Mapping[str, Any]) -> Set[str]:
        slots: Set[str] = set()
        condition = query_plan_log.get("query_condition", {}) or {}
        if isinstance(condition, Mapping):
            answer_type = self._norm(condition.get("answer_type"))
            if answer_type:
                slots.add(f"answer_type:{answer_type}")
            for key in ("relation_terms", "relation_signatures", "relation_families"):
                for value in condition.get(key, []) or []:
                    value_norm = self._norm(value)
                    if not value_norm:
                        continue
                    slots.add(f"relation:{value_norm}")
                    for token in tokenize(value_norm):
                        if len(token) > 2:
                            slots.add(f"relation_token:{token}")
            for token in condition.get("query_tokens", []) or []:
                token_norm = self._norm(token)
                if len(token_norm) > 2:
                    slots.add(f"query_token:{token_norm}")
        for anchor in query_plan_log.get("anchor_entities", []) or []:
            anchor_norm = self._norm(anchor)
            if anchor_norm:
                slots.add(f"anchor:{anchor_norm}")
        for plan in query_plan_log.get("matched_plans", []) or []:
            if not isinstance(plan, Mapping):
                continue
            intent = self._norm(plan.get("intent"))
            if intent:
                slots.add(f"intent:{intent}")
            answer_type = self._norm(plan.get("answer_type"))
            if answer_type:
                slots.add(f"answer_type:{answer_type}")
            for key in ("relation_families", "relation_signatures"):
                for value in plan.get(key, []) or []:
                    value_norm = self._norm(value)
                    if not value_norm:
                        continue
                    slots.add(f"relation:{value_norm}")
                    for token in tokenize(value_norm):
                        if len(token) > 2:
                            slots.add(f"relation_token:{token}")
        return slots

    def _evidence_join_context_slots(
        self,
        contexts: Iterable[Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
    ) -> Set[str]:
        slots: Set[str] = set()
        query_condition = query_plan_log.get("query_condition", {}) or {}
        default_answer_type = ""
        if isinstance(query_condition, Mapping):
            default_answer_type = self._norm(query_condition.get("answer_type"))
        for context in contexts or []:
            if not isinstance(context, Mapping):
                continue
            plan_id = self._norm(context.get("plan_id"))
            anchor = self._norm(context.get("anchor_entity"))
            terminal = self._norm(context.get("end_entity"))
            answer_type = self._norm(context.get("answer_type")) or default_answer_type
            if plan_id:
                slots.add(f"plan:{plan_id}")
            if anchor:
                slots.add(f"anchor:{anchor}")
            if terminal:
                slots.add(f"terminal:{terminal}")
            if answer_type:
                slots.add(f"answer_type:{answer_type}")
            if anchor and terminal:
                slots.add(f"endpoint:{anchor}|{terminal}")
            relations = [
                self._norm(relation)
                for relation in (context.get("relations", []) or [])
                if self._norm(relation)
            ]
            for relation in relations:
                slots.add(f"relation:{relation}")
                for token in tokenize(relation):
                    if len(token) > 2:
                        slots.add(f"relation_token:{token}")
                if anchor:
                    slots.add(f"anchor_relation:{anchor}|{relation}")
                if terminal:
                    slots.add(f"terminal_relation:{terminal}|{relation}")
            if context.get("ontology_path_executor") or context.get("path_seed_hit"):
                slots.add("source:path_executor")
                if plan_id:
                    slots.add(f"path_plan:{plan_id}")
            if context.get("schema_slot_recall"):
                slots.add("source:schema_slot_recall")
            if context.get("ontology_bind_probe_join") or context.get("bind_probe_join"):
                slots.add("source:bind_probe_join")
            if context.get("evidence_grounded"):
                slots.add("source:evidence_grounded")
            if context.get("support_evidence"):
                slots.add("source:support")
            if context.get("ontology_evidence_index"):
                slots.add("source:evidence_index")
            if context.get("failure_evidence"):
                slots.add("source:failure_evidence")
            if context.get("fact_indices"):
                slots.add("fact_linked")
        return slots

    def _evidence_join_slot_value(self, slots: Iterable[str], query_slots: Set[str]) -> float:
        value = 0.0
        for slot in set(slots or []):
            if slot in query_slots:
                value += 0.32
            elif slot.startswith("endpoint:"):
                value += 0.30
            elif slot.startswith("anchor_relation:") or slot.startswith("terminal_relation:"):
                value += 0.26
            elif slot.startswith("answer_type:"):
                value += 0.18
            elif slot.startswith("relation:"):
                value += 0.16
            elif slot.startswith("relation_token:"):
                value += 0.12
            elif slot.startswith("source:path_executor"):
                value += 0.20
            elif slot.startswith("path_plan:"):
                value += 0.14
            elif slot == "fact_linked":
                value += 0.12
            elif slot.startswith("source:"):
                value += 0.08
            elif slot.startswith("anchor:") or slot.startswith("terminal:"):
                value += 0.10
            elif slot.startswith("plan:") or slot.startswith("intent:"):
                value += 0.06
        return min(float(value), 2.0)

    def _evidence_join_doc_slots(
        self,
        doc_id: int,
        passage_details: Mapping[int, Mapping[str, Any]],
        query_plan_log: Mapping[str, Any],
    ) -> Set[str]:
        detail = passage_details.get(int(doc_id), {}) or {}
        return self._evidence_join_context_slots(detail.get("contexts", []) or [], query_plan_log)

    def _evidence_join_answer_slot(self, query_plan_log: Mapping[str, Any]) -> str:
        query_text = self._norm(query_plan_log.get("query"))
        condition = query_plan_log.get("query_condition", {}) or {}
        answer_type = ""
        if isinstance(condition, Mapping):
            answer_type = self._norm(condition.get("answer_type"))
            relation_parts: List[str] = []
            for key in ("relation_terms", "relation_signatures", "relation_families", "query_tokens"):
                relation_parts.extend(str(value) for value in condition.get(key, []) or [])
            if relation_parts:
                query_text = " ".join(part for part in [query_text, self._norm(" ".join(relation_parts))] if part)
        padded = f" {query_text} "
        if any(term in padded for term in {" occupation ", " profession ", " job ", " career "}):
            return "occupation"
        if any(term in padded for term in {" nationality ", " citizen ", " country of "}):
            return "nationality"
        if re.search(r"\b(city|town|place|location)\b.*\bborn\b", query_text) or " born in " in padded:
            return "birth_place"
        if re.search(r"\b(city|town|place|location)\b.*\bdie[sd]?\b", query_text) or " place of death " in padded:
            return "death_place"
        if any(term in padded for term in {" father ", " paternal grandfather ", " grandfather "}):
            return "father"
        if any(term in padded for term in {" mother ", " maternal grandmother ", " grandmother "}):
            return "mother"
        if any(term in padded for term in {" spouse ", " husband ", " wife ", " married "}):
            return "spouse"
        if any(term in padded for term in {" record label ", " publisher ", " publication ", " published by "}):
            return "organization"
        if any(term in padded for term in {" genre ", " category ", " type of ", " kind of "}):
            return "type"
        if query_text.startswith(("when ", "what date ", "which date ", "what year ", "which year ")):
            return "date"
        if query_text.startswith(("where ", "what city ", "which city ", "what country ", "which country ")):
            return "location"
        if answer_type in {"date", "number", "person", "organization", "location"}:
            return answer_type
        return ""

    def _evidence_join_operator_profile(self, query_plan_log: Mapping[str, Any]) -> Dict[str, Any]:
        query_text = self._norm(query_plan_log.get("query"))
        padded = f" {query_text} "
        condition = query_plan_log.get("query_condition", {}) or {}
        answer_type = ""
        relation_terms: Set[str] = set()
        query_tokens: Set[str] = set(tokenize(query_text))
        if isinstance(condition, Mapping):
            answer_type = self._norm(condition.get("answer_type"))
            for key in ("relation_terms", "relation_signatures", "relation_families"):
                for value in condition.get(key, []) or []:
                    value_norm = self._norm(value)
                    if not value_norm:
                        continue
                    relation_terms.add(value_norm)
                    relation_terms.update(token for token in tokenize(value_norm) if len(token) > 2)
            for value in condition.get("query_tokens", []) or []:
                value_norm = self._norm(value)
                if value_norm:
                    query_tokens.update(token for token in tokenize(value_norm) if len(token) > 2)

        anchors = [
            self._norm(anchor)
            for anchor in (query_plan_log.get("anchor_entities", []) or [])
            if self._norm(anchor)
        ]
        matched_plans = [
            plan for plan in (query_plan_log.get("matched_plans", []) or [])
            if isinstance(plan, Mapping)
        ]
        intents = {self._norm(plan.get("intent")) for plan in matched_plans if self._norm(plan.get("intent"))}
        plan_count = len(matched_plans)
        relation_count = len(relation_terms)

        comparison_terms = {
            "both", "same", "first", "last", "earlier", "later", "older", "younger",
            "larger", "smaller", "greater", "less", "highest", "lowest", "more",
            "between", "or",
        }
        boolean_starts = ("are ", "were ", "is ", "was ", "do ", "does ", "did ", "can ", "could ")
        is_boolean = query_text.startswith(boolean_starts) or " yes or no " in padded
        is_comparison = (
            any(term in query_tokens for term in comparison_terms)
            or (" same " in padded and len(anchors) >= 2)
            or (len(anchors) >= 2 and any(term in query_tokens for term in {"first", "later", "earlier"}))
        )
        is_temporal = answer_type == "date" or query_text.startswith(("when ", "what date ", "which date "))
        is_bridge = (
            plan_count >= 2
            or len(anchors) >= 2
            or query_text.count(" of ") >= 2
            or any("bridge" in intent or "attribute" in intent for intent in intents)
        )
        if is_comparison:
            operator = "comparison"
        elif is_boolean:
            operator = "boolean"
        elif is_bridge:
            operator = "bridge"
        elif is_temporal:
            operator = "temporal"
        else:
            operator = "single"

        required_slots: Set[str] = set()
        if answer_type:
            required_slots.add(f"answer_type:{answer_type}")
        for relation in relation_terms:
            required_slots.add(f"relation_token:{relation}")
            if " " in relation:
                required_slots.add(f"relation:{relation}")
        for anchor in anchors[:4]:
            required_slots.add(f"anchor:{anchor}")
        if operator in {"bridge", "comparison", "boolean"}:
            required_slots.add("fact_linked")
        if operator == "bridge":
            required_slots.add("source:path_executor")
        if operator == "comparison" and len(anchors) >= 2:
            required_slots.update(f"anchor:{anchor}" for anchor in anchors[:4])

        chain_pressure = 0.12
        chain_pressure += min(float(max(len(anchors) - 1, 0)) * 0.16, 0.36)
        chain_pressure += min(float(max(plan_count - 1, 0)) * 0.12, 0.24)
        chain_pressure += min(float(max(relation_count - 1, 0)) * 0.08, 0.16)
        if operator in {"bridge", "comparison", "boolean"}:
            chain_pressure += 0.18
        if is_temporal:
            chain_pressure += 0.04
        chain_pressure = min(max(float(chain_pressure), 0.0), 1.0)

        return {
            "operator": operator,
            "answer_type": answer_type,
            "anchors": sorted(set(anchors))[:6],
            "relation_terms": sorted(relation_terms)[:24],
            "query_tokens": sorted(query_tokens)[:32],
            "intents": sorted(intent for intent in intents if intent)[:8],
            "plan_count": int(plan_count),
            "required_slots": sorted(required_slots)[:80],
            "chain_pressure": round(float(chain_pressure), 6),
            "complex": bool(operator in {"bridge", "comparison", "boolean"} or chain_pressure >= 0.42),
        }

    def _evidence_join_operator_score(
        self,
        operator_profile: Mapping[str, Any],
        slots: Set[str],
        query_overlap: Set[str],
        text_info: Mapping[str, Any],
        source_precision: float,
        confidence: float,
        path_score: float,
        structural: bool,
        relation_only: bool,
    ) -> Dict[str, Any]:
        required_slots = set(operator_profile.get("required_slots", []) or [])
        covered_required_slots = set(slots) & required_slots
        anchor_slots = {slot for slot in required_slots if slot.startswith("anchor:")}
        relation_slots = {slot for slot in required_slots if slot.startswith("relation_token:")}
        answer_slots = {slot for slot in required_slots if slot.startswith("answer_type:")}
        anchor_hits = len({slot for slot in covered_required_slots if slot.startswith("anchor:")})
        relation_hits = len({slot for slot in covered_required_slots if slot.startswith("relation_token:")})
        answer_type_hit = bool(covered_required_slots & answer_slots)
        text_anchor_hits = self._safe_int(text_info.get("anchor_hits"), 0)
        text_terminal_hits = self._safe_int(text_info.get("terminal_hits"), 0)
        text_relation_hits = len(text_info.get("relation_overlap", []) or [])
        text_answer_hits = len(text_info.get("answer_overlap", []) or [])
        text_query_hits = len(text_info.get("query_overlap", []) or [])
        operator = str(operator_profile.get("operator") or "single")
        chain_pressure = self._safe_float(operator_profile.get("chain_pressure"), 0.0)

        anchor_score = anchor_hits / max(len(anchor_slots), 1) if anchor_slots else 0.0
        relation_score = relation_hits / max(len(relation_slots), 1) if relation_slots else 0.0
        answer_score = 1.0 if answer_type_hit else 0.0
        text_score = min(
            (0.30 * text_anchor_hits + 0.28 * text_terminal_hits + 0.22 * text_relation_hits
             + 0.12 * text_answer_hits + 0.08 * text_query_hits),
            1.0,
        )
        structure_score = 1.0 if structural else 0.0
        path_signal = min(max(float(path_score), 0.0), 1.0)
        score = (
            0.20 * anchor_score
            + 0.18 * relation_score
            + 0.12 * answer_score
            + 0.16 * text_score
            + 0.12 * path_signal
            + 0.10 * structure_score
            + 0.07 * min(float(source_precision), 1.0)
            + 0.05 * min(float(confidence), 1.0)
        )
        if operator in {"bridge", "comparison"}:
            score += 0.08 * chain_pressure
        if operator == "boolean":
            score += 0.06 if (anchor_score > 0.0 and relation_score > 0.0) else 0.0
        if relation_only and not (text_terminal_hits > 0 or path_signal >= 0.55 or anchor_score > 0.0):
            score -= 0.14
        score = min(max(float(score), 0.0), 1.0)
        return {
            "operator_score": round(float(score), 6),
            "operator": operator,
            "operator_required_slots": sorted(required_slots)[:80],
            "operator_covered_slots": sorted(covered_required_slots)[:48],
            "operator_anchor_score": round(float(anchor_score), 6),
            "operator_relation_score": round(float(relation_score), 6),
            "operator_answer_type_hit": bool(answer_type_hit),
            "operator_text_score": round(float(text_score), 6),
            "operator_chain_pressure": round(float(chain_pressure), 6),
        }

    def _evidence_join_answer_slot_profile(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
        slots: Set[str],
        query_overlap: Set[str],
        features: Mapping[str, Any],
        text_info: Mapping[str, Any],
        source_precision: float,
        confidence: float,
        original_rank: int,
        text_signal: bool,
        path_score: float,
        structural: bool,
        relation_only: bool,
    ) -> Dict[str, Any]:
        answer_slot = self._evidence_join_answer_slot(query_plan_log)
        if not self.evidence_join_planner_enable_answer_slot_rescue or not answer_slot:
            return {
                "answer_slot": answer_slot,
                "answer_slot_score": 0.0,
                "answer_slot_signal": False,
                "answer_slot_terms": [],
            }

        slot_terms_by_name = {
            "occupation": {"occupation", "profession", "job", "career", "role", "actor", "writer", "singer", "player"},
            "nationality": {"nationality", "citizen", "country", "nation", "born", "from"},
            "birth_place": {"born", "birth", "birthplace", "place", "city", "town", "country"},
            "death_place": {"died", "death", "die", "place", "city", "town", "country"},
            "father": {"father", "parent", "grandfather", "paternal"},
            "mother": {"mother", "parent", "grandmother", "maternal"},
            "spouse": {"spouse", "husband", "wife", "married", "marriage"},
            "organization": {"organization", "organisation", "company", "publisher", "label", "team", "group"},
            "type": {"genre", "category", "type", "kind", "class"},
            "date": {"date", "year", "month", "when", "born", "died", "released", "published"},
            "number": {"number", "count", "rank", "age", "many", "much"},
            "person": {"person", "who", "name", "father", "mother", "spouse", "founder"},
            "location": {"where", "place", "city", "country", "state", "location", "headquarters"},
        }
        slot_terms = slot_terms_by_name.get(answer_slot, {answer_slot})
        slot_text_parts: List[str] = list(slots) + list(query_overlap)
        for context in item.get("_all_contexts", item.get("contexts", [])) or []:
            if not isinstance(context, Mapping):
                continue
            slot_text_parts.extend(str(value) for value in context.get("relations", []) or [])
            for key in ("plan_id", "intent", "answer_type", "anchor_entity", "end_entity", "support_key"):
                value = context.get(key)
                if value:
                    slot_text_parts.append(str(value))
        slot_text = self._norm(" ".join(slot_text_parts))
        matched_terms = sorted(term for term in slot_terms if term and term in slot_text)
        answer_type_hit = any(slot.startswith(f"answer_type:{answer_slot}") for slot in slots)
        relation_hit_count = len(text_info.get("relation_overlap", []) or [])
        answer_hit_count = len(text_info.get("answer_overlap", []) or [])
        query_hit_count = len(text_info.get("query_overlap", []) or [])
        terminal_hits = self._safe_int(text_info.get("terminal_hits"), 0)
        anchor_hits = self._safe_int(text_info.get("anchor_hits"), 0)

        score = (
            0.23 * min(float(len(matched_terms)) / 2.0, 1.0)
            + 0.12 * (1.0 if answer_type_hit else 0.0)
            + 0.14 * min(float(len(query_overlap)) / 3.0, 1.0)
            + 0.13 * min(float(relation_hit_count + query_hit_count) / 4.0, 1.0)
            + 0.16 * (1.0 if text_signal or answer_hit_count > 0 or terminal_hits > 0 else 0.0)
            + 0.11 * (1.0 if structural or path_score > 0.0 else 0.0)
            + 0.08 * min(float(source_precision), 1.0)
            + 0.07 * min(float(confidence), 1.0)
        )
        if anchor_hits > 0 and terminal_hits > 0:
            score += 0.05
        if original_rank <= 5:
            score += 0.04
        elif original_rank <= 20:
            score += 0.02
        if relation_only and not (text_signal or terminal_hits > 0 or path_score > 0.0):
            score -= 0.16
        score = min(max(float(score), 0.0), 1.0)
        signal = (
            score >= min(self.evidence_join_planner_answer_slot_min_score, 0.50)
            and bool(matched_terms or answer_type_hit or text_signal or structural or path_score > 0.0)
            and not (relation_only and terminal_hits <= 0 and not text_signal and path_score <= 0.0)
        )
        return {
            "answer_slot": answer_slot,
            "answer_slot_score": round(float(score), 6),
            "answer_slot_signal": bool(signal),
            "answer_slot_terms": matched_terms[:12],
        }

    def _evidence_join_profile(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        query_slots = self._evidence_join_query_slots(query_plan_log)
        slots = self._evidence_join_context_slots(item.get("_all_contexts", item.get("contexts", [])) or [], query_plan_log)
        query_overlap = slots & query_slots
        features = self._intervention_features(item, query_plan_log)
        text_info = item.get("text_verifier", {}) or {}
        if not isinstance(text_info, Mapping):
            text_info = {}
        path_info = item.get("path_aware", {}) or {}
        if not isinstance(path_info, Mapping):
            path_info = {}
        provenance_info = item.get("provenance_groupwise", {}) or {}
        if not isinstance(provenance_info, Mapping):
            provenance_info = {}
        source_policy = item.get("source_policy", {}) or {}
        if not isinstance(source_policy, Mapping):
            source_policy = {}
        source_precision = max(
            self._safe_float(provenance_info.get("source_precision"), 0.0),
            self._safe_float(source_policy.get("selected_precision"), 0.0),
            self._safe_float(source_policy.get("precision"), 0.0),
            2.0 * self._safe_float(source_policy.get("gt5_precision"), 0.0),
        )
        source_precision = min(max(float(source_precision), 0.0), 1.0)
        text_score = self._safe_float(text_info.get("score"), 0.0)
        relation_hits = len(text_info.get("relation_overlap", []) or [])
        answer_hits = len(text_info.get("answer_overlap", []) or [])
        text_signal = (
            text_score >= 0.38
            or self._safe_int(text_info.get("anchor_hits"), 0) > 0
            or self._safe_int(text_info.get("terminal_hits"), 0) > 0
            or relation_hits >= 2
            or answer_hits > 0
        )
        path_score = self._safe_float(path_info.get("score"), 0.0) if bool(path_info.get("approved", False)) else 0.0
        structural = (
            bool(features.get("has_endpoint_pair"))
            or bool(features.get("has_terminal_relation"))
            or bool(features.get("has_anchor_relation"))
            or bool(features.get("has_path_seed"))
            or bool(features.get("has_path_neighbor"))
            or bool(item.get("has_multihop"))
            or bool(item.get("has_strict"))
        )
        relation_only = bool(features.get("relation_only"))
        slot_value = self._evidence_join_slot_value(slots, query_slots)
        query_slot_value = self._evidence_join_slot_value(query_overlap, query_slots)
        confidence = self._safe_float(item.get("confidence"), 0.0)
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        rank_cost = min(float(original_rank) / float(max(self.candidate_pool_top_k, 1)), 1.0)
        operator_profile = self._evidence_join_operator_profile(query_plan_log)
        operator_score_profile = self._evidence_join_operator_score(
            operator_profile=operator_profile,
            slots=slots,
            query_overlap=query_overlap,
            text_info=text_info,
            source_precision=source_precision,
            confidence=confidence,
            path_score=path_score,
            structural=structural,
            relation_only=relation_only,
        )
        operator_score = self._safe_float(operator_score_profile.get("operator_score"), 0.0)
        operator_chain_pressure = self._safe_float(operator_score_profile.get("operator_chain_pressure"), 0.0)
        score = (
            0.18 * confidence
            + 0.17 * source_precision
            + 0.16 * min(text_score, 1.0)
            + 0.14 * min(path_score, 1.0)
            + 0.16 * (1.0 if structural else 0.0)
            + 0.13 * min(slot_value / 1.2, 1.0)
            + 0.12 * min(query_slot_value / 0.8, 1.0)
            - 0.07 * rank_cost
        )
        if self.evidence_join_planner_enable_operator_aware:
            score += self.evidence_join_planner_operator_score_weight * operator_score
            score += self.evidence_join_planner_operator_chain_pressure_weight * operator_chain_pressure * min(
                operator_score,
                1.0,
            )
        if relation_only:
            score -= 0.18
        if self.evidence_join_planner_require_text_or_path and not (text_signal or path_score > 0.0 or structural):
            score -= 0.08
        answer_slot_profile = self._evidence_join_answer_slot_profile(
            item=item,
            query_plan_log=query_plan_log,
            slots=slots,
            query_overlap=query_overlap,
            features=features,
            text_info=text_info,
            source_precision=source_precision,
            confidence=confidence,
            original_rank=original_rank,
            text_signal=text_signal,
            path_score=path_score,
            structural=structural,
            relation_only=relation_only,
        )
        answer_slot_score = self._safe_float(answer_slot_profile.get("answer_slot_score"), 0.0)
        if self.evidence_join_planner_enable_answer_slot_rescue:
            score += self.evidence_join_planner_answer_slot_score_weight * answer_slot_score
        score = min(max(float(score), 0.0), 1.0)
        answer_slot_router_bypass = (
            self.evidence_join_planner_enable_answer_slot_rescue
            and bool(answer_slot_profile.get("answer_slot_signal", False))
            and answer_slot_score >= self.evidence_join_planner_answer_slot_router_bypass_min_score
            and original_rank <= self.candidate_pool_top_k
        )
        router_bypass = (
            self.enable_evidence_join_planner
            and (
                (
                    score >= self.evidence_join_planner_router_bypass_min_score
                    and not relation_only
                    and (text_signal or path_score > 0.0 or structural)
                )
                or answer_slot_router_bypass
            )
            and original_rank <= self.candidate_pool_top_k
        )
        return {
            "enabled": self.enable_evidence_join_planner,
            "score": round(float(score), 6),
            "router_bypass": bool(router_bypass),
            "slots": sorted(slots)[:80],
            "query_overlap": sorted(query_overlap)[:32],
            "slot_value": round(float(slot_value), 6),
            "query_slot_value": round(float(query_slot_value), 6),
            "source_precision": round(float(source_precision), 6),
            "text_score": round(float(text_score), 6),
            "text_signal": bool(text_signal),
            "path_score": round(float(path_score), 6),
            "structural": bool(structural),
            "relation_only": bool(relation_only),
            "rank_cost": round(float(rank_cost), 6),
            "operator_aware_enabled": bool(self.evidence_join_planner_enable_operator_aware),
            **operator_score_profile,
            **answer_slot_profile,
            "answer_slot_router_bypass": bool(answer_slot_router_bypass),
        }

    def _apply_evidence_join_profile(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> str:
        if not self.enable_evidence_join_planner:
            item["evidence_join_planner"] = {
                "enabled": False,
                "score": 0.0,
                "router_bypass": False,
                "reason": "disabled",
            }
            return "disabled"
        profile = self._evidence_join_profile(item, query_plan_log)
        item["evidence_join_planner"] = profile
        score = self._safe_float(profile.get("score"), 0.0)
        answer_slot_score = self._safe_float(profile.get("answer_slot_score"), 0.0)
        answer_slot_candidate = (
            self.evidence_join_planner_enable_answer_slot_rescue
            and bool(profile.get("answer_slot_signal", False))
            and answer_slot_score >= self.evidence_join_planner_answer_slot_min_score
        )
        if score >= self.evidence_join_planner_min_score or answer_slot_candidate:
            item["_evidence_join_candidate"] = True
            item["score"] = self._safe_float(item.get("score"), 0.0) + self.evidence_join_planner_score_weight * score
            if answer_slot_candidate:
                item["score"] = self._safe_float(item.get("score"), 0.0) + (
                    self.evidence_join_planner_answer_slot_score_weight * answer_slot_score
                )
                item["_evidence_join_answer_slot_candidate"] = True
            item["effective_min_confidence"] = min(
                self._safe_float(item.get("effective_min_confidence"), self.min_candidate_confidence),
                max(0.52, self.min_candidate_confidence - 0.04 * score - 0.03 * answer_slot_score),
            )
            return "answer_slot_candidate" if answer_slot_candidate and score < self.evidence_join_planner_min_score else "candidate"
        return "low_score"

    def _passes_evidence_join_planner(
        self,
        item: Mapping[str, Any],
        selected: Sequence[int],
        selected_set: Set[int],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        query_plan_log: Mapping[str, Any],
        target_top2: bool = False,
    ) -> Tuple[bool, str, Dict[str, Any]]:
        if not self.enable_evidence_join_planner:
            return False, "evidence_join_disabled", {}
        candidate_doc = int(item.get("passage_idx", -1))
        if candidate_doc < 0:
            return False, "evidence_join_invalid_doc", {}
        if candidate_doc in selected_set:
            return False, "evidence_join_already_selected", {}
        profile = item.get("evidence_join_planner", {}) or {}
        if not isinstance(profile, Mapping):
            profile = {}
        score = self._safe_float(profile.get("score"), 0.0)
        min_score = self.evidence_join_planner_top2_min_score if target_top2 else self.evidence_join_planner_min_score
        answer_slot_score = self._safe_float(profile.get("answer_slot_score"), 0.0)
        answer_slot_min_score = (
            self.evidence_join_planner_answer_slot_top2_min_score
            if target_top2
            else self.evidence_join_planner_answer_slot_min_score
        )
        answer_slot_rescue = (
            self.evidence_join_planner_enable_answer_slot_rescue
            and bool(profile.get("answer_slot_signal", False))
            and answer_slot_score >= answer_slot_min_score
        )
        if score < min_score and not answer_slot_rescue:
            return False, "evidence_join_low_score", {
                "score": round(float(score), 6),
                "min_score": round(float(min_score), 6),
                "answer_slot_score": round(float(answer_slot_score), 6),
                "answer_slot_min_score": round(float(answer_slot_min_score), 6),
            }
        if bool(profile.get("relation_only", False)) and not answer_slot_rescue:
            return False, "evidence_join_relation_only", {"score": round(float(score), 6)}
        if self.evidence_join_planner_require_text_or_path and not (
            bool(profile.get("text_signal", False))
            or self._safe_float(profile.get("path_score"), 0.0) > 0.0
            or bool(profile.get("structural", False))
            or answer_slot_rescue
        ):
            return False, "evidence_join_weak_text_or_path", {"score": round(float(score), 6)}

        top_without_candidate: List[int] = [int(doc_id) for doc_id in selected[: self.final_top_k]]
        top_without_set = set(top_without_candidate)
        for doc_id in base_doc_ids:
            doc_id = int(doc_id)
            if doc_id in top_without_set:
                continue
            top_without_candidate.append(doc_id)
            top_without_set.add(doc_id)
            if len(top_without_candidate) >= self.final_top_k:
                break
        if len(top_without_candidate) < self.final_top_k:
            return False, "evidence_join_short_window", {
                "top_without_candidate": top_without_candidate,
            }

        query_slots = self._evidence_join_query_slots(query_plan_log)
        candidate_slots = set(profile.get("slots", []) or [])
        selected_slots: Set[str] = set()
        for doc_id in top_without_candidate[: self.final_top_k]:
            selected_slots.update(self._evidence_join_doc_slots(doc_id, passage_details, query_plan_log))
        new_slots = candidate_slots - selected_slots
        query_new_slots = new_slots & query_slots
        operator_required_slots = set(profile.get("operator_required_slots", []) or [])
        operator_missing_slots = operator_required_slots - selected_slots
        operator_new_slots = new_slots & operator_required_slots
        operator_chain_pressure = self._safe_float(profile.get("operator_chain_pressure"), 0.0)
        operator_score = self._safe_float(profile.get("operator_score"), 0.0)
        operator_name = str(profile.get("operator") or "single")
        operator_gain = min(
            1.5,
            self._evidence_join_slot_value(operator_new_slots, operator_required_slots)
            + 0.25 * self._evidence_join_slot_value(operator_new_slots & operator_missing_slots, operator_required_slots)
            + 0.20 * operator_score * operator_chain_pressure,
        )
        marginal_gain = min(
            1.5,
            self._evidence_join_slot_value(new_slots, query_slots)
            + 0.35 * self._evidence_join_slot_value(query_new_slots, query_slots),
        )
        operator_aware_complex = (
            self.evidence_join_planner_enable_operator_aware
            and operator_name in {"bridge", "comparison", "boolean"}
        )
        if self.evidence_join_planner_enable_operator_aware:
            marginal_gain = min(
                1.5,
                marginal_gain
                + 0.46 * operator_gain
                + 0.12 * operator_chain_pressure * min(operator_score, 1.0),
            )
        normalized_gain = min(marginal_gain / 1.1, 1.0)
        min_marginal_gain = self.evidence_join_planner_min_marginal_gain
        operator_min_gain = (
            self.evidence_join_planner_operator_top2_min_gain
            if target_top2
            else self.evidence_join_planner_operator_min_gain
        )
        if answer_slot_rescue:
            min_marginal_gain = min(min_marginal_gain, 0.08 if target_top2 else 0.05)
        if operator_aware_complex and operator_gain < operator_min_gain and not answer_slot_rescue:


            return False, "evidence_join_low_operator_gain", {
                "operator": operator_name,
                "operator_gain": round(float(operator_gain), 6),
                "operator_min_gain": round(float(operator_min_gain), 6),
                "operator_score": round(float(operator_score), 6),
                "operator_chain_pressure": round(float(operator_chain_pressure), 6),
                "operator_new_slots": sorted(operator_new_slots)[:24],
                "operator_missing_slots": sorted(operator_missing_slots)[:24],
                "new_slots": sorted(new_slots)[:24],
                "query_new_slots": sorted(query_new_slots)[:16],
            }
        if marginal_gain < min_marginal_gain:
            return False, "evidence_join_low_marginal_gain", {
                "marginal_gain": round(float(marginal_gain), 6),
                "min_marginal_gain": round(float(min_marginal_gain), 6),
                "answer_slot_rescue": bool(answer_slot_rescue),
                "operator": operator_name,
                "operator_gain": round(float(operator_gain), 6),
                "operator_min_gain": round(float(operator_min_gain), 6),
                "new_slots": sorted(new_slots)[:24],
                "query_new_slots": sorted(query_new_slots)[:16],
            }

        replaceable = []
        start_index = 1 if target_top2 else 2
        end_index = 2 if target_top2 else min(self.final_top_k, len(top_without_candidate))
        for index in range(start_index, end_index):
            doc_id = int(top_without_candidate[index])
            replacement_rank = int(original_rank_by_doc.get(doc_id, index + 1))
            replacement_slots = self._evidence_join_doc_slots(doc_id, passage_details, query_plan_log)
            other_slots: Set[str] = set()
            for other_index, other_doc in enumerate(top_without_candidate[: self.final_top_k]):
                if other_index == index:
                    continue
                other_slots.update(self._evidence_join_doc_slots(other_doc, passage_details, query_plan_log))
            lost_slots = replacement_slots - (other_slots | candidate_slots)
            lost_value = self._evidence_join_slot_value(lost_slots, query_slots)
            replacement_value = self._baseline_replacement_value(
                doc_id,
                replacement_rank,
                passage_details,
                max_raw_score,
            ) + 0.07 * lost_value
            replaceable.append((replacement_value, index, doc_id, replacement_rank, lost_value, lost_slots))
        if not replaceable:
            return False, "evidence_join_no_replaceable_slot", {}
        replacement_value, replacement_index, replacement_doc, replacement_rank, lost_value, lost_slots = min(
            replaceable,
            key=lambda row: (row[0], -row[1]),
        )

        candidate_value = self._candidate_evidence_value(item)
        candidate_utility = min(
            1.45,
            candidate_value
            + self.evidence_join_planner_score_weight * score
            + self.evidence_join_planner_marginal_gain_weight * normalized_gain
            + self.evidence_join_planner_answer_slot_score_weight * answer_slot_score
            + (
                self.evidence_join_planner_operator_score_weight * operator_score
                + 0.20 * operator_gain
                if self.evidence_join_planner_enable_operator_aware
                else 0.0
            )
            + 0.05 * self._safe_float(profile.get("source_precision"), 0.0),
        )
        margin = candidate_utility - replacement_value
        required_margin = self.evidence_join_planner_min_value_margin
        source_precision = self._safe_float(profile.get("source_precision"), 0.0)
        text_signal = bool(profile.get("text_signal", False))
        path_score = self._safe_float(profile.get("path_score"), 0.0)
        answer_slot_signal = bool(profile.get("answer_slot_signal", False))
        text_info = item.get("text_verifier", {}) or {}
        if not isinstance(text_info, Mapping):
            text_info = {}
        answer_hits = len(text_info.get("answer_overlap", []) or [])
        terminal_hits = self._safe_int(text_info.get("terminal_hits"), 0)
        has_answer_signal = bool(
            answer_slot_rescue
            or answer_slot_signal
            or text_signal
            or path_score >= 0.45
            or answer_hits > 0
            or terminal_hits > 0
        )
        if target_top2:
            required_margin = max(required_margin, 0.06)
            if answer_slot_rescue:
                required_margin = min(required_margin, -0.02)
            if operator_aware_complex and operator_gain >= operator_min_gain:
                required_margin = max(required_margin - 0.025, 0.04)
            if not bool(profile.get("text_signal", False)) and not answer_slot_rescue:
                required_margin += 0.05
            if self._safe_float(profile.get("source_precision"), 0.0) < 0.10 and not answer_slot_rescue:
                required_margin += 0.05
        elif replacement_index == 2:
            required_margin += 0.025
        if (
            self.evidence_join_planner_enable_operator_aware
            and not target_top2
            and operator_gain >= operator_min_gain
        ):
            required_margin = min(required_margin, self.evidence_join_planner_min_value_margin)
        if answer_slot_rescue and not target_top2:
            required_margin = min(required_margin, -0.04)
        if self.evidence_join_planner_enable_risk_gate:
            if target_top2 and not has_answer_signal:
                return False, "evidence_join_top2_missing_answer_signal", {
                    "score": round(float(score), 6),
                    "answer_slot_score": round(float(answer_slot_score), 6),
                    "source_precision": round(float(source_precision), 6),
                    "path_score": round(float(path_score), 6),
                    "margin": round(float(margin), 6),
                    "required_margin": round(float(required_margin), 6),
                }
            if (
                target_top2
                and source_precision < self.evidence_join_planner_risk_gate_top2_min_source_precision
                and not answer_slot_rescue
            ):
                return False, "evidence_join_top2_low_source_precision", {
                    "source_precision": round(float(source_precision), 6),
                    "min_source_precision": round(
                        float(self.evidence_join_planner_risk_gate_top2_min_source_precision),
                        6,
                    ),
                    "margin": round(float(margin), 6),
                    "required_margin": round(float(required_margin), 6),
                }
            if (
                not target_top2
                and source_precision < self.evidence_join_planner_risk_gate_top5_min_source_precision
                and not has_answer_signal
            ):
                return False, "evidence_join_top5_low_source_precision", {
                    "source_precision": round(float(source_precision), 6),
                    "min_source_precision": round(
                        float(self.evidence_join_planner_risk_gate_top5_min_source_precision),
                        6,
                    ),
                    "margin": round(float(margin), 6),
                    "required_margin": round(float(required_margin), 6),
                }
            if (
                lost_value > self.evidence_join_planner_risk_gate_max_lost_value
                and not query_new_slots
                and not answer_slot_rescue
                and not (operator_aware_complex and operator_gain >= operator_min_gain)
            ):
                return False, "evidence_join_lost_slot_risk", {
                    "lost_value": round(float(lost_value), 6),
                    "max_lost_value": round(
                        float(self.evidence_join_planner_risk_gate_max_lost_value),
                        6,
                    ),
                    "lost_slots": sorted(lost_slots)[:24],
                    "new_slots": sorted(new_slots)[:24],
                    "margin": round(float(margin), 6),
                    "required_margin": round(float(required_margin), 6),
                }
            required_margin = max(
                required_margin,
                (
                    self.evidence_join_planner_risk_gate_top2_min_margin
                    if target_top2
                    else self.evidence_join_planner_risk_gate_top5_min_margin
                ),
            )
        approved = margin >= required_margin
        return approved, "evidence_join_gain" if approved else "evidence_join_low_margin", {
            "score": round(float(score), 6),
            "answer_slot": str(profile.get("answer_slot") or ""),
            "answer_slot_score": round(float(answer_slot_score), 6),
            "answer_slot_rescue": bool(answer_slot_rescue),
            "answer_signal": bool(has_answer_signal),
            "candidate_value": round(float(candidate_value), 6),
            "candidate_utility": round(float(candidate_utility), 6),
            "replacement_doc": int(replacement_doc),
            "replacement_index": int(replacement_index),
            "replacement_rank": int(replacement_rank),
            "replacement_value": round(float(replacement_value), 6),
            "lost_value": round(float(lost_value), 6),
            "margin": round(float(margin), 6),
            "required_margin": round(float(required_margin), 6),
            "marginal_gain": round(float(marginal_gain), 6),
            "normalized_gain": round(float(normalized_gain), 6),
            "operator_aware": bool(self.evidence_join_planner_enable_operator_aware),
            "operator": operator_name,
            "operator_score": round(float(operator_score), 6),
            "operator_gain": round(float(operator_gain), 6),
            "operator_min_gain": round(float(operator_min_gain), 6),
            "operator_chain_pressure": round(float(operator_chain_pressure), 6),
            "operator_new_slots": sorted(operator_new_slots)[:32],
            "operator_missing_slots": sorted(operator_missing_slots)[:32],
            "new_slots": sorted(new_slots)[:32],
            "query_new_slots": sorted(query_new_slots)[:24],
            "lost_slots": sorted(lost_slots)[:24],
            "top_without_candidate": top_without_candidate[: self.final_top_k],
            "target_top2": bool(target_top2),
            "risk_gate_enabled": bool(self.evidence_join_planner_enable_risk_gate),
        }

    def _apply_evidence_join_planner(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        rejections: Counter,
        rejected_candidates: List[Dict[str, Any]],
        selected_candidates: List[Dict[str, Any]],
    ) -> Tuple[int, int]:
        if not self.enable_evidence_join_planner:
            return 0, 0
        for doc_id in base_doc_ids:
            if len(selected) >= self.final_top_k:
                break
            doc_id = int(doc_id)
            if doc_id in selected_set:
                continue
            selected.append(doc_id)
            selected_set.add(doc_id)

        top2_swaps = 0
        top5_swaps = 0

        def _score_candidates(target_top2: bool) -> List[Tuple[float, float, int, Dict[str, Any], Dict[str, Any]]]:
            scored: List[Tuple[float, float, int, Dict[str, Any], Dict[str, Any]]] = []
            for item in candidates:
                candidate_doc = int(item.get("passage_idx", -1))
                if candidate_doc < 0 or candidate_doc in selected_set:
                    continue
                approved, reason, features = self._passes_evidence_join_planner(
                    item=item,
                    selected=selected,
                    selected_set=selected_set,
                    base_doc_ids=base_doc_ids,
                    original_rank_by_doc=original_rank_by_doc,
                    passage_details=passage_details,
                    max_raw_score=max_raw_score,
                    query_plan_log=query_plan_log,
                    target_top2=target_top2,
                )
                item["evidence_join_gate"] = {
                    "approved": bool(approved),
                    "reason": reason,
                    "features": features,
                }
                if approved:
                    scored.append((
                        self._safe_float(features.get("margin"), 0.0),
                        self._safe_float(features.get("marginal_gain"), 0.0),
                        -self._safe_int(item.get("original_rank"), 10**9),
                        item,
                        features,
                    ))
                else:
                    rejections[reason] += 1
                    if len(rejected_candidates) < 12 and reason not in {
                        "evidence_join_low_score",
                        "evidence_join_already_selected",
                    }:
                        rejected_candidates.append(
                            self._decision_for_log(
                                item,
                                selected=False,
                                reason=f"evidence_join_rejected:{reason}",
                            )
                        )
            scored.sort(key=lambda row: (row[0], row[1], row[2]), reverse=True)
            return scored

        if self.evidence_join_planner_max_top2_swaps > 0 and len(selected) >= 2:
            for _, _, _, item, features in _score_candidates(target_top2=True):
                if top2_swaps >= self.evidence_join_planner_max_top2_swaps:
                    break
                candidate_doc = int(item.get("passage_idx", -1))
                if candidate_doc < 0 or candidate_doc in selected_set:
                    continue
                replacement_index = self._safe_int(features.get("replacement_index"), 1)
                if replacement_index != 1:
                    rejections["evidence_join_bad_top2_replacement"] += 1
                    continue
                replaced_doc = int(selected[replacement_index])
                selected[replacement_index] = candidate_doc
                selected_set.discard(replaced_doc)
                selected_set.add(candidate_doc)
                item["_evidence_join_top2_selected"] = True
                item["_evidence_join_replaced_doc"] = replaced_doc
                if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                    selected_ontology.append(item)
                top2_swaps += 1
                if len(selected_candidates) < 12:
                    selected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=True,
                            reason="evidence_join_top2_selected",
                            final_rank=2,
                        )
                    )
        elif self.evidence_join_planner_max_top5_swaps <= 0 and len(selected) >= 2:


            _score_candidates(target_top2=True)

        max_top5_swaps = self.evidence_join_planner_max_top5_swaps
        if max_top5_swaps <= 0 or len(selected) < self.final_top_k:
            return top2_swaps, top5_swaps
        for _, _, _, item, features in _score_candidates(target_top2=False):
            if top5_swaps >= max_top5_swaps:
                break
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0 or candidate_doc in selected_set:
                continue
            replacement_index = self._safe_int(features.get("replacement_index"), self.final_top_k - 1)
            if replacement_index < 2 or replacement_index >= min(self.final_top_k, len(selected)):
                rejections["evidence_join_bad_top5_replacement"] += 1
                continue
            replaced_doc = int(selected[replacement_index])
            selected[replacement_index] = candidate_doc
            selected_set.discard(replaced_doc)
            selected_set.add(candidate_doc)
            item["_evidence_join_top5_selected"] = True
            item["_evidence_join_replaced_doc"] = replaced_doc
            if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                selected_ontology.append(item)
            top5_swaps += 1
            if len(selected_candidates) < 12:
                selected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason="evidence_join_top5_selected",
                        final_rank=int(replacement_index + 1),
                    )
                )
        return top2_swaps, top5_swaps

    def _answer_pairwise_doc_item(
        self,
        doc_id: int,
        original_rank: int,
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        detail = passage_details.get(int(doc_id), {}) or {}
        contexts = list(detail.get("contexts", []) or [])
        confidence = self._candidate_confidence(detail, max_raw_score) if detail else 0.0
        source_policy = self._evidence_grounded_profile(contexts, int(original_rank)) if contexts else {}
        path_aware = self._path_aware_features(contexts) if contexts else {
            "enabled": self.enable_path_aware_selector,
            "approved": False,
            "score": 0.0,
        }
        item: Dict[str, Any] = {
            "passage_idx": int(doc_id),
            "original_rank": int(original_rank),
            "confidence": confidence,
            "score": 0.0,
            "contexts": contexts[:3],
            "_all_contexts": contexts,
            "source_policy": source_policy,
            "path_aware": path_aware,
            **self._candidate_quality_flags(contexts),
        }


        self._apply_text_verifier(item, query_plan_log)
        item["evidence_join_planner"] = self._evidence_join_profile(item, query_plan_log)
        return item

    def _answer_pairwise_profile(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        text_info = item.get("text_verifier", {}) or {}
        if not isinstance(text_info, Mapping):
            text_info = {}
        path_info = item.get("path_aware", {}) or {}
        if not isinstance(path_info, Mapping):
            path_info = {}
        source_policy = item.get("source_policy", {}) or {}
        if not isinstance(source_policy, Mapping):
            source_policy = {}
        join_info = item.get("evidence_join_planner", {}) or {}
        if not isinstance(join_info, Mapping):
            join_info = self._evidence_join_profile(item, query_plan_log)

        text_score = self._safe_float(text_info.get("score"), 0.0)
        anchor_hits = self._safe_int(text_info.get("anchor_hits"), 0)
        terminal_hits = self._safe_int(text_info.get("terminal_hits"), 0)
        relation_hits = len(text_info.get("relation_overlap", []) or [])
        query_hits = len(text_info.get("query_overlap", []) or [])
        answer_hits = len(text_info.get("answer_overlap", []) or [])
        endpoint_signal = 1.0 if anchor_hits > 0 and terminal_hits > 0 else 0.0
        answer_signal = (
            answer_hits > 0
            or terminal_hits > 0
            or endpoint_signal > 0.0
            or text_score >= 0.46
        )

        path_score = self._safe_float(path_info.get("score"), 0.0) if bool(path_info.get("approved", False)) else 0.0
        source_precision = max(
            self._safe_float(source_policy.get("selected_precision"), 0.0),
            self._safe_float(source_policy.get("precision"), 0.0),
            2.0 * self._safe_float(source_policy.get("gt5_precision"), 0.0),
            self._safe_float(join_info.get("source_precision"), 0.0),
        )
        source_precision = min(max(float(source_precision), 0.0), 1.0)
        join_score = self._safe_float(join_info.get("score"), 0.0)
        query_slot_value = self._safe_float(join_info.get("query_slot_value"), 0.0)
        slot_value = self._safe_float(join_info.get("slot_value"), 0.0)
        confidence = self._safe_float(item.get("confidence"), 0.0)
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        rank_cost = min(float(original_rank) / float(max(self.candidate_pool_top_k, 1)), 1.0)
        structural = (
            bool(item.get("has_strict"))
            or bool(item.get("has_multihop"))
            or bool(item.get("has_terminal") and item.get("has_relation"))
            or bool(join_info.get("structural", False))
        )
        relation_only = bool(join_info.get("relation_only", False))
        relation_signal = min((relation_hits + 0.5 * query_hits) / 4.0, 1.0)

        score = (
            0.24 * min(text_score, 1.0)
            + 0.15 * min(float(terminal_hits + answer_hits), 2.0) / 2.0
            + 0.12 * endpoint_signal
            + 0.12 * relation_signal
            + 0.11 * source_precision
            + 0.10 * min(path_score, 1.0)
            + 0.08 * min(join_score, 1.0)
            + 0.06 * min(query_slot_value / 0.8, 1.0)
            + 0.05 * min(slot_value / 1.2, 1.0)
            + 0.07 * confidence
            + 0.07 * (1.0 if structural else 0.0)
            - 0.06 * rank_cost
        )
        if relation_only:
            score -= 0.15
        if self.answer_pairwise_require_answer_signal and not (
            answer_signal or path_score >= 0.55 or (structural and text_score >= 0.30)
        ):
            score -= 0.10
        score = min(max(float(score), 0.0), 1.0)
        return {
            "enabled": self.enable_answer_pairwise_verifier,
            "score": round(float(score), 6),
            "text_score": round(float(text_score), 6),
            "anchor_hits": int(anchor_hits),
            "terminal_hits": int(terminal_hits),
            "relation_hits": int(relation_hits),
            "query_hits": int(query_hits),
            "answer_hits": int(answer_hits),
            "endpoint_signal": bool(endpoint_signal > 0.0),
            "answer_signal": bool(answer_signal),
            "path_score": round(float(path_score), 6),
            "source_precision": round(float(source_precision), 6),
            "join_score": round(float(join_score), 6),
            "query_slot_value": round(float(query_slot_value), 6),
            "slot_value": round(float(slot_value), 6),
            "confidence": round(float(confidence), 6),
            "structural": bool(structural),
            "relation_only": bool(relation_only),
            "rank_cost": round(float(rank_cost), 6),
        }

    def _apply_answer_pairwise_profile(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> str:
        if not self.enable_answer_pairwise_verifier:
            item["answer_pairwise_verifier"] = {
                "enabled": False,
                "score": 0.0,
                "reason": "disabled",
            }
            return "disabled"
        profile = self._answer_pairwise_profile(item, query_plan_log)
        item["answer_pairwise_verifier"] = profile
        score = self._safe_float(profile.get("score"), 0.0)
        if score >= self.answer_pairwise_min_score:
            item["_answer_pairwise_candidate"] = True
            item["score"] = self._safe_float(item.get("score"), 0.0) + self.answer_pairwise_score_weight * score
            return "candidate"
        return "low_score"

    def _passes_answer_pairwise_verifier(
        self,
        item: Mapping[str, Any],
        selected: Sequence[int],
        selected_set: Set[int],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        query_plan_log: Mapping[str, Any],
        target_top2: bool = False,
    ) -> Tuple[bool, str, Dict[str, Any]]:
        if not self.enable_answer_pairwise_verifier:
            return False, "answer_pairwise_disabled", {}
        candidate_doc = int(item.get("passage_idx", -1))
        if candidate_doc < 0:
            return False, "answer_pairwise_invalid_doc", {}
        if candidate_doc in selected_set:
            return False, "answer_pairwise_already_selected", {}
        profile = item.get("answer_pairwise_verifier", {}) or {}
        if not isinstance(profile, Mapping):
            profile = self._answer_pairwise_profile(item, query_plan_log)
        score = self._safe_float(profile.get("score"), 0.0)
        min_score = self.answer_pairwise_top2_min_score if target_top2 else self.answer_pairwise_min_score
        if score < min_score:
            return False, "answer_pairwise_low_score", {
                "score": round(float(score), 6),
                "min_score": round(float(min_score), 6),
            }
        answer_signal = bool(profile.get("answer_signal", False))
        if self.answer_pairwise_require_answer_signal and not (
            answer_signal
            or self._safe_float(profile.get("path_score"), 0.0) >= 0.55
            or (
                bool(profile.get("structural", False))
                and self._safe_float(profile.get("text_score"), 0.0) >= 0.34
            )
        ):
            return False, "answer_pairwise_no_answer_signal", dict(profile)
        if bool(profile.get("relation_only", False)):
            return False, "answer_pairwise_relation_only", dict(profile)

        top_without_candidate: List[int] = [int(doc_id) for doc_id in selected[: self.final_top_k]]
        top_without_set = set(top_without_candidate)
        for doc_id in base_doc_ids:
            doc_id = int(doc_id)
            if doc_id in top_without_set:
                continue
            top_without_candidate.append(doc_id)
            top_without_set.add(doc_id)
            if len(top_without_candidate) >= self.final_top_k:
                break
        if len(top_without_candidate) < self.final_top_k:
            return False, "answer_pairwise_short_window", {
                "top_without_candidate": top_without_candidate,
            }

        replacement_rows = []
        if target_top2:
            replacement_indices = [1] if len(top_without_candidate) > 1 else []
        else:
            replacement_indices = list(range(2, min(self.final_top_k, len(top_without_candidate))))
        for index in replacement_indices:
            doc_id = int(top_without_candidate[index])
            replacement_rank = int(original_rank_by_doc.get(doc_id, index + 1))
            replacement_item = self._answer_pairwise_doc_item(
                doc_id,
                replacement_rank,
                passage_details,
                max_raw_score,
                query_plan_log,
            )
            replacement_profile = replacement_item.get("answer_pairwise_verifier") or self._answer_pairwise_profile(
                replacement_item,
                query_plan_log,
            )
            replacement_score = self._safe_float(replacement_profile.get("score"), 0.0)
            replacement_prior = self._baseline_replacement_value(
                doc_id,
                replacement_rank,
                passage_details,
                max_raw_score,
            )
            replacement_utility = min(1.2, replacement_score + 0.16 * replacement_prior)
            replacement_rows.append((
                replacement_utility,
                index,
                doc_id,
                replacement_rank,
                replacement_score,
                replacement_profile,
            ))
        if not replacement_rows:
            return False, "answer_pairwise_no_replaceable_slot", {}
        replacement_utility, replacement_index, replacement_doc, replacement_rank, replacement_score, replacement_profile = min(
            replacement_rows,
            key=lambda row: (row[0], -row[1]),
        )
        candidate_utility = min(
            1.25,
            score
            + 0.10 * self._candidate_evidence_value(item)
            + 0.06 * self._safe_float(profile.get("join_score"), 0.0)
            + 0.04 * self._safe_float(profile.get("source_precision"), 0.0),
        )
        margin = candidate_utility - replacement_utility
        required_margin = self.answer_pairwise_top2_min_margin if target_top2 else self.answer_pairwise_min_margin
        if target_top2 and self._safe_float(profile.get("text_score"), 0.0) < 0.40:
            required_margin += 0.03
        if not answer_signal:
            required_margin += 0.03
        approved = margin >= required_margin
        return approved, "answer_pairwise_gain" if approved else "answer_pairwise_low_margin", {
            "score": round(float(score), 6),
            "candidate_utility": round(float(candidate_utility), 6),
            "replacement_doc": int(replacement_doc),
            "replacement_index": int(replacement_index),
            "replacement_rank": int(replacement_rank),
            "replacement_score": round(float(replacement_score), 6),
            "replacement_utility": round(float(replacement_utility), 6),
            "replacement_profile": replacement_profile,
            "margin": round(float(margin), 6),
            "required_margin": round(float(required_margin), 6),
            "target_top2": bool(target_top2),
            "candidate_profile": profile,
            "top_without_candidate": top_without_candidate[: self.final_top_k],
        }

    def _apply_answer_pairwise_verifier(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        rejections: Counter,
        rejected_candidates: List[Dict[str, Any]],
        selected_candidates: List[Dict[str, Any]],
    ) -> Tuple[int, int]:
        if not self.enable_answer_pairwise_verifier:
            return 0, 0
        for doc_id in base_doc_ids:
            if len(selected) >= self.final_top_k:
                break
            doc_id = int(doc_id)
            if doc_id in selected_set:
                continue
            selected.append(doc_id)
            selected_set.add(doc_id)

        def _score(target_top2: bool) -> List[Tuple[float, float, int, Dict[str, Any], Dict[str, Any]]]:
            scored: List[Tuple[float, float, int, Dict[str, Any], Dict[str, Any]]] = []
            for item in candidates:
                candidate_doc = int(item.get("passage_idx", -1))
                if candidate_doc < 0 or candidate_doc in selected_set:
                    continue
                approved, reason, features = self._passes_answer_pairwise_verifier(
                    item=item,
                    selected=selected,
                    selected_set=selected_set,
                    base_doc_ids=base_doc_ids,
                    original_rank_by_doc=original_rank_by_doc,
                    passage_details=passage_details,
                    max_raw_score=max_raw_score,
                    query_plan_log=query_plan_log,
                    target_top2=target_top2,
                )
                item["answer_pairwise_gate"] = {
                    "approved": bool(approved),
                    "reason": reason,
                    "features": features,
                }
                if approved:
                    scored.append((
                        self._safe_float(features.get("margin"), 0.0),
                        self._safe_float(features.get("score"), 0.0),
                        -self._safe_int(item.get("original_rank"), 10**9),
                        item,
                        features,
                    ))
                else:
                    rejections[reason] += 1
                    if len(rejected_candidates) < 12 and reason not in {
                        "answer_pairwise_low_score",
                        "answer_pairwise_already_selected",
                    }:
                        rejected_candidates.append(
                            self._decision_for_log(
                                item,
                                selected=False,
                                reason=f"answer_pairwise_rejected:{reason}",
                            )
                        )
            scored.sort(key=lambda row: (row[0], row[1], row[2]), reverse=True)
            return scored

        top2_swaps = 0
        if self.answer_pairwise_max_top2_swaps > 0 and len(selected) >= 2:
            for _, _, _, item, features in _score(target_top2=True):
                if top2_swaps >= self.answer_pairwise_max_top2_swaps:
                    break
                candidate_doc = int(item.get("passage_idx", -1))
                if candidate_doc < 0 or candidate_doc in selected_set:
                    continue
                replacement_index = self._safe_int(features.get("replacement_index"), 1)
                if replacement_index != 1:
                    rejections["answer_pairwise_bad_top2_replacement"] += 1
                    continue
                replaced_doc = int(selected[replacement_index])
                selected[replacement_index] = candidate_doc
                selected_set.discard(replaced_doc)
                selected_set.add(candidate_doc)
                item["_answer_pairwise_top2_selected"] = True
                item["_answer_pairwise_replaced_doc"] = replaced_doc
                if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                    selected_ontology.append(item)
                top2_swaps += 1
                if len(selected_candidates) < 12:
                    selected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=True,
                            reason="answer_pairwise_top2_selected",
                            final_rank=2,
                        )
                    )
        elif self.answer_pairwise_max_top5_swaps <= 0 and len(selected) >= 2:


            _score(target_top2=True)

        top5_swaps = 0
        if self.answer_pairwise_max_top5_swaps <= 0 or len(selected) < self.final_top_k:
            return top2_swaps, top5_swaps
        for _, _, _, item, features in _score(target_top2=False):
            if top5_swaps >= self.answer_pairwise_max_top5_swaps:
                break
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0 or candidate_doc in selected_set:
                continue
            replacement_index = self._safe_int(features.get("replacement_index"), self.final_top_k - 1)
            if replacement_index < 2 or replacement_index >= min(self.final_top_k, len(selected)):
                rejections["answer_pairwise_bad_top5_replacement"] += 1
                continue
            replaced_doc = int(selected[replacement_index])
            selected[replacement_index] = candidate_doc
            selected_set.discard(replaced_doc)
            selected_set.add(candidate_doc)
            item["_answer_pairwise_top5_selected"] = True
            item["_answer_pairwise_replaced_doc"] = replaced_doc
            if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                selected_ontology.append(item)
            top5_swaps += 1
            if len(selected_candidates) < 12:
                selected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason="answer_pairwise_top5_selected",
                        final_rank=int(replacement_index + 1),
                    )
                )
        return top2_swaps, top5_swaps

    def _counterfactual_text_profile(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        text_info = item.get("text_verifier", {}) or {}
        if not isinstance(text_info, Mapping):
            text_info = {}
        answer_profile = item.get("answer_pairwise_verifier", {}) or {}
        if not isinstance(answer_profile, Mapping):
            answer_profile = self._answer_pairwise_profile(item, query_plan_log)
        join_info = item.get("evidence_join_planner", {}) or {}
        if not isinstance(join_info, Mapping):
            join_info = self._evidence_join_profile(item, query_plan_log)
        path_info = item.get("path_aware", {}) or {}
        if not isinstance(path_info, Mapping):
            path_info = {}
        source_policy = item.get("source_policy", {}) or {}
        if not isinstance(source_policy, Mapping):
            source_policy = {}

        text_score = self._safe_float(text_info.get("score"), 0.0)
        anchor_hits = self._safe_int(text_info.get("anchor_hits"), 0)
        terminal_hits = self._safe_int(text_info.get("terminal_hits"), 0)
        relation_hits = len(text_info.get("relation_overlap", []) or [])
        query_hits = len(text_info.get("query_overlap", []) or [])
        answer_hits = len(text_info.get("answer_overlap", []) or [])
        answer_signal = (
            bool(answer_profile.get("answer_signal", False))
            or answer_hits > 0
            or terminal_hits > 0
            or (anchor_hits > 0 and terminal_hits > 0)
            or text_score >= 0.48
        )
        path_score = self._safe_float(path_info.get("score"), 0.0) if bool(path_info.get("approved")) else 0.0
        source_precision = max(
            self._safe_float(answer_profile.get("source_precision"), 0.0),
            self._safe_float(source_policy.get("selected_precision"), 0.0),
            self._safe_float(source_policy.get("precision"), 0.0),
            self._safe_float(join_info.get("source_precision"), 0.0),
        )
        source_precision = min(max(float(source_precision), 0.0), 1.0)
        join_score = max(
            self._safe_float(join_info.get("score"), 0.0),
            self._safe_float(answer_profile.get("join_score"), 0.0),
        )
        query_slot_value = self._safe_float(join_info.get("query_slot_value"), 0.0)
        slot_value = self._safe_float(join_info.get("slot_value"), 0.0)
        confidence = self._safe_float(item.get("confidence"), 0.0)
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        rank_cost = min(float(original_rank) / float(max(self.candidate_pool_top_k, 1)), 1.0)
        structural = (
            bool(item.get("has_strict"))
            or bool(item.get("has_multihop"))
            or bool(item.get("has_terminal") and item.get("has_relation"))
            or bool(answer_profile.get("structural", False))
            or bool(join_info.get("structural", False))
        )
        relation_only = bool(answer_profile.get("relation_only", False)) or bool(join_info.get("relation_only", False))
        endpoint_signal = 1.0 if anchor_hits > 0 and terminal_hits > 0 else 0.0
        relation_signal = min((float(relation_hits) + 0.5 * float(query_hits)) / 4.0, 1.0)
        answer_term_signal = min(float(answer_hits + terminal_hits) / 2.0, 1.0)
        query_slot_signal = min(query_slot_value / 0.8, 1.0)
        slot_signal = min(slot_value / 1.2, 1.0)

        score = (
            0.30 * min(text_score, 1.0)
            + 0.15 * answer_term_signal
            + 0.11 * endpoint_signal
            + 0.10 * relation_signal
            + 0.10 * min(join_score, 1.0)
            + 0.08 * source_precision
            + 0.07 * min(path_score, 1.0)
            + 0.06 * query_slot_signal
            + 0.04 * slot_signal
            + 0.05 * confidence
            + 0.06 * (1.0 if structural else 0.0)
            - 0.07 * rank_cost
        )
        if relation_only:
            score -= 0.14
        if self.counterfactual_text_verifier_require_answer_signal and not (
            answer_signal or path_score >= 0.55 or (structural and text_score >= 0.34)
        ):
            score -= 0.10
        score = min(max(float(score), 0.0), 1.0)
        return {
            "enabled": self.enable_counterfactual_text_verifier,
            "score": round(float(score), 6),
            "text_score": round(float(text_score), 6),
            "answer_pairwise_score": round(self._safe_float(answer_profile.get("score"), 0.0), 6),
            "join_score": round(float(join_score), 6),
            "path_score": round(float(path_score), 6),
            "source_precision": round(float(source_precision), 6),
            "query_slot_value": round(float(query_slot_value), 6),
            "slot_value": round(float(slot_value), 6),
            "anchor_hits": int(anchor_hits),
            "terminal_hits": int(terminal_hits),
            "relation_hits": int(relation_hits),
            "query_hits": int(query_hits),
            "answer_hits": int(answer_hits),
            "answer_signal": bool(answer_signal),
            "endpoint_signal": bool(endpoint_signal > 0.0),
            "structural": bool(structural),
            "relation_only": bool(relation_only),
            "confidence": round(float(confidence), 6),
            "rank_cost": round(float(rank_cost), 6),
        }

    def _apply_counterfactual_text_profile(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> str:
        if not self.enable_counterfactual_text_verifier:
            item["counterfactual_text_verifier"] = {
                "enabled": False,
                "score": 0.0,
                "reason": "disabled",
            }
            return "disabled"
        profile = self._counterfactual_text_profile(item, query_plan_log)
        item["counterfactual_text_verifier"] = profile
        score = self._safe_float(profile.get("score"), 0.0)
        text_score = self._safe_float(profile.get("text_score"), 0.0)
        if score >= self.counterfactual_text_verifier_min_score and (
            text_score >= self.counterfactual_text_verifier_min_candidate_text_score
            or bool(profile.get("answer_signal", False))
            or self._safe_float(profile.get("path_score"), 0.0) >= 0.55
        ):
            item["_counterfactual_text_candidate"] = True
            item["score"] = (
                self._safe_float(item.get("score"), 0.0)
                + self.counterfactual_text_verifier_score_weight * score
            )
            return "candidate"
        return "low_score"

    def _counterfactual_text_replacement_profile(
        self,
        doc_id: int,
        original_rank: int,
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        replacement_item = self._answer_pairwise_doc_item(
            doc_id,
            original_rank,
            passage_details,
            max_raw_score,
            query_plan_log,
        )
        return self._counterfactual_text_profile(replacement_item, query_plan_log)

    def _passes_counterfactual_text_verifier(
        self,
        item: Mapping[str, Any],
        selected: Sequence[int],
        selected_set: Set[int],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        query_plan_log: Mapping[str, Any],
        target_top2: bool = False,
    ) -> Tuple[bool, str, Dict[str, Any]]:
        if not self.enable_counterfactual_text_verifier:
            return False, "counterfactual_text_disabled", {}
        candidate_doc = int(item.get("passage_idx", -1))
        if candidate_doc < 0:
            return False, "counterfactual_text_invalid_doc", {}
        if candidate_doc in selected_set:
            return False, "counterfactual_text_already_selected", {}
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        if (
            self.counterfactual_text_verifier_max_original_rank > 0
            and original_rank > self.counterfactual_text_verifier_max_original_rank
        ):
            return False, "counterfactual_text_rank_too_low", {
                "original_rank": int(original_rank),
                "max_original_rank": int(self.counterfactual_text_verifier_max_original_rank),
            }

        profile = item.get("counterfactual_text_verifier", {}) or {}
        if not isinstance(profile, Mapping):
            profile = self._counterfactual_text_profile(item, query_plan_log)
        score = self._safe_float(profile.get("score"), 0.0)
        min_score = (
            self.counterfactual_text_verifier_top2_min_score
            if target_top2
            else self.counterfactual_text_verifier_min_score
        )
        if score < min_score:
            return False, "counterfactual_text_low_score", {
                "score": round(float(score), 6),
                "min_score": round(float(min_score), 6),
            }
        text_score = self._safe_float(profile.get("text_score"), 0.0)
        if text_score < self.counterfactual_text_verifier_min_candidate_text_score and not (
            bool(profile.get("answer_signal", False))
            or self._safe_float(profile.get("path_score"), 0.0) >= 0.55
        ):
            return False, "counterfactual_text_weak_candidate_text", dict(profile)
        if self.counterfactual_text_verifier_require_answer_signal and not (
            bool(profile.get("answer_signal", False))
            or self._safe_float(profile.get("path_score"), 0.0) >= 0.55
            or (
                bool(profile.get("structural", False))
                and self._safe_float(profile.get("text_score"), 0.0) >= 0.42
            )
        ):
            return False, "counterfactual_text_no_answer_signal", dict(profile)
        if bool(profile.get("relation_only", False)):
            return False, "counterfactual_text_relation_only", dict(profile)

        top_without_candidate: List[int] = [int(doc_id) for doc_id in selected[: self.final_top_k]]
        top_without_set = set(top_without_candidate)
        for doc_id in base_doc_ids:
            doc_id = int(doc_id)
            if doc_id in top_without_set:
                continue
            top_without_candidate.append(doc_id)
            top_without_set.add(doc_id)
            if len(top_without_candidate) >= self.final_top_k:
                break
        if len(top_without_candidate) < self.final_top_k:
            return False, "counterfactual_text_short_window", {
                "top_without_candidate": top_without_candidate,
            }

        replacement_indices = [1] if target_top2 else list(range(2, min(self.final_top_k, len(top_without_candidate))))
        replacement_rows = []
        for index in replacement_indices:
            doc_id = int(top_without_candidate[index])
            replacement_rank = int(original_rank_by_doc.get(doc_id, index + 1))
            replacement_profile = self._counterfactual_text_replacement_profile(
                doc_id,
                replacement_rank,
                passage_details,
                max_raw_score,
                query_plan_log,
            )
            replacement_score = self._safe_float(replacement_profile.get("score"), 0.0)
            replacement_text_score = self._safe_float(replacement_profile.get("text_score"), 0.0)
            replacement_prior = self._baseline_replacement_value(
                doc_id,
                replacement_rank,
                passage_details,
                max_raw_score,
            )
            replacement_utility = min(
                1.25,
                0.76 * replacement_score
                + 0.14 * replacement_text_score
                + 0.10 * replacement_prior,
            )
            replacement_rows.append((
                replacement_utility,
                index,
                doc_id,
                replacement_rank,
                replacement_score,
                replacement_profile,
            ))
        if not replacement_rows:
            return False, "counterfactual_text_no_replaceable_slot", {}
        replacement_utility, replacement_index, replacement_doc, replacement_rank, replacement_score, replacement_profile = min(
            replacement_rows,
            key=lambda row: (row[0], -row[1]),
        )

        candidate_utility = min(
            1.30,
            0.78 * score
            + 0.12 * text_score
            + 0.06 * self._safe_float(profile.get("source_precision"), 0.0)
            + 0.04 * self._candidate_evidence_value(item),
        )
        margin = candidate_utility - replacement_utility
        text_margin = text_score - self._safe_float(replacement_profile.get("text_score"), 0.0)
        required_margin = (
            self.counterfactual_text_verifier_top2_min_margin
            if target_top2
            else self.counterfactual_text_verifier_min_margin
        )
        if target_top2 and text_score < 0.46:
            required_margin += 0.025
        if not bool(profile.get("answer_signal", False)):
            required_margin += 0.025
        if text_margin < -0.08 and self._safe_float(profile.get("path_score"), 0.0) < 0.65:
            required_margin += 0.04

        approved = margin >= required_margin
        return approved, "counterfactual_text_gain" if approved else "counterfactual_text_low_margin", {
            "score": round(float(score), 6),
            "min_score": round(float(min_score), 6),
            "candidate_utility": round(float(candidate_utility), 6),
            "replacement_doc": int(replacement_doc),
            "replacement_index": int(replacement_index),
            "replacement_rank": int(replacement_rank),
            "replacement_score": round(float(replacement_score), 6),
            "replacement_utility": round(float(replacement_utility), 6),
            "replacement_profile": replacement_profile,
            "margin": round(float(margin), 6),
            "required_margin": round(float(required_margin), 6),
            "text_margin": round(float(text_margin), 6),
            "target_top2": bool(target_top2),
            "candidate_profile": profile,
            "top_without_candidate": top_without_candidate[: self.final_top_k],
        }

    def _apply_counterfactual_text_verifier(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        rejections: Counter,
        rejected_candidates: List[Dict[str, Any]],
        selected_candidates: List[Dict[str, Any]],
    ) -> Tuple[int, int]:
        if not self.enable_counterfactual_text_verifier:
            return 0, 0
        for doc_id in base_doc_ids:
            if len(selected) >= self.final_top_k:
                break
            doc_id = int(doc_id)
            if doc_id in selected_set:
                continue
            selected.append(doc_id)
            selected_set.add(doc_id)

        def _score(target_top2: bool) -> List[Tuple[float, float, int, Dict[str, Any], Dict[str, Any]]]:
            scored: List[Tuple[float, float, int, Dict[str, Any], Dict[str, Any]]] = []
            for item in candidates:
                candidate_doc = int(item.get("passage_idx", -1))
                if candidate_doc < 0 or candidate_doc in selected_set:
                    continue
                approved, reason, features = self._passes_counterfactual_text_verifier(
                    item=item,
                    selected=selected,
                    selected_set=selected_set,
                    base_doc_ids=base_doc_ids,
                    original_rank_by_doc=original_rank_by_doc,
                    passage_details=passage_details,
                    max_raw_score=max_raw_score,
                    query_plan_log=query_plan_log,
                    target_top2=target_top2,
                )
                item["counterfactual_text_gate"] = {
                    "approved": bool(approved),
                    "reason": reason,
                    "features": features,
                }
                if approved:
                    scored.append((
                        self._safe_float(features.get("margin"), 0.0),
                        self._safe_float(features.get("score"), 0.0),
                        -self._safe_int(item.get("original_rank"), 10**9),
                        item,
                        features,
                    ))
                else:
                    rejections[reason] += 1
                    if len(rejected_candidates) < 12 and reason not in {
                        "counterfactual_text_low_score",
                        "counterfactual_text_rank_too_low",
                        "counterfactual_text_already_selected",
                    }:
                        rejected_candidates.append(
                            self._decision_for_log(
                                item,
                                selected=False,
                                reason=f"counterfactual_text_rejected:{reason}",
                            )
                        )
            scored.sort(key=lambda row: (row[0], row[1], row[2]), reverse=True)
            return scored

        top2_swaps = 0
        if self.counterfactual_text_verifier_max_top2_swaps > 0 and len(selected) >= 2:
            for _, _, _, item, features in _score(target_top2=True):
                if top2_swaps >= self.counterfactual_text_verifier_max_top2_swaps:
                    break
                candidate_doc = int(item.get("passage_idx", -1))
                if candidate_doc < 0 or candidate_doc in selected_set:
                    continue
                replacement_index = self._safe_int(features.get("replacement_index"), 1)
                if replacement_index != 1:
                    rejections["counterfactual_text_bad_top2_replacement"] += 1
                    continue
                replaced_doc = int(selected[replacement_index])
                selected[replacement_index] = candidate_doc
                selected_set.discard(replaced_doc)
                selected_set.add(candidate_doc)
                item["_counterfactual_text_top2_selected"] = True
                item["_counterfactual_text_replaced_doc"] = replaced_doc
                if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                    selected_ontology.append(item)
                top2_swaps += 1
                if len(selected_candidates) < 12:
                    selected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=True,
                            reason="counterfactual_text_top2_selected",
                            final_rank=2,
                        )
                    )

        top5_swaps = 0
        if self.counterfactual_text_verifier_max_top5_swaps <= 0 or len(selected) < self.final_top_k:
            return top2_swaps, top5_swaps
        for _, _, _, item, features in _score(target_top2=False):
            if top5_swaps >= self.counterfactual_text_verifier_max_top5_swaps:
                break
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0 or candidate_doc in selected_set:
                continue
            replacement_index = self._safe_int(features.get("replacement_index"), self.final_top_k - 1)
            if replacement_index < 2 or replacement_index >= min(self.final_top_k, len(selected)):
                rejections["counterfactual_text_bad_top5_replacement"] += 1
                continue
            replaced_doc = int(selected[replacement_index])
            selected[replacement_index] = candidate_doc
            selected_set.discard(replaced_doc)
            selected_set.add(candidate_doc)
            item["_counterfactual_text_top5_selected"] = True
            item["_counterfactual_text_replaced_doc"] = replaced_doc
            if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                selected_ontology.append(item)
            top5_swaps += 1
            if len(selected_candidates) < 12:
                selected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason="counterfactual_text_top5_selected",
                        final_rank=int(replacement_index + 1),
                    )
                )
        return top2_swaps, top5_swaps

    def _gold_aware_text_config(self) -> Dict[str, Any]:
        if self.utility_planner.is_ready():
            config = self.utility_planner.model.get("gold_aware_text_top5_planner", {}) or {}
            if isinstance(config, Mapping):
                return dict(config)
        return {}

    def _gold_aware_text_heuristic_score(self, profile: Mapping[str, Any]) -> float:
        text_score = self._safe_float(profile.get("text_score"), 0.0)
        source_precision = self._safe_float(profile.get("source_precision"), 0.0)
        relation_hits = self._safe_float(profile.get("relation_hits"), 0.0)
        query_hits = self._safe_float(profile.get("query_hits"), 0.0)
        terminal_hits = self._safe_float(profile.get("terminal_hits"), 0.0)
        answer_hits = self._safe_float(profile.get("answer_hits"), 0.0)
        confidence = self._safe_float(profile.get("confidence"), 0.0)
        path_score = self._safe_float(profile.get("path_score"), 0.0)
        join_score = self._safe_float(profile.get("join_score"), 0.0)
        query_slot_value = self._safe_float(profile.get("query_slot_value"), 0.0)
        slot_value = self._safe_float(profile.get("slot_value"), 0.0)
        anchor_hits = self._safe_float(profile.get("anchor_hits"), 0.0)
        rank_cost = self._safe_float(profile.get("rank_cost"), 0.0)
        relation_signal = min((relation_hits + 0.5 * query_hits) / 4.0, 1.0)
        terminal_signal = min((terminal_hits + answer_hits) / 2.0, 1.0)
        anchor_pressure = min(anchor_hits / 2.0, 1.0)
        slot_pressure = min((query_slot_value + slot_value) / 3.2, 1.0)
        score = (
            0.20 * source_precision
            + 0.18 * relation_signal
            + 0.16 * terminal_signal
            + 0.13 * confidence
            + 0.12 * min(text_score, 1.0)
            + 0.08 * min(path_score, 1.0)
            + 0.05 * (1.0 if bool(profile.get("structural", False)) else 0.0)
            + 0.04 * (1.0 if bool(profile.get("answer_signal", False)) else 0.0)
            - 0.09 * min(join_score, 1.0)
            - 0.06 * slot_pressure
            - 0.05 * anchor_pressure
            - 0.06 * rank_cost
        )
        if bool(profile.get("relation_only", False)):
            score -= 0.16
        if terminal_signal <= 0.0 and relation_signal < 0.35 and path_score < 0.55:
            score -= 0.08
        return min(max(float(score), 0.0), 1.0)

    def _gold_aware_text_utility_profile(
        self,
        item: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        profile = item.get("counterfactual_text_verifier", {}) or {}
        if not isinstance(profile, Mapping) or not profile:
            profile = self._counterfactual_text_profile(item, query_plan_log)
        heuristic_score = self._gold_aware_text_heuristic_score(profile)
        model_ready = self.utility_planner.is_ready()
        model_score = heuristic_score
        model_snapshot: Dict[str, Any] = {}
        if model_ready:
            planner_score = self.utility_planner.score(query_plan_log, item)
            model_score = self._safe_float(planner_score.get("score"), heuristic_score)
            model_snapshot = dict(planner_score.get("feature_snapshot", {}) or {})
        config = self._gold_aware_text_config()
        model_weight = self._safe_float(config.get("model_weight"), 0.62 if model_ready else 0.0)
        model_weight = min(max(model_weight, 0.0), 1.0)
        score = model_weight * model_score + (1.0 - model_weight) * heuristic_score
        score = min(max(float(score), 0.0), 1.0)
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        max_original_rank = int(config.get("max_original_rank", self.utility_planner_max_original_rank) or 0)
        rank_ok = max_original_rank <= 0 or original_rank <= max_original_rank
        min_source_precision = self._safe_float(config.get("min_source_precision"), 0.16)
        source_precision = self._safe_float(profile.get("source_precision"), 0.0)
        relation_hits = self._safe_int(profile.get("relation_hits"), 0)
        query_hits = self._safe_int(profile.get("query_hits"), 0)
        terminal_hits = self._safe_int(profile.get("terminal_hits"), 0)
        answer_hits = self._safe_int(profile.get("answer_hits"), 0)
        path_score = self._safe_float(profile.get("path_score"), 0.0)
        confidence = self._safe_float(
            profile.get("confidence"),
            self._safe_float(item.get("confidence"), 0.0),
        )
        evidence_signal = (
            terminal_hits > 0
            or answer_hits > 0
            or relation_hits >= 2
            or (relation_hits >= 1 and query_hits >= 1)
            or path_score >= 0.55
        )
        min_heuristic = self._safe_float(config.get("min_heuristic_score"), 0.34)
        relation_only = bool(profile.get("relation_only", False))
        hard_safe_candidate = bool(
            rank_ok
            and source_precision >= min_source_precision
            and heuristic_score >= min_heuristic
            and evidence_signal
            and not relation_only
        )
        soft_safe_min_model_score = self._safe_float(
            config.get("soft_safe_min_model_score"),
            0.68,
        )
        soft_safe_min_source_precision = self._safe_float(
            config.get("soft_safe_min_source_precision"),
            0.42,
        )
        soft_safe_min_confidence = self._safe_float(
            config.get("soft_safe_min_confidence"),
            0.86,
        )
        relation_only_min_model_score = self._safe_float(
            config.get("relation_only_min_model_score"),
            0.74,
        )
        allow_relation_only_high_model = bool(config.get("allow_relation_only_high_model", False))
        soft_evidence_signal = bool(
            evidence_signal
            or (relation_hits >= 1 and query_hits >= 1)
            or (
                relation_hits >= 1
                and self._safe_float(profile.get("text_score"), 0.0) >= 0.36
                and confidence >= soft_safe_min_confidence
            )
        )
        relation_only_ok = bool(
            not relation_only
            or (
                allow_relation_only_high_model
                and model_score >= relation_only_min_model_score
                and source_precision >= soft_safe_min_source_precision
            )
        )
        soft_safe_candidate = bool(
            rank_ok
            and model_score >= soft_safe_min_model_score
            and source_precision >= soft_safe_min_source_precision
            and confidence >= soft_safe_min_confidence
            and soft_evidence_signal
            and relation_only_ok
        )
        safe_candidate = bool(hard_safe_candidate or soft_safe_candidate)
        safe_reason = (
            "hard_evidence_signal"
            if hard_safe_candidate
            else ("soft_model_source" if soft_safe_candidate else "unsafe")
        )
        return {
            "enabled": True,
            "mode": self.utility_planner_mode,
            "model_ready": bool(model_ready),
            "score": round(float(score), 6),
            "score_for_sort": 0.0,
            "model_score": round(float(model_score), 6),
            "heuristic_score": round(float(heuristic_score), 6),
            "model_weight": round(float(model_weight), 6),
            "safe_candidate": bool(safe_candidate),
            "safe_reason": safe_reason,
            "hard_safe_candidate": bool(hard_safe_candidate),
            "soft_safe_candidate": bool(soft_safe_candidate),
            "rank_ok": bool(rank_ok),
            "evidence_signal": bool(evidence_signal),
            "soft_evidence_signal": bool(soft_evidence_signal),
            "relation_only_ok": bool(relation_only_ok),
            "source_precision": round(float(source_precision), 6),
            "confidence": round(float(confidence), 6),
            "min_source_precision": round(float(min_source_precision), 6),
            "min_heuristic_score": round(float(min_heuristic), 6),
            "soft_safe_min_model_score": round(float(soft_safe_min_model_score), 6),
            "soft_safe_min_source_precision": round(float(soft_safe_min_source_precision), 6),
            "soft_safe_min_confidence": round(float(soft_safe_min_confidence), 6),
            "feature_snapshot": model_snapshot,
        }

    def _apply_gold_aware_text_utility_score(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> str:
        if self.utility_planner_mode != "gold_aware_text_top5_planner":
            return "disabled"
        planner = self._gold_aware_text_utility_profile(item, query_plan_log)
        item["utility_planner"] = planner
        score = self._safe_float(planner.get("score"), 0.0)
        if not bool(planner.get("safe_candidate", False)):
            return "gold_aware_text_unsafe"
        if score < self.utility_planner_min_score:
            return "gold_aware_text_low_score"
        item["_utility_planner_gold_aware_text_candidate"] = True
        return "gold_aware_text_candidate"

    def _gold_aware_text_replacement_profile(
        self,
        doc_id: int,
        original_rank: int,
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        replacement_item = self._answer_pairwise_doc_item(
            doc_id,
            original_rank,
            passage_details,
            max_raw_score,
            query_plan_log,
        )
        replacement_item["counterfactual_text_verifier"] = self._counterfactual_text_profile(
            replacement_item,
            query_plan_log,
        )
        return self._gold_aware_text_utility_profile(replacement_item, query_plan_log)

    def _passes_gold_aware_text_top5_planner(
        self,
        item: Mapping[str, Any],
        selected: Sequence[int],
        selected_set: Set[int],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        query_plan_log: Mapping[str, Any],
        target_top2: bool = False,
    ) -> Tuple[bool, str, Dict[str, Any]]:
        if self.utility_planner_mode != "gold_aware_text_top5_planner":
            return False, "gold_aware_text_disabled", {}
        candidate_doc = int(item.get("passage_idx", -1))
        if candidate_doc < 0:
            return False, "gold_aware_text_invalid_doc", {}
        if candidate_doc in selected_set:
            return False, "gold_aware_text_already_selected", {}
        planner = item.get("utility_planner", {}) or {}
        if not isinstance(planner, Mapping):
            planner = self._gold_aware_text_utility_profile(item, query_plan_log)
        if not bool(planner.get("safe_candidate", False)):
            return False, "gold_aware_text_unsafe", dict(planner)
        score = self._safe_float(planner.get("score"), 0.0)
        config = self._gold_aware_text_config()
        min_score = (
            self._safe_float(config.get("top2_min_score"), self.utility_planner_top2_min_score)
            if target_top2
            else self._safe_float(config.get("min_score"), self.utility_planner_min_score)
        )
        if score < min_score:
            return False, "gold_aware_text_low_score", {
                "score": round(float(score), 6),
                "min_score": round(float(min_score), 6),
            }

        top_without_candidate: List[int] = [int(doc_id) for doc_id in selected[: self.final_top_k]]
        top_without_set = set(top_without_candidate)
        for doc_id in base_doc_ids:
            doc_id = int(doc_id)
            if doc_id in top_without_set:
                continue
            top_without_candidate.append(doc_id)
            top_without_set.add(doc_id)
            if len(top_without_candidate) >= self.final_top_k:
                break
        if len(top_without_candidate) < self.final_top_k:
            return False, "gold_aware_text_short_window", {}

        replacement_indices = [1] if target_top2 else list(range(2, min(self.final_top_k, len(top_without_candidate))))
        replacement_rows = []
        for index in replacement_indices:
            doc_id = int(top_without_candidate[index])
            replacement_rank = int(original_rank_by_doc.get(doc_id, index + 1))
            replacement_profile = self._gold_aware_text_replacement_profile(
                doc_id,
                replacement_rank,
                passage_details,
                max_raw_score,
                query_plan_log,
            )
            replacement_score = self._safe_float(replacement_profile.get("score"), 0.0)
            replacement_prior = self._baseline_replacement_value(
                doc_id,
                replacement_rank,
                passage_details,
                max_raw_score,
            )
            replacement_utility = min(
                1.25,
                0.78 * replacement_score + 0.22 * replacement_prior,
            )
            replacement_rows.append((
                replacement_utility,
                index,
                doc_id,
                replacement_rank,
                replacement_score,
                replacement_profile,
            ))
        if not replacement_rows:
            return False, "gold_aware_text_no_replaceable_slot", {}
        replacement_utility, replacement_index, replacement_doc, replacement_rank, replacement_score, replacement_profile = min(
            replacement_rows,
            key=lambda row: (row[0], -row[1]),
        )
        candidate_utility = min(
            1.30,
            0.84 * score
            + 0.10 * self._safe_float(planner.get("heuristic_score"), 0.0)
            + 0.06 * self._candidate_evidence_value(item),
        )
        margin = candidate_utility - replacement_utility
        required_margin = (
            self._safe_float(config.get("top2_min_margin"), self.utility_planner_top2_min_value_margin)
            if target_top2
            else self._safe_float(config.get("min_margin"), self.utility_planner_min_value_margin)
        )
        if target_top2:
            top2_min_heuristic = self._safe_float(config.get("top2_min_heuristic_score"), 0.44)
            top2_min_model_override = self._safe_float(
                config.get("top2_min_model_score_override"),
                0.78,
            )
            if (
                self._safe_float(planner.get("heuristic_score"), 0.0) < top2_min_heuristic
                and self._safe_float(planner.get("model_score"), 0.0) < top2_min_model_override
            ):
                return False, "gold_aware_text_low_top2_heuristic", {
                    **dict(planner),
                    "top2_min_model_score_override": round(float(top2_min_model_override), 6),
                }
        approved = margin >= required_margin
        return approved, "gold_aware_text_gain" if approved else "gold_aware_text_low_margin", {
            "score": round(float(score), 6),
            "min_score": round(float(min_score), 6),
            "candidate_utility": round(float(candidate_utility), 6),
            "replacement_doc": int(replacement_doc),
            "replacement_index": int(replacement_index),
            "replacement_rank": int(replacement_rank),
            "replacement_score": round(float(replacement_score), 6),
            "replacement_utility": round(float(replacement_utility), 6),
            "replacement_profile": replacement_profile,
            "margin": round(float(margin), 6),
            "required_margin": round(float(required_margin), 6),
            "target_top2": bool(target_top2),
            "candidate_profile": dict(planner),
            "top_without_candidate": top_without_candidate[: self.final_top_k],
        }

    def _apply_gold_aware_text_top5_planner(
        self,
        selected: List[int],
        selected_set: Set[int],
        candidates: Sequence[Dict[str, Any]],
        selected_ontology: List[Dict[str, Any]],
        query_plan_log: Mapping[str, Any],
        base_doc_ids: Sequence[int],
        original_rank_by_doc: Mapping[int, int],
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        rejections: Counter,
        rejected_candidates: List[Dict[str, Any]],
        selected_candidates: List[Dict[str, Any]],
    ) -> Tuple[int, int]:
        if self.utility_planner_mode != "gold_aware_text_top5_planner":
            return 0, 0
        config = self._gold_aware_text_config()
        max_top2_swaps = max(int(config.get("max_top2_swaps", 1) or 0), 0)
        max_top5_swaps = max(int(config.get("max_top5_swaps", 1) or 0), 0)

        def _score(target_top2: bool) -> List[Tuple[float, float, int, Dict[str, Any], Dict[str, Any]]]:
            scored: List[Tuple[float, float, int, Dict[str, Any], Dict[str, Any]]] = []
            for item in candidates:
                candidate_doc = int(item.get("passage_idx", -1))
                if candidate_doc < 0 or candidate_doc in selected_set:
                    continue
                approved, reason, features = self._passes_gold_aware_text_top5_planner(
                    item=item,
                    selected=selected,
                    selected_set=selected_set,
                    base_doc_ids=base_doc_ids,
                    original_rank_by_doc=original_rank_by_doc,
                    passage_details=passage_details,
                    max_raw_score=max_raw_score,
                    query_plan_log=query_plan_log,
                    target_top2=target_top2,
                )
                item["utility_planner_gold_aware_text_gate"] = {
                    "approved": bool(approved),
                    "reason": reason,
                    "features": features,
                }
                if approved:
                    scored.append((
                        self._safe_float(features.get("margin"), 0.0),
                        self._safe_float(features.get("score"), 0.0),
                        -self._safe_int(item.get("original_rank"), 10**9),
                        item,
                        features,
                    ))
                else:
                    rejections[reason] += 1
                    if len(rejected_candidates) < 12 and reason not in {
                        "gold_aware_text_low_score",
                        "gold_aware_text_already_selected",
                    }:
                        rejected_candidates.append(
                            self._decision_for_log(
                                item,
                                selected=False,
                                reason=f"utility_planner_rejected:{reason}",
                            )
                        )
            scored.sort(key=lambda row: (row[0], row[1], row[2]), reverse=True)
            return scored

        top2_swaps = 0
        if max_top2_swaps > 0 and len(selected) >= 2:
            for _, _, _, item, features in _score(target_top2=True):
                if top2_swaps >= max_top2_swaps:
                    break
                candidate_doc = int(item.get("passage_idx", -1))
                if candidate_doc < 0 or candidate_doc in selected_set:
                    continue
                replacement_index = self._safe_int(features.get("replacement_index"), 1)
                if replacement_index != 1:
                    rejections["gold_aware_text_bad_top2_replacement"] += 1
                    continue
                replaced_doc = int(selected[replacement_index])
                selected[replacement_index] = candidate_doc
                selected_set.discard(replaced_doc)
                selected_set.add(candidate_doc)
                item["_utility_planner_selected"] = True
                item["_utility_planner_gold_aware_text_top2_selected"] = True
                item["_utility_planner_replaced_doc"] = replaced_doc
                if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                    selected_ontology.append(item)
                top2_swaps += 1
                if len(selected_candidates) < 12:
                    selected_candidates.append(
                        self._decision_for_log(
                            item,
                            selected=True,
                            reason="utility_planner_gold_aware_text_top2_selected",
                            final_rank=2,
                        )
                    )

        top5_swaps = 0
        if max_top5_swaps <= 0 or len(selected) < self.final_top_k:
            return top2_swaps, top5_swaps
        for _, _, _, item, features in _score(target_top2=False):
            if top5_swaps >= max_top5_swaps:
                break
            candidate_doc = int(item.get("passage_idx", -1))
            if candidate_doc < 0 or candidate_doc in selected_set:
                continue
            replacement_index = self._safe_int(features.get("replacement_index"), self.final_top_k - 1)
            if replacement_index < 2 or replacement_index >= min(self.final_top_k, len(selected)):
                rejections["gold_aware_text_bad_top5_replacement"] += 1
                continue
            replaced_doc = int(selected[replacement_index])
            selected[replacement_index] = candidate_doc
            selected_set.discard(replaced_doc)
            selected_set.add(candidate_doc)
            item["_utility_planner_selected"] = True
            item["_utility_planner_gold_aware_text_top5_selected"] = True
            item["_utility_planner_replaced_doc"] = replaced_doc
            if not any(int(prev.get("passage_idx", -1)) == candidate_doc for prev in selected_ontology):
                selected_ontology.append(item)
            top5_swaps += 1
            if len(selected_candidates) < 12:
                selected_candidates.append(
                    self._decision_for_log(
                        item,
                        selected=True,
                        reason="utility_planner_gold_aware_text_top5_selected",
                        final_rank=int(replacement_index + 1),
                    )
                )
        return top2_swaps, top5_swaps

    def _gap_aware_topk_config(self) -> Dict[str, Any]:
        if not self.utility_planner.is_ready():
            return {}
        if self.utility_planner_mode == "set_counterfactual_recall_planner":
            config_key = "set_counterfactual_recall_planner"
        elif self.utility_planner_mode == "metric_aligned_action_risk_planner":
            config_key = "metric_aligned_action_risk_planner"
        elif self.utility_planner_mode == "counterfactual_topk_benefit_planner":
            config_key = "counterfactual_topk_benefit_planner"
        elif self.utility_planner_mode == "oracle_delta_recall_planner":
            config_key = "oracle_delta_recall_planner"
        else:
            config_key = "gap_aware_topk_planner"
        config = self.utility_planner.model.get(config_key, {}) or {}
        if (
            self.utility_planner_mode in {
                "counterfactual_topk_benefit_planner",
                "metric_aligned_action_risk_planner",
                "set_counterfactual_recall_planner",
            }
            and not isinstance(config, Mapping)
        ):
            config = {}
        if (
            self.utility_planner_mode in {
                "counterfactual_topk_benefit_planner",
                "metric_aligned_action_risk_planner",
                "set_counterfactual_recall_planner",
            }
            and not config
            and self.utility_planner_mode == "set_counterfactual_recall_planner"
        ):
            config = self.utility_planner.model.get("metric_aligned_action_risk_planner", {}) or {}
        if (
            self.utility_planner_mode in {
                "counterfactual_topk_benefit_planner",
                "metric_aligned_action_risk_planner",
                "set_counterfactual_recall_planner",
            }
            and not config
        ):
            config = self.utility_planner.model.get("counterfactual_topk_benefit_planner", {}) or {}
        if (
            self.utility_planner_mode in {
                "counterfactual_topk_benefit_planner",
                "metric_aligned_action_risk_planner",
                "set_counterfactual_recall_planner",
            }
            and not config
        ):
            config = self.utility_planner.model.get("oracle_delta_recall_planner", {}) or {}
        return config if isinstance(config, dict) else {}

    def _gap_aware_source_priors(
        self,
        item: Mapping[str, Any],
        source_signature: str,
        query_plan_log: Mapping[str, Any],
    ) -> Tuple[float, float, int, float, Dict[str, Any], Dict[str, Any]]:
        config = self._gap_aware_topk_config()
        source_stats = config.get("source_stats", {}) or {}
        dataset_source_stats = config.get("dataset_source_stats", {}) or {}
        dataset = str(query_plan_log.get("dataset") or "").strip()
        source_record: Dict[str, Any] = {}
        dataset_source_record: Dict[str, Any] = {}
        source_prior = self._groupwise_source_prior(item, source_signature)
        dataset_source_prior = -1.0
        dataset_source_count = 0
        false_positive_rate = 0.0
        if isinstance(source_stats, Mapping):
            stats = source_stats.get(source_signature, {}) or {}
            if isinstance(stats, Mapping):
                source_record = dict(stats)
                source_prior = self._safe_float(stats.get("precision"), source_prior)
                false_positive_rate = max(
                    false_positive_rate,
                    self._safe_float(stats.get("selected_false_positive_rate"), 0.0),
                )
        if dataset and isinstance(dataset_source_stats, Mapping):
            stats = dataset_source_stats.get(f"{dataset}::{source_signature}", {}) or {}
            if isinstance(stats, Mapping):
                dataset_source_record = dict(stats)
                dataset_source_prior = self._safe_float(stats.get("precision"), -1.0)
                dataset_source_count = self._safe_int(stats.get("count"), 0)
                false_positive_rate = max(
                    false_positive_rate,
                    self._safe_float(stats.get("selected_false_positive_rate"), 0.0),
                )
        return (
            min(max(source_prior, 0.0), 1.0),
            dataset_source_prior if dataset_source_prior >= 0.0 else -1.0,
            int(dataset_source_count),
            min(max(false_positive_rate, 0.0), 1.0),
            source_record,
            dataset_source_record,
        )

    def _gap_aware_model_profile(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        if not self.utility_planner.is_ready():
            return {
                "enabled": False,
                "mode": self.utility_planner_mode,
                "model_ready": False,
                "score": 0.0,
            }
        if not isinstance(item.get("counterfactual_text_verifier"), Mapping):
            item["counterfactual_text_verifier"] = self._counterfactual_text_profile(item, query_plan_log)
        planner = self.utility_planner.score(query_plan_log, item)
        score = self._safe_float(planner.get("score"), 0.0)
        planner.update({
            "enabled": True,
            "mode": self.utility_planner_mode,
            "model_ready": True,
            "score": round(float(score), 6),
            "score_for_sort": 0.0,
            "deferred": False,
        })
        return planner

    def _apply_gap_aware_utility_score(
        self,
        item: Dict[str, Any],
        query_plan_log: Mapping[str, Any],
    ) -> str:
        if self.utility_planner_mode not in {
            "gap_aware_topk_planner",
            "oracle_delta_recall_planner",
            "counterfactual_topk_benefit_planner",
            "metric_aligned_action_risk_planner",
            "set_counterfactual_recall_planner",
        }:
            return "disabled"
        planner = self._gap_aware_model_profile(item, query_plan_log)
        item["utility_planner"] = planner
        config = self._gap_aware_topk_config()
        score = self._safe_float(planner.get("score"), 0.0)
        min_score = self._safe_float(config.get("min_score"), self.utility_planner_min_score)
        benefit_score, benefit_detail = self._benefit_planner_score(
            item,
            query_plan_log,
            target_top2=False,
        )
        benefit_ready = bool(benefit_detail.get("ready", False))
        if benefit_ready:
            item["benefit_planner"] = benefit_detail
            benefit_root = self._benefit_planner_root_config()
            use_benefit_gate = bool(benefit_root.get("use_benefit_gate", True))
            action_selectivity_bypass = bool(
                (
                    self._action_selectivity_gate_ready(False)
                    or self._action_selectivity_gate_ready(True)
                )
                and (
                    self._action_selectivity_gate_config(False).get("bypass_benefit_gate")
                    or self._action_selectivity_gate_config(True).get("bypass_benefit_gate")
                )
            )
            benefit_min_score = self._safe_float(
                benefit_detail.get("min_score"),
                min_score,
            )
            legacy_fallback_min_score = self._safe_float(
                benefit_root.get("legacy_fallback_min_score"),
                max(min_score, self.utility_planner_min_score),
            )
            if (
                use_benefit_gate
                and not action_selectivity_bypass
                and benefit_score < benefit_min_score
                and score < legacy_fallback_min_score
            ):
                item["benefit_planner_gate"] = {
                    "approved": False,
                    "reason": "gap_aware_benefit_low_score",
                    "score": round(float(score), 6),
                    "benefit_score": round(float(benefit_score), 6),
                    "benefit_min_score": round(float(benefit_min_score), 6),
                    "legacy_fallback_min_score": round(float(legacy_fallback_min_score), 6),
                }
                return "gap_aware_benefit_low_score"
            if action_selectivity_bypass:
                item["benefit_planner_gate"] = {
                    "approved": True,
                    "reason": "action_selectivity_bypass",
                    "score": round(float(score), 6),
                    "benefit_score": round(float(benefit_score), 6),
                    "benefit_min_score": round(float(benefit_min_score), 6),
                    "legacy_fallback_min_score": round(float(legacy_fallback_min_score), 6),
                }
        elif score < min_score:
            return "gap_aware_low_score"
        original_rank = self._safe_int(item.get("original_rank"), 10**9)
        max_original_rank = int(config.get("max_original_rank", self.utility_planner_max_original_rank) or 0)
        if max_original_rank > 0 and original_rank > max_original_rank:
            return "gap_aware_rank_too_low"
        item["_utility_planner_gap_aware_candidate"] = True
        return "gap_aware_candidate"

    def _gap_aware_replacement_profile(
        self,
        doc_id: int,
        original_rank: int,
        passage_details: Mapping[int, Mapping[str, Any]],
        max_raw_score: float,
        query_plan_log: Mapping[str, Any],
    ) -> Dict[str, Any]:
        replacement_item = self._answer_pairwise_doc_item(
            doc_id,
            original_rank,
            passage_details,
            max_raw_score,
            query_plan_log,
        )
        replacement_item["counterfactual_text_verifier"] = self._counterfactual_text_profile(
            replacement_item,
            query_plan_log,
        )
        planner = self._gap_aware_model_profile(replacement_item, query_plan_log)
        return {
            "item": replacement_item,
            "planner": planner,
            "text_profile": replacement_item.get("counterfactual_text_verifier", {}) or {},
            "baseline_value": self._baseline_replacement_value(
                doc_id,
                original_rank,
                passage_details,
                max_raw_score,
            ),
        }

    def _pairwise_swap_config(self) -> Dict[str, Any]:
        if not self.utility_planner.is_ready():
            return {}
        config = self._gap_aware_topk_config()
        pairwise_config = config.get("pairwise_swap_planner", {}) if isinstance(config, Mapping) else {}
        if not isinstance(pairwise_config, Mapping) or not pairwise_config:
            pairwise_config = self.utility_planner.model.get("pairwise_swap_planner", {}) or {}
        return dict(pairwise_config) if isinstance(pairwise_config, Mapping) else {}

    def _pairwise_swap_section_config(self, target_top2: bool) -> Dict[str, Any]:
        root = self._pairwise_swap_config()
        if not root:
            return {}
        section_key = "top2" if target_top2 else "top5"
        section = root.get(section_key, {})
        if isinstance(section, Mapping) and section.get("weights") and section.get("feature_names"):
            merged = dict(root)
            merged.update(dict(section))
            merged["section"] = section_key
            return merged
        root["section"] = "root"
        return root

    def _pairwise_swap_ready(self) -> bool:
        config = self._pairwise_swap_config()
        if bool(config.get("weights")) and bool(config.get("feature_names")):
            return True
        for section_key in ("top2", "top5"):
            section = config.get(section_key, {}) if isinstance(config, Mapping) else {}
            if isinstance(section, Mapping) and bool(section.get("weights")) and bool(section.get("feature_names")):
                return True
        return False

    def _pairwise_swap_score(
        self,
        candidate: Mapping[str, Any],
        replacement: Mapping[str, Any],
        query_plan_log: Mapping[str, Any],
        target_top2: bool,
    ) -> Tuple[float, Dict[str, Any]]:
        config = self._pairwise_swap_section_config(target_top2)
        names = list(config.get("feature_names") or EVIDENCE_SET_POLICY_FEATURE_NAMES)
        weights = [self._safe_float(value, 0.0) for value in (config.get("weights") or [])]
        if not names or not weights:
            return 0.0, {"ready": False}
        means = [self._safe_float(value, 0.0) for value in (config.get("means") or [0.0] * len(names))]
        stds = [self._safe_float(value, 1.0) for value in (config.get("stds") or [1.0] * len(names))]
        if len(means) < len(names):
            means.extend([0.0] * (len(names) - len(means)))
        if len(stds) < len(names):
            stds.extend([1.0] * (len(names) - len(stds)))
        feature_family = str(config.get("feature_family") or "").strip().lower()
        use_rank2_pairwise_features = (
            feature_family in {"rank2_pairwise", "access_path_pairwise"}
            or any(str(name).startswith("candidate_") for name in names)
        )
        if use_rank2_pairwise_features:
            replacement_info = {
                "doc_id": self._safe_int(replacement.get("passage_idx"), None),
                "rank": self._safe_int(replacement.get("original_rank"), 0),
                "value": self._candidate_evidence_value(replacement),
                "confidence": self._safe_float(replacement.get("confidence"), 0.0),
                "score": self._safe_float(replacement.get("score"), 0.0),
            }
            features = extract_rank2_pairwise_features(query_plan_log, candidate, replacement_info)
        else:
            candidate_features = extract_evidence_set_policy_features(query_plan_log, candidate)
            replacement_features = extract_evidence_set_policy_features(query_plan_log, replacement)
            features = {
                name: self._safe_float(candidate_features.get(name), 0.0)
                - self._safe_float(replacement_features.get(name), 0.0)
                for name in names
            }
        total = self._safe_float(config.get("bias"), 0.0)
        feature_snapshot: Dict[str, float] = {}
        for index, name in enumerate(names):
            if index >= len(weights):
                break
            std = stds[index] if abs(stds[index]) > 1e-9 else 1.0
            value = self._safe_float(features.get(name), 0.0)
            total += weights[index] * ((value - means[index]) / std)
            if name in {
                "original_rank_log",
                "candidate_confidence",
                "candidate_candidate_confidence",
                "coverage_gain",
                "candidate_coverage_gain",
                "has_terminal",
                "candidate_has_terminal",
                "has_relation",
                "candidate_has_relation",
                "counterfactual_text_score",
                "candidate_counterfactual_text_score",
                "counterfactual_text_answer_signal",
                "candidate_counterfactual_text_answer_signal",
                "counterfactual_text_endpoint_signal",
                "candidate_counterfactual_text_endpoint_signal",
                "counterfactual_text_relation_only",
                "candidate_counterfactual_text_relation_only",
                "replacement_rank_log",
                "replacement_value",
                "candidate_value",
                "value_margin",
                "source_score",
                "path_aware_score",
                "evidence_join_score",
                "answer_pairwise_score",
                "schema_slot_utility_score",
            }:
                feature_snapshot[name if use_rank2_pairwise_features else f"delta_{name}"] = round(
                    float(value),
                    6,
                )
        score = 1.0 / (1.0 + float(np.exp(-np.clip(total, -40.0, 40.0))))
        return min(max(float(score), 0.0), 1.0), {
            "ready": True,
            "target_top2": bool(target_top2),
            "section": str(config.get("section") or ("top2" if target_top2 else "top5")),
            "feature_family": feature_family or ("rank2_pairwise" if use_rank2_pairwise_features else "delta"),
            "feature_snapshot": feature_snapshot,
            "candidate_original_rank": self._safe_int(candidate.get("original_rank"), -1),
            "replacement_original_rank": self._safe_int(replacement.get("original_rank"), -1),
        }

    def _action_risk_config(self) -> Dict[str, Any]:
        if not self.utility_planner.is_ready():
            return {}
        config = self._gap_aware_topk_config()
        action_config = config.get("action_risk_planner", {}) if isinstance(config, Mapping) else {}
        if not isinstance(action_config, Mapping) or not action_config:
            action_config = self.utility_planner.model.get("action_risk_planner", {}) or {}
        return dict(action_config) if isinstance(action_config, Mapping) else {}

    def _action_risk_section_config(self, target_top2: bool) -> Dict[str, Any]:
        root = self._action_risk_config()
        if not root:
            return {}
        section_key = "top2" if target_top2 else "top5"
        section = root.get(section_key, {})
