        def flush_rank_window_recall_log() -> None:
            log["rank_window_recall_candidate_count"] = int(rank_window_recall_candidates)
            log["rank_window_recall_deferred_direct_count"] = int(rank_window_recall_deferred_direct)
            log["rank_window_recall_top2_used_count"] = int(rank_window_recall_top2_used)
            log["rank_window_recall_top5_used_count"] = int(rank_window_recall_top5_used)
            log["rank_window_recall_no_new_slot_bypass_count"] = int(
                rank_window_recall_no_new_slot_bypasses
            )
            log["rank_window_recall_low_confidence_bypass_count"] = int(
                rank_window_recall_low_confidence_bypasses
            )
            log["rank_window_recall_precision_bypass_count"] = int(
                rank_window_recall_precision_bypasses
            )
            log["rank_window_recall_router_override"] = bool(rank_window_recall_router_override)
            log["rank_window_recall_rejection_reasons"] = dict(rank_window_recall_rejections)
            log["rank_window_recall_rejected_candidates"] = rank_window_recall_rejected_candidates
            log["rank_window_recall_selected_candidates"] = rank_window_recall_selected_candidates

        def flush_evidence_warehouse_log(candidate_items: Sequence[Mapping[str, Any]]) -> None:
            best_net_benefit = 0.0
            for item in candidate_items:
                profile = item.get("evidence_warehouse_optimizer", {}) or {}
                if not isinstance(profile, Mapping):
                    continue
                action = profile.get("action", {}) or {}
                if isinstance(action, Mapping):
                    best_net_benefit = max(
                        best_net_benefit,
                        self._safe_float(action.get("net_benefit"), 0.0),
                    )
            log["evidence_warehouse_optimizer_candidate_count"] = int(evidence_warehouse_candidates)
            log["evidence_warehouse_optimizer_selected_count"] = sum(
                1 for item in selected_ontology if bool(item.get("_evidence_warehouse_selected", False))
            )
            log["evidence_warehouse_optimizer_top2_selected_count"] = sum(
                1 for item in selected_ontology if bool(item.get("_evidence_warehouse_top2_selected", False))
            )
            log["evidence_warehouse_optimizer_top5_selected_count"] = sum(
                1 for item in selected_ontology if bool(item.get("_evidence_warehouse_top5_selected", False))
            )
            log["evidence_warehouse_optimizer_top2_used_count"] = int(evidence_warehouse_top2_used)
            log["evidence_warehouse_optimizer_top5_used_count"] = int(evidence_warehouse_top5_used)
            log["evidence_warehouse_optimizer_best_net_benefit"] = round(float(best_net_benefit), 6)
            log["evidence_warehouse_optimizer_rejection_reasons"] = dict(evidence_warehouse_rejections)
            log["evidence_warehouse_optimizer_rejected_candidates"] = evidence_warehouse_rejected_candidates
            log["evidence_warehouse_optimizer_selected_candidates"] = evidence_warehouse_selected_candidates
            log["evidence_warehouse_optimizer_row_samples"] = evidence_warehouse_row_samples

